// ===== GLOBAL ERROR HANDLER =====
window.onerror = function(msg, url, line, col, err) {
 console.error('Candooka error:', msg, 'at', url, line, col, err);
 return false;
};

// ===== USER-SPECIFIC LOCAL STORAGE HELPER =====
// Returns a localStorage key that is specific to the current logged-in user
function userKey(baseKey) {
 const user = state.currentUser || 'guest';
 // Sanitize username to be safe for localStorage keys
 const safeUser = user.replace(/[^a-zA-Z0-9_-]/g, '_');
 return `candooka_${safeUser}_${baseKey}`;
}

// Brand UI / survey labels: English letters, digits, and basic punctuation only.
// Strips CJK and any other script so line names never show foreign glyphs.
function sanitizeLineName(raw, fallback) {
 const fb = (fallback != null && String(fallback).trim() !== '') ? String(fallback) : 'Line';
 let s = (raw == null) ? '' : String(raw);
 // Normalize common mojibake / smart punctuation before the strict ASCII pass
 s = s
  .replace(/\uFEFF/g, '')
  .replace(/[\u2013\u2014\u2212\u00AD]/g, '-') // en/em dash, minus, soft hyphen
  .replace(/[\u2018\u2019\u201A\u2032\u00B4`]/g, "'")
  .replace(/[\u201C\u201D\u201E\u2033]/g, '"')
  .replace(/[\u2026]/g, '...')
  .replace(/[\u00A0\u2000-\u200B\u202F\u205F\u3000]/g, ' ')
  .replace(/[\u2190-\u21FF]/g, '-'); // arrows -> hyphen
 // Drop remaining non-ASCII, control chars, nulls from binary P1 fields
 s = s.replace(/[^\x20-\x7E]/g, '');
 // Line names: letters, digits, and basic punctuation only
 s = s.replace(/[^A-Za-z0-9\-_./ ]+/g, '');
 s = s.replace(/\s+/g, ' ').trim();
 // Collapse accidental multi-hyphen/dot junk from the replacements above
 s = s.replace(/[-_]{2,}/g, '-').replace(/\.{2,}/g, '.').replace(/^[-_.\s]+|[-_.\s]+$/g, '');
 if (!s) {
  s = String(fb).replace(/[^\x20-\x7E]/g, '').replace(/[^A-Za-z0-9\-_./ ]+/g, '').trim() || 'Line';
 }
 // Cap length for P1/export friendliness
 if (s.length > 32) s = s.slice(0, 32).replace(/[-_.\s]+$/g, '');
 return s;
}

function sanitizeAllLineNames(lines) {
 if (!Array.isArray(lines)) return lines;
 lines.forEach((l, i) => {
 if (!l || typeof l !== 'object') return;
 l.name = sanitizeLineName(l.name, 'Line-' + (i + 1));
 if (l._importName) l._importName = sanitizeLineName(l._importName, l.name);
 });
 return lines;
}

// ===== DIALOG WINDOW CONTROLS (Drag, Minimize, Maximize, Scroll) =====
function makeDialogInteractive(dlg, opts = {}) {
 if (!dlg || dlg._interactive) return;
 dlg._interactive = true;
 dlg._minimized = false;
 dlg._maximized = false;

 // Ensure scroll
 dlg.style.overflowY = 'auto';

 // Store original styles for restore
 dlg._origStyle = {
 top: dlg.style.top, left: dlg.style.left, width: dlg.style.width, height: dlg.style.height,
 maxWidth: dlg.style.maxWidth, maxHeight: dlg.style.maxHeight, minWidth: dlg.style.minWidth,
 transform: dlg.style.transform, borderRadius: dlg.style.borderRadius
 };

 // Find or create a drag handle (first child div that looks like a header)
 let header = dlg.querySelector('[data-dialog-header]');
 if (!header) {
 // Look for .panel-title (settings panels)
 const pTitle = dlg.querySelector('.panel-title');
 if (pTitle) {
 header = pTitle;
 } else {
 // Look for the first flex row with a title and close button
 const firstDiv = dlg.querySelector('div');
 if (firstDiv && (firstDiv.style.display === 'flex' || firstDiv.querySelector('button'))) {
 header = firstDiv;
 } else {
 header = firstDiv || dlg;
 }
 }
 }
 header.setAttribute('data-dialog-header', '1');
 header.style.cursor = 'move';
 header.style.userSelect = 'none';

 // Keep absolute panel close buttons clickable (title flex must not cover them)
 dlg.querySelectorAll('.panel-close-btn').forEach(btn => {
 btn.style.zIndex = '20';
 btn.style.position = 'absolute';
 btn.style.pointerEvents = 'auto';
 });

 // Add window control buttons (min/max) if not already present
 if (!dlg.querySelector('.dlg-ctrl-btns')) {
 const ctrlWrap = document.createElement('span');
 ctrlWrap.className = 'dlg-ctrl-btns';
 ctrlWrap.style.cssText = 'display:inline-flex;gap:4px;margin-left:auto;margin-right:28px;';
 ctrlWrap.innerHTML = `
 <button class="dlg-min-btn" title="Minimize" style="background:none;border:1px solid #444;color:#ffd60a;font-size:12px;width:20px;height:20px;border-radius:3px;cursor:pointer;line-height:1;display:flex;align-items:center;justify-content:center;">&#9472;</button>
 <button class="dlg-max-btn" title="Maximize" style="background:none;border:1px solid #444;color:#30d158;font-size:11px;width:20px;height:20px;border-radius:3px;cursor:pointer;line-height:1;display:flex;align-items:center;justify-content:center;">&#9723;</button>`;
 // Insert before the close button if it exists in the header
 const closeBtn = header.querySelector('button:last-child');
 const closeTxt = closeBtn ? (closeBtn.textContent || '') : '';
 if (closeBtn && (/[xX\u00d7\u2715]/.test(closeTxt) || closeBtn.classList.contains('panel-close-btn'))) {
 header.insertBefore(ctrlWrap, closeBtn);
 } else {
 // For .panel-title style headers, insert after the title (leave room for X)
 header.style.display = 'flex';
 header.style.alignItems = 'center';
 header.style.justifyContent = 'space-between';
 header.style.paddingRight = '28px';
 header.appendChild(ctrlWrap);
 }

 // Minimize handler
 ctrlWrap.querySelector('.dlg-min-btn').onclick = (e) => {
 e.stopPropagation();
 if (dlg._minimized) {
 // Restore
 Array.from(dlg.children).forEach(ch => { if (ch !== header) ch.style.display = ''; });
 dlg.style.maxHeight = dlg._origStyle.maxHeight || '';
 dlg.style.overflow = 'auto';
 dlg._minimized = false;
 } else {
 // Collapse to header only
 Array.from(dlg.children).forEach(ch => { if (ch !== header) ch.style.display = 'none'; });
 dlg.style.maxHeight = 'none';
 dlg.style.overflow = 'hidden';
 dlg._minimized = true;
 if (dlg._maximized) { _dlgRestoreSize(dlg); dlg._maximized = false; }
 }
 };

 // Maximize handler
 ctrlWrap.querySelector('.dlg-max-btn').onclick = (e) => {
 e.stopPropagation();
 if (dlg._maximized) {
 _dlgRestoreSize(dlg);
 dlg._maximized = false;
 } else {
 dlg.style.top = '5px'; dlg.style.left = '5px'; dlg.style.right = '5px'; dlg.style.bottom = '5px';
 dlg.style.width = 'calc(100vw - 10px)'; dlg.style.height = 'calc(100vh - 10px)';
 dlg.style.maxWidth = 'none'; dlg.style.maxHeight = 'none';
 dlg.style.transform = 'none'; dlg.style.borderRadius = '4px';
 dlg._maximized = true;
 if (dlg._minimized) {
 Array.from(dlg.children).forEach(ch => { if (ch !== header) ch.style.display = ''; });
 dlg.style.overflow = 'auto';
 dlg._minimized = false;
 }
 }
 };
 }

 // Dragging logic
 let isDragging = false, startX, startY, origX, origY;
 header.addEventListener('mousedown', (e) => {
 if (e.target.tagName === 'BUTTON' || e.target.tagName === 'INPUT' || e.target.tagName === 'SELECT') return;
 if (dlg._maximized) return;
 isDragging = true;
 startX = e.clientX; startY = e.clientY;
 const rect = dlg.getBoundingClientRect();
 origX = rect.left; origY = rect.top;
 dlg.style.transform = 'none';
 dlg.style.left = origX + 'px'; dlg.style.top = origY + 'px';
 e.preventDefault();
 });
 document.addEventListener('mousemove', (e) => {
 if (!isDragging) return;
 const dx = e.clientX - startX, dy = e.clientY - startY;
 dlg.style.left = (origX + dx) + 'px';
 dlg.style.top = (origY + dy) + 'px';
 });
 document.addEventListener('mouseup', () => { isDragging = false; });
}

function _dlgRestoreSize(dlg) {
 const o = dlg._origStyle;
 dlg.style.top = o.top || '50%'; dlg.style.left = o.left || '50%';
 dlg.style.width = o.width || ''; dlg.style.height = o.height || '';
 dlg.style.maxWidth = o.maxWidth || ''; dlg.style.maxHeight = o.maxHeight || '';
 dlg.style.transform = o.transform || 'translate(-50%,-50%)';
 dlg.style.borderRadius = o.borderRadius || '8px';
 dlg.style.right = ''; dlg.style.bottom = '';
}

// ===== STATE =====
const state = {
 lines: [], // { id, name, start: [lat,lon], end: [lat,lon] }
 obstructions: [], // { id, name, polygon: [[lat,lon],...] }
 userFeatures: [], // { id, name, type, polygon/center, exclusionZone } (non-obstruction reference)
 obnNodes: [], // OBN seabed nodes { id, name, lat, lon }
 skippedRanges: [], // { lineName, fromFrac, toFrac, distKm }
 settings: {
 turnRadius: 3500, // metres
 speed: 4.8, // knots (online / survey)
 turnSpeed: 4.6, // knots (line turns / transit)
 runIn: 7500, // metres
 runOut: 3050, // metres
 lineSpacing: 0, // metres (for sq km calc, 0 = auto-detect)
 spInterval: 25, // shot point interval in metres
 // Cross-track offline (m) beyond which detour coverage is treated as no SP acquired.
 // null = not set yet; user is prompted when an obstruction affects the plan.
 offlineNoSpM: null,
 numStreamers: 6, // number of streamers
 streamerSeparation: 100, // metres between streamers
 swathWidth: 0, // metres (0 = auto-detect from line spacing)
 channelsPerStreamer: 480, // number of channels per streamer
 channelSpacing: 12.5, // channel spacing in metres
 numSources: 2, // number of sources
 spIntervalPerSource: 50, // SP interval per source in metres
 modeOfShooting: 'flip-flop', // mode of shooting (user text input)
 optimizerIterations: 1500, // deep-search ILS iterations for the auto route optimizer
 startTime: null,
 startPoint: null, // [lat, lon] or null (use first line start)
 weatherDowntime: 15, // % technical downtime
 standbyPct: 0, // % standby time
 timeAdjustmentsPct: 0, // % time adjustments
 infillPct: 0, // % infill
 mobDemobDays: 0, // mob/demob time in days
 additionalPlanned: 0, // additional planned time in days
 additionalUnplanned: 0, // additional unplanned time in days
 vesselDayRate: 0, // USD per day (0 = don't show cost)
 primeCostMode: 'dayrate', // 'dayrate', 'linekm', or 'sqkm' for prime lines
 infillCostMode: 'dayrate', // 'dayrate', 'linekm', or 'sqkm' for infill lines
 costPerLineKm: 0, // cost per full fold line km
 costPerSqKm: 0, // cost per full fold sq km
 costPerKm: 0, // legacy: cost per km (alternative to day rate)
 costMode: 'dayrate', // legacy: 'dayrate' or 'perkm'
 chargeableStandby: 0, // standby day rate
 permitting: 0, // fixed cost
 environmental: 0, // fixed cost
 fisheriesComp: 0, // fixed cost
 ancilVesselRate: 0, ancilVesselCount: 0,
 pmRate: 0, pmMultiplier: 1, pmCount: 0,
 clientRepRate: 0, clientRepCount: 0,
 mfoRate: 0, mfoCount: 0,
 svcRate: 0, svcCount: 0,
 ancilEquipRate: 0, ancilEquipFixed: 0,
 preSurveyScout: 0, // fixed cost
 bathySurvey: 0, // fixed cost
 mobDemob: 0 // USD mobilisation/demobilisation cost (legacy)
 },
 route: null, // planned route waypoints
 activeTab: 'plan',
 showAnnotations: false,
 sstMapDay: 'default', // GIBS SST tile day: 'default' or YYYY-MM-DD
 showLabels: true,
 coordFormat: 'utm', // 'utm' or 'latlon'
 currentUser: 'Guest'
};

// ===== DEVICE PERFORMANCE & WEBGL CAPABILITIES =====
function isWebGLSupported() {
 try {
 const canvas = document.createElement('canvas');
 return !!(window.WebGLRenderingContext && (canvas.getContext('webgl') || canvas.getContext('experimental-webgl')));
 } catch (e) {
 return false;
 }
}

function isMobileDevice() {
 return /Android|iPhone|iPad|iPod|webOS|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent) ||
 (window.innerWidth <= 768);
}

// ===== CESIUM 3D GLOBE =====
var cesiumViewer = null;
var globeActive = isWebGLSupported() && !isMobileDevice() && (typeof Cesium !== 'undefined');

try {
 if (globeActive && typeof Cesium !== 'undefined') {
 cesiumViewer = new Cesium.Viewer('cesium-globe', {
 baseLayerPicker: false,
 geocoder: false,
 homeButton: false,
 infoBox: false,
 navigationHelpButton: false,
 sceneModePicker: false,
 selectionIndicator: false,
 timeline: false,
 animation: false,
 fullscreenButton: false,
 vrButton: false,
 creditContainer: document.createElement('div'),
 terrainProvider: new Cesium.EllipsoidTerrainProvider()
 });

 // Asynchronously load the local earth satellite texture
 Cesium.SingleTileImageryProvider.fromUrl('earth.jpg').then(provider => {
 if (cesiumViewer) {
 cesiumViewer.imageryLayers.removeAll();
 cesiumViewer.imageryLayers.addImageryProvider(provider);
 }
 }).catch(err => {
 console.warn('Failed to load local earth texture:', err);
 });

 // Slow auto-rotation
 cesiumViewer.clock.onTick.addEventListener(() => {
 if (globeActive && cesiumViewer) {
 cesiumViewer.scene.camera.rotateRight(0.001);
 }
 });

 // Center camera on user'location if available, otherwise fallback
 if (navigator.geolocation) {
 navigator.geolocation.getCurrentPosition(
 (pos) => {
 const lat = pos.coords.latitude;
 const lon = pos.coords.longitude;
 if (cesiumViewer && globeActive) {
 cesiumViewer.camera.setView({
 destination: Cesium.Cartesian3.fromDegrees(lon, lat, 12000000)
 });
 }
 },
 () => {
 if (cesiumViewer) {
 cesiumViewer.camera.setView({
 destination: Cesium.Cartesian3.fromDegrees(10, 20, 15000000)
 });
 }
 },
 { timeout: 5000 }
 );
 } else {
 cesiumViewer.camera.setView({
 destination: Cesium.Cartesian3.fromDegrees(10, 20, 15000000)
 });
 }

 // Live Bathymetry and Coordinates tracking for Cesium Globe
 const cesiumHandler = new Cesium.ScreenSpaceEventHandler(cesiumViewer.scene.canvas);
 cesiumHandler.setInputAction(movement => {
 if (!globeActive || !cesiumViewer) return;
 const cartesian = cesiumViewer.camera.pickEllipsoid(movement.endPosition, cesiumViewer.scene.globe.ellipsoid);
 if (cartesian) {
 const cartographic = Cesium.Cartographic.fromCartesian(cartesian);
 const lat = Cesium.Math.toDegrees(cartographic.latitude);
 const lon = Cesium.Math.toDegrees(cartographic.longitude);
 const depthStr = getBathymetry(lat, lon);
 const el = document.getElementById('coords-display');
 const utmZone = state.settings.utmZone || Math.floor((lon + 180) / 6) + 1;
 const utm = latLonToUtm(lat, lon, utmZone);
 el.textContent = `E: ${utm.easting.toFixed(1)} N: ${utm.northing.toFixed(1)} | ${lat.toFixed(5)}, ${lon.toFixed(5)} | ${depthStr}`;
 } else {
 document.getElementById('coords-display').textContent = 'E: -- N: -- | --, -- | --';
 }
 }, Cesium.ScreenSpaceEventType.MOUSE_MOVE);

 } else {
 // No Cesium (mobile or no WebGL) - go straight to 2D Leaflet map
 var cesEl = document.getElementById('cesium-globe');
 var mapEl = document.getElementById('map');
 if (cesEl) cesEl.style.display = 'none';
 if (mapEl) mapEl.style.display = 'block';
 var modeBtn = document.getElementById('ctrl-mode-toggle');
 if (modeBtn) {
 modeBtn.textContent = '3D';
 modeBtn.style.background = '#e67e22';
 }
 // Wait for Leaflet to be available before initializing
 function waitForLeaflet() {
 if (typeof L !== 'undefined' && typeof initLeafletMap === 'function') {
 initLeafletMap();
 } else {
 setTimeout(waitForLeaflet, 100);
 }
 }
 setTimeout(waitForLeaflet, 100);
 }

 // Force resize on load and window resize
 window.addEventListener('load', () => {
 if (cesiumViewer) cesiumViewer.resize();
 });
 window.addEventListener('resize', () => {
 if (cesiumViewer) cesiumViewer.resize();
 });
 setTimeout(() => {
 if (cesiumViewer) cesiumViewer.resize();
 }, 100);
 setTimeout(() => {
 if (cesiumViewer) cesiumViewer.resize();
 }, 500);
} catch (e) {
 console.warn('Cesium failed to load, falling back to flat map:', e);
 globeActive = false;
 var cesGlobe = document.getElementById('cesium-globe');
 var mapDiv = document.getElementById('map');
 if (cesGlobe) cesGlobe.style.display = 'none';
 if (mapDiv) mapDiv.style.display = 'block';
 setTimeout(function() {
 if (typeof initLeafletMap === 'function') initLeafletMap();
 }, 200);
}

// ===== BATHYMETRY (DEPTH) FROM GEBCO VIA SERVER PROXY =====
var _lastDepthQuery = 0;
var _lastDepthStr = 'Depth: --';

function getBathymetry(lat, lon) {
 // Throttle: max 1 query per 600ms
 const now = Date.now();
 if (now - _lastDepthQuery < 600) return _lastDepthStr;
 _lastDepthQuery = now;

 // Query via server-side proxy to avoid CORS
 const url = `/api/get-depth.php?lat=${lat.toFixed(5)}&lon=${lon.toFixed(5)}`;

 fetch(url).then(r =>r.json()).then(data => {
 if (data.elevation !== undefined) {
 const val = data.elevation;
 if (val <= 0) {
 _lastDepthStr = `Depth: ${Math.abs(val).toFixed(1)}m`;
 } else {
 _lastDepthStr = `Elev: ${val.toFixed(0)}m (land)`;
 }
 } else {
 _lastDepthStr = 'Depth: --';
 }
 // Update display immediately
 const el = document.getElementById('coords-display');
 if (el && el.textContent.includes('Lat:')) {
 el.textContent = el.textContent.replace(/Depth:.*|Elev:.*/, _lastDepthStr);
 }
 }).catch(() => { _lastDepthStr = 'Depth: --'; });

 return _lastDepthStr;
}

// ===== MAP SETUP (Leaflet - initially hidden) =====
var map = null;
var layerSurveyLines, layerRoute, layerLabels, layerAnnotations, layerObstructions, layerArrows, layerSwaths, layerStartPoint, layerRayTrace, layerObnNodes;

// Dates and times are shown one way only, so a date can never be read the
// wrong way round and a time can never be mistaken for am/pm: the month is
// always spelled (03 Aug 2026) and clock times are 24-hour with an explicit
// suffix (00:00 hrs, 18:00 hrs, 23:59 hrs - midnight is 00:00, never 24:00).
const MONTH_ABBR = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];

// Clock time alone: 18:00 hrs.
function fmtT24(d) {
 if (!(d instanceof Date)) d = new Date(d);
 if (isNaN(d)) return '';
 return `${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')} hrs`;
}

// Full timestamp: 03 Aug 2026 18:00 hrs.
function fmtDT24(d) {
 if (!(d instanceof Date)) d = new Date(d);
 if (isNaN(d)) return '';
 return `${fmtD24(d)} ${fmtT24(d)}`;
}

// Date without time: 03 Aug 2026.
function fmtD24(d) {
 if (!(d instanceof Date)) d = new Date(d);
 if (isNaN(d)) return '';
 return `${String(d.getDate()).padStart(2, '0')} ${MONTH_ABBR[d.getMonth()]} ${d.getFullYear()}`;
}

// Day and month only, for space-constrained schedule/timeline labels: 03 Aug.
function fmtDM24(d) {
 if (!(d instanceof Date)) d = new Date(d);
 if (isNaN(d)) return '';
 return `${String(d.getDate()).padStart(2, '0')} ${MONTH_ABBR[d.getMonth()]}`;
}

// Day, month and time, no year: 03 Aug 18:00 hrs.
function fmtDMT24(d) {
 if (!(d instanceof Date)) d = new Date(d);
 if (isNaN(d)) return '';
 return `${fmtDM24(d)} ${fmtT24(d)}`;
}

function initLeafletMap() {
 if (map) return; // already initialized

 document.getElementById('map').style.display = 'block';
 map = L.map('map', {
 center: [20, 0],
 zoom: 3,
 zoomControl: false,
 attributionControl: true,
 // Fine-grained zoom: fractional zoom levels in 0.1 steps, quarter-level
 // +/- buttons and a slow, smooth scroll-wheel zoom.
 zoomSnap: 0.1,
 zoomDelta: 0.25,
 wheelPxPerZoomLevel: 240,
 wheelDebounceTime: 25
 });

 currentBaseLayer = L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}', {
 attribution: 'Tiles &copy; Esri',
 maxZoom: 19,
 crossOrigin: true
 }).addTo(map);

 // Apply pending base layer choice (from chooser before map init)
 const pending = window._pendingBaseLayer || localStorage.getItem('candooka_baseLayer');
 if (pending) {
 switchBaseMap(pending);
 window._pendingBaseLayer = null;
 }

 // Scale bar
 L.control.scale({ position: 'bottomleft', metric: true, imperial: true, maxWidth: 200 }).addTo(map);

 // Layer groups
 layerSurveyLines = L.layerGroup().addTo(map);
 layerRoute = L.layerGroup().addTo(map);
 layerLabels = L.layerGroup().addTo(map);
 layerAnnotations = L.layerGroup(); // default off; user toggles via Annotations button
 layerArrows = L.layerGroup().addTo(map);
 layerObstructions = L.layerGroup().addTo(map);
 layerSwaths = L.layerGroup().addTo(map);
 layerStartPoint = L.layerGroup().addTo(map);
 layerRayTrace = L.layerGroup().addTo(map);
 layerObnNodes = L.layerGroup().addTo(map);

 // Map events
 map.on('mousemove', e => {
 const dStr = getBathymetry(e.latlng.lat, e.latlng.lng);
 const el = document.getElementById('coords-display');
 const utmZone = state.settings.utmZone || Math.floor((e.latlng.lng + 180) / 6) + 1;
 const utm = latLonToUtm(e.latlng.lat, e.latlng.lng, utmZone);
 let sstExtra = '';
 if (typeof isSstMapActive === 'function' && isSstMapActive()) {
  // Live SST under cursor (throttled probe updates the legend panel)
  if (typeof _sstScheduleProbe === 'function') _sstScheduleProbe(e.latlng.lat, e.latlng.lng);
  const ro = document.getElementById('sst-probe-readout');
  if (ro && ro.dataset.filled === '1') {
   // Pull numeric degC if present in the readout text for the status bar
   const m = (ro.textContent || '').match(/(-?\d+(?:\.\d+)?)\s*degC/);
   if (m) sstExtra = ' | SST ' + m[1] + ' degC';
  } else {
   sstExtra = ' | SST...';
  }
 }
 el.textContent = `E: ${utm.easting.toFixed(1)} N: ${utm.northing.toFixed(1)} | ${e.latlng.lat.toFixed(5)}, ${e.latlng.lng.toFixed(5)} | ${dStr}${sstExtra}`;
 });
 map.on('zoomend', () => {
 document.getElementById('zoom-level').textContent = `Z: ${map.getZoom()}`;
 });
 map.on('click', e => {
 if (drawingObstruction) return;
 if (settingStartPoint) {
 state.settings.startPoint = [e.latlng.lat, e.latlng.lng];
 // A custom start point overrides any previously selected start line.
 state.settings.startLineIdx = null;
 state.settings.startLineId = null;
 state.settings.startLineReversed = false;
 state.settings.startConfigured = true;
 settingStartPoint = false;
 map.getContainer().style.cursor = '';
 _syncStartPointPanel();
 showToast('Start point set');
 }
 });
 map.on('click', e => { onMapClickObstruction(e); });

 // Right-click context menu - quick add obstruction at click location
 map.on('contextmenu', e => {
 if (drawingObstruction || settingStartPoint) return;
 const lat = e.latlng.lat.toFixed(5);
 const lon = e.latlng.lng.toFixed(5);
 const popup = L.popup({ closeButton: true, className: 'context-popup' })
 .setLatLng(e.latlng)
 .setContent(`
 <div style="font-family:'Inter',sans-serif;font-size:11px;min-width:180px;">
 <div style="font-weight:700;margin-bottom:6px;color:#222;">Add at ${lat}, ${lon}</div>
 <div style="display:flex;flex-direction:column;gap:4px;">
 <button onclick="quickAddObstruction(${e.latlng.lat},${e.latlng.lng},'platform');map.closePopup();" style="padding:5px 8px;border:none;background:#e74c3c;color:#fff;border-radius:3px;cursor:pointer;font-size:10px;font-weight:600;text-align:left;">sTM Platform / Rig</button>
 <button onclick="quickAddObstruction(${e.latlng.lat},${e.latlng.lng},'shallow');map.closePopup();" style="padding:5px 8px;border:none;background:#f39c12;color:#fff;border-radius:3px;cursor:pointer;font-size:10px;font-weight:600;text-align:left;">s Shallow / Shoal</button>
 <button onclick="quickAddObstruction(${e.latlng.lat},${e.latlng.lng},'wreck');map.closePopup();" style="padding:5px 8px;border:none;background:#9b59b6;color:#fff;border-radius:3px;cursor:pointer;font-size:10px;font-weight:600;text-align:left;">s" Wreck</button>
 <button onclick="quickAddObstruction(${e.latlng.lat},${e.latlng.lng},'island');map.closePopup();" style="padding:5px 8px;border:none;background:#27ae60;color:#fff;border-radius:3px;cursor:pointer;font-size:10px;font-weight:600;text-align:left;">Island / Rock</button>
 <button onclick="quickAddObstruction(${e.latlng.lat},${e.latlng.lng},'cable');map.closePopup();" style="padding:5px 8px;border:none;background:#e67e22;color:#fff;border-radius:3px;cursor:pointer;font-size:10px;font-weight:600;text-align:left;">s Cable / Pipeline</button>
 <button onclick="quickAddObstruction(${e.latlng.lat},${e.latlng.lng},'restricted');map.closePopup();" style="padding:5px 8px;border:none;background:#c0392b;color:#fff;border-radius:3px;cursor:pointer;font-size:10px;font-weight:600;text-align:left;">" Restricted Area</button>
 <button onclick="quickAddObstruction(${e.latlng.lat},${e.latlng.lng},'other');map.closePopup();" style="padding:5px 8px;border:none;background:#555;color:#fff;border-radius:3px;cursor:pointer;font-size:10px;font-weight:600;text-align:left;">x Other</button>
 </div>
 </div>
 `)
 .openOn(map);
 });

 map.invalidateSize();
}

// Transition from Cesium globe to Leaflet map
function transitionToMap(centerLat, centerLon, zoom) {
 if (!globeActive) {
 // Globe never loaded - just init Leaflet
 initLeafletMap();
 if (centerLat !== undefined) map.setView([centerLat, centerLon], zoom || 10);
 return;
 }

 globeActive = false;
 // Fade out globe
 const globeEl = document.getElementById('cesium-globe');
 globeEl.style.transition = 'opacity 0.6s ease';
 globeEl.style.opacity = '0';

 setTimeout(() => {
 globeEl.style.display = 'none';
 if (cesiumViewer) {
 cesiumViewer.destroy();
 cesiumViewer = null;
 }
 initLeafletMap();
 if (centerLat !== undefined) map.setView([centerLat, centerLon], zoom || 10);
 // Hide no-survey overlay
 const overlay = document.getElementById('no-survey-overlay');
 if (overlay) overlay.style.display = 'none';
 }, 600);
}

// ===== GEOLOCATION & ZOOM =====
function flyToMyLocation() {
 if (!navigator.geolocation) {
 showToast('Geolocation not supported by your browser');
 return;
 }
 showToast('Getting your location...');
 navigator.geolocation.getCurrentPosition(
 (pos) => {
 const lat = pos.coords.latitude;
 const lon = pos.coords.longitude;
 if (globeActive && cesiumViewer) {
 // Fly the Cesium globe to user location
 cesiumViewer.camera.flyTo({
 destination: Cesium.Cartesian3.fromDegrees(lon, lat, 500000),
 duration: 2.0
 });
 } else if (map) {
 map.flyTo([lat, lon], 12, { duration: 1.5 });
 }
 showToast(`Location: ${lat.toFixed(4)}, ${lon.toFixed(4)}`);
 },
 (err) => {
 showToast('Could not get location: ' + err.message);
 },
 { enableHighAccuracy: true, timeout: 10000 }
 );
}

// SP count for a preplot line. FIXED RULE - the app never invents its own
// math when the preplot defines SP numbering:
// 1. spStart/spEnd range: Total SP = high SP - low SP + 1. Authoritative,
// NEVER overridden by distance-based estimates.
// 2. spCount - number of distinct SP records parsed from a fully-listed
// file (only used when no usable SP range exists).
// 3. Line length / SP interval - last resort for hand-drawn or generated
// lines that carry no SP numbering at all.
function lineSpCount(l, spInt) {
 if (l && l.spStart != null && l.spEnd != null && l.spEnd !== l.spStart) {
 return Math.abs(l.spEnd - l.spStart) + 1;
 }
 if (l && l.spCount != null && l.spCount > 2) return l.spCount;
 return (l && l.start && l.end) ? Math.round(haversine(l.start, l.end) / spInt) + 1 : 1;
}

// Full-fold coverage length of a line from its SP count. Each shotpoint owns a
// CMP bin of one SP interval centred on it, so N shotpoints cover N x spInt - // coverage runs half a bin beyond the first and last SP. This is CMP distance
// as used in geophysics, not centre-to-centre distance between end SPs:
// 1077 SP at 25 m covers 26.925 km, not 26.900 km.
function lineFullFoldM(l, spInt) {
 return lineSpCount(l, spInt) * spInt;
}

function zoomInView() {
 if (globeActive && cesiumViewer) {
 cesiumViewer.camera.zoomIn(cesiumViewer.camera.positionCartographic.height * 0.4);
 } else if (map) {
 map.zoomIn(0.25);
 }
}

function zoomOutView() {
 if (globeActive && cesiumViewer) {
 cesiumViewer.camera.zoomOut(cesiumViewer.camera.positionCartographic.height * 0.6);
 } else if (map) {
 map.zoomOut(0.25);
 }
}

// ===== UI HELPERS =====
let activePanels = new Set();

function toggleCoordFormat() {
 state.coordFormat = state.coordFormat === 'utm' ? 'latlon' : 'utm';
 const label = document.getElementById('coord-format-label');
 if (label) {
 label.textContent = state.coordFormat === 'utm' ? 'UTM' : 'GEO';
 label.style.color = state.coordFormat === 'utm' ? '#ffd60a' : '#00d2ff';
 }
 localStorage.setItem('candooka_coord_format', state.coordFormat);
}

// Restore saved coord format preference
(function() {
 const saved = localStorage.getItem('candooka_coord_format');
 if (saved === 'latlon') state.coordFormat = 'latlon';
})();

function hideAllPanels() {
 document.querySelectorAll('.settings-panel').forEach(p =>p.style.display = 'none');
 activePanels.clear();
}

function togglePanel(id) {
 const el = document.getElementById(`panel-${id}`);
 if (!el) return;
 const showing = el.style.display === 'block';
 
 // Close all other panels first
 hideAllPanels();
 
 if (!showing) {
 el.style.display = 'block';
 activePanels.add(id);
 // Populate speed panel inputs with current values
 if (id === 'speed') {
 const sEl = document.getElementById('input-speed'); if (sEl) sEl.value = state.settings.speed ?? 4.5;
 const tEl = document.getElementById('input-turn-speed'); if (tEl) tEl.value = state.settings.turnSpeed ?? 6;
 }
 // Reflect the current Start Time (from Survey Criteria or a prior edit).
 if (id === 'start-time') {
 const tEl = document.getElementById('input-start-time');
 if (tEl) tEl.value = state.settings.startTime || localStorage.getItem('candooka_default_starttime') || new Date().toISOString().slice(0, 16);
 }
 // Reflect the current Start Point selection.
 if (id === 'start-point') {
 _syncStartPointPanel();
 }
 makeDialogInteractive(el);
 }
}

function hidePanel(id) {
 const el = document.getElementById(`panel-${id}`);
 if (el) el.style.display = 'none';
 activePanels.delete(id);
}

function switchTab(tab) {
 state.activeTab = tab;
 const tabEl = document.getElementById('tab-plan');
 if (tabEl) tabEl.classList.add('active');
 
 if (tab === 'plan') {
 if (!state.lines || state.lines.length === 0) {
 const fileInput = document.getElementById('file-input');
 if (fileInput) {
 showToast('Please select your P1/UKOOA survey file...');
 fileInput.click();
 }
 } else {
 // Re-trigger survey planning parameters verification dialog!
 const detected = detectUtmZone(state.rawRows || []);
 askSurveyCriteria(detected, (zone, hemi) => {
 if (state.rawText) {
 const lines = parseCSVWithUtm(state.rawText, zone, hemi);
 if (lines.length > 0) {
 setLines(lines);
 return;
 }
 }
 showLineManager();
 });
 }
 }
}

// ===== GENERATE PREPLOT =====
// ===== PREPLOT POLYGON STATE =====
var _ppgPolygon = null; // [[lat,lon], ...] polygon vertices
var _ppgPreviewLayer = null; // Leaflet layer for polygon preview
var _ppgImportedLines = []; // 2D lines loaded from a polyline shapefile
var _ppgRefLayer = null; // shapefile drawn as a background reference only
var _ppgRefName = null; // file name behind _ppgRefLayer
var _ppgDrawing = false;
var _ppgDrawPoints = [];
var _ppgDrawMarkers = [];
var _ppgDrawPolyline = null;
var _ppgEditNodes = []; // OBN node patch [{id,name,lat,lon}]
var layerObnNodes = null;

/** Build a regular OBN node grid inside the current AOI / centre patch. */
function _ppgComputeObnNodes() {
 const dx = Math.max(10, parseFloat(document.getElementById('ppg-obn-dx')?.value) || 400);
 const dy = Math.max(10, parseFloat(document.getElementById('ppg-obn-dy')?.value) || 400);
 const prefix = document.getElementById('ppg-obn-prefix')?.value || 'N-';
 const startNum = parseInt(document.getElementById('ppg-obn-start')?.value, 10) || 1;
 const mode = document.getElementById('ppg-mode')?.value || 'polygon';
 const nodes = [];

 let south, north, west, east, cLat, cLon;
 if (mode === 'polygon') {
  if (!_ppgPolygon || _ppgPolygon.length < 3) return [];
  const lats = _ppgPolygon.map(p => p[0]);
  const lons = _ppgPolygon.map(p => p[1]);
  south = Math.min(...lats); north = Math.max(...lats);
  west = Math.min(...lons); east = Math.max(...lons);
  cLat = (south + north) / 2;
  cLon = (west + east) / 2;
 } else {
  cLat = parseFloat(document.getElementById('ppg-lat')?.value);
  cLon = parseFloat(document.getElementById('ppg-lon')?.value);
  const length = parseFloat(document.getElementById('ppg-length')?.value) || 10000;
  const count = parseInt(document.getElementById('ppg-count')?.value, 10) || 20;
  const spacing = parseFloat(document.getElementById('ppg-spacing')?.value) || 300;
  if (!isFinite(cLat) || !isFinite(cLon)) return [];
  const halfLen = length / 2;
  const halfW = ((count - 1) * spacing) / 2;
  // Approximate lat/lon box around centre
  const mPerDegLat = 111320;
  const mPerDegLon = 111320 * Math.cos(cLat * Math.PI / 180);
  south = cLat - halfLen / mPerDegLat;
  north = cLat + halfLen / mPerDegLat;
  west = cLon - halfW / mPerDegLon;
  east = cLon + halfW / mPerDegLon;
 }

 const mPerDegLat = 111320;
 const mPerDegLon = Math.max(1e-6, 111320 * Math.cos(cLat * Math.PI / 180));
 const nRows = Math.max(1, Math.floor(((north - south) * mPerDegLat) / dy) + 1);
 const nCols = Math.max(1, Math.floor(((east - west) * mPerDegLon) / dx) + 1);
 // Cap runaway grids
 if (nRows * nCols > 50000) {
  showToast('Node grid too dense - increase node spacing (max 50,000 nodes)', 6000);
  return [];
 }

 let num = startNum;
 for (let r = 0; r < nRows; r++) {
  const lat = south + (r * dy) / mPerDegLat;
  for (let c = 0; c < nCols; c++) {
   const lon = west + (c * dx) / mPerDegLon;
   if (mode === 'polygon' && typeof pointInPolygon === 'function') {
    if (!pointInPolygon([lat, lon], _ppgPolygon)) continue;
   }
   const name = sanitizeLineName(
    prefix + String(num).padStart(Math.max(3, String(startNum + nRows * nCols).length), '0'),
    'N' + String(num).padStart(3, '0')
   );
   nodes.push({ id: nodes.length, name, lat, lon });
   num++;
  }
 }
 return nodes;
}

function _ppgDrawNodesOnLayer(layer, nodes) {
 if (!layer || !nodes || !nodes.length) return;
 nodes.forEach(n => {
  L.circleMarker([n.lat, n.lon], {
   radius: 3, color: '#0ea5e9', weight: 1, fillColor: '#38bdf8', fillOpacity: 0.95
  }).bindTooltip(n.name, { permanent: false, direction: 'top' }).addTo(layer);
 });
}

