 state.settings.environmental = saved.environmental ?? state.settings.environmental;
 state.settings.fisheriesComp = saved.fisheriesComp ?? state.settings.fisheriesComp;
 state.settings.ancilVesselRate = saved.ancilVesselRate ?? state.settings.ancilVesselRate;
 state.settings.ancilVesselCount = saved.ancilVesselCount ?? state.settings.ancilVesselCount;
 state.settings.pmRate = saved.pmRate ?? state.settings.pmRate;
 state.settings.pmMultiplier = saved.pmMultiplier ?? state.settings.pmMultiplier;
 state.settings.pmCount = saved.pmCount ?? state.settings.pmCount;
 state.settings.clientRepRate = saved.clientRepRate ?? state.settings.clientRepRate;
 state.settings.clientRepCount = saved.clientRepCount ?? state.settings.clientRepCount;
 state.settings.mfoRate = saved.mfoRate ?? state.settings.mfoRate;
 state.settings.mfoCount = saved.mfoCount ?? state.settings.mfoCount;
