 state.settings.primeCostMode = saved.primeCostMode || state.settings.primeCostMode || 'dayrate';
 state.settings.infillCostMode = saved.infillCostMode || state.settings.infillCostMode || 'dayrate';
 state.settings.costPerLineKm = saved.costPerLineKm ?? state.settings.costPerLineKm;
 state.settings.costPerSqKm = saved.costPerSqKm ?? state.settings.costPerSqKm;
 // Start point is file-specific; only restore if custom coordinates
 if (saved.startPoint && Array.isArray(saved.startPoint)) {
 state.settings.startPoint = saved.startPoint;
 }
 if (!zone || zone === 31) zone = saved.utmZone || zone;
 if (hemi === 'N' && saved.utmHemi) hemi = saved.utmHemi;
