 const numSwathsEl = document.getElementById('crit-num-swaths');
 numSwathsEl.addEventListener('input', () => { numSwathsEl.dataset.userEdited = '1'; });
 numSwathsEl.addEventListener('change', updateSwathDirectionUI);
 ['input', 'change'].forEach(ev => {
 document.getElementById('crit-swath').addEventListener(ev, _refreshAutoSwathCount);
 document.getElementById('crit-swath-unit').addEventListener(ev, _refreshAutoSwathCount);
 });
