 state.settings.additionalUnplanned = parseFloat(document.getElementById('crit-add-unplanned').value) || 0;
 state.settings.primeCostMode = document.getElementById('crit-prime-cost-mode').value || 'dayrate';
 state.settings.infillCostMode = document.getElementById('crit-infill-cost-mode').value || 'dayrate';
 state.settings.vesselDayRate = parseFloat(document.getElementById('crit-dayrate').value) || 0;
 state.settings.costPerLineKm = parseFloat(document.getElementById('crit-cost-linekm').value) || 0;
 state.settings.costPerSqKm = parseFloat(document.getElementById('crit-cost-sqkm').value) || 0;
 state.settings.costMode = document.getElementById('crit-cost-mode').value || 'dayrate'; // legacy
 state.settings.costPerKm = parseFloat(document.getElementById('crit-cost-perkm').value) || 0; // legacy
 state.settings.chargeableStandby = parseFloat(document.getElementById('crit-standby-rate').value) || 0;
 state.settings.permitting = parseFloat(document.getElementById('crit-permitting').value) || 0;
 state.settings.environmental = parseFloat(document.getElementById('crit-environmental').value) || 0;
 state.settings.fisheriesComp = parseFloat(document.getElementById('crit-fisheries').value) || 0;
 state.settings.ancilVesselRate = parseFloat(document.getElementById('crit-ancil-vessel-rate').value) || 0;
