 state.settings.ancilVesselCount3 = parseInt(document.getElementById('crit-ancil-vessel-count-3').value) || 0;
 state.settings.pmRate = parseFloat(document.getElementById('crit-pm-rate').value) || 0;
 state.settings.pmMultiplier = parseFloat(document.getElementById('crit-pm-mult').value) || 1;
 state.settings.pmCount = parseInt(document.getElementById('crit-pm-count').value) || 0;
 state.settings.clientRepRate = parseFloat(document.getElementById('crit-rep-rate').value) || 0;
 state.settings.clientRepCount = parseInt(document.getElementById('crit-rep-count').value) || 0;
 state.settings.mfoRate = parseFloat(document.getElementById('crit-mfo-rate').value) || 0;
