 state.settings.ancilEquipFixed = parseFloat(document.getElementById('crit-equip-fixed').value) || 0;
 state.settings.preSurveyScout = parseFloat(document.getElementById('crit-scout').value) || 0;
 state.settings.bathySurvey = parseFloat(document.getElementById('crit-bathy').value) || 0;
 state.settings.ud1Name = document.getElementById('crit-ud1-name').value || '';
 state.settings.ud1Rate = parseFloat(document.getElementById('crit-ud1-rate').value) || 0;
 state.settings.ud1Fixed = parseFloat(document.getElementById('crit-ud1-fixed').value) || 0;
 state.settings.ud2Name = document.getElementById('crit-ud2-name').value || '';
 state.settings.ud2Rate = parseFloat(document.getElementById('crit-ud2-rate').value) || 0;
 state.settings.ud2Fixed = parseFloat(document.getElementById('crit-ud2-fixed').value) || 0;
 state.settings.ud3Name = document.getElementById('crit-ud3-name').value || '';
 state.settings.ud3Rate = parseFloat(document.getElementById('crit-ud3-rate').value) || 0;
 state.settings.ud3Fixed = parseFloat(document.getElementById('crit-ud3-fixed').value) || 0;
 state.settings.mobDemob = parseFloat(document.getElementById('crit-dayrate').value) || 0; // legacy

 // (Config save/load handled by dedicated buttons)

