 // (input-start-time is synced by _applyCriteriaStartSettings above)

 // Update Tier 2 Toolbar labels
 document.getElementById('val-turn-radius').textContent = (r / 1000).toFixed(1) + 'km';
 document.getElementById('val-speed').textContent = s + '/' + ts + 'kn';
 document.getElementById('val-run-inout').textContent = ri + '/' + ro + 'm';

 dlg.style.display = 'none';
 callback(z, h);
