// ===== FORMAT DETECTION =====
function detectFormat(rows) {
 for (const row of rows) {
 const t = row.trim();
 if (t.startsWith('H') && t.length > 10) return 'p190';
 if (/^\d{4}\s/.test(t) && t.length >= 48) return 'p190';
 if (/^[SVGTR]\s*[A-Z0-9_\-]{1,20}/i.test(t) && t.length >= 30) return 'p190';
 if (/^[A-Z0-9_\-]{1,15}\s+\d+\s+\d/.test(t) && t.length >= 30) return 'p190';
 }
 for (const row of rows) {
 if (row.includes(',') || row.includes('\t') || row.includes(';')) return 'csv';
 }
 // Whitespace-delimited numeric tables are common P1 exports
 let numericish = 0;
 for (const row of rows.slice(0, 40)) {
 const parts = row.trim().split(/\s+/);
 if (parts.length >= 4 && parts.filter(p => /^-?\d+(\.\d+)?$/.test(p)).length >= 2) numericish++;
 }
 if (numericish >= 3) return 'csv';
 return 'unknown';
}

// ===== GEOGRAPHIC COORDINATE PARSERS & UTM CONVERSION =====

function parseP190Angle(str, isLongitude) {
 // Format: DDMMSS.SSh or DDDMMSS.SSh where h is N/S/E/W
 const len = str.length;
 if (len < 5) return null;
 const hemi = str.charAt(len - 1).toUpperCase();
 if (!['N', 'S', 'E', 'W'].includes(hemi)) return null;

 const numPart = str.substring(0, len - 1).trim();
 const floatVal = parseFloat(numPart);
 if (isNaN(floatVal)) return null;

 const dotIdx = numPart.indexOf('.');
 let secondsStr, minAndDegStr;
 if (dotIdx >= 0) {
 secondsStr = numPart.substring(dotIdx - 2);
 minAndDegStr = numPart.substring(0, dotIdx - 2);
 } else {
 secondsStr = numPart.substring(numPart.length - 2);
 minAndDegStr = numPart.substring(0, numPart.length - 2);
 }

 const seconds = parseFloat(secondsStr);
 const minutes = parseFloat(minAndDegStr.substring(minAndDegStr.length - 2));
 const degrees = parseFloat(minAndDegStr.substring(0, minAndDegStr.length - 2) || '0');

 if (isNaN(seconds) || isNaN(minutes) || isNaN(degrees)) return null;

 let decimal = degrees + (minutes / 60) + (seconds / 3600);
 if (hemi === 'S' || hemi === 'W') decimal = -decimal;
 return decimal;
}

function getUTMZoneFromLatLon(lat, lon) {
 let zone = Math.floor((lon + 180) / 6) + 1;
 if (zone < 1) zone = 1;
 if (zone > 60) zone = 60;

 // Handle special zones (Norway / Svalbard)
 if (lat >= 56.0 && lat < 64.0 && lon >= 3.0 && lon < 12.0) {
 zone = 32;
 }
 if (lat >= 72.0 && lat < 84.0) {
 if (lon >= 0.0 && lon < 9.0) zone = 31;
 else if (lon >= 9.0 && lon < 21.0) zone = 33;
 else if (lon >= 21.0 && lon < 33.0) zone = 35;
 else if (lon >= 33.0 && lon < 42.0) zone = 37;
 }

 const hemi = lat >= 0 ? 'N' : 'S';
 return { zone, hemi };
}

// ===== UTM ZONE DETECTION =====
// Returns { zone, hemi, confident }
// confident=true ' both zone and hemisphere read from file headers or calculated from Lat/Lon
// confident=false ' at least one value was guessed / defaulted
function detectUtmZone(rows) {
 let zone = 0, hemi = null;

 // 1. PRIORITY: Header Scanner for explicit "UTM" or "ZONE" keywords
 // Headers are authoritative - they declare the intended projection zone
 for (const row of rows) {
 if (row.toUpperCase().startsWith('H')) {
 const upper = row.toUpperCase();

 // EPSG UTM: 326zz = northern, 327zz = southern (Mentawai H1900 "32747")
 let epsg = upper.match(/\b(326|327)(\d{2})\b/);
 if (epsg) {
 const z = parseInt(epsg[2], 10);
 if (z >= 1 && z <= 60) {
 return { zone: z, hemi: epsg[1] === '327' ? 'S' : 'N', confident: true };
 }
 }

 // WGS84_UTM47S / UTM_Zone_47S
 let named = upper.match(/UTM[_\s-]*ZONE[_\s-]*(\d{1,2})\s*([NS])/);
 if (named) {
 return { zone: parseInt(named[1], 10), hemi: named[2], confident: true };
 }
 named = upper.match(/WGS84_UTM\s*(\d{1,2})\s*([NS])/);
 if (named) {
 return { zone: parseInt(named[1], 10), hemi: named[2], confident: true };
 }
 
 // Match UTM/ZONE then a zone number (1-60) or full EPSG (326zz/327zz)
 let m = upper.match(/(?:UTM|ZONE)[^0-9]*?(\d{1,5})\s*([NS]?)/);
 if (m) {
 let z = parseInt(m[1], 10);
 let h = m[2] ? m[2].toUpperCase() : null;
 if (z >= 32601 && z <= 32660) { z -= 32600; h = 'N'; }
 else if (z >= 32701 && z <= 32760) { z -= 32700; h = 'S'; }
 // "51 NORTHERN HEMISPHERE" / "52 SOUTHERN HEMISPHERE"
 if (!h || (h !== 'N' && h !== 'S')) {
 if (upper.includes('SOUTH')) h = 'S';
 else if (upper.includes('NORTH')) h = 'N';
 }
 if (!h) {
 h = (upper.includes('SOUTH') || /\bS\b/.test(upper.replace(/WGS.?84/g, ''))) ? 'S' : 'N';
 }
 if (z >= 1 && z <= 60) return { zone: z, hemi: h, confident: true };
 }
 }
 }

 // 2. Fallback: Geographic Coordinate Regex Scanner (infer zone from lat/lon in data)
 for (const row of rows) {
 if (row.length >= 40) {
 const first = row.charAt(0);
 // Do not skip C/R when they carry coordinates (line names like C01).
 if (first === 'H' || first === '#') continue;
 if ((first === 'C' || first === 'R') && !/[NS].*[EW]/i.test(row)) continue;
 
 const block = row.substring(10, Math.min(row.length, 80));
 const m = block.match(/(\d{6}\.?\d*[NS])\s*(\d{7}\.?\d*[EW])/i);
 if (m) {
 const lat = parseP190Angle(m[1], false);
 const lon = parseP190Angle(m[2], true);
 if (lat !== null && lon !== null && Math.abs(lat) <= 90 && Math.abs(lon) <= 180) {
 const calculated = getUTMZoneFromLatLon(lat, lon);
 return { zone: calculated.zone, hemi: calculated.hemi, confident: true };
 }
 }
 // Spaced / semi-glued DMS used by freestyle outline preplots (SK309 style)
 const spaced = (typeof extractP190SpacedDms === 'function')
  ? extractP190SpacedDms(row)
  : null;
 if (spaced && Math.abs(spaced.lat) <= 90 && Math.abs(spaced.lon) <= 180) {
  const calculated = getUTMZoneFromLatLon(spaced.lat, spaced.lon);
  return { zone: calculated.zone, hemi: calculated.hemi, confident: true };
 }
 }
 }

 // 3. Strict match fallbacks for header lines
 for (const row of rows) {
 const upper = row.toUpperCase();

 // "UTM zone 49S" or "UTM zone 49 S"
 let m = row.match(/UTM\s+zone\s+(\d+)\s*([NS]?)/i);
 if (m) { 
 zone = parseInt(m[1]); 
 hemi = m[2] ? m[2].toUpperCase() : 'N'; 
 return { zone, hemi, confident: true }; 
 }

 // "UTM-50S" / "UTM50S" (Veritas Chandon header style)
 m = row.match(/\bUTM\s*[- ]?\s*(\d{1,2})\s*([NS])\b/i);
 if (m) {
 zone = parseInt(m[1]);
 hemi = m[2].toUpperCase();
 return { zone, hemi, confident: true };
 }

 // "UTM,54,S" or "UTM 54S" or "UTM 54 S"
 m = row.match(/UTM[,\s]+(\d{1,2})[,\s]*([NS]?)\b/i);
 if (m) { 
 zone = parseInt(m[1]); 
 hemi = m[2] ? m[2].toUpperCase() : 'N'; 
 return { zone, hemi, confident: true }; 
 }

 // "PROJECTION ZONE 49 S" or "PROJECTION ZONE 49S"
 m = row.match(/PROJECTION\s+ZONE\s+(\d+)\s*([NS]?)/i);
 if (m && m[1]) {
 zone = parseInt(m[1]);
 hemi = m[2] ? m[2].toUpperCase() : 'N';
 return { zone, hemi, confident: true };
 }

 // "002 UTM 49S" or any "UTMnnnN/S" pattern in a header line
 if (upper.startsWith('H')) {
 m = row.match(/\bUTM\s*(\d{1,2})\s*([NS])\b/i);
 if (m) { zone = parseInt(m[1]); hemi = m[2].toUpperCase(); return { zone, hemi, confident: true }; }

 // Last-resort: bare "49S" or "49 S" on a header line
 m = row.match(/\b(\d{1,2})\s*([NS])\b/i);
 if (m) {
 const z = parseInt(m[1]);
 if (z >= 1 && z <= 60) { 
 zone = zone || z; 
 hemi = hemi || m[2].toUpperCase(); 
 return { zone, hemi: hemi || 'N', confident: true }; 
 }
 }
 }
 }

 // "" Auto-infer hemisphere from northing magnitudes
 // If headers didn't give us the hemisphere, examine the data northings.
 // Southern hemisphere northings have a 10,000,000 m false northing added,
 // so typical Australian/Antarctic survey data has northings of 5.5-9.5 M.
 // Converting such a value as N gives latitudes of ~50-85 degN - too far
 // north for most offshore surveys. If N-lat > 55 deg AND northing > 5.5M,
 // flip to S. This correctly handles zone 54 data in NW Australia.
 if (!hemi) {
 const sampleNorthing = extractSampleNorthing(rows);
 if (sampleNorthing !== null && sampleNorthing > 5500000) {
 const nLat = quickUtmLatEstimate(sampleNorthing, 'N');
 const sLat = quickUtmLatEstimate(sampleNorthing, 'S');
 // Prefer S if N gives implausibly high latitude for an offshore survey
 hemi = (nLat > 55 && sLat > -75 && sLat < 0) ? 'S' : 'N';
 }
 }

 const confident = zone > 0 && hemi !== null;
 return { zone: zone || 54, hemi: hemi || 'N', confident };
}

// Grab the first plausible 7-digit northing value from data rows
function extractSampleNorthing(rows) {
 for (const row of rows) {
 if (!row || row.charAt(0) === 'H' || row.charAt(0) === '#') continue;
 const m = row.match(/\b(\d{7}(?:\.\d+)?)\b/);
 if (m) {
 const v = parseFloat(m[1]);
 if (v > 0) return v;
 }
 }
 return null;
}

// Extract line names from P190 rows without coordinate conversion (for dialog dropdown)
function extractLineNames(rows) {
 const names = new Set();
 for (const row of rows) {
 if (row.length < 20) continue;
 const first = row.charAt(0);
 const upper = first.toUpperCase();
 const hasCoordCue = /[NS].*[EW]/i.test(row) || /\d{5,7}\.\d/.test(row);
 if (upper === 'H' || first === '#' || upper === 'E' || first === '') continue;
 if ((upper === 'C' || upper === 'R') && !hasCoordCue) continue;
 let lineName = '';
 const recordType = row.substring(0, 4).trim();
 if (/^\d{4}$/.test(recordType)) {
 lineName = row.substring(4, 12).trim();
 } else if (isUkuaaTypePrefixRow(row) && row.length >= 40) {
 lineName = row.substring(1, 13).trim();
 } else if (row.length >= 30) {
 // Includes vendors that put the line name in col 1 (e.g. C01, SK309-A)
 lineName = row.trim().match(/^(\S+)/)?.[1] || row.substring(0, 16).trim().split(/\s+/)[0] || row.substring(0, 10).trim();
 }
 if (lineName) names.add(sanitizeLineName(lineName, ''));
 }
 return Array.from(names).filter(Boolean).map((name, idx) => ({
 id: idx, name, start: [0, 0], end: [0, 0]
 }));
}

// Fast approximate UTM northing ' latitude (good to ~+/-5 deg)
function quickUtmLatEstimate(northing, hemi) {
 const y = hemi === 'S' ? northing - 10000000 : northing;
 return (y / 6378137) * (180 / Math.PI);
}

/**
 * True when the leading S/V/G/T/Z is a UKOOA record type, not part of a line
 * name such as SK309-A or SOLAR-01. Type rows have space after the code, or a
 * numeric/padded field; free-format names continue with a letter (SK..., MT...).
 */
function isUkuaaTypePrefixRow(row) {
 const u = (row.charAt(0) || '').toUpperCase();
 if (!'SVGTZ'.includes(u)) return false;
 const c1 = row.charAt(1);
 if (c1 === ' ' || c1 === '\t' || c1 === '') return true;
 // Second character is a letter => free-format line name (SK309-A, SOLAR-1)
 if (/[A-Za-z]/.test(c1)) return false;
 // Digit / punctuation after type code: classic fixed-width type row
 return true;
}

/** Parse spaced / semi-glued DMS geo after SP, e.g.:
 *  "3 8 0.00N113 0 0.00E"
 *  "320 0.00N113 0 0.00E"   (3 20 0.00)
 *  "4 0 0.00N11310 0.00E"  (113 10 0.00)
 *  "410 0.00N11353 0.00E"  (4 10 / 113 53)
 */
function extractP190SpacedDms(row) {
 // Fully spaced D M S.s N/S DDD M S.s E/W (lon may be glued onto the N)
 let m = row.match(
  /(\d{1,2})\s+(\d{1,2})\s+(\d{1,2}(?:\.\d+)?)\s*([NS])\s*(\d{1,3})\s+(\d{1,2})\s+(\d{1,2}(?:\.\d+)?)\s*([EW])/i
 );
 if (m) {
  const lat = dmsPartsToDec(m[1], m[2], m[3], m[4]);
  const lon = dmsPartsToDec(m[5], m[6], m[7], m[8]);
  if (lat != null && lon != null) return { lat, lon };
 }
 // Lat DMM packed + sec, lon fully spaced: "320 0.00N113 0 0.00E"
 m = row.match(
  /(\d{3,5})\s+(\d{1,2}(?:\.\d+)?)\s*([NS])\s*(\d{1,3})\s+(\d{1,2})\s+(\d{1,2}(?:\.\d+)?)\s*([EW])/i
 );
 if (m) {
  const lat = dmsPackedToDec(m[1], m[2], m[3]);
  const lon = dmsPartsToDec(m[4], m[5], m[6], m[7]);
  if (lat != null && lon != null) return { lat, lon };
 }
 // Both sides DMM-packed: "320 0.00N11230 0.00E"
 m = row.match(
  /(\d{3,5})\s+(\d{1,2}(?:\.\d+)?)\s*([NS])\s*(\d{3,5})\s+(\d{1,2}(?:\.\d+)?)\s*([EW])/i
 );
 if (m) {
  const lat = dmsPackedToDec(m[1], m[2], m[3]);
  const lon = dmsPackedToDec(m[4], m[5], m[6]);
  if (lat != null && lon != null) return { lat, lon };
 }
 // Deg + min + sec with packed lon: "4 0 0.00N11310 0.00E"
 m = row.match(
  /(\d{1,2})\s+(\d{1,2})\s+(\d{1,2}(?:\.\d+)?)\s*([NS])\s*(\d{3,5})\s+(\d{1,2}(?:\.\d+)?)\s*([EW])/i
 );
 if (m) {
  const lat = dmsPartsToDec(m[1], m[2], m[3], m[4]);
  const lon = dmsPackedToDec(m[5], m[6], m[7]);
  if (lat != null && lon != null) return { lat, lon };
 }
 return null;
}

/** Degrees + optional min/sec hemi -> decimal degrees. */
function dmsPartsToDec(d, min, sec, hemi) {
 const deg = parseFloat(d);
 const mi = min != null && min !== '' ? parseFloat(min) : 0;
 const se = sec != null && sec !== '' ? parseFloat(sec) : 0;
 if (![deg, mi, se].every(isFinite)) return null;
 // Guard against lat degrees > 90 when packed as DMM without separators
 if (String(hemi).toUpperCase() === 'N' || String(hemi).toUpperCase() === 'S') {
  if (deg > 90 && min === undefined) return dmsPackedToDec(d, sec != null ? String(se) : '0', hemi);
 }
 let dec = deg + mi / 60 + se / 3600;
 const h = String(hemi).toUpperCase();
 if (h === 'S' || h === 'W') dec = -dec;
 if ((h === 'N' || h === 'S') && Math.abs(dec) > 90) return null;
 if ((h === 'E' || h === 'W') && Math.abs(dec) > 180) return null;
 return dec;
}

/** "320" + "0.00" + N => 3 deg 20 min 0 sec; "11230" + "0.00" + E => 112 deg 30 min. */
function dmsPackedToDec(packed, secPart, hemi) {
 const s = String(packed).replace(/\D/g, '');
 const sec = parseFloat(secPart);
 if (!s.length || !isFinite(sec)) return null;
 let deg, min;
 if (s.length <= 2) { deg = parseInt(s, 10); min = 0; }
 else if (s.length === 3) { deg = parseInt(s.slice(0, 1), 10); min = parseInt(s.slice(1), 10); }
 else if (s.length === 4) { deg = parseInt(s.slice(0, 2), 10); min = parseInt(s.slice(2), 10); }
 else { deg = parseInt(s.slice(0, s.length - 2), 10); min = parseInt(s.slice(-2), 10); }
 if (![deg, min, sec].every(isFinite) || min >= 60) return null;
 let dec = deg + min / 60 + sec / 3600;
 const h = String(hemi).toUpperCase();
 if (h === 'S' || h === 'W') dec = -dec;
 if ((h === 'N' || h === 'S') && Math.abs(dec) > 90) return null;
 if ((h === 'E' || h === 'W') && Math.abs(dec) > 180) return null;
 return dec;
}

// ===== P190 FIXED-WIDTH PARSER =====
/** Extract projected E/N from the tail of a UKOOA-style P1 row (many vendor flavours). */
function extractP190GridCoords(row) {
 // Grid usually follows lon hemisphere E/W. Tail may also hold depth / IDs
 // (Veritas Chandon: "192345.57819449.5 0.0 0102829").
 let grid = null;
 const m = row.match(/[NS][\d .]*[EW]\s*([+\-\d. ]+)/i);
 if (m) grid = m[1].trim();
 if (!grid) {
 const m2 = row.match(/[EW]\s*([+\-\d. ]{6,})/i);
 if (m2) grid = m2[1].trim();
 }
 if (!grid) {
 const m3 = row.match(/(-?\d+\.\d+)\s+(-?\d+\.\d+)/);
 if (m3) return { easting: parseFloat(m3[1]), northing: parseFloat(m3[2]) };
 return null;
 }
 // Spaced: "722235.4 346517.2" (ignore trailing depth/id tokens)
 let p = grid.match(/^([+\-]?\d+\.?\d*)\s+([+\-]?\d+\.?\d*)/);
 if (p) {
 const e = parseFloat(p[1]), n = parseFloat(p[2]);
 // Reject "192345.57819449.5 0.0" false spaced split (first token has 2 dots)
 if (isFinite(e) && isFinite(n) && !/^\d+\.\d+\.\d+/.test(grid)) {
 return { easting: e, northing: n };
 }
 }
 // Glued with sign: "162057.4-127878.8" (Soma local grid)
 p = grid.match(/^([+\-]?\d+\.\d+)([+\-]\d+\.\d+)/);
 if (p) return { easting: parseFloat(p[1]), northing: parseFloat(p[2]) };
 // Classic UKOOA glue: 6.1 easting + 7.1 northing -> "511275.03770148.0" / "192345.57819449.5"
 p = grid.match(/^(\d{5,7}\.\d)(\d{6,8}\.\d)/);
 if (p) return { easting: parseFloat(p[1]), northing: parseFloat(p[2]) };
 // Slightly looser glue
 p = grid.match(/^(\d{5,7}\.\d+)(\d{6,8}\.\d+)/);
 if (p) {
 const e = parseFloat(p[1]), n = parseFloat(p[2]);
 if (isFinite(e) && isFinite(n)) return { easting: e, northing: n };
 }
 return null;
}

/**
 * Shotpoint often sits immediately before lat DMS:
 * KNOC/Chandon glued: "1001340419.27N" / "2135194147.30S"
 * Mentawai spaced: "1001 33934.35S" / "1001 4 221.96S"
 */
function extractP190Shotpoint(row) {
 // Glued SP + 6-digit lat DDMMSS.ss
 const glued = row.match(/(\d{3,6})(\d{6}\.\d+)([NS])/i);
 if (glued) {
 const sp = parseInt(glued[1], 10);
 if (isFinite(sp) && sp > 0) return sp;
 }
 // Spaced SP before a lat token that ends in N/S (compact or messy spaced DMS)
 const spaced = row.match(/\b(\d{3,5})\s+(\d{1,3}(?:\s+\d{1,2}){0,2}\s*\d*\.?\d*\s*[NS])/i);
 if (spaced) {
 const sp = parseInt(spaced[1], 10);
 if (isFinite(sp) && sp > 0) return sp;
 }
 return null;
}

/** Parse lat/lon from DDMMSS.ssN / DDDMMSS.ssE fragments embedded in a P1 row. */
function extractP190Geographic(row) {
 const compact = row.match(/(\d{4,7}\.\d+)([NS])\s*(\d{5,8}\.\d+)([EW])/i);
 if (compact) {
 const lat = parseP190DmsNumber(compact[1], compact[2]);
 const lon = parseP190DmsNumber(compact[3], compact[4]);
 if (lat != null && lon != null) return { lat, lon };
 }
 const spaced = row.match(/(\d{1,2})\s+(\d{1,2})\s+(\d+\.\d+)([NS])\s*(\d{1,3})\s+(\d{1,2})\s+(\d+\.\d+)([EW])/i);
 if (spaced) {
 const lat = (parseInt(spaced[1], 10) + parseInt(spaced[2], 10) / 60 + parseFloat(spaced[3]) / 3600)
 * (spaced[4].toUpperCase() === 'S' ? -1 : 1);
 const lon = (parseInt(spaced[5], 10) + parseInt(spaced[6], 10) / 60 + parseFloat(spaced[7]) / 3600)
 * (spaced[8].toUpperCase() === 'W' ? -1 : 1);
 if (isFinite(lat) && isFinite(lon)) return { lat, lon };
 }
 return extractP190SpacedDms(row);
}

function parseP190DmsNumber(numStr, hemi) {
 const s = String(numStr);
 const dot = s.indexOf('.');
 const whole = dot >= 0 ? s.slice(0, dot) : s;
 const frac = dot >= 0 ? s.slice(dot) : '';
 let deg, min, sec;
 if (whole.length >= 7) {
 deg = parseInt(whole.slice(0, whole.length - 4), 10);
 min = parseInt(whole.slice(-4, -2), 10);
 sec = parseFloat(whole.slice(-2) + frac);
 } else if (whole.length >= 5) {
 deg = parseInt(whole.slice(0, whole.length - 4), 10);
 min = parseInt(whole.slice(-4, -2), 10);
 sec = parseFloat(whole.slice(-2) + frac);
 } else return null;
 if (![deg, min, sec].every(isFinite)) return null;
 let dec = deg + min / 60 + sec / 3600;
 const h = String(hemi).toUpperCase();
 if (h === 'S' || h === 'W') dec = -dec;
 return dec;
}

function parseP190FixedWidth(rows, zone, hemi) {
 const lineMap = new Map();
 const spCounters = {};
 const geoHints = new Map();
 let sawVessel = false;

 for (const row of rows) {
 if (row.length < 20) continue;
 const first = row.charAt(0);
 const upper = first.toUpperCase();

 const hasGeo = /[NS].*[EW]/i.test(row);
 const hasCoordCue = hasGeo || /\d{5,7}\.\d/.test(row);
 if (upper === 'H' || first === '#' || upper === 'E') continue;
 // NTP C01 lines carry full geo; 3D receiver packs (R0001 E/N depth...) do not - skip those.
 if (upper === 'R' && !hasGeo) continue;
 if (upper === 'C' && !hasCoordCue) continue;

 let lineName = '', sp = null, easting = null, northing = null;
 const rec = upper;

 const recordType = row.substring(0, 4).trim();
 if (/^\d{4}$/.test(recordType)) {
 lineName = row.substring(4, 12).trim();
 const spV = parseFloat(row.substring(12, 20));
 if (isFinite(spV)) sp = spV;
 } else if (isUkuaaTypePrefixRow(row) && row.length >= 40) {
 // Prefer non-space line token (Mentawai: MTW16-1001) over fixed 12-col slice
 const token = row.slice(1).match(/^(\S+)/);
 lineName = token ? token[1] : row.substring(1, 13).trim();
 const spV = parseFloat(row.substring(13, 21));
 if (isFinite(spV)) sp = spV;
 if (upper === 'V') sawVessel = true;
 } else if (row.length >= 30) {
 // Free-format: "SK309-A                 1 3 8 0.00N ... E 722235.4 346517.2"
 lineName = row.trim().match(/^(\S+)/)?.[1]
  || row.substring(0, 16).trim().split(/\s+/)[0]
  || row.substring(0, 10).trim();
 // SP = first integer token after the line name
 const afterName = row.trim().slice(lineName.length).trim();
 const spTok = afterName.match(/^(\d{1,6})(?:\s|$)/);
 if (spTok) sp = parseInt(spTok[1], 10);
 if (!isFinite(sp)) {
  const spV = parseFloat(row.substring(16, 25));
  if (isFinite(spV)) sp = spV;
 }
 }

 // Prefer SP glued to lat DMS (overrides vessel-id false positives like Chandon "11")
 const spGlued = extractP190Shotpoint(row);
 if (spGlued != null) sp = spGlued;

 const grid = extractP190GridCoords(row);
 if (grid) {
 easting = grid.easting;
 northing = grid.northing;
 }

 const geo = extractP190Geographic(row) || extractP190SpacedDms(row);
 const gridLooksBad = grid && (
 !isFinite(grid.easting) || !isFinite(grid.northing) ||
 (Math.abs(grid.northing) < 1000 && Math.abs(grid.easting) < 1000) ||
 grid.northing < 0 ||
 grid.easting < 0 ||
 grid.easting > 1000000
 );

 // English-only name keys (binary P1 often has null pads / high bytes)
 lineName = sanitizeLineName(lineName, '');
 if (!lineName) continue;

 if ((!grid || gridLooksBad) && geo) {
 easting = geo.lon;
 northing = geo.lat;
 geoHints.set(lineName, true);
 }

 if (easting === null || northing === null) continue;
 if (easting === 0 && northing === 0) continue;

 if (!spCounters[lineName]) spCounters[lineName] = 0;
 spCounters[lineName]++;
 const spVal = (sp && sp > 0) ? sp : spCounters[lineName];

 if (!lineMap.has(lineName)) lineMap.set(lineName, []);
 lineMap.get(lineName).push({ sp: spVal, x: easting, y: northing, rec });
 }

 if (lineMap.size === 0) return [];

 // 3D postplot: V/S/T/Z share the sail-line name - keep vessel (V) track when present.
 // CMP (C...) stays as its own line name. Receiver packs already skipped.
 if (sawVessel) {
 for (const [name, pts] of lineMap) {
 const vessel = pts.filter(p =>p.rec === 'V');
 if (vessel.length >= 2) lineMap.set(name, vessel);
 else if (vessel.length === 1 && pts.length > 1) {
 // Single V + many auxiliaries: still prefer V endpoints only if we can
 const aux = pts.filter(p =>p.rec === 'V' || p.rec === 'C');
 if (aux.length >= 1) lineMap.set(name, vessel.length ? vessel : aux);
 } else {
 // No V on this name (e.g. C838P1001) - drop S/T/Z/G clutter if mixed
 const cleaned = pts.filter(p => !'STZG'.includes(p.rec));
 if (cleaned.length >= 2) lineMap.set(name, cleaned);
 }
 }
 }

 const samplePts = lineMap.values().next().value;
 // Prefer a UTM-looking sample when the file mixes local/negative grids (geo fallback)
 // with normal UTM rows - e.g. Soma 2D Ver4.
 let sampleX = samplePts[0].x, sampleY = samplePts[0].y;
 outerSample:
 for (const [name, pts] of lineMap) {
 if (geoHints.has(name)) continue;
 for (const p of pts) {
 if (p.x >= 100000 && p.x <= 900000 && p.y >= 0 && p.y <= 10000000) {
 sampleX = p.x; sampleY = p.y;
 break outerSample;
 }
 }
 }
 // Only treat the whole file as geographic when sample coords themselves look like lon/lat.
 // Per-line geoHints still override for rows that used DMS fallback (negative local grids).
 const isGeographic = (Math.abs(sampleX) <= 180 && Math.abs(sampleY) <= 90);
 const isDDMMSS = (!isGeographic && sampleX > 100000 && sampleX < 1800000 && sampleY > 100000 && sampleY < 900000);
 const isUTM = (!isGeographic && sampleX >= 100000 && sampleX <= 900000 && sampleY >= 0 && sampleY <= 10000000 && !isDDMMSS);

 const lines = [];
 let idx = 0;
 let detectedSpInterval = 0;

 // Helper: UTM/geo point record -> [lat,lon]
 const ptToLatLon = (p, name) => {
  const useGeo = geoHints.has(name) || (isGeographic && Math.abs(p.y) <= 90 && Math.abs(p.x) <= 180);
  let start;
  if (useGeo) {
   if (Math.abs(p.y) <= 90 && Math.abs(p.x) <= 180) start = [p.y, p.x];
   else start = [p.x, p.y];
  } else if (isDDMMSS) {
   const parseDMS = (v, isLon) => {
    const s = v.toString();
    let deg, min, sec;
    if (isLon) { deg = parseInt(s.substring(0, 3)); min = parseInt(s.substring(3, 5)); sec = parseFloat(s.substring(5)); }
    else { deg = parseInt(s.substring(0, 2)); min = parseInt(s.substring(2, 4)); sec = parseFloat(s.substring(4)); }
    return deg + min / 60 + sec / 3600;
   };
   start = [parseDMS(p.y, false), parseDMS(p.x, true)];
  } else {
   start = utmToLatLon(p.x, p.y, zone, hemi);
  }
  if (!Array.isArray(start)) start = [start.lat, start.lon];
  return start;
 };

 // Outline / polygon vertices: one shot per named corner (e.g. SK309-A..Q).
 // Join consecutive vertices into survey segments in file order instead of
 // emitting zero-length "lines".
 const ordered = [];
 for (const [name, pts] of lineMap) {
  pts.sort((a, b) => a.sp - b.sp);
  ordered.push({ name, pts });
 }
 const allSingle = ordered.length >= 2 && ordered.every(o => o.pts.length === 1);
 if (allSingle) {
  for (let i = 0; i < ordered.length - 1; i++) {
   const a = ordered[i], b = ordered[i + 1];
   const start = ptToLatLon(a.pts[0], a.name);
   const end = ptToLatLon(b.pts[0], b.name);
   if (![start[0], start[1], end[0], end[1]].every(isFinite)) continue;
   if (Math.abs(start[0]) > 90 || Math.abs(end[0]) > 90) continue;
   if (Math.abs(start[1]) > 180 || Math.abs(end[1]) > 180) continue;
   lines.push({
    id: idx++,
    name: sanitizeLineName(a.name, 'L' + (idx)),
    start, end,
    spStart: a.pts[0].sp,
    spEnd: b.pts[0].sp,
    spCount: 2
   });
  }
  return lines;
 }

 for (const { name, pts } of ordered) {
 const first = pts[0], last = pts[pts.length - 1];
 let start = ptToLatLon(first, name);
 let end = ptToLatLon(last, name);
 if (![start[0], start[1], end[0], end[1]].every(isFinite)) continue;
 if (Math.abs(start[0]) > 90 || Math.abs(end[0]) > 90) continue;
 if (Math.abs(start[1]) > 180 || Math.abs(end[1]) > 180) continue;

 lines.push({ id: idx++, name: sanitizeLineName(name, 'L' + idx), start, end, spStart: first.sp, spEnd: last.sp, spCount: new Set(pts.map(p =>p.sp)).size });

 if (detectedSpInterval === 0 && pts.length >= 3) {
 const spRange = last.sp - first.sp;
 if (spRange > 0) {
 const dx = last.x - first.x;
 const dy = last.y - first.y;
 const distM = isUTM ? Math.sqrt(dx * dx + dy * dy) : (typeof haversine === 'function' ? haversine(start, end) : 0);
 detectedSpInterval = distM / spRange;
 }
 }
 }

 if (detectedSpInterval > 0) {
 console.log('[P1] Detected SP record interval:', Math.round(detectedSpInterval * 100) / 100, 'm');
 }
 return lines;
}

// ===== UTM ' LAT/LON CONVERSION =====
function utmToLatLon(easting, northing, zone, hemisphere) {
 // WGS84 ellipsoid parameters
 const a = 6378137.0;
 const f = 1 / 298.257223563;
 const b = a * (1 - f);
 const e2 = (a * a - b * b) / (a * a);
 const e1sq = e2 / (1 - e2);
 const k0 = 0.9996;

 const x = easting - 500000;
 const y = hemisphere === 'S' ? northing - 10000000 : northing;
 const lon0 = ((zone - 1) * 6 - 180 + 3) * Math.PI / 180;

 const M = y / k0;
 const mu = M / (a * (1 - e2/4 - 3*e2*e2/64 - 5*e2*e2*e2/256));

 const e1 = (1 - Math.sqrt(1 - e2)) / (1 + Math.sqrt(1 - e2));
 const phi1 = mu
 + (3*e1/2 - 27*e1*e1*e1/32) * Math.sin(2*mu)
 + (21*e1*e1/16 - 55*e1*e1*e1*e1/32) * Math.sin(4*mu)
 + (151*e1*e1*e1/96) * Math.sin(6*mu)
 + (1097*e1*e1*e1*e1/512) * Math.sin(8*mu);

 const N1 = a / Math.sqrt(1 - e2*Math.sin(phi1)*Math.sin(phi1));
 const T1 = Math.tan(phi1)*Math.tan(phi1);
 const C1 = e1sq * Math.cos(phi1)*Math.cos(phi1);
 const R1 = a*(1-e2) / Math.pow(1 - e2*Math.sin(phi1)*Math.sin(phi1), 1.5);
 const D = x / (N1*k0);

 let lat = phi1 - (N1*Math.tan(phi1)/R1) * (
 D*D/2 - (5 + 3*T1 + 10*C1 - 4*C1*C1 - 9*e1sq)*D*D*D*D/24 +
 (61 + 90*T1 + 298*C1 + 45*T1*T1 - 252*e1sq - 3*C1*C1)*D*D*D*D*D*D/720
 );
 let lon = lon0 + (
 D - (1 + 2*T1 + C1)*D*D*D/6 +
 (5 - 2*C1 + 28*T1 - 3*C1*C1 + 8*e1sq + 24*T1*T1)*D*D*D*D*D/120
 ) / Math.cos(phi1);

 return [lat * 180 / Math.PI, lon * 180 / Math.PI];
}

function latLonToUtm(lat, lon, forceZone) {
 // Convert WGS84 lat/lon to UTM easting/northing
 const a = 6378137.0;
 const f = 1 / 298.257223563;
 const e2 = 2 * f - f * f;
 const e4 = e2 * e2;
 const e6 = e4 * e2;
 const k0 = 0.9996;

 const zone = forceZone || (Math.floor((lon + 180) / 6) + 1);
 const lon0 = ((zone - 1) * 6 - 180 + 3) * Math.PI / 180;
 const latRad = lat * Math.PI / 180;
 const lonRad = lon * Math.PI / 180;

 const N = a / Math.sqrt(1 - e2 * Math.sin(latRad) * Math.sin(latRad));
 const T = Math.tan(latRad) * Math.tan(latRad);
 const C = (e2 / (1 - e2)) * Math.cos(latRad) * Math.cos(latRad);
 const A = Math.cos(latRad) * (lonRad - lon0);
 const M = a * (
 (1 - e2/4 - 3*e4/64 - 5*e6/256) * latRad - (3*e2/8 + 3*e4/32 + 45*e6/1024) * Math.sin(2*latRad) +
 (15*e4/256 + 45*e6/1024) * Math.sin(4*latRad) - (35*e6/3072) * Math.sin(6*latRad)
 );

 let easting = k0 * N * (A + (1-T+C)*A*A*A/6 + (5-18*T+T*T+72*C-58*(e2/(1-e2)))*A*A*A*A*A/120) + 500000;
 let northing = k0 * (M + N * Math.tan(latRad) * (A*A/2 + (5-T+9*C+4*C*C)*A*A*A*A/24 + (61-58*T+T*T+600*C-330*(e2/(1-e2)))*A*A*A*A*A*A/720));
 if (lat < 0) northing += 10000000;

 return { easting, northing, zone, hemi: lat >= 0 ? 'N' : 'S' };
}

// ===== MAIN FILE PARSER - dispatches to P190 or CSV sub-parsers =====
// parseCSVWithUtm: explicit zone+hemi (used after dialog confirmation)
function parseCSVWithUtm(text, zone, hemi) {
 return parsePreplotBestEffort(text, zone, hemi).lines;
}
// parseCSV: auto-detect zone+hemi from file (used for backward compat)
function parseCSV(text) {
 const rows = text.split('\n').map(r =>r.trimEnd());
 const { zone, hemi } = detectUtmZone(rows);
 return parsePreplotBestEffort(text, zone, hemi).lines;
}

/**
 * Best-effort preplot parse across P1 flavours (2D and 3D).
 * Returns { lines, confidence: 'high'|'medium'|'low'|'none', layout }.
 * Never silently invents coordinates when confidence is low - caller should ask user.
 */
function parsePreplotBestEffort(text, zone, hemi) {
 const rows = text.split('\n').map(r =>r.trimEnd());
 const fmt = detectFormat(rows);

 if (fmt === 'p190' || fmt === 'unknown') {
 let lines = parseP190FixedWidth(rows, zone, hemi);
 if (lines.length > 0) {
 // Sanity: drop lines with non-finite lat/lon (bad zone / bad columns)
 const good = lines.filter(l =>l.start && l.end &&
 [l.start[0], l.start[1], l.end[0], l.end[1]].every(isFinite) &&
 Math.abs(l.start[0]) <= 90 && Math.abs(l.end[0]) <= 90 &&
 Math.abs(l.start[1]) <= 180 && Math.abs(l.end[1]) <= 180
 );
 if (good.length === 0) {
 // Parsed numbers but projection looks wrong - ask user to map columns / confirm
 return { lines: [], confidence: 'none', layout: null, reason: 'coords_out_of_range' };
 }
 if (good.length < lines.length * 0.5) {
 return { lines: good, confidence: 'low', layout: null, reason: 'many_invalid_coords' };
 }
 const plaus = assessPreplotPlausibility(good);
 if (!plaus.ok) {
  return { lines: good, confidence: 'low', layout: null, reason: plaus.reason };
 }
 return { lines: good, confidence: 'high', layout: null };
 }
 lines = parseP190LooseWhitespace(rows, zone, hemi);
 if (lines.length > 0) {
  const plaus = assessPreplotPlausibility(lines);
  // Loose P1 is always unsure enough to confirm columns if extent looks wrong
  if (!plaus.ok) return { lines, confidence: 'low', layout: null, reason: plaus.reason };
  return { lines, confidence: 'medium', layout: null };
 }
 }

 const layout = inferDelimitedLayout(rows);
 if (layout && layout.colX >= 0 && layout.colY >= 0 && layout.colLine >= 0) {
 const lines = parseDelimitedWithLayout(rows, layout, zone, hemi);
 if (lines.length > 0) {
 let conf = layout.confidence >= 0.7 ? 'high' : (layout.confidence >= 0.45 ? 'medium' : 'low');
 const plaus = assessPreplotPlausibility(lines);
 if (!plaus.ok) {
  // World-spanning / absurd extents → always ask the user
  return { lines, confidence: 'low', layout, reason: plaus.reason };
 }
 // Delimited medium/low ->treat as unsure so UI asks the user to confirm columns
 return {
 lines,
 confidence: conf === 'high' ? 'high' : 'low',
 layout,
 reason: layout.reason
 };
 }
 // Layout guessed lat/lon but values were metres → empty lines; still return layout for mapper
 if (layout.isLatLon === false || layout.confidence < 0.7) {
  return { lines: [], confidence: 'low', layout, reason: 'need_column_confirm' };
 }
 }

 const fallback = fallbackParseCSV(text);
 if (fallback.length > 0) {
  const plaus = assessPreplotPlausibility(fallback);
  return { lines: fallback, confidence: 'low', layout: layout || null, reason: plaus.ok ? 'fallback' : plaus.reason };
 }

 return { lines: [], confidence: 'none', layout: layout || null };
}

/**
 * Reject globe-spanning garbage from bad column / UTM-as-degrees parses.
 * Typical seismic lines are tens of km, not hundreds of thousands.
 */
function assessPreplotPlausibility(lines) {
 if (!lines || !lines.length) return { ok: false, reason: 'no_lines' };
 let maxLenM = 0, minLat = 90, maxLat = -90, minLon = 180, maxLon = -180;
 let invalid = 0;
 for (const l of lines) {
  if (!l || !l.start || !l.end) { invalid++; continue; }
  const lat1 = l.start[0], lon1 = l.start[1], lat2 = l.end[0], lon2 = l.end[1];
  if (![lat1, lon1, lat2, lon2].every(isFinite) ||
   Math.abs(lat1) > 90 || Math.abs(lat2) > 90 ||
   Math.abs(lon1) > 180 || Math.abs(lon2) > 180) {
   invalid++;
   continue;
  }
  minLat = Math.min(minLat, lat1, lat2);
  maxLat = Math.max(maxLat, lat1, lat2);
  minLon = Math.min(minLon, lon1, lon2);
  maxLon = Math.max(maxLon, lon1, lon2);
  maxLenM = Math.max(maxLenM, haversine(l.start, l.end));
 }
 if (invalid === lines.length) return { ok: false, reason: 'coords_out_of_range' };
 if (invalid > lines.length * 0.5) return { ok: false, reason: 'many_invalid_coords' };
 // Single line longer than 500 km is almost never a valid preplot segment
 if (maxLenM > 500000) {
  return {
   ok: false,
   reason: 'line_too_long',
   detail: `Longest line ${(maxLenM / 1000).toFixed(0)} km - likely wrong columns (UTM read as lat/lon)`
  };
 }
 // Survey bbox diagonal beyond ~2500 km → ask user
 const sw = [minLat, minLon], ne = [maxLat, maxLon];
 const diagM = haversine(sw, ne);
 if (diagM > 2500000) {
  return {
   ok: false,
   reason: 'extent_too_large',
   detail: `Survey span ${(diagM / 1000).toFixed(0)} km - confirm Line / X / Y columns and UTM vs lat/lon`
  };
 }
 return { ok: true, maxLenM, diagM };
}

function parseWithKnownUtm(rows, zone, hemi) {
 return parsePreplotBestEffort(rows.join('\n'), zone, hemi).lines;
}

/** Pick delimiter from a sample of rows. */
function detectRowDelimiter(rows) {
 const sample = rows.slice(0, 30).join('\n');
 const score = (ch) => (sample.match(new RegExp('\\' + ch === '\\' ? '\\\\' : ('\\' + ch), 'g')) || []).length;
 // Simpler counts:
 const cComma = (sample.match(/,/g) || []).length;
 const cTab = (sample.match(/\t/g) || []).length;
 const cSemi = (sample.match(/;/g) || []).length;
 if (cTab >= cComma && cTab >= cSemi && cTab > 0) return '\t';
 if (cSemi >cComma && cSemi >cTab) return ';';
 if (cComma > 0) return ',';
 return /\s+/; // whitespace
}

function splitRow(row, delimiter) {
 if (delimiter instanceof RegExp) return row.trim().split(delimiter).filter(Boolean);
 // Respect simple quoted CSV fields
 if (delimiter === ',') {
 const out = [];
 let cur = '', inQ = false;
 for (let i = 0; i < row.length; i++) {
 const ch = row[i];
 if (ch === '"') { inQ = !inQ; continue; }
 if (ch === ',' && !inQ) { out.push(cur.trim()); cur = ''; continue; }
 cur += ch;
 }
 out.push(cur.trim());
 return out;
 }
 return row.split(delimiter).map(s =>s.trim());
}

/**
 * Infer Line / SP / X / Y columns from delimited text.
 * Uses header names when present, otherwise scores numeric columns by UTM vs lat/lon ranges.
 */
function inferDelimitedLayout(rows) {
 const nonempty = rows.filter(r =>r && r.trim() && !r.trim().startsWith('#'));
 if (nonempty.length < 2) return null;
 const delimiter = detectRowDelimiter(nonempty);
 const split = (r) =>splitRow(r, delimiter);

 const first = split(nonempty[0]);
 const firstNums = first.filter(c => /^-?\d+(\.\d+)?$/.test(c)).length;
 const hasHeader = firstNums < Math.max(2, Math.floor(first.length / 2));
 const headers = hasHeader
 ? first.map((h, i) => (h || ('Column ' + (i + 1))))
 : first.map((_, i) => 'Column ' + (i + 1));
 const dataRows = (hasHeader ? nonempty.slice(1) : nonempty)
 .slice(0, 80)
 .map(split)
 .filter(r =>r.length >= 2);

 if (!dataRows.length) return null;
 const width = Math.max(headers.length, ...dataRows.map(r =>r.length));

 const lc = headers.map(h =>String(h).toLowerCase().replace(/[\s_\-]/g, ''));
 const findHeader = (preds) => {
 // Prefer exact match, then prefix/includes - short tokens like "x"/"y" must be exact
 for (const p of preds) {
 if (typeof p !== 'string') continue;
 const iExact = lc.findIndex(h =>h === p);
 if (iExact >= 0) return iExact;
 }
 for (const p of preds) {
 if (typeof p === 'string') {
 if (p.length <= 1) continue; // never fuzzy-match single letters
 const i = lc.findIndex(h =>h.includes(p));
 if (i >= 0) return i;
 } else {
 const i = lc.findIndex(h =>p(h));
 if (i >= 0) return i;
 }
 }
 return -1;
 };

 let colLine = findHeader(['linename', 'lineid', 'linename', 'line', 'name', 'lin']);
 let colSP = findHeader(['shotpoint', 'shot', 'sp', 'point', 'station', 'kp']);
 let colX = findHeader(['easting', 'east', 'utme', 'utmeasting', 'longitude', 'long', 'lon', 'xcoord', 'x']);
 let colY = findHeader(['northing', 'north', 'utmn', 'utmnorthing', 'latitude', 'lat', 'ycoord', 'y']);

 // Score numeric column pairs when headers are missing/ambiguous
 const colStats = [];
 for (let c = 0; c < width; c++) {
 const vals = [];
 for (const r of dataRows) {
 const v = parseFloat(r[c]);
 if (isFinite(v)) vals.push(v);
 }
 if (vals.length < Math.max(3, dataRows.length * 0.4)) {
 colStats.push(null);
 continue;
 }
 const min = Math.min(...vals), max = Math.max(...vals), absMax = Math.max(Math.abs(min), Math.abs(max));
 const median = vals.slice().sort((a, b) =>a - b)[Math.floor(vals.length / 2)];
 colStats.push({ min, max, absMax, median, vals });
 }

 const scorePair = (xi, yi) => {
 const xs = colStats[xi], ys = colStats[yi];
 if (!xs || !ys) return { score: 0, isLatLon: false };
 // UTM: easting typically 1e5-9e5, northing 0-1e7 (often larger than easting)
 const utmE = xs.median >= 100000 && xs.median <= 900000 && xs.absMax < 1e7;
 const utmN = ys.median >= 0 && ys.median <= 10000000 && ys.absMax > 10000;
 let utmScore = (utmE ? 0.45 : 0) + (utmN ? 0.45 : 0);
 if (utmE && utmN && ys.median >xs.median) utmScore += 0.1;

 // Lat/lon decimal degrees
 const lonOk = xs.absMax <= 180;
 const latOk = ys.absMax <= 90;
 let llScore = (lonOk ? 0.4 : 0) + (latOk ? 0.4 : 0);
 if (lonOk && latOk && Math.abs(ys.median) <= 90 && Math.abs(xs.median) <= 180) llScore += 0.15;

 if (utmScore >= llScore) return { score: utmScore, isLatLon: false };
 return { score: llScore, isLatLon: true };
 };

 let bestPair = { score: 0, x: colX, y: colY, isLatLon: false };
 if (colX >= 0 && colY >= 0 && colX !== colY) {
 bestPair = Object.assign({ x: colX, y: colY }, scorePair(colX, colY));
 } else {
 for (let i = 0; i < width; i++) {
 for (let j = 0; j < width; j++) {
 if (i === j) continue;
 const s = scorePair(i, j);
 if (s.score >bestPair.score) bestPair = { score: s.score, x: i, y: j, isLatLon: s.isLatLon };
 }
 }
 colX = bestPair.x;
 colY = bestPair.y;
 }

 // Line column: prefer non-numeric / alphanumeric
 if (colLine < 0) {
 let best = -1, bestScore = -1;
 for (let c = 0; c < width; c++) {
 if (c === colX || c === colY || c === colSP) continue;
 let alpha = 0, total = 0;
 for (const r of dataRows) {
 if (r[c] == null || r[c] === '') continue;
 total++;
 if (/[A-Za-z_]/.test(r[c]) || !/^-?\d+(\.\d+)?$/.test(r[c])) alpha++;
 }
 const sc = total ? alpha / total : 0;
 if (sc >bestScore) { bestScore = sc; best = c; }
 }
 colLine = best >= 0 ? best : 0;
 }
 if (colSP < 0) {
 for (let c = 0; c < width; c++) {
 if (c === colLine || c === colX || c === colY) continue;
 const st = colStats[c];
 if (st && st.absMax < 1e6 && Number.isFinite(st.median)) { colSP = c; break; }
 }
 }

 // Header-driven lat/lon hint — but NEVER override numeric magnitude.
 // Headers saying "lon" while values are UTM metres (e.g. 500000) caused
 // world-spanning preplots when metres were treated as degrees.
 const headerJoined = lc.join(' ');
 const xs = (bestPair.x >= 0) ? colStats[bestPair.x] : null;
 const ys = (bestPair.y >= 0) ? colStats[bestPair.y] : null;
 const valuesLookGeographic = !!(xs && ys && xs.absMax <= 180 && ys.absMax <= 180);
 const valuesLookUtm = !!(xs && ys && (xs.absMax > 180 || ys.absMax > 180) &&
  (xs.absMax > 1000 || ys.absMax > 1000));

 let isLatLon = bestPair.isLatLon;
 if (valuesLookGeographic &&
  (headerJoined.includes('lat') || headerJoined.includes('lon') || headerJoined.includes('long'))) {
  isLatLon = true;
 }
 if (valuesLookUtm ||
  headerJoined.includes('east') || headerJoined.includes('north') || headerJoined.includes('utm')) {
  isLatLon = false;
 }
 // Magnitudes always win over header keywords
 if (valuesLookUtm) isLatLon = false;
 if (valuesLookGeographic && !valuesLookUtm && bestPair.isLatLon) isLatLon = true;

 let confidence = bestPair.score;
 // Only boost confidence from headers when the numeric ranges agree
 if (colX >= 0 && colY >= 0 && findHeader(['east', 'north', 'lon', 'lat', 'x', 'y']) >= 0) {
  if ((isLatLon && valuesLookGeographic) || (!isLatLon && valuesLookUtm)) {
   confidence = Math.max(confidence, 0.75);
  } else {
   // Header/value conflict — force user confirmation
   confidence = Math.min(confidence, 0.4);
  }
 }
 if (colX === colY || colX < 0 || colY < 0) confidence = 0;
 // UTM metres labeled as lon/lat is the classic globe-spanning failure mode
 if (isLatLon && valuesLookUtm) {
  isLatLon = false;
  confidence = Math.min(confidence, 0.35);
 }

 return {
 delimiter,
 hasHeader,
 headers,
 colLine,
 colSP,
 colX,
 colY,
 isLatLon,
 confidence,
 reason: 'inferred from ' + (hasHeader ? 'headers + values' : 'numeric ranges')
 };
}

function parseDelimitedWithLayout(rows, layout, zone, hemi) {
 const nonempty = rows.filter(r =>r && r.trim() && !r.trim().startsWith('#'));
 const dataRows = (layout.hasHeader ? nonempty.slice(1) : nonempty);
 const lineMap = new Map();
 for (const row of dataRows) {
 const cols = splitRow(row, layout.delimiter);
 if (cols.length <= Math.max(layout.colLine, layout.colX, layout.colY)) continue;
 // Skip leftover header-like rows
 if (/^line$/i.test(cols[layout.colLine]) || /^hc/i.test(cols[0] || '')) continue;
 const name = cols[layout.colLine];
 const sp = layout.colSP >= 0 ? parseFloat(cols[layout.colSP]) : NaN;
 const x = parseFloat(cols[layout.colX]);
 const y = parseFloat(cols[layout.colY]);
 if (!name || !isFinite(x) || !isFinite(y)) continue;
 if (!lineMap.has(name)) lineMap.set(name, []);
 lineMap.get(name).push({ sp: isFinite(sp) ? sp : 0, x, y });
 }
 if (!lineMap.size) return [];

 // If layout claims lat/lon but sample values are clearly metre-scale, refuse
 // silent conversion — caller must ask the user (UTM vs geographic).
 if (layout.isLatLon) {
  let absMax = 0, n = 0;
  for (const pts of lineMap.values()) {
   for (const p of pts) {
    absMax = Math.max(absMax, Math.abs(p.x), Math.abs(p.y));
    if (++n > 40) break;
   }
   if (n > 40) break;
  }
  if (absMax > 180) {
   // Do not emit world-spanning garbage; return empty so confidence drops
   return [];
  }
 }

 const lines = [];
 let idx = 0;
 for (const [name, pts] of lineMap) {
 if (pts.length < 1) continue;
 pts.sort((a, b) =>a.sp - b.sp);
 const first = pts[0], last = pts[pts.length - 1];
 let start, end;
 if (layout.isLatLon || zone === 0) {
 // X=lon, Y=lat (common) - also accept swapped if values clearly say so
 let x1 = first.x, y1 = first.y, x2 = last.x, y2 = last.y;
 if (Math.abs(y1) > 90 && Math.abs(x1) <= 90) { // likely X=lat Y=lon
 start = [x1, y1]; end = [x2, y2];
 } else {
 start = [y1, x1]; end = [y2, x2];
 }
 } else {
 start = utmToLatLon(first.x, first.y, zone, hemi);
 end = utmToLatLon(last.x, last.y, zone, hemi);
 }
 if (!start || !end) continue;
 // utmToLatLon may return {lat,lon} or [lat,lon] depending on code path
 if (!Array.isArray(start)) start = [start.lat, start.lon];
 if (!Array.isArray(end)) end = [end.lat, end.lon];
 if (![start[0], start[1], end[0], end[1]].every(isFinite)) continue;
 // Hard reject out-of-range geographic results
 if (Math.abs(start[0]) > 90 || Math.abs(end[0]) > 90 ||
  Math.abs(start[1]) > 180 || Math.abs(end[1]) > 180) continue;
 lines.push({
 id: idx++,
 name,
 start,
 end,
 spStart: first.sp,
 spEnd: last.sp,
 spCount: new Set(pts.map(p =>p.sp)).size
 });
 }
 return lines;
}

/** Loose P1: whitespace tokens - pick line name + best UTM/latlon pair from floats. */
function parseP190LooseWhitespace(rows, zone, hemi) {
 const lineMap = new Map();
 const spCounters = {};
 for (const row of rows) {
 const t = row.trim();
 if (!t || t[0] === 'H' || t[0] === '#' || /^E\b/.test(t)) continue;
 // Do not skip C when it carries coords (line names like C01)
 if ((t[0] === 'C' || t[0] === 'R') && !/[NS].*[EW]/i.test(t) && !/\d{5,7}\.\d/.test(t)) continue;
 const parts = t.split(/\s+/).filter(Boolean);
 if (parts.length < 3) continue;
 const nums = [];
 let lineName = null;
 let sp = null;
 for (const p of parts) {
 if (/^-?\d+(\.\d+)?$/.test(p)) {
 nums.push(parseFloat(p));
 } else if (!lineName && /[A-Za-z]/.test(p) && p.length <= 24) {
 // Keep full name (SK309-A); only strip a lone UKOOA type prefix when
 // the row really starts with that convention.
 if (isUkuaaTypePrefixRow(t) && /^[SVGTR]/i.test(p) && p.length > 1) {
  lineName = p.slice(1) || p;
 } else {
  lineName = p;
 }
 }
 }
 if (!lineName) {
 // Leading 4-digit record type + line token
 if (/^\d{4}$/.test(parts[0]) && parts[1]) lineName = parts[1];
 else continue;
 }
 lineName = sanitizeLineName(lineName, '');
 if (!lineName) continue;
 if (nums.length < 2) continue;
 // Prefer trailing UTM grid pair first (ignore small DMS numbers as X/Y).
 let easting = null, northing = null;
 for (let i = 0; i + 1 < nums.length; i++) {
  const a = nums[i], b = nums[i + 1];
  if (a >= 100000 && a <= 900000 && b >= 0 && b <= 10000000) {
   easting = a; northing = b; // keep last UTM pair (real grid is at row end)
  }
 }
 // Explicit E/N after hemisphere still wins via extractP190GridCoords
 const grid = extractP190GridCoords(t);
 if (grid && isFinite(grid.easting) && isFinite(grid.northing)
  && grid.easting >= 100000 && grid.easting <= 900000) {
  easting = grid.easting;
  northing = grid.northing;
 }
 if (easting == null) {
  // Fall back to lat/lon magnitudes only when no UTM pair exists
  for (let i = 0; i + 1 < nums.length; i++) {
   const a = nums[i], b = nums[i + 1];
   if (Math.abs(a) <= 180 && Math.abs(b) <= 90) { easting = a; northing = b; break; }
   if (Math.abs(b) <= 180 && Math.abs(a) <= 90) { easting = b; northing = a; break; }
  }
 }
 if (easting == null) {
  easting = nums[nums.length - 2];
  northing = nums[nums.length - 1];
 }
 // SP often the first integer after line name
 for (const n of nums) {
 if (n !== easting && n !== northing && n > 0 && n < 1e6 && Number.isInteger(n)) { sp = n; break; }
 }
 if (!isFinite(easting) || !isFinite(northing)) continue;
 if (!spCounters[lineName]) spCounters[lineName] = 0;
 spCounters[lineName]++;
 if (!lineMap.has(lineName)) lineMap.set(lineName, []);
 lineMap.get(lineName).push({ sp: sp || spCounters[lineName], x: easting, y: northing });
 }
 if (!lineMap.size) return [];
 // Detect lat/lon from sample magnitudes
 let isLatLon = false;
 const sample = lineMap.values().next().value[0];
 if (sample && Math.abs(sample.x) <= 180 && Math.abs(sample.y) <= 90) isLatLon = true;
 // Reuse conversion path via a fake layout
 const fakeRows = ['line,sp,x,y'];
 for (const [name, pts] of lineMap) {
 pts.forEach(p =>fakeRows.push([name, p.sp, p.x, p.y].join(',')));
 }
 return parseDelimitedWithLayout(fakeRows, {
 delimiter: ',', hasHeader: true, headers: ['line', 'sp', 'x', 'y'],
 colLine: 0, colSP: 1, colX: 2, colY: 3,
 isLatLon, confidence: 0.55
 }, zone, hemi);
}

/** Open column mapper - always confirm UTM zone first (unless skipZoneConfirm). */
function promptPreplotColumnMap(text, zone, hemi, opts) {
 opts = opts || {};
 const openMapper = (z, h) => {
 const rows = text.split('\n').map(r =>r.trimEnd()).filter(r =>r.length > 0);
 if (rows.length < 2) { showToast('File appears empty or has too few rows.'); return; }
 const layout = opts.guess || inferDelimitedLayout(rows) || {};
 const delimiter = layout.delimiter || detectRowDelimiter(rows);
 const split = (r) =>splitRow(r, delimiter);
 const hasHeader = layout.hasHeader !== false;
 const headerCols = (layout.headers && layout.headers.length)
 ? layout.headers
 : split(rows[0]).map((hdr, i) =>hdr || ('Column ' + (i + 1)));
 const sampleSource = hasHeader ? rows.slice(1, 6) : rows.slice(0, 5);
 const sampleRows = sampleSource.map(split);
 _showColumnMapperDialog(text, hasHeader ? rows : ([''].concat(rows)), headerCols, sampleRows, delimiter, {
 message: opts.message || 'Confirm which columns hold Line, X and Y. P1 files vary - your call wins.',
 zone: z,
 hemi: h,
 guess: layout,
 onDone: opts.onDone || null,
 hasHeader: hasHeader
 });
 };

 if (opts.skipZoneConfirm) {
 openMapper(zone, hemi);
 return;
 }

 confirmUtmZoneFirst({
 zone,
 hemi,
 message: 'Confirm UTM zone first, then choose which columns are Line, X and Y.'
 }, (z, h) =>openMapper(z, h));
}

// Simple lat/lon fallback: name, lat1, lon1, lat2, lon2
function fallbackParseCSV(text) {
 const rows = text.trim().split('\n').map(r =>r.trim()).filter(r =>r && !r.startsWith('#'));
 const lines = [];
 for (let i = 0; i < rows.length; i++) {
 const cols = rows[i].split(/[,\t\s]+/).map(s =>s.trim()).filter(Boolean);
 if (cols.length >= 4) {
 let name, lat1, lon1, lat2, lon2;
 if (isNaN(parseFloat(cols[0])) || /[A-Za-z]/.test(cols[0])) {
 name = cols[0]; lat1 = parseFloat(cols[1]); lon1 = parseFloat(cols[2]);
 lat2 = parseFloat(cols[3]); lon2 = parseFloat(cols[4]);
 } else {
 lat1 = parseFloat(cols[0]); lon1 = parseFloat(cols[1]);
 lat2 = parseFloat(cols[2]); lon2 = parseFloat(cols[3]);
 name = `L${String(i+1).padStart(3,'0')}`;
 }
 if ([lat1,lon1,lat2,lon2].every(isFinite))
 lines.push({ id: i, name: sanitizeLineName(name, 'L' + String(i + 1).padStart(3, '0')), start: [lat1,lon1], end: [lat2,lon2] });
 }
 }
 return lines;
}

// ===== DEMO DATA =====
function loadDemo() {
 // Simulated offshore survey block - 12 parallel N-S lines off a coast
 const baseLat = 20.50, baseLon = 110.20;
 const lineLen = 0.08; // degrees lat ~8.9 km
 const spacing = 0.012; // degrees lon ~1.2 km
 const lines = [];
 for (let i = 0; i < 14; i++) {
 const lon = baseLon + i * spacing;
 lines.push({
 id: i,
 name: `PNNO V${101 + i}`,
 start: [baseLat, lon],
 end: [baseLat + lineLen, lon]
 });
 }
 setLines(lines);
 showToast('Demo survey loaded (14 lines)');
}

function resetRoute() {
 if ((!state.route || !state.route.length) && (!state.lines || state.lines.length === 0)) {
 showToast('No route to reset.');
 return;
 }
 hardResetRouteState();
 const nObs = (state.obstructions || []).length;
 showToast(nObs
  ? `Route hard-reset. ${nObs} obstruction${nObs === 1 ? '' : 's'} kept and will be applied on the next plan.`
  : 'Route hard-reset - survey lines preserved. Adjust settings and re-solve when ready.');
}

/** Full route clear so a replan never reuses a prior solution's shortcuts. */
function hardResetRouteState() {
 // Line-Manager / partial plans stashed the full preplot separately - restore it.
 if (state._allLines && state._allLines.length) {
  state.lines = state._allLines.slice();
  state._allLines = null;
 }
 state.route = null;
 state.skippedRanges = [];
 state._optimizerStats = null;
 state._plannedDir = null;
 // Keep startConfigured if the user already set START PT / criteria; otherwise
 // allow the start-line chooser again on the next plan.
 if (!state.settings || !state.settings.startConfigured) {
  _startLineChooserShown = false;
 }
 if (layerRoute) layerRoute.clearLayers();
 if (layerAnnotations) layerAnnotations.clearLayers();
 if (layerArrows) layerArrows.clearLayers();
 const stats = document.getElementById('route-stats');
 if (stats) stats.style.display = 'none';
 const stepper = document.getElementById('route-stepper');
 if (stepper) stepper.style.display = 'none';
 // Discard optimality readout left on screen from the previous plan
 const optEl = document.getElementById('stat-optimality');
 if (optEl) optEl.textContent = '';
 if (typeof renderSurveyLines === 'function') renderSurveyLines();
}

function setLines(lines) {
 // Preserve any user-added infill lines when the preplot is re-parsed (e.g.
 // after editing the Survey Criteria on an already-loaded file).
 lines = _mergeExistingInfill(lines);
 // Hard rule: line names are English letters/digits/basic punctuation only.
 sanitizeAllLineNames(lines);
 state.lines = lines;
 // Clear any cached full-line set from a previous Line-Manager route so reports
 // and stats never read a stale preplot (which would blank the acquired split).
 state._allLines = null;
 state.route = null;
 _startLineChooserShown = false;

 // Initialise line status tracking (all lines default to 'planned')
 if (!state.lineStatus) state.lineStatus = {};
 lines.forEach(l => {
 if (!state.lineStatus[l.id]) {
 state.lineStatus[l.id] = { status: 'planned', partialPct: 0, priority: 0 };
 }
 });

 // Enable export button when lines are loaded
 const exportBtn = document.getElementById('btn-export-menu');
 if (exportBtn) {
 exportBtn.removeAttribute('disabled');
 exportBtn.style.opacity = '1';
 exportBtn.style.cursor = 'pointer';
 }

 // Compute center of survey for map transition
 const allPts = lines.flatMap(l => [l.start, l.end]);
 const avgLat = allPts.reduce((s, p) =>s + p[0], 0) / allPts.length;
 const avgLon = allPts.reduce((s, p) =>s + p[1], 0) / allPts.length;

 if (globeActive) {
 transitionToMap(avgLat, avgLon, 10);
 setTimeout(() => {
 renderSurveyLines();
 updateSurveyList();
 fitMapToLines();
 showLineManager();
 }, 700);
 } else {
 if (!map) initLeafletMap();
 renderSurveyLines();
 updateSurveyList();
 hideSurveyOverlay();
 fitMapToLines();
 showLineManager();
 }

 // Line & SP labels are ON by default - let the user know (once per session)
 // that they can hide them via the Layers menu if the map gets cluttered.
 if (!window._labelsWarnShown) {
 window._labelsWarnShown = true;
 setTimeout(() =>showToast('Line numbers & SP labels are shown by default - turn them off anytime in the LAYERS menu.', 6000), 4200);
 }
}

// ===== RENDER SURVEY LINES =====
function renderSurveyLines() {
 layerSurveyLines.clearLayers();
 layerLabels.clearLayers();
 // ALWAYS draw the FULL preplot: after a Line-Manager route plan, state.lines
 // temporarily holds only the routed subset (acquired lines excluded, partial
 // lines replaced by segments). Rendering that subset made acquired lines
 // vanish from the map on any redraw - draw from the cached full list instead.
 const allLines = (state._allLines && state._allLines.length) ? state._allLines : state.lines;
 const hasObs = (state.obstructions || []).length > 0;
 allLines.forEach((line, idx) => {
 const ls = (state.lineStatus && state.lineStatus[line.id]) || { status: 'planned' };
 let lineColor = '#00ff88', lineOpacity = idx % 2 === 0 ? 0.9 : 0.7, lineWeight = 2.5, dashArr = null;
 if (ls.status === 'acquired') { lineColor = '#1a5f2a'; lineOpacity = 0.85; lineWeight = 2.5; }
 else if (ls.status === 'partial') { lineColor = '#f5a623'; lineOpacity = 0.8; lineWeight = 2.5; }
 else if (line._infill) { lineColor = '#ff44ff'; lineOpacity = 0.9; lineWeight = 2.5; dashArr = '6,3'; }

 const polyOpts = { color: lineColor, weight: lineWeight, opacity: lineOpacity };
 if (dashArr) polyOpts.dashArray = dashArr;

 // Gap the preplot where it crosses exclusions so the map never looks like
 // acquisition runs straight through a hazard (route detours are separate).
 let drawn = false;
 if (hasObs && line.start && line.end) {
  const hits = findLineObstructionIntersections(line.start, line.end);
  if (hits && hits.length) {
   hits.sort((a, b) => a.enterFrac - b.enterFrac);
   let last = 0;
   hits.forEach(h => {
    const enter = Math.max(0, Math.min(1, h.enterFrac));
    const exit = Math.max(0, Math.min(1, h.exitFrac));
    if (enter > last + 1e-6) {
     const a = interpolatePoint(line.start, line.end, last);
     const b = interpolatePoint(line.start, line.end, enter);
     const poly = L.polyline([a, b], polyOpts).addTo(layerSurveyLines);
     poly.on('click', () => highlightLine(line.id));
    }
    // Sacrificed span through exclusion - faint red dashed remnant of preplot
    if (exit > enter + 1e-6) {
     const a = interpolatePoint(line.start, line.end, enter);
     const b = interpolatePoint(line.start, line.end, exit);
     L.polyline([a, b], {
      color: '#e74c3c', weight: Math.max(1.5, lineWeight - 0.5),
      opacity: 0.35, dashArray: '2,6', interactive: false
     }).addTo(layerSurveyLines);
    }
    last = Math.max(last, exit);
   });
   if (last < 1 - 1e-6) {
    const a = interpolatePoint(line.start, line.end, last);
    const poly = L.polyline([a, line.end], polyOpts).addTo(layerSurveyLines);
    poly.on('click', () => highlightLine(line.id));
   }
   drawn = true;
  }
 }
 if (!drawn) {
  const poly = L.polyline([line.start, line.end], polyOpts).addTo(layerSurveyLines);
  poly.on('click', () =>highlightLine(line.id));
 }

 // For partial lines, show the acquired portion as a dimmed overlay
 if (ls.status === 'partial' && ls.partialPct > 0) {
 const pct = ls.partialPct / 100;
 const splitPt = [
 line.start[0] + (line.end[0] - line.start[0]) * pct,
 line.start[1] + (line.end[1] - line.start[1]) * pct
 ];
 L.polyline([line.start, splitPt], { color: '#444', weight: 3, opacity: 0.6, dashArray: '3,3' }).addTo(layerSurveyLines);
 }

 if (state.showLabels) {
 const mid = [(line.start[0]+line.end[0])/2, (line.start[1]+line.end[1])/2];
 const statusTag = ls.status === 'acquired' ? ' [A]' : ls.status === 'partial' ? ` ${ls.partialPct}%` : '';
 // Line number: English/digits only (never CJK or other scripts)
 const lineLabel = sanitizeLineName(line.name, `L${idx + 1}`);
 if (line.name !== lineLabel) line.name = lineLabel;
 // First & last shot-point numbers (fall back to computed SP count from length)
 const startSP = line.spStart != null ? line.spStart : 1;
 const endSP = line.spEnd != null ? line.spEnd : (startSP + Math.round(haversine(line.start, line.end) / (state.settings.spInterval || 12.5)));

 // On-screen angle of the line (web mercator is conformal, so this slope
 // is zoom-independent). Screen y grows downward, hence the negation.
 const p1 = L.Projection.SphericalMercator.project(L.latLng(line.start[0], line.start[1]));
 const p2 = L.Projection.SphericalMercator.project(L.latLng(line.end[0], line.end[1]));
 let angle = Math.atan2(-(p2.y - p1.y), p2.x - p1.x) * 180 / Math.PI;
 // Keep text upright (never upside-down); remember the flip so start/end
 // SP labels are still pushed outward beyond the correct line ends.
 let flipped = false;
 if (angle > 90) { angle -= 180; flipped = true; }
 else if (angle < -90) { angle += 180; flipped = true; }

 // shift: 0 = centred on the point (mid-line), -1 = pushed out beyond the
 // line start, +1 = pushed out beyond the line end (along the line axis).
 const addLabel = (pt, text, shift) => {
 const dir = flipped ? -shift : shift;
 const along = dir === 0 ? '0px' : `calc(${dir * 55}% ${dir > 0 ? '+' : '-'} 8px)`;
 L.marker(pt, {
 interactive: false,
 icon: L.divIcon({
 className: '',
 iconSize: [0, 0],
 iconAnchor: [0, 0],
 html: `<div style="display:inline-block;color:${lineColor};` +
 `font:700 10px/13px -apple-system,'Segoe UI',Arial,sans-serif;` +
 `padding:0 3px;background:rgba(6,8,14,0.82);border-radius:2px;` +
 `white-space:nowrap;pointer-events:none;` +
 `transform:translate(-50%,-58%) rotate(${-angle}deg) translateX(${along});` +
 `transform-origin:center center;">${text}</div>`
 })
 }).addTo(layerLabels);
 };

 addLabel(mid, `${lineLabel}${statusTag}`, 0);
 addLabel(line.start, `SP ${startSP}`, -1);
 addLabel(line.end, `SP ${endSP}`, 1);
 }
 });
 renderAcquiredRoute();
 renderSwathOverlays();
 _renderStartPointMarker();
 updateSurveySummary();
}

// Group prime lines into swaths exactly as the route solver does, so on-map
// swath labels match the per-swath acquisition-direction settings. Returns an
// array of groups (index g === "Swath g+1"), each an array of line objects.
function _computeSwathGroups(numSwaths, progression) {
 const _pool = (state._allLines && state._allLines.length) ? state._allLines : state.lines;
 const prime = _pool.filter(l => !l._infill);
 if (prime.length < 1 || numSwaths < 1) return [];
 const keyOf = (l, i) => _lineNumOf(l, i); // unsigned parse - never -1234 from "INFILL-1234"

 const mid = l => [(l.start[0] + l.end[0]) / 2, (l.start[1] + l.end[1]) / 2];
 const idx = prime.map((l, i) =>i);
 // Line-number progressions band by ASCENDING line number so Swath 1 always
 // covers the lowest line numbers (for intuition). Compass progressions band
 // along their spatial sort order.
 if (progression === 'west-east') idx.sort((a, b) =>mid(prime[a])[1] - mid(prime[b])[1]);
 else if (progression === 'east-west') idx.sort((a, b) =>mid(prime[b])[1] - mid(prime[a])[1]);
 else if (progression === 'south-north') idx.sort((a, b) =>mid(prime[a])[0] - mid(prime[b])[0]);
 else if (progression === 'north-south') idx.sort((a, b) =>mid(prime[b])[0] - mid(prime[a])[0]);
 else idx.sort((a, b) =>keyOf(prime[a], a) - keyOf(prime[b], b)); // low-high / high-low / interleaved(-reverse) / auto

 const groupSize = Math.ceil(idx.length / numSwaths);
 const groups = [];
 for (let g = 0; g < numSwaths; g++) {
 const slice = idx.slice(g * groupSize, (g + 1) * groupSize).map(i =>prime[i]);
 if (slice.length) groups.push(slice);
 }
 return groups;
}

// Draw a label and a boundary line for each swath, positioned clear of the
// preplot lines and the planned route (offset beyond the lines' start ends).
function renderSwathOverlays() {
 if (!layerSwaths) return;
 layerSwaths.clearLayers();
 const s = state.settings;
 if ((s.surveyType || '3d') !== '3d') return;
 const numSwaths = s.numSwaths || 1;
 if (numSwaths < 2) return;
 const progression = s.progression || 'interleaved';
 const groups = _computeSwathGroups(numSwaths, progression);
 if (groups.length < 1) return;
 const swathDirections = s.swathDirections || [];

 groups.forEach((grp, g) => {
 if (!grp.length) return;
 const midLine = grp[Math.floor(grp.length / 2)];
 const brg = bearing(midLine.start, midLine.end);
 const lineLenM = haversine(midLine.start, midLine.end);
 // Cross-line centre of the group.
 let latSum = 0, lonSum = 0;
 grp.forEach(l => { latSum += (l.start[0] + l.end[0]) / 2; lonSum += (l.start[1] + l.end[1]) / 2; });
 const centre = [latSum / grp.length, lonSum / grp.length];
 // Push the label beyond the "start" end of the lines so it clears the lines
 // and the run-in/turn loops of the route. Fixed at ~15 km to avoid overlap.
 const offsetM = 15000;
 const labelPt = destinationPoint(centre, (brg + 180) % 360, offsetM);
 const dir = swathDirections[g] || defaultSwathDirection(g);
 const dirTxt = dir === 'high-low' ? 'High\u2192Low SP' : 'Low\u2192High SP';
 L.marker(labelPt, {
 interactive: false,
 icon: L.divIcon({
 className: '',
 html: `<div style="background:rgba(4,16,30,0.82);border:1px solid #00d2ff;color:#00d2ff;font-size:11px;font-weight:700;padding:2px 7px;border-radius:3px;white-space:nowrap;text-shadow:1px 1px 2px #000;pointer-events:none;transform:translate(-50%,-50%);">SWATH ${g + 1}<span style="color:#9fb2c4;font-weight:400;font-size:9px;"> \u00b7 ${dirTxt}</span></div>`,
 iconAnchor: [0, 0]
 })
 }).addTo(layerSwaths);
 });

 // Dividing line between consecutive swaths (parallel to the survey lines,
 // midway between the two boundary lines, extended slightly past both ends).
 for (let g = 0; g < groups.length - 1; g++) {
 const a = groups[g][groups[g].length - 1];
 const b = groups[g + 1][0];
 if (!a || !b) continue;
 // Align b'endpoints with a'so averaging doesn't produce a diagonal.
 let bStart = b.start, bEnd = b.end;
 if (haversine(a.start, b.start) >haversine(a.start, b.end)) { bStart = b.end; bEnd = b.start; }
 const dS = [(a.start[0] + bStart[0]) / 2, (a.start[1] + bStart[1]) / 2];
 const dE = [(a.end[0] + bEnd[0]) / 2, (a.end[1] + bEnd[1]) / 2];
 const dBrg = bearing(dS, dE);
 const dLen = haversine(dS, dE);
 const ext = dLen * 0.06 + 150;
 const p1 = destinationPoint(dS, (dBrg + 180) % 360, ext);
 const p2 = destinationPoint(dE, dBrg, ext);
 L.polyline([p1, p2], { color: '#00d2ff', weight: 1.5, opacity: 0.55, dashArray: '10,8', interactive: false }).addTo(layerSwaths);
 }
}

function _makeSummaryOverlayDraggable(box) {
 // Lightweight drag handler that lives on the box element, so it survives the
 // innerHTML rebuilds that happen on every summary refresh.
 var dragging = false, startX = 0, startY = 0, origLeft = 0, origTop = 0;
 box.addEventListener('mousedown', function(e) {
 // Ignore clicks on any interactive children (buttons/links/inputs)
 if (e.target.closest('button, a, input, select')) return;
 dragging = true;
 var rect = box.getBoundingClientRect();
 var parentRect = box.offsetParent ? box.offsetParent.getBoundingClientRect() : { left: 0, top: 0 };
 origLeft = rect.left - parentRect.left;
 origTop = rect.top - parentRect.top;
 startX = e.clientX;
 startY = e.clientY;
 // Switch to explicit left/top positioning and drop any right/bottom anchor
 box.style.left = origLeft + 'px';
 box.style.top = origTop + 'px';
 box.style.right = 'auto';
 box.style.bottom = 'auto';
 e.preventDefault();
 });
 document.addEventListener('mousemove', function(e) {
 if (!dragging) return;
 box.style.left = (origLeft + (e.clientX - startX)) + 'px';
 box.style.top = (origTop + (e.clientY - startY)) + 'px';
 });
 document.addEventListener('mouseup', function() { dragging = false; });
}

function updateSurveySummary(extraStats) {
 var _srcLines = state._allLines || state.lines;
 if (!_srcLines || _srcLines.length === 0) return;
 var box = document.getElementById('survey-summary-overlay');
 if (!box) {
 box = document.createElement('div');
 box.id = 'survey-summary-overlay';
 box.style.cssText = 'position:absolute;top:8px;left:8px;z-index:1200;' +
 'background:rgba(8,8,16,0.88);border:1px solid #1a1a2e;border-radius:6px;padding:10px 14px;' +
 'color:#e0e0e4;font-size:11px;line-height:1.7;pointer-events:auto;min-width:180px;cursor:move;' +
 'box-shadow:0 4px 20px rgba(0,0,0,0.6);backdrop-filter:blur(6px);user-select:none;';
 box.title = 'Drag to move';
 document.getElementById('main').appendChild(box);
 _makeSummaryOverlayDraggable(box);
 }
 // Always use full original line set for summary (route solver may have replaced state.lines)
 var allLines = state._allLines || state.lines;
 var lineCount = allLines.length;
 var nStr = state.settings.numStreamers || 6;
 var strSep = state.settings.streamerSeparation || 100;
 var spInt = state.settings.spInterval || 12.5;
 var crossLineM = (nStr * strSep) / 2;

 // Per-line: SP count from the preplot'SP records (see lineSpCount),
 // coverage = numSP x spInt (CMP bins). Separate prime and infill
 // lines, and track acquired vs remaining
 var primeSP = 0, primeFullFoldM = 0, primeCount = 0;
 var infillSP = 0, infillFullFoldM = 0, infillCount = 0;
 var acquiredM = 0, acquiredSP = 0, acquiredCount = 0;
 var remainingM = 0, remainingSP = 0, remainingCount = 0;
 var infillAcquiredM = 0, infillRemainingM = 0, infillAcquiredCount = 0;
 allLines.forEach(function(l) {
 var lineSP = lineSpCount(l, spInt);
 var lineM = lineFullFoldM(l, spInt);
 var ls = (state.lineStatus && state.lineStatus[l.id]) || { status: 'planned', partialPct: 0 };
 if (l._infill) {
 infillSP += lineSP;
 infillFullFoldM += lineM;
 infillCount++;
 if (ls.status === 'acquired') { infillAcquiredM += lineM; infillAcquiredCount++; }
 else if ((ls.status === 'partial' || ls.status === 'partial_infill') && ls.partialPct > 0) {
 infillAcquiredM += lineM * (ls.partialPct / 100);
 infillRemainingM += lineM * (1 - ls.partialPct / 100);
 } else { infillRemainingM += lineM; }
 } else {
 primeSP += lineSP;
 primeFullFoldM += lineM;
 primeCount++;
 if (ls.status === 'acquired') {
 acquiredM += lineM; acquiredSP += lineSP; acquiredCount++;
 } else if ((ls.status === 'partial' || ls.status === 'partial_infill') && ls.partialPct > 0) {
 var acqPortion = lineM * (ls.partialPct / 100);
 acquiredM += acqPortion; acquiredSP += Math.round(lineSP * (ls.partialPct / 100));
 remainingM += lineM - acqPortion; remainingSP += lineSP - Math.round(lineSP * (ls.partialPct / 100));
 remainingCount++;
 } else {
 remainingM += lineM; remainingSP += lineSP; remainingCount++;
 }
 }
 });
 var totalSP = primeSP + infillSP;
 var totalFullFoldM = primeFullFoldM + infillFullFoldM;
 var fullFoldKm = totalFullFoldM / 1000;
 var primeKm = primeFullFoldM / 1000;
 var infillKm = infillFullFoldM / 1000;
 var acquiredKm = acquiredM / 1000;
 var remainingKm = remainingM / 1000;
 var avgLineKm = primeCount > 0 ? primeKm / primeCount : 0;

 // Line separation (detect from midpoints of adjacent prime lines)
 var primeLines = allLines.filter(function(l) { return !l._infill; });
 var lineSepM = 0;
 if (primeLines.length >= 2) {
 var mids = primeLines.map(function(l) { return [(l.start[0]+l.end[0])/2, (l.start[1]+l.end[1])/2]; });
 var sepSum = 0, sepCnt = 0;
 for (var si = 1; si < mids.length; si++) { sepSum += haversine(mids[si-1], mids[si]); sepCnt++; }
 lineSepM = sepCnt > 0 ? Math.round(sepSum / sepCnt) : 0;
 }

 // Line bearing (grid and geographic) from first prime line
 var gridBrg = 0, geoBrg = 0;
 if (primeLines.length > 0) {
 gridBrg = gridBearing(primeLines[0].start, primeLines[0].end);
 geoBrg = bearing(primeLines[0].start, primeLines[0].end);
 }
 var gridRecip = (gridBrg + 180) % 360;
 var geoRecip = (geoBrg + 180) % 360;

 // Run-outs only (run-ins are part of line turn, never included)
 var runOutM = state.settings.runOut || 0;
 var primeRunOutKm = (runOutM / 1000) * primeCount;
 var acquiredRunOutKm = (runOutM / 1000) * acquiredCount;
 var infillAcquiredRunOutKm = (runOutM / 1000) * infillAcquiredCount;
 var totalProdKm = primeKm + primeRunOutKm;

 // Full fold area = fullFoldLength x crossLineWidth / 1,000,000
 var sqKmPrime = primeFullFoldM * crossLineM / 1000000;
 var sqKmInfill = infillFullFoldM * crossLineM / 1000000;
 var sqKmAcquired = acquiredM * crossLineM / 1000000;
 var sqKmRemaining = remainingM * crossLineM / 1000000;
 var infillAcquiredKm = infillAcquiredM / 1000;
 var infillRemainingKm = infillRemainingM / 1000;
 var sqKmInfillAcquired = infillAcquiredM * crossLineM / 1000000;
 var sqKmInfillRemaining = infillRemainingM * crossLineM / 1000000;

 // Acquired lines: full fold + runouts
 var acquiredFullFoldRunOutKm = acquiredKm + acquiredRunOutKm;
 var acquiredFullFoldRunOutSqKm = (acquiredM + acquiredRunOutKm * 1000) * crossLineM / 1000000;
 var infillAcquiredFullFoldRunOutKm = infillAcquiredKm + infillAcquiredRunOutKm;
 var infillAcquiredFullFoldRunOutSqKm = (infillAcquiredM + infillAcquiredRunOutKm * 1000) * crossLineM / 1000000;

 // Production area (incl run-outs, no run-ins)
 var totalProdM = totalProdKm * 1000;
 var sqKmProd = totalProdM * crossLineM / 1000000;

 // Infill percentage of prime
 var infillPctKm = primeKm > 0 ? ((infillKm / primeKm) * 100).toFixed(1) : '-';
 var infillPctArea = sqKmPrime > 0 ? ((sqKmInfill / sqKmPrime) * 100).toFixed(1) : '-';
 var hasAcquisition = acquiredM > 0 || infillAcquiredM > 0;

 var utmLabel = (state.settings.utmZone || '-') + (state.settings.utmHemi || 'N');
 var is3D = (state.settings.surveyType || '3d') === '3d';
 var html =
 '<div style="font-size:10px;color:#00d2ff;font-weight:700;letter-spacing:0.6px;margin-bottom:4px;">PREPLOT SUMMARY <span style="color:#ffd60a;font-size:9px;margin-left:6px;">UTM ' + utmLabel + '</span></div>' +
 '<div><span style="color:#8a9bb0;">Prime Lines:</span> <strong>' + primeCount + '</strong>' + (infillCount > 0 ? ' <span style="color:#ff44ff;font-size:9px;">+ ' + infillCount + ' infill</span>' : '') + '</div>' +
 (is3D ? '<div><span style="color:#8a9bb0;">Line Separation:</span> <strong>' + lineSepM.toFixed(0) + ' m</strong></div>' : '') +
 '<div><span style="color:#8a9bb0;">Line Bearing:</span> <strong>' + gridBrg.toFixed(2) + ' deg / ' + gridRecip.toFixed(2) + ' deg (Grid) | ' + geoBrg.toFixed(2) + ' deg / ' + geoRecip.toFixed(2) + ' deg (Geo)</strong></div>' +
 '<div><span style="color:#8a9bb0;">Spread:</span> <strong>' + nStr + ' x ' + strSep + 'm</strong></div>' +
 '<div><span style="color:#8a9bb0;">SP Interval:</span> <strong>' + spInt + ' m</strong></div>' +
 '<div><span style="color:#8a9bb0;">Fold of Coverage:</span> <strong style="color:#ffd60a;">' + calculateFoldOfCoverage().toFixed(1) + 'x</strong></div>' +
 '<div><span style="color:#8a9bb0;">Avg Line Length:</span> <strong>' + avgLineKm.toFixed(3) + ' km</strong> <span style="color:#666;font-size:9px;">(' + (avgLineKm / 1.852).toFixed(3) + ' nm)</span></div>' +
 '<div><span style="color:#8a9bb0;">Prime SP:</span> <strong>' + primeSP.toLocaleString() + '</strong>' + (infillSP > 0 ? ' <span style="color:#ff44ff;font-size:9px;">+ ' + infillSP.toLocaleString() + ' infill</span>' : '') + '</div>' +
 '<div style="border-top:1px solid #1a1a2e;margin-top:4px;padding-top:4px;"></div>' +
 '<div><span style="color:#8a9bb0;">Prime Full Fold Line km:</span> <strong style="color:#00ff88;">' + primeKm.toFixed(3) + ' km</strong> <span style="color:#666;font-size:9px;">(' + (primeKm / 1.852).toFixed(3) + ' nm)</span></div>' +
 (infillKm > 0 ? '<div><span style="color:#8a9bb0;">Infill Full Fold Line km:</span> <strong style="color:#ff44ff;">' + infillKm.toFixed(3) + ' km</strong> <span style="color:#666;font-size:9px;">(' + infillPctKm + '% of prime)</span></div>' : '') +
 '<div><span style="color:#8a9bb0;">Total km (incl run-outs):</span> <strong>' + totalProdKm.toFixed(3) + ' km</strong> <span style="color:#666;font-size:9px;">(' + (totalProdKm / 1.852).toFixed(3) + ' nm)</span></div>' +
 '<div style="border-top:1px solid #1a1a2e;margin-top:4px;padding-top:4px;"></div>' +
 (is3D ? '<div><span style="color:#8a9bb0;">Prime Full Fold Area:</span> <strong style="color:#00ff88;">' + sqKmPrime.toFixed(4) + ' km2</strong></div>' : '') +
 (is3D && sqKmInfill > 0 ? '<div><span style="color:#8a9bb0;">Infill Full Fold Area:</span> <strong style="color:#ff44ff;">' + sqKmInfill.toFixed(4) + ' km2</strong> <span style="color:#666;font-size:9px;">(' + infillPctArea + '% of prime)</span></div>' : '') +
 (is3D ? '<div style="color:#666;font-size:9px;margin-left:4px;">' + primeSP.toLocaleString() + ' SP x ' + spInt + 'm CMP bins x (' + nStr + 'x' + strSep + 'm)/2</div>' : '') +
 (is3D ? '<div><span style="color:#8a9bb0;">Total Area (incl run-outs):</span> <strong>' + sqKmProd.toFixed(4) + ' km2</strong></div>' : '');
 // Acquired vs Remaining breakdown (only shown when there'acquisition data)
 if (hasAcquisition) {
 html += '<div style="border-top:1px solid #1a1a2e;margin-top:4px;padding-top:4px;">' +
 '<div style="font-size:9px;color:#00d2ff;font-weight:700;letter-spacing:0.4px;margin-bottom:3px;">ACQUISITION STATUS</div>' +
 '<div><span style="color:#8a9bb0;">Prime Acquired (full fold):</span> <strong style="color:#888;">' + acquiredKm.toFixed(3) + ' km</strong>' + (is3D ? ' | <strong style="color:#888;">' + sqKmAcquired.toFixed(4) + ' km2</strong>' : '') + '</div>' +
 '<div><span style="color:#8a9bb0;">Prime Acquired (inc. run-outs):</span> <strong style="color:#888;">' + acquiredFullFoldRunOutKm.toFixed(3) + ' km</strong>' + (is3D ? ' | <strong style="color:#888;">' + acquiredFullFoldRunOutSqKm.toFixed(4) + ' km2</strong>' : '') + '</div>' +
 '<div><span style="color:#8a9bb0;">Prime Remaining:</span> <strong style="color:#30d158;">' + remainingKm.toFixed(3) + ' km</strong>' + (is3D ? ' | <strong style="color:#30d158;">' + sqKmRemaining.toFixed(4) + ' km2</strong>' : '') + '</div>';
 if (infillKm > 0) {
 html += '<div><span style="color:#8a9bb0;">Infill Acquired (full fold):</span> <strong style="color:#888;">' + infillAcquiredKm.toFixed(3) + ' km</strong>' + (is3D ? ' | <strong style="color:#888;">' + sqKmInfillAcquired.toFixed(4) + ' km2</strong>' : '') + '</div>' +
 '<div><span style="color:#8a9bb0;">Infill Acquired (inc. run-outs):</span> <strong style="color:#888;">' + infillAcquiredFullFoldRunOutKm.toFixed(3) + ' km</strong>' + (is3D ? ' | <strong style="color:#888;">' + infillAcquiredFullFoldRunOutSqKm.toFixed(4) + ' km2</strong>' : '') + '</div>' +
 '<div><span style="color:#8a9bb0;">Infill Remaining:</span> <strong style="color:#ff44ff;">' + infillRemainingKm.toFixed(3) + ' km</strong>' + (is3D ? ' | <strong style="color:#ff44ff;">' + sqKmInfillRemaining.toFixed(4) + ' km2</strong>' : '') + '</div>';
 }
 html += '</div>';
 }
 if (extraStats) {
 html += '<div style="border-top:1px solid #1a1a2e;margin-top:4px;padding-top:4px;">' +
 '<span style="color:#8a9bb0;">Line Changes:</span> <strong>' + extraStats.transitNm + ' nm</strong></div>' +
 '<div><span style="color:#8a9bb0;">Total:</span> <strong>' + extraStats.totalNm + ' nm</strong></div>';
 if (extraStats.surveyTime) {
 html += '<div style="border-top:1px solid #1a1a2e;margin-top:4px;padding-top:4px;">' +
 '<span style="color:#8a9bb0;">Survey:</span> <strong>' + extraStats.surveyTime + '</strong></div>' +
 '<div><span style="color:#8a9bb0;">Line Changes:</span> <strong>' + extraStats.transitTime + '</strong></div>';
 }
 html += '<div><span style="color:#8a9bb0;">Productive:</span> <strong style="color:#30d158;">' + extraStats.time + '</strong></div>';

 // Weather-adjusted total (not shown in preplot summary)

 // Vessel utilization bar
 if (extraStats.utilOnline) {
 html += '<div style="border-top:1px solid #1a1a2e;margin-top:4px;padding-top:4px;">' +
 '<div style="font-size:9px;color:#00d2ff;font-weight:700;letter-spacing:0.4px;margin-bottom:3px;">VESSEL UTILIZATION</div>' +
 '<div style="display:flex;height:12px;border-radius:3px;overflow:hidden;margin-bottom:2px;">' +
 '<div style="width:' + extraStats.utilOnline + '%;background:#30d158;" title="On-line ' + extraStats.utilOnline + '%"></div>' +
 '<div style="width:' + extraStats.utilTransit + '%;background:#ff9500;" title="Line Changes ' + extraStats.utilTransit + '%"></div>' +
 '</div>' +
 '<div style="display:flex;gap:10px;font-size:9px;color:#8a9bb0;">' +
 '<span><span style="color:#30d158;">&#9632;</span>On-line ' + extraStats.utilOnline + '%</span>' +
 '<span><span style="color:#ff9500;">&#9632;</span>Line Changes ' + extraStats.utilTransit + '%</span>' +
 '</div></div>';
 }

 if (extraStats.skipped) html += '<div style="color:#ff9500;font-size:10px;margin-top:2px;">' + extraStats.skipped + '</div>';
 }
 box.innerHTML = html;
 box.style.display = 'block';
}

function highlightLine(id) {
 const item = document.querySelector(`.survey-line-item[data-id="${id}"]`);
 if (item) {
 document.querySelectorAll('.survey-line-item').forEach(el =>el.classList.remove('active'));
 item.classList.add('active');
 item.scrollIntoView({ block: 'nearest' });
 }
}

