function updateSurveyList() {
 const container = document.getElementById('survey-list');
 container.innerHTML = '';
 state.lines.forEach(line => {
 const div = document.createElement('div');
 div.className = 'survey-line-item';
 div.dataset.id = line.id;
 const startStr = `${line.start[0].toFixed(4)}, ${line.start[1].toFixed(4)}`;
 const endStr = `${line.end[0].toFixed(4)}, ${line.end[1].toFixed(4)}`;
 div.innerHTML = `<span class="line-name">${sanitizeLineName(line.name, 'Line')}</span>
 <span class="line-coords">${startStr} - ${endStr}</span>`;
 div.onclick = () => {
 map.setView(line.start, 11);
 highlightLine(line.id);
 };
 container.appendChild(div);
 });
}

function fitMapToLines() {
 if (state.lines.length === 0) return;
 const latlngs = state.lines.flatMap(l => [l.start, l.end]);
 map.fitBounds(L.latLngBounds(latlngs), { padding: [40, 40] });
}

