// ===== GEODESIC HELPERS =====
const R = 6371000; // Earth radius metres

function toRad(d) { return d * Math.PI / 180; }
function toDeg(r) { return r * 180 / Math.PI; }

function haversine(a, b) {
 // Returns distance in metres between two [lat,lon] points
 const dLat = toRad(b[0] - a[0]);
 const dLon = toRad(b[1] - a[1]);
 const sinLat = Math.sin(dLat / 2);
 const sinLon = Math.sin(dLon / 2);
 const h = sinLat * sinLat +
 Math.cos(toRad(a[0])) * Math.cos(toRad(b[0])) * sinLon * sinLon;
 return 2 * R * Math.asin(Math.min(1, Math.sqrt(h)));
}

function bearing(a, b) {
 // Initial bearing from a to b in degrees [0,360)
 const dLon = toRad(b[1] - a[1]);
 const lat1 = toRad(a[0]), lat2 = toRad(b[0]);
 const y = Math.sin(dLon) * Math.cos(lat2);
 const x = Math.cos(lat1) * Math.sin(lat2) - Math.sin(lat1) * Math.cos(lat2) * Math.cos(dLon);
 return (toDeg(Math.atan2(y, x)) + 360) % 360;
}

function gridConvergence(lat, lon) {
 // UTM grid convergence (angle true north ' grid north) in degrees
 // Positive = grid north is east of true north
 const zone = Math.floor((lon + 180) / 6) + 1;
 const centralMeridian = (zone - 1) * 6 - 180 + 3;
 const dLon = lon - centralMeridian;
 const dLonRad = toRad(dLon);
 const latRad = toRad(lat);
 // Approximate convergence: I3 dLon | sin(lat) + (dLon3 | sin(lat) | cos2(lat))/3
 const sinLat = Math.sin(latRad);
 const cosLat = Math.cos(latRad);
 const conv = dLonRad * sinLat + (Math.pow(dLonRad, 3) * sinLat * cosLat * cosLat) / 3;
 return toDeg(conv);
}

// Exact grid (projected) bearing a'b in degrees [0,360): atan2(I"Easting, I"Northing)
// on the UTM projection. This equals a manual Pythagoras/atan2 calc from the
// E/N grid coordinates, unlike the (geographic bearing - convergence)
// approximation, which ignores the arc-to-chord correction and convergence
// variation along the line. Both endpoints are projected with the SAME zone so
// the deltas are consistent.
function gridBearing(a, b, forceZone) {
 const zone = forceZone || (state.settings && state.settings.utmZone) || (Math.floor((a[1] + 180) / 6) + 1);
 const p1 = latLonToUtm(a[0], a[1], zone);
 const p2 = latLonToUtm(b[0], b[1], zone);
 return (toDeg(Math.atan2(p2.easting - p1.easting, p2.northing - p1.northing)) + 360) % 360;
}

// Move a point distMetres along a GRID bearing, in projected (E/N) space, then
// convert back to lat/lon. This is the exact inverse of gridBearing(), so a line
// built at grid bearing X reads back as grid bearing X.
function gridDestination(origin, gridBrgDeg, distMetres, forceZone) {
 const zone = forceZone || (state.settings && state.settings.utmZone) || (Math.floor((origin[1] + 180) / 6) + 1);
 const hemi = origin[0] >= 0 ? 'N' : 'S';
 const p = latLonToUtm(origin[0], origin[1], zone);
 const br = toRad(gridBrgDeg);
 return utmToLatLon(p.easting + distMetres * Math.sin(br), p.northing + distMetres * Math.cos(br), zone, hemi);
}

function destinationPoint(origin, bearingDeg, distMetres) {
 // Returns [lat,lon] of point dist metres from origin along bearing
 const d = distMetres / R;
 const brng = toRad(bearingDeg);
 const lat1 = toRad(origin[0]);
 const lon1 = toRad(origin[1]);
 const lat2 = Math.asin(
 Math.sin(lat1) * Math.cos(d) +
 Math.cos(lat1) * Math.sin(d) * Math.cos(brng)
 );
 const lon2 = lon1 + Math.atan2(
 Math.sin(brng) * Math.sin(d) * Math.cos(lat1),
 Math.cos(d) - Math.sin(lat1) * Math.sin(lat2)
 );
 return [toDeg(lat2), toDeg(lon2)];
}

// ===== OBSTRUCTION AVOIDANCE HELPERS =====

// Interpolate between two [lat,lon] points at fraction t (0-1)
function interpolatePoint(a, b, t) {
 return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t];
}

// 2D segment-segment intersection test (in lat/lon space, fine for small areas)
// Returns fractional position along segment AB where it crosses CD, or null
function segmentIntersection(a, b, c, d) {
 const dx1 = b[0] - a[0], dy1 = b[1] - a[1];
 const dx2 = d[0] - c[0], dy2 = d[1] - c[1];
 const denom = dx1 * dy2 - dy1 * dx2;
 if (Math.abs(denom) < 1e-12) return null; // parallel

 const t = ((c[0] - a[0]) * dy2 - (c[1] - a[1]) * dx2) / denom;
 const u = ((c[0] - a[0]) * dy1 - (c[1] - a[1]) * dx1) / denom;

 if (t >= 0 && t <= 1 && u >= 0 && u <= 1) return t;
 return null;
}

// Check if point is inside polygon (ray-casting algorithm)
function pointInPolygon(pt, polygon) {
 let inside = false;
 for (let i = 0, j = polygon.length - 1; i < polygon.length; j = i++) {
 const xi = polygon[i][0], yi = polygon[i][1];
 const xj = polygon[j][0], yj = polygon[j][1];
 if (((yi >pt[1]) !== (yj >pt[1])) &&
 (pt[0] < (xj - xi) * (pt[1] - yi) / (yj - yi) + xi)) {
 inside = !inside;
 }
 }
 return inside;
}

// Generate a circle polygon (N vertices) from a center point and radius in metres
function generateCirclePolygon(center, radiusMetres, nPoints) {
 nPoints = nPoints || 24;
 const pts = [];
 for (let i = 0; i < nPoints; i++) {
 const angle = (360 / nPoints) * i;
 pts.push(destinationPoint(center, angle, radiusMetres));
 }
 return pts;
}

// Expand a polygon outward by bufferMetres using edge-normal offset
// Computes offset along the bisector of adjacent edges at each vertex
function bufferPolygon(polygon, bufferMetres) {
 if (bufferMetres <= 0) return polygon;
 const n = polygon.length;
 if (n < 3) return polygon;

 // Ensure polygon is counter-clockwise (for outward normal direction)
 let area = 0;
 for (let i = 0; i < n; i++) {
 const j = (i + 1) % n;
 area += (polygon[j][1] - polygon[i][1]) * (polygon[j][0] + polygon[i][0]);
 }
 const pts = area > 0 ? [...polygon] : [...polygon].reverse();

 // Convert to local XY (metres) for accurate normal computation
 let cx = 0, cy = 0;
 pts.forEach(p => { cx += p[0]; cy += p[1]; });
 cx /= n; cy /= n;
 const mPerDegLat = 111320;
 const mPerDegLon = 111320 * Math.cos(cx * Math.PI / 180);

 const local = pts.map(p => [(p[1] - cy) * mPerDegLon, (p[0] - cx) * mPerDegLat]);

 // Compute offset polygon using edge normals and miter joins
 const offsetPts = [];
 for (let i = 0; i < n; i++) {
 const prev = local[(i - 1 + n) % n];
 const curr = local[i];
 const next = local[(i + 1) % n];

 // Edge vectors
 const e1x = curr[0] - prev[0], e1y = curr[1] - prev[1];
 const e2x = next[0] - curr[0], e2y = next[1] - curr[1];

 // Outward normals (left-hand normals for CCW polygon)
 const len1 = Math.sqrt(e1x * e1x + e1y * e1y) || 1;
 const len2 = Math.sqrt(e2x * e2x + e2y * e2y) || 1;
 const n1x = -e1y / len1, n1y = e1x / len1;
 const n2x = -e2y / len2, n2y = e2x / len2;

 // Bisector direction
 let bx = n1x + n2x, by = n1y + n2y;
 const bLen = Math.sqrt(bx * bx + by * by);
 if (bLen < 1e-10) {
 // Edges are parallel, just offset along one normal
 bx = n1x; by = n1y;
 } else {
 bx /= bLen; by /= bLen;
 }

 // Miter distance: bufferMetres / cos(half-angle between normals)
 const dot = n1x * bx + n1y * by;
 const miterDist = dot > 0.25 ? bufferMetres / dot : bufferMetres * 2; // clamp to avoid extreme miter
 const clampedDist = Math.min(miterDist, bufferMetres * 3); // safety clamp

 offsetPts.push([curr[0] + bx * clampedDist, curr[1] + by * clampedDist]);
 }

 // Convert back to lat/lon
 return offsetPts.map(p => [
 cx + p[1] / mPerDegLat,
 cy + p[0] / mPerDegLon
 ]);
}

// Get the effective exclusion polygon for an obstruction (geometry + buffer)
function getEffectivePolygon(obs) {
 const buffer = obs.exclusionZone || 0;
 if (obs.type === 'point') {
 // Point with exclusion radius ' circle polygon
 const radius = buffer > 0 ? buffer : 500; // default 500m if unset
 return generateCirclePolygon(obs.center, radius);
 }
 // Polygon type: expand by buffer
 if (buffer > 0) {
 return bufferPolygon(obs.polygon, buffer);
 }
 return obs.polygon;
}

// Find all obstruction intersections with a survey line segment s'e
// Returns [{ enterFrac, exitFrac, obstructionIdx }]
function findLineObstructionIntersections(s, e) {
 const results = [];
 if (!s || !e || !state.obstructions || !state.obstructions.length) return results;
 state.obstructions.forEach((obs, obsIdx) => {
 const poly = getEffectivePolygon(obs);
 if (!poly || poly.length < 3) return;

 // Find all crossing fractions where line s'e crosses polygon edges
 const crossings = [];
 for (let i = 0; i < poly.length; i++) {
 const j = (i + 1) % poly.length;
 const t = segmentIntersection(s, e, poly[i], poly[j]);
 if (t !== null) crossings.push(t);
 }

 // Also check if s or e are inside the polygon
 const sInside = pointInPolygon(s, poly);
 const eInside = pointInPolygon(e, poly);

 if (crossings.length === 0 && !sInside && !eInside) {
  // Safety net: pure edge tests can miss thin grazes / vertex hits.
  // Sample the chord; if any interior sample is inside, treat as a hit.
  let hit = false;
  for (let k = 1; k < 20; k++) {
   if (pointInPolygon(interpolatePoint(s, e, k / 20), poly)) { hit = true; break; }
  }
  if (!hit) return;
  // Approximate enter/exit by walking samples
  let enterF = 0, exitF = 1, sawIn = false;
  for (let k = 0; k <= 40; k++) {
   const f = k / 40;
   const inside = pointInPolygon(interpolatePoint(s, e, f), poly);
   if (inside && !sawIn) { enterF = f; sawIn = true; }
   if (sawIn && !inside) { exitF = f; break; }
   if (sawIn) exitF = f;
  }
  results.push({ enterFrac: Math.max(0, enterF - 0.01), exitFrac: Math.min(1, exitF + 0.01), obstructionIdx: obsIdx });
  return;
 }

 crossings.sort((a, b) =>a - b);
 // De-dupe near-identical crossings (vertex shared by two edges)
 const uniq = [];
 crossings.forEach(t => {
  if (!uniq.length || Math.abs(uniq[uniq.length - 1] - t) > 1e-9) uniq.push(t);
 });

 // Determine enter/exit pairs
 if (uniq.length >= 2) {
 for (let k = 0; k < uniq.length - 1; k += 2) {
 results.push({
 enterFrac: uniq[k],
 exitFrac: uniq[k + 1],
 obstructionIdx: obsIdx
 });
 }
 // Odd leftover crossing: treat remaining as exit-to-end or start-to-enter
 if (uniq.length % 2 === 1) {
  const last = uniq[uniq.length - 1];
  if (eInside) results.push({ enterFrac: last, exitFrac: 1, obstructionIdx: obsIdx });
  else if (sInside) results.push({ enterFrac: 0, exitFrac: last, obstructionIdx: obsIdx });
 }
 } else if (uniq.length === 1) {
 if (sInside) {
 results.push({ enterFrac: 0, exitFrac: uniq[0], obstructionIdx: obsIdx });
 } else {
 results.push({ enterFrac: uniq[0], exitFrac: 1, obstructionIdx: obsIdx });
 }
 } else if (sInside && eInside) {
 results.push({ enterFrac: 0, exitFrac: 1, obstructionIdx: obsIdx });
 }
 });
 return results;
}

/** True if any segment of a polyline crosses / enters an exclusion polygon. */
function polylineHitsObstruction(pts) {
 if (!pts || pts.length < 2 || !state.obstructions || !state.obstructions.length) return false;
 for (let i = 0; i < pts.length - 1; i++) {
  if (findLineObstructionIntersections(pts[i], pts[i + 1]).length > 0) return true;
  if (!segmentClearOfAllObstructions(pts[i], pts[i + 1])) return true;
 }
 return false;
}

/** Index of the first obstruction hit by a polyline, or 0. */
function firstObstructionHitByPolyline(pts) {
 if (!pts || pts.length < 2) return 0;
 for (let i = 0; i < pts.length - 1; i++) {
  const hits = findLineObstructionIntersections(pts[i], pts[i + 1]);
  if (hits.length) return hits[0].obstructionIdx;
 }
 // Fall back: any sample inside
 for (let oi = 0; oi < state.obstructions.length; oi++) {
  const poly = getEffectivePolygon(state.obstructions[oi]);
  if (!poly || poly.length < 3) continue;
  for (let i = 0; i < pts.length; i++) {
   if (pointInPolygon(pts[i], poly)) return oi;
  }
 }
 return 0;
}

// Check if a segment from A to B crosses any active obstruction polygon
// Returns true if clear (no intersection with any obstruction interior)
function segmentClearOfAllObstructions(a, b) {
 for (let oi = 0; oi < state.obstructions.length; oi++) {
 const poly = getEffectivePolygon(state.obstructions[oi]);
 if (!poly || poly.length < 3) continue;
 // Check segment-polygon edge intersections
 for (let i = 0; i < poly.length; i++) {
 const j = (i + 1) % poly.length;
 if (segmentIntersection(a, b, poly[i], poly[j]) !== null) return false;
 }
 // Check if midpoint is inside polygon (segment entirely within)
 const mid = interpolatePoint(a, b, 0.5);
 if (pointInPolygon(mid, poly)) return false;
 // Additional check at quarter-points for thin polygons
 if (pointInPolygon(interpolatePoint(a, b, 0.25), poly)) return false;
 if (pointInPolygon(interpolatePoint(a, b, 0.75), poly)) return false;
 }
 return true;
}

// Preplot line separation (m): average adjacent prime-line midpoint distance.
// Do NOT use settings.lineSpacing here - that stores swath width.
function getPreplotLineSeparationM() {
 const lines = ((state._allLines || state.lines) || []).filter(l => !l._infill);
 if (lines.length >= 2) {
 const mids = lines.map(l => [(l.start[0] + l.end[0]) / 2, (l.start[1] + l.end[1]) / 2]);
 let sepSum = 0, sepCnt = 0;
 for (let i = 1; i < mids.length; i++) {
 sepSum += haversine(mids[i - 1], mids[i]);
 sepCnt++;
 }
 if (sepCnt > 0) return Math.max(1, Math.round(sepSum / sepCnt));
 }
 const nStr = state.settings.numStreamers || 6;
 const strSep = state.settings.streamerSeparation || 100;
 return Math.max(1, nStr * strSep);
}

/** Suggested default for offline no-SP threshold (m): half line sep, min 50. */
function suggestOfflineNoSpM() {
 const sep = getPreplotLineSeparationM();
 return Math.max(50, Math.round(sep / 2));
}

/**
 * Cross-track offline (m) beyond which detour coverage is "no SP acquired".
 * Reads live UI inputs, then settings, then localStorage.
 */
function getOfflineNoSpThresholdM() {
 const fromObs = parseFloat(document.getElementById('input-offline-nosp')?.value);
 if (isFinite(fromObs) && fromObs > 0) {
  state.settings.offlineNoSpM = fromObs;
  return fromObs;
 }
 const fromCrit = parseFloat(document.getElementById('crit-offline-nosp')?.value);
 if (isFinite(fromCrit) && fromCrit > 0) {
  state.settings.offlineNoSpM = fromCrit;
  return fromCrit;
 }
 const s = parseFloat(state.settings.offlineNoSpM);
 if (isFinite(s) && s > 0) return s;
 const saved = parseFloat(localStorage.getItem(userKey('offline_nosp_m')));
 if (isFinite(saved) && saved > 0) {
  state.settings.offlineNoSpM = saved;
  return saved;
 }
 return null;
}

function setOfflineNoSpThresholdM(metres, saveDefault) {
 const v = parseFloat(metres);
 if (!isFinite(v) || v <= 0) return null;
 state.settings.offlineNoSpM = v;
 const inp = document.getElementById('input-offline-nosp');
 if (inp) inp.value = v;
 const crit = document.getElementById('crit-offline-nosp');
 if (crit) crit.value = v;
 if (saveDefault) localStorage.setItem(userKey('offline_nosp_m'), String(v));
 return v;
}

/**
 * Ensure the user has specified the offline no-SP threshold before planning
 * around obstructions. Prompts with a suggested default when unset.
 * Returns a Promise that resolves to the threshold (metres) or null if cancelled.
 */
function ensureOfflineNoSpThreshold() {
 return new Promise((resolve) => {
  const existing = getOfflineNoSpThresholdM();
  if (existing != null) { resolve(existing); return; }

  const suggested = suggestOfflineNoSpM();
  const overlay = document.createElement('div');
  overlay.id = 'offline-nosp-dialog';
  overlay.style.cssText = 'position:fixed;inset:0;z-index:10020;background:rgba(0,0,0,0.55);display:flex;align-items:center;justify-content:center;';
  overlay.innerHTML = `
   <div style="background:#0e0e16;border:1px solid #334;border-radius:8px;padding:18px 20px;max-width:420px;width:92%;box-shadow:0 16px 48px rgba(0,0,0,0.65);">
    <div style="font-size:13px;font-weight:700;color:#ffd60a;margin-bottom:8px;">Offline no-SP threshold</div>
    <div style="font-size:11px;color:#c0c8d4;line-height:1.45;margin-bottom:12px;">
     When the vessel is more than <b style="color:#fff;">X metres</b> offline from the planned survey line
     (obstacle detour), that along-line span is treated as <b style="color:#fff;">no SP acquired</b>
     and is deducted from overall SP, line km, and sq km (3D).
    </div>
    <div style="display:flex;align-items:center;gap:8px;margin-bottom:14px;">
     <label style="font-size:11px;color:#a0aebb;white-space:nowrap;">No SP when offline &gt;</label>
     <input id="dlg-offline-nosp" type="number" min="1" step="10" value="${suggested}"
      style="width:100px;padding:6px 8px;border-radius:4px;border:1px solid #333;background:#111;color:#fff;font-size:13px;outline:none;"/>
     <span style="font-size:11px;color:#8a9bb0;">m</span>
    </div>
    <div style="font-size:9px;color:#666;margin-bottom:12px;">Suggested from half line separation: ${suggested} m</div>
    <div style="display:flex;gap:8px;">
     <button id="dlg-offline-ok" style="flex:1.4;padding:8px;border:none;border-radius:4px;background:#1abc9c;color:#fff;font-weight:700;cursor:pointer;font-size:12px;">Use threshold</button>
     <button id="dlg-offline-save" style="flex:1.2;padding:8px;border:none;border-radius:4px;background:#00d2ff;color:#000;font-weight:700;cursor:pointer;font-size:11px;">Save as default</button>
     <button id="dlg-offline-cancel" style="flex:0.8;padding:8px;border:1px solid #333;border-radius:4px;background:#1a1a24;color:#9090c0;cursor:pointer;font-size:11px;">Cancel</button>
    </div>
   </div>`;
  document.body.appendChild(overlay);
  const inp = overlay.querySelector('#dlg-offline-nosp');
  setTimeout(() => { try { inp.focus(); inp.select(); } catch (_) {} }, 40);

  const finish = (saveDef) => {
   const v = setOfflineNoSpThresholdM(inp.value, !!saveDef);
   if (!v) { showToast('Enter a positive offline threshold in metres'); return; }
   overlay.remove();
   if (saveDef) showToast(`Offline no-SP threshold saved as default: ${v} m`);
   else showToast(`Offline no-SP threshold: ${v} m`);
   resolve(v);
  };
  overlay.querySelector('#dlg-offline-ok').onclick = () => finish(false);
  overlay.querySelector('#dlg-offline-save').onclick = () => finish(true);
  overlay.querySelector('#dlg-offline-cancel').onclick = () => {
   overlay.remove();
   resolve(null);
  };
  inp.addEventListener('keydown', (e) => {
   if (e.key === 'Enter') finish(false);
   if (e.key === 'Escape') { overlay.remove(); resolve(null); }
  });
 });
}

function syncOfflineNoSpUi() {
 const v = getOfflineNoSpThresholdM();
 if (v == null) return null;
 const inp = document.getElementById('input-offline-nosp');
 if (inp && String(inp.value) !== String(v)) inp.value = v;
 const crit = document.getElementById('crit-offline-nosp');
 if (crit && document.activeElement !== crit) crit.value = v;
 return v;
}

// Fraction of point P along segment AB in local metres (may be outside 0..1).
function projectFracOnSegment(p, a, b) {
 const midLat = (a[0] + b[0]) / 2;
 const mPerDegLat = 111320;
 const mPerDegLon = 111320 * Math.cos(midLat * Math.PI / 180);
 const ax = 0, ay = 0;
 const bx = (b[1] - a[1]) * mPerDegLon;
 const by = (b[0] - a[0]) * mPerDegLat;
 const px = (p[1] - a[1]) * mPerDegLon;
 const py = (p[0] - a[0]) * mPerDegLat;
 const denom = bx * bx + by * by;
 if (denom < 1e-6) return 0;
 return (px * bx + py * by) / denom;
}

function crossTrackDistM(p, a, b) {
 const midLat = (a[0] + b[0]) / 2;
 const mPerDegLat = 111320;
 const mPerDegLon = 111320 * Math.cos(midLat * Math.PI / 180);
 const bx = (b[1] - a[1]) * mPerDegLon;
 const by = (b[0] - a[0]) * mPerDegLat;
 const px = (p[1] - a[1]) * mPerDegLon;
 const py = (p[0] - a[0]) * mPerDegLat;
 const len = Math.hypot(bx, by);
 if (len < 1e-6) return haversine(p, a);
 return Math.abs(px * by - py * bx) / len;
}

// Densify a visibility-graph polyline so corners respect min turn radius R.
// Fillet each interior vertex with a circular arc of radius R that stays on
// the outside of the turn (same side as the path offset from the obstacle).
function densifyDetourWithMinTurnRadius(pathPts, joinHeadingDeg) {
 const R = getEffectiveTurnRadius();
 if (!pathPts || pathPts.length < 2) return pathPts || [];
 if (pathPts.length === 2) return [pathPts[0], pathPts[1]];

 const out = [pathPts[0]];
 for (let i = 1; i < pathPts.length - 1; i++) {
  const a = pathPts[i - 1];
  const b = pathPts[i];
  const c = pathPts[i + 1];
  const dIn = haversine(a, b);
  const dOut = haversine(b, c);
  if (dIn < 5 || dOut < 5) { out.push(b); continue; }

  const hdgIn = bearing(a, b);
  const hdgOut = bearing(b, c);
  let turn = ((hdgOut - hdgIn + 540) % 360) - 180; // -180..180
  const absTurn = Math.abs(turn);
  // Nearly straight: keep vertex
  if (absTurn < 3) { out.push(b); continue; }

  // Fillet geometry in local metres
  const midLat = b[0], midLon = b[1];
  const mPerDegLat = 111320;
  const mPerDegLon = 111320 * Math.cos(midLat * Math.PI / 180);
  const toXY = (p) => [(p[1] - midLon) * mPerDegLon, (p[0] - midLat) * mPerDegLat];
  const toLL = (x, y) => [midLat + y / mPerDegLat, midLon + x / mPerDegLon];
  const A = toXY(a), B = toXY(b), C = toXY(c);
  const v1x = A[0] - B[0], v1y = A[1] - B[1];
  const v2x = C[0] - B[0], v2y = C[1] - B[1];
  const n1 = Math.hypot(v1x, v1y) || 1;
  const n2 = Math.hypot(v2x, v2y) || 1;
  const u1x = v1x / n1, u1y = v1y / n1;
  const u2x = v2x / n2, u2y = v2y / n2;
  // Half-angle for fillet distance along each edge: d = R / tan(theta/2)
  const theta = absTurn * Math.PI / 180;
  const half = theta / 2;
  const tanHalf = Math.tan(half);
  if (tanHalf < 1e-4) { out.push(b); continue; }
  let d = R / tanHalf;
  // Clamp so fillet stays on both edges
  d = Math.min(d, n1 * 0.45, n2 * 0.45);
  if (d < 2) { out.push(b); continue; }
  const p1 = [B[0] + u1x * d, B[1] + u1y * d];
  const p2 = [B[0] + u2x * d, B[1] + u2y * d];
  // Arc centre: from p1, move R along inward normal of incoming edge
  const left = turn > 0; // positive turn = clockwise in heading (north CW) => screen
  // Incoming direction A->B in XY: -u1 (since u1 is B->A)
  const ix = -u1x, iy = -u1y;
  // Perp: left of travel = (-iy, ix), right = (iy, -ix) in CCW math coords
  // Heading is CW from north; XY here is east=x, north=y. Travel A->B:
  const tx = (B[0] - A[0]) / n1, ty = (B[1] - A[1]) / n1;
  // Rotate 90 deg toward the INSIDE of the turn (toward C side)
  // Cross product tx*u2y - ty*u2x tells which side C is on (CCW positive)
  const cross = tx * u2y - ty * u2x; // u2 is B->C
  // For a left (CCW) turn in XY, centre is to the left of travel: (-ty, tx)
  const ccw = cross > 0;
  const nx = ccw ? -ty : ty;
  const ny = ccw ? tx : -tx;
  const cx = p1[0] + nx * R;
  const cy = p1[1] + ny * R;
  const a0 = Math.atan2(p1[1] - cy, p1[0] - cx);
  const a1 = Math.atan2(p2[1] - cy, p2[0] - cx);
  let sweep = a1 - a0;
  if (ccw) {
   while (sweep < 0) sweep += Math.PI * 2;
   while (sweep > Math.PI * 2) sweep -= Math.PI * 2;
  } else {
   while (sweep > 0) sweep -= Math.PI * 2;
   while (sweep < -Math.PI * 2) sweep += Math.PI * 2;
  }
  // If sweep is wrong direction (reflex), flip
  if (Math.abs(sweep) > Math.PI + 0.2) {
   if (ccw) sweep -= Math.PI * 2;
   else sweep += Math.PI * 2;
  }
  const steps = Math.max(4, Math.ceil(Math.abs(sweep) / (Math.PI / 18)));
  out.push(toLL(p1[0], p1[1]));
  for (let s = 1; s < steps; s++) {
   const ang = a0 + sweep * (s / steps);
   out.push(toLL(cx + Math.cos(ang) * R, cy + Math.sin(ang) * R));
  }
  out.push(toLL(p2[0], p2[1]));
 }
 out.push(pathPts[pathPts.length - 1]);

 // Prefer filleted path if clear; else fall back to original offset polyline
 if (polylineHitsObstruction(out) && !polylineHitsObstruction(pathPts)) return pathPts;
 return out;
}

// Outward offset ring for routing clearance. Prefer proper edge-normal buffer
// (works for irregular polygons); centroid push is a last-resort fallback.
function offsetRingForClearance(poly, metres) {
 if (!poly || poly.length < 3 || !(metres > 0)) return poly ? poly.slice() : [];
 let ring = null;
 try { ring = bufferPolygon(poly, metres); } catch (_) { ring = null; }
 if (!ring || ring.length < 3) {
  const cx = poly.reduce((s, p) => s + p[0], 0) / poly.length;
  const cy = poly.reduce((s, p) => s + p[1], 0) / poly.length;
  ring = poly.map(v => destinationPoint(v, bearing([cx, cy], v), metres));
 }
 // Drop vertices that still sit inside the exclusion (bad miters / concave fails)
 const cleaned = ring.filter(p => !pointInPolygon(p, poly));
 return cleaned.length >= 3 ? cleaned : ring;
}

/** Densify a closed ring so the visibility graph has edge midpoints. */
function densifyRing(ring, maxEdgeM) {
 if (!ring || ring.length < 2) return ring || [];
 const out = [];
 const lim = Math.max(200, maxEdgeM || 800);
 for (let i = 0; i < ring.length; i++) {
  const a = ring[i], b = ring[(i + 1) % ring.length];
  out.push(a);
  const d = haversine(a, b);
  const steps = Math.min(8, Math.floor(d / lim));
  for (let s = 1; s <= steps; s++) out.push(interpolatePoint(a, b, s / (steps + 1)));
 }
 return out;
}

// Fallback walk around an obstruction: use vertices offset by clearance (>= R).
function findClosestPolygonSide(start, end, poly, clearanceM) {
 const R = clearanceM != null ? clearanceM : getEffectiveTurnRadius();
 const ring = densifyRing(offsetRingForClearance(poly, Math.max(R, 500)), Math.max(R * 0.5, 400));
 // Try going "left" and "right" around the offset ring, pick shorter
 let nearStart = 0, nearEnd = 0;
 let dS = Infinity, dE = Infinity;
 for (let i = 0; i < ring.length; i++) {
 const ds = haversine(start, ring[i]);
 const de = haversine(end, ring[i]);
 if (ds < dS) { dS = ds; nearStart = i; }
 if (de < dE) { dE = de; nearEnd = i; }
 }

 if (nearStart === nearEnd) return [ring[nearStart]];

 const pathA = [];
 let idx = nearStart;
 while (idx !== nearEnd) {
 pathA.push(ring[idx]);
 idx = (idx + 1) % ring.length;
 }
 pathA.push(ring[nearEnd]);

 const pathB = [];
 idx = nearStart;
 while (idx !== nearEnd) {
 pathB.push(ring[idx]);
 idx = (idx - 1 + ring.length) % ring.length;
 }
 pathB.push(ring[nearEnd]);

 const lenA = pathLength(pathA);
 const lenB = pathLength(pathB);
 return lenA <= lenB ? pathA : pathB;
}

function pathLength(pts) {
 let d = 0;
 for (let i = 1; i < pts.length; i++) d += haversine(pts[i-1], pts[i]);
 return d;
}

// Compute a detour path around obstructions using a multi-obstacle visibility graph
// Routes around ALL active obstructions simultaneously, not just one.
// Vertices are offset by at least the vessel min turn radius, then corners are
// filleted to radius R so the path is physically feasible.
function computeDetourPath(detourStart, detourEnd, obstructionIdx) {
 const R = getEffectiveTurnRadius();
 // Clearance must be >= R: a vessel with min turn radius R cannot hug a vertex
 // at 0.15R without cutting an unrealistically sharp corner.
 const clearances = [Math.max(R, 500), Math.max(R * 1.5, 750), Math.max(R * 2, 1000), Math.max(R * 3, 1500)];

 let bestPath = null;
 let bestLen = Infinity;
 let anyAttempt = false;

 for (const clearance of clearances) {
  anyAttempt = true;
  const allPolys = [];
  const allVertices = [];
  for (let oi = 0; oi < state.obstructions.length; oi++) {
   const poly = getEffectivePolygon(state.obstructions[oi]);
   if (!poly || poly.length < 3) { allPolys.push(null); continue; }
   allPolys.push(poly);
   const ring = densifyRing(offsetRingForClearance(poly, clearance), Math.max(clearance * 0.4, 400));
   ring.forEach((pt, vi) => {
    // Keep only vertices that are actually outside the exclusion
    if (!pointInPolygon(pt, poly)) allVertices.push({ pt, polyIdx: oi, vertIdx: vi });
   });
  }

  if (allPolys.every(p => p === null)) return [detourStart, detourEnd];

  const nodes = [detourStart, detourEnd, ...allVertices.map(v => v.pt)];
  const nNodes = nodes.length;
  const adjDist = Array.from({ length: nNodes }, () => new Array(nNodes).fill(Infinity));
  for (let i = 0; i < nNodes; i++) {
   for (let j = i + 1; j < nNodes; j++) {
    if (segmentClearOfAllObstructions(nodes[i], nodes[j])) {
     const d = haversine(nodes[i], nodes[j]);
     adjDist[i][j] = d;
     adjDist[j][i] = d;
    }
   }
  }

  const INF = Infinity;
  const visited = new Array(nNodes).fill(false);
  const best = new Array(nNodes).fill(INF);
  const prev = new Array(nNodes).fill(-1);
  best[0] = 0;

  for (let step = 0; step < nNodes; step++) {
   let u = -1, uDist = INF;
   for (let i = 0; i < nNodes; i++) {
    if (!visited[i] && best[i] < uDist) { u = i; uDist = best[i]; }
   }
   if (u === -1 || u === 1) break;
   visited[u] = true;
   for (let v = 0; v < nNodes; v++) {
    if (!visited[v] && adjDist[u][v] < INF) {
     const alt = best[u] + adjDist[u][v];
     if (alt < best[v]) { best[v] = alt; prev[v] = u; }
    }
   }
  }

  let path;
  if (best[1] === INF) {
   const primaryPoly = allPolys[obstructionIdx] || allPolys.find(p => p);
   if (primaryPoly) {
    path = [detourStart, ...findClosestPolygonSide(detourStart, detourEnd, primaryPoly, clearance), detourEnd];
   } else {
    continue;
   }
  } else {
   path = [];
   let cur = 1;
   while (cur !== -1) {
    path.unshift(nodes[cur]);
    cur = prev[cur];
   }
  }

  // Ban pure chords that still cut exclusions
  if (path.length === 2 && polylineHitsObstruction(path)) continue;
  if (polylineHitsObstruction(path)) continue;

  const densified = densifyDetourWithMinTurnRadius(path);
  const usePath = (!polylineHitsObstruction(densified)) ? densified
   : (!polylineHitsObstruction(path) ? path : null);
  if (!usePath) continue;

  const len = pathLength(usePath);
  if (len < bestLen) {
   bestLen = len;
   bestPath = usePath;
   // Prefer the smallest clearance that works (first success is fine)
   break;
  }
 }

 if (bestPath) return bestPath;

 // Last resort: offset walk around primary obstacle — still R-aware, never a cutting chord
 const primary = (state.obstructions[obstructionIdx] && getEffectivePolygon(state.obstructions[obstructionIdx]))
  || (state.obstructions || []).map(getEffectivePolygon).find(p => p && p.length >= 3);
 if (primary) {
  // Try several clearances; pick the first clear walk
  for (const c of [Math.max(R, 500), Math.max(R * 2, 1000), Math.max(R * 4, 2000)]) {
   const walk = findClosestPolygonSide(detourStart, detourEnd, primary, c);
   const alt = [detourStart, ...walk, detourEnd];
   if (polylineHitsObstruction(alt)) continue;
   const densified = densifyDetourWithMinTurnRadius(alt);
   if (!polylineHitsObstruction(densified)) return densified;
   return alt;
  }
 }

 state._detourFailCount = (state._detourFailCount || 0) + 1;
 // Absolute last resort: still walk the offset ring (may graze) — never a bare chord
 if (primary) {
  return [detourStart, ...findClosestPolygonSide(detourStart, detourEnd, primary, Math.max(R, 500)), detourEnd];
 }
 return [detourStart, detourEnd];
}

/* (duplicate legacy detour helpers removed — see densifyDetourWithMinTurnRadius / computeDetourPath above) */

// Where the detour is more than offlineThresholdM metres offline from the
// planned survey line, that along-line span is sacrificed (no SP acquired).
function sacrificedRangeFromDetour(lineStart, lineEnd, detourPts, offlineThresholdM) {
 if (!detourPts || detourPts.length < 2) return null;
 const lineDistM = haversine(lineStart, lineEnd);
 if (lineDistM < 1) return null;
 const thresh = (isFinite(offlineThresholdM) && offlineThresholdM > 0)
  ? offlineThresholdM
  : suggestOfflineNoSpM();

 // Sample along each detour segment; mark online->offline and offline->online
 const samples = [];
 for (let i = 0; i < detourPts.length - 1; i++) {
 const a = detourPts[i], b = detourPts[i + 1];
 const segM = haversine(a, b);
 const steps = Math.max(2, Math.ceil(segM / Math.max(25, thresh / 4)));
 for (let s = 0; s <= steps; s++) {
 const t = s / steps;
 const p = interpolatePoint(a, b, t);
 const frac = projectFracOnSegment(p, lineStart, lineEnd);
 const offline = crossTrackDistM(p, lineStart, lineEnd);
 samples.push({ frac, offline });
 }
 }
 if (!samples.length) return null;

 // Contiguous spans where offline > threshold (along-line frac)
 const spans = [];
 let spanStart = null;
 for (let i = 0; i < samples.length; i++) {
 const sm = samples[i];
 const f = Math.max(0, Math.min(1, sm.frac));
 const off = sm.offline > thresh;
 if (off && spanStart === null) spanStart = f;
 if ((!off || i === samples.length - 1) && spanStart !== null) {
  const spanEnd = off ? f : Math.max(0, Math.min(1, samples[Math.max(0, i - 1)].frac));
  if (spanEnd > spanStart) spans.push({ fromFrac: spanStart, toFrac: spanEnd });
  spanStart = null;
 }
 }
 if (!spans.length) return null;

 // Merge overlapping / adjacent spans into one envelope for this detour
 let fromFrac = spans[0].fromFrac, toFrac = spans[0].toFrac;
 for (let i = 1; i < spans.length; i++) {
  fromFrac = Math.min(fromFrac, spans[i].fromFrac);
  toFrac = Math.max(toFrac, spans[i].toFrac);
 }
 if (toFrac <= fromFrac) return null;

 const distKm = ((toFrac - fromFrac) * lineDistM) / 1000;
 const spInt = state.settings.spInterval || 12.5;
 const spLost = Math.max(0, Math.round((toFrac - fromFrac) * lineDistM / spInt));
 return {
 fromFrac,
 toFrac,
 distKm,
 spLost,
 offlineThresholdM: thresh,
 maxOfflineM: Math.max(...samples.map(s => s.offline)),
 spans
 };
}

// ===== REROUTE AFTER OBSTRUCTION CHANGE =====
// Always rebuild the route when an obstruction is installed. Optional toast
// "Later" left the old acquisition path cutting straight through the new zone
// (exactly what the map screenshot showed).
function promptReroute() {
 if (state.lines.length === 0) return;

 // No existing plan yet - next Plan Route will apply exclusions.
 if (!state.route || !state.route.length) {
  showToast('Obstruction saved - it will be avoided on the next Plan Route.', 5000);
  renderSurveyLines(); // gap preplot through the new exclusion immediately
  // Still ask for offline threshold so it is ready for the next plan
  ensureOfflineNoSpThreshold();
  return;
 }

 // Ask for offline no-SP threshold, then auto re-route
 ensureOfflineNoSpThreshold().then((thresh) => {
  if (thresh == null) {
   showToast('Re-route cancelled - set offline no-SP threshold in Obstructions, then Plan Route.', 6000);
   renderSurveyLines();
   return;
  }
  showToast('Obstruction saved - re-routing to avoid exclusion zones\u2026', 4000);
  hardResetRouteState();
  renderSurveyLines();
  setTimeout(() => {
   try {
    if (typeof executePlanRoute === 'function') executePlanRoute();
    else if (typeof planRoute === 'function') planRoute();
   } catch (err) {
    console.error('Auto re-route failed:', err);
    showToast('Auto re-route failed - use Plan Route to avoid the obstruction.', 6000);
   }
  }, 80);
 });
}

// ===== LAYER PANEL DRAWING (Add Features) =====
var layerDrawIsObstruction = true;

function layerDrawPolygon() {
 _obsDrawSource = 'layers';
 layerDrawIsObstruction = document.getElementById('layer-mark-obstruction')?.checked ?? true;
 hidePanel('layers');
 drawingMode = 'polygon';
 drawingObstruction = true;
 drawingPoints = [];
 map.getContainer().style.cursor = 'crosshair';
 showToast('Click map vertices to define polygon zone. Press "Finish" or double-click last point to close.');
 // Show a floating finish button
 showLayerFinishBtn();
}

function layerDrawPoint() {
 _obsDrawSource = 'layers';
 layerDrawIsObstruction = document.getElementById('layer-mark-obstruction')?.checked ?? true;
 hidePanel('layers');
 drawingMode = 'point';
 drawingObstruction = true;
 drawingPoints = [];
 map.getContainer().style.cursor = 'crosshair';
 showToast('Click map to place point feature.');
}

function showLayerFinishBtn() {
 let btn = document.getElementById('layer-finish-draw-btn');
 if (!btn) {
 btn = document.createElement('button');
 btn.id = 'layer-finish-draw-btn';
 btn.textContent = 'Finish Polygon';
 btn.style.cssText = 'position:fixed;bottom:80px;left:50%;transform:translateX(-50%);z-index:9000;padding:8px 20px;background:#2a5580;color:#e2e8f0;border:none;border-radius:4px;font-size:12px;font-weight:700;cursor:pointer;box-shadow:0 4px 16px rgba(0,0,0,0.5);';
 btn.onclick = () => { finishLayerPolygon(); };
 document.body.appendChild(btn);
 }
 btn.style.display = 'block';
}

function hideLayerFinishBtn() {
 const btn = document.getElementById('layer-finish-draw-btn');
 if (btn) btn.style.display = 'none';
}

function finishLayerPolygon() {
 hideLayerFinishBtn();
 finishDrawObstruction();
}

function getLayerExclusionZone() {
 const el = document.getElementById('layer-exclusion-zone');
 return el ? (parseFloat(el.value) || 0) : 0;
}

function refreshLayerFeaturesList() {
 const container = document.getElementById('layer-features-list');
 if (!container) return;
 const obs = state.obstructions || [];
 const features = state.userFeatures || [];

 // Group imported file features by _groupId
 const groups = {};
 const ungroupedObs = [];
 obs.forEach(o => {
 if (o._groupId) {
 if (!groups[o._groupId]) groups[o._groupId] = { name: o._sourceFile || 'Imported', color: o.customColor || '#ff6b6b', items: [] };
 groups[o._groupId].items.push(o);
 } else {
 ungroupedObs.push(o);
 }
 });

 const all = [...ungroupedObs.map(o => ({ ...o, _src: 'obstruction' })), ...features.map(f => ({ ...f, _src: 'feature' }))];
 const groupEntries = Object.entries(groups);

 if (all.length === 0 && groupEntries.length === 0) {
 container.innerHTML = '<div style="text-align:center; padding:6px; color:#7c8c9e;">No features added yet.</div>';
 return;
 }

 let html = '';

 // Render grouped imports as single entities
 groupEntries.forEach(([gid, group]) => {
 const pts = group.items.filter(i =>i.type === 'point').length;
 const polys = group.items.filter(i =>i.type === 'polygon').length;
 const desc = [polys ? `${polys} polygon${polys > 1 ? 's' : ''}` : '', pts ? `${pts} point${pts > 1 ? 's' : ''}` : ''].filter(Boolean).join(', ');
 html += `<div style="display:flex; justify-content:space-between; align-items:center; padding:5px 6px; border-bottom:1px solid #1a1a24;">
 <span style="display:flex;align-items:center;gap:5px;">
 <span style="display:inline-block;width:10px;height:10px;border-radius:2px;background:${group.color};"></span>
 <span style="font-size:11px;color:#e0e8f0;"><strong>${group.name}</strong> <span style="color:#7c8c9e;font-size:9px;">(${desc})</span></span>
 </span>
 <button onclick="removeLayerGroup(${gid})" style="background:none; border:none; color:#ff453a; cursor:pointer; font-size:11px; font-weight:700;">x</button>
 </div>`;
 });

 // Render ungrouped items
 html += all.map((item) => {
 const typeLabel = item._src === 'obstruction' ? '<span style="color:#ff6b6b;">OBS</span>' : '<span style="color:#5ba3d9;">REF</span>';
 const shape = item.type === 'point' ? '*' : '*';
 return `<div style="display:flex; justify-content:space-between; align-items:center; padding:4px 6px; border-bottom:1px solid #1a1a24;">
 <span>${shape} ${item.name || 'Unnamed'} ${typeLabel}</span>
 <div style="display:flex; gap:6px;">
 <button onclick="editLayerFeature('${item._src}', ${item.id})" style="background:none; border:none; color:#30d158; cursor:pointer; font-size:11px; font-weight:700;">Z</button>
 <button onclick="removeLayerFeature('${item._src}', ${item.id})" style="background:none; border:none; color:#ff453a; cursor:pointer; font-size:11px; font-weight:700;">x</button>
 </div>
 </div>`;
 }).join('');

 container.innerHTML = html;
}

function removeLayerGroup(groupId) {
 state.obstructions = state.obstructions.filter(o =>o._groupId !== groupId);
 renderObstructions();
 updateObstructionList();
 refreshLayerFeaturesList();
 promptReroute();
}

function removeLayerFeature(src, id) {
 if (src === 'obstruction') {
 state.obstructions = state.obstructions.filter(o =>o.id !== id);
 } else {
 state.userFeatures = (state.userFeatures || []).filter(f =>f.id !== id);
 }
 renderObstructions();
 updateObstructionList();
 refreshLayerFeaturesList();
 promptReroute();
}

function editLayerFeature(src, id) {
 const feature = src === 'obstruction' 
 ? state.obstructions.find(o =>o.id === id)
 : state.userFeatures.find(f =>f.id === id);
 
 if (!feature) return;

 const isPoint = feature.type === 'point';
 const currentColor = feature.customColor || (src === 'obstruction' ? '#ff6b6b' : '#5ba3d9');
 const currentName = feature.name || '';
 const currentExclusion = feature.exclusionZone || (isPoint ? 500 : 0);
 const currentWeight = feature.strokeWeight != null ? feature.strokeWeight : 2;
 const showLabelOn = !!feature.showLabel;
 
 let coordsText = '';
 if (isPoint && feature.center) {
 coordsText = `${feature.center[0].toFixed(6)}, ${feature.center[1].toFixed(6)}`;
 } else if (feature.polygon && feature.polygon.length > 0) {
 coordsText = feature.polygon.map(p => `${p[0].toFixed(6)}, ${p[1].toFixed(6)}`).join('\n');
 }

 const dlg = document.createElement('div');
 dlg.style.cssText = 'position:fixed;top:50%;left:50%;transform:translate(-50%,-50%);z-index:10000;background:#0e0e16;border:1px solid #1a1a24;border-radius:8px;box-shadow:0 8px 32px rgba(0,0,0,0.8);min-width:400px;max-width:90vw;max-height:90vh;overflow-y:auto;padding:16px;font-family:inherit;';
 
 dlg.innerHTML = `
 <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:16px;">
 <h3 style="margin:0;color:#e0e8f0;font-size:14px;">Edit layer</h3>
 <button type="button" class="edit-layer-close" style="background:none;border:none;color:#7c8c9e;cursor:pointer;font-size:18px;">x</button>
 </div>
 <div style="font-size:10px;color:#64748b;margin:-8px 0 12px 0;">Double-click the feature on the map anytime to edit</div>
 <div style="display:flex;flex-direction:column;gap:12px;">
 <div>
 <label style="display:block;color:#a0aebb;font-size:11px;margin-bottom:4px;">Name</label>
 <input id="edit-layer-name" type="text" value="${String(currentName).replace(/"/g, '&quot;')}" style="width:100%;padding:8px;border-radius:4px;border:1px solid #222;background:#111;color:#fff;font-size:12px;outline:none;" />
 </div>
 <div>
 <label style="display:block;color:#a0aebb;font-size:11px;margin-bottom:4px;">Outline colour</label>
 <div style="display:flex;gap:8px;align-items:center;">
 <input id="edit-layer-color" type="color" value="${currentColor}" style="width:40px;height:32px;border:none;border-radius:4px;cursor:pointer;" />
 <input id="edit-layer-color-text" type="text" value="${currentColor}" style="flex:1;padding:8px;border-radius:4px;border:1px solid #222;background:#111;color:#fff;font-size:12px;outline:none;" />
 </div>
 </div>
 <div>
 <label style="display:block;color:#a0aebb;font-size:11px;margin-bottom:4px;">Outline weight (px)</label>
 <input id="edit-layer-weight" type="number" value="${currentWeight}" min="0" max="20" step="0.5" style="width:100%;padding:8px;border-radius:4px;border:1px solid #222;background:#111;color:#fff;font-size:12px;outline:none;" />
 </div>
 <div style="display:flex;align-items:center;gap:8px;">
 <input id="edit-layer-show-label" type="checkbox"${showLabelOn ? ' checked' : ''} style="accent-color:#00d2ff;" />
 <label for="edit-layer-show-label" style="color:#a0aebb;font-size:11px;">Show label on map</label>
 </div>
 ${isPoint ? `
 <div>
 <label style="display:block;color:#a0aebb;font-size:11px;margin-bottom:4px;">Exclusion zone (metres)</label>
 <input id="edit-layer-exclusion" type="number" value="${currentExclusion}" min="0" style="width:100%;padding:8px;border-radius:4px;border:1px solid #222;background:#111;color:#fff;font-size:12px;outline:none;" />
 </div>
 ` : ''}
 
 <div>
 <label style="display:block;color:#a0aebb;font-size:11px;margin-bottom:4px;">Coordinates (Lat, Lon - one per line for polygons)</label>
 <textarea id="edit-layer-coords" rows="${isPoint ? 2 : 6}" style="width:100%;padding:8px;border-radius:4px;border:1px solid #222;background:#111;color:#fff;font-size:11px;outline:none;font-family:monospace;resize:vertical;">${coordsText}</textarea>
 </div>
 <div style="display:flex;gap:8px;margin-top:8px;">
 <button type="button" id="edit-layer-save" style="flex:1;padding:10px;border-radius:4px;border:none;background:#30d158;color:#fff;font-size:12px;font-weight:700;cursor:pointer;">Save changes</button>
 <button type="button" class="edit-layer-close" style="flex:1;padding:10px;border-radius:4px;border:none;background:#333;color:#e0e8f0;font-size:12px;cursor:pointer;">Cancel</button>
 </div>
 </div>
 `;

 document.body.appendChild(dlg);
 makeDialogInteractive(dlg);
 dlg.querySelectorAll('.edit-layer-close').forEach(btn => {
  btn.onclick = () => dlg.remove();
 });

 // Sync color picker and text input
 const colorPicker = dlg.querySelector('#edit-layer-color');
 const colorText = dlg.querySelector('#edit-layer-color-text');
 colorPicker.addEventListener('input', () =>colorText.value = colorPicker.value);
 colorText.addEventListener('input', () => {
  if (/^#[0-9a-fA-F]{6}$/.test(colorText.value.trim())) colorPicker.value = colorText.value.trim();
 });

 // Save handler
 dlg.querySelector('#edit-layer-save').onclick = () => {
 const newName = dlg.querySelector('#edit-layer-name').value.trim();
 const newColor = dlg.querySelector('#edit-layer-color-text').value.trim();
 const newExclusion = parseFloat(dlg.querySelector('#edit-layer-exclusion')?.value) || 0;
 let newWeight = parseFloat(dlg.querySelector('#edit-layer-weight')?.value);
 if (isNaN(newWeight)) newWeight = currentWeight;
 newWeight = Math.max(0, Math.min(20, newWeight));
 const showLabel = !!dlg.querySelector('#edit-layer-show-label')?.checked;
 const coordsTextVal = dlg.querySelector('#edit-layer-coords').value.trim();

 // Parse coordinates
 let newCoords = [];
 if (coordsTextVal) {
 const lines = coordsTextVal.split('\n').filter(l =>l.trim());
 lines.forEach(line => {
 const parts = line.split(',').map(p =>parseFloat(p.trim()));
 if (parts.length >= 2 && !isNaN(parts[0]) && !isNaN(parts[1])) {
 newCoords.push([parts[0], parts[1]]);
 }
 });
 }

 if (newCoords.length === 0) {
 showToast('Invalid coordinates');
 return;
 }

 // Update feature
 feature.name = newName || feature.name;
 feature.customColor = newColor;
 feature.exclusionZone = newExclusion;
 feature.strokeWeight = newWeight;
 feature.showLabel = showLabel;

 if (isPoint) {
 feature.center = newCoords[0];
 } else {
 feature.polygon = newCoords;
 }

 // Re-render (renderObstructions also draws userFeatures)
 renderObstructions();
 updateObstructionList();
 refreshLayerFeaturesList();
 promptReroute();

 dlg.remove();
 showToast('Layer updated successfully');
 };
}

function renderUserFeatures() {
 // Drawn as part of renderObstructions (layer is cleared there first).
 if (!layerObstructions) return;
 (state.userFeatures || []).forEach(f => {
 let lyr = null;
 const col = f.customColor || '#5ba3d9';
 const w = f.strokeWeight != null ? f.strokeWeight : 1.5;
 if (f.type === 'point') {
 lyr = L.circle(f.center, { radius: f.exclusionZone || 200, color: col, fillColor: col, fillOpacity: 0.1, weight: w, dashArray: '4,4' }).addTo(layerObstructions);
 } else if (f.polygon && f.polygon.length >= 3) {
 lyr = L.polygon(f.polygon, { color: col, fillColor: col, fillOpacity: 0.08, weight: w, dashArray: '4,4' }).addTo(layerObstructions);
 }
 if (lyr) {
 if (f.showLabel && f.name) {
 lyr.bindTooltip(f.name, { permanent: true, direction: 'center', className: 'user-layer-label' });
 } else if (f.name) {
 lyr.bindTooltip(f.name, { sticky: true });
 }
 lyr.on('dblclick', (e) => {
 if (typeof L !== 'undefined' && L.DomEvent) L.DomEvent.stop(e);
 editLayerFeature('feature', f.id);
 });
 }
 });
}

// ===== OBSTRUCTION DRAWING TOOLS =====
var drawingObstruction = false;
var drawingMode = 'polygon'; // 'polygon' or 'point'
var drawingPoints = [];
var drawingPolyline = null;
var drawingMarkers = [];
var _drawingBufferPreview = null;

var _obsDrawSource = 'obstructions'; // tracks which panel initiated the obstruction draw

function getExclusionZoneInput() {
 // Determine which input to use based on which panel initiated the draw
 const obsEl = document.getElementById('input-exclusion-zone');
 const layerEl = document.getElementById('layer-exclusion-zone');

 if (_obsDrawSource === 'layers') {
 // Initiated from Layers panel
 if (layerEl && parseFloat(layerEl.value) > 0) return parseFloat(layerEl.value);
 if (obsEl && parseFloat(obsEl.value) > 0) return parseFloat(obsEl.value);
 return 500;
 }

 // Initiated from Obstructions panel (default)
 if (obsEl && parseFloat(obsEl.value) > 0) return parseFloat(obsEl.value);
 if (layerEl && parseFloat(layerEl.value) > 0) return parseFloat(layerEl.value);
 return 500;
}

function applyObstructionExclusion(saveAsDefault = false) {
 const v = parseFloat(document.getElementById('input-exclusion-zone').value) || 0;
 const offline = parseFloat(document.getElementById('input-offline-nosp')?.value);
 if (isFinite(v) && v > 0) {
 if (saveAsDefault) {
 localStorage.setItem(userKey('default_exclusion'), v);
 }
 }
 if (isFinite(offline) && offline > 0) {
  setOfflineNoSpThresholdM(offline, saveAsDefault);
  if (saveAsDefault) {
   showToast(`Defaults saved: exclusion ${v || 0} m, offline no-SP ${offline} m`);
  } else {
   showToast(`Exclusion ${v || 0} m | No SP when offline > ${offline} m`);
  }
 } else if (saveAsDefault && isFinite(v) && v > 0) {
  showToast('Default Exclusion Zone saved as system default.');
 } else if (isFinite(v) && v > 0) {
  showToast('Exclusion Zone size applied.');
 }
 hidePanel('obstructions');
}

function startDrawObstruction() {
 _obsDrawSource = 'obstructions';
 drawingMode = 'polygon';
 drawingObstruction = true;
 drawingPoints = [];
 map.getContainer().style.cursor = 'crosshair';
 document.getElementById('btn-draw-obstruction').style.display = 'none';
 document.getElementById('btn-draw-point-obs').style.display = 'none';
 document.getElementById('btn-finish-obstruction').style.display = 'block';
 showToast('Click map vertices to define polygon. Click "Finish" when done.');
}

function startDrawPointObstruction() {
 _obsDrawSource = 'obstructions';
 drawingMode = 'point';
 drawingObstruction = true;
 drawingPoints = [];
 map.getContainer().style.cursor = 'crosshair';
 document.getElementById('btn-draw-obstruction').style.display = 'none';
 document.getElementById('btn-draw-point-obs').style.display = 'none';
 document.getElementById('btn-finish-obstruction').style.display = 'none';
 showToast('Click map to place point obstruction');
}

function onMapClickObstruction(e) {
 if (!drawingObstruction || settingStartPoint) return;
 const pt = [e.latlng.lat, e.latlng.lng];

 if (drawingMode === 'point') {
 // Single click places a point feature
 const exclusion = getExclusionZoneInput();
 const id = Date.now();
 drawingObstruction = false;
 map.getContainer().style.cursor = '';
 const btnDraw = document.getElementById('btn-draw-obstruction');
 const btnPt = document.getElementById('btn-draw-point-obs');
 if (btnDraw) btnDraw.style.display = 'block';
 if (btnPt) btnPt.style.display = 'block';

 if (layerDrawIsObstruction) {
 const hazardType = document.getElementById('layer-obstruction-type')?.value || 'other';
 const { name, color } = _getObsNameAndColor(`PT-${state.obstructions.length + 1}`);
 state.obstructions.push({
 id, name, type: 'point',
 hazardType,
 center: pt,
 polygon: [],
 exclusionZone: exclusion > 0 ? exclusion : 500,
 customColor: color
 });
 renderObstructions();
 updateObstructionList();
 showToast(`${getHazardLabel(hazardType)} "${name}" added (${exclusion || 500}m zone)`);
 promptReroute();
 } else {
 if (!state.userFeatures) state.userFeatures = [];
 const name = `REF-${state.userFeatures.length + 1}`;
 state.userFeatures.push({
 id, name, type: 'point',
 center: pt,
 exclusionZone: exclusion > 0 ? exclusion : 200
 });
 renderObstructions();
 showToast(`Reference point "${name}" added (${exclusion || 200}m zone - not an obstruction)`);
 }
 refreshLayerFeaturesList();
 return;
 }

 // Polygon drawing mode
 drawingPoints.push(pt);

 // Draw marker at vertex
 const marker = L.circleMarker(pt, {
 radius: 5, color: '#e74c3c', fillColor: '#e74c3c', fillOpacity: 1, weight: 1
 }).addTo(layerObstructions);
 drawingMarkers.push(marker);

 // Update preview polyline
 if (drawingPolyline) layerObstructions.removeLayer(drawingPolyline);
 if (drawingPoints.length > 1) {
 drawingPolyline = L.polyline(drawingPoints, {
 color: '#e74c3c', weight: 2, opacity: 0.8, dashArray: '4,4'
 }).addTo(layerObstructions);
 }

 // Live exclusion zone buffer preview (show buffered outline when >= 3 points)
 if (_drawingBufferPreview) { layerObstructions.removeLayer(_drawingBufferPreview); _drawingBufferPreview = null; }
 if (drawingPoints.length >= 3) {
 const exclusion = getExclusionZoneInput();
 if (exclusion > 0) {
 const buffered = bufferPolygon(drawingPoints, exclusion);
 _drawingBufferPreview = L.polygon(buffered, {
 color: '#e74c3c', weight: 1.5, fillColor: '#e74c3c', fillOpacity: 0.06, dashArray: '5,5'
 }).addTo(layerObstructions);
 }
 }
}

function finishDrawObstruction() {
 drawingObstruction = false;
 map.getContainer().style.cursor = '';
 hideLayerFinishBtn();
 const btnDraw = document.getElementById('btn-draw-obstruction');
 const btnPt = document.getElementById('btn-draw-point-obs');
 const btnFinish = document.getElementById('btn-finish-obstruction');
 if (btnDraw) btnDraw.style.display = 'block';
 if (btnPt) btnPt.style.display = 'block';
 if (btnFinish) btnFinish.style.display = 'none';

 // Clean up drawing aids
 drawingMarkers.forEach(m =>layerObstructions.removeLayer(m));
 drawingMarkers = [];
 if (drawingPolyline) { layerObstructions.removeLayer(drawingPolyline); drawingPolyline = null; }
 if (_drawingBufferPreview) { layerObstructions.removeLayer(_drawingBufferPreview); _drawingBufferPreview = null; }

 if (drawingPoints.length < 3) {
 showToast('Need at least 3 points for a polygon');
 drawingPoints = [];
 return;
 }

 const exclusion = getExclusionZoneInput();
 const id = Date.now();

 if (layerDrawIsObstruction) {
 const hazardType = document.getElementById('layer-obstruction-type')?.value || 'other';
 const { name, color } = _getObsNameAndColor(`OBS-${state.obstructions.length + 1}`);
 state.obstructions.push({
 id, name, type: 'polygon',
 hazardType,
 polygon: [...drawingPoints],
 exclusionZone: exclusion,
 customColor: color
 });
 renderObstructions();
 updateObstructionList();
 showToast(`${getHazardLabel(hazardType)} "${name}" added` + (exclusion > 0 ? ` (+${exclusion}m buffer)` : ''));
 promptReroute();
 } else {
 if (!state.userFeatures) state.userFeatures = [];
 const name = `REF-${state.userFeatures.length + 1}`;
 state.userFeatures.push({
 id, name, type: 'polygon',
 polygon: [...drawingPoints],
 exclusionZone: exclusion
 });
 renderObstructions();
 showToast(`Reference polygon "${name}" added - not an obstruction`);
 }
 drawingPoints = [];
 refreshLayerFeaturesList();
}

// ===== KML / SHAPEFILE / GEOJSON IMPORT =====
function importObstructionFile(event) {
 const file = event.target.files[0];
 if (!file) return;
 const ext = file.name.split('.').pop().toLowerCase();
 const reader = new FileReader();

 reader.onload = ev => {
 try {
 let features = [];
 if (ext === 'kml') {
 features = parseKML(ev.target.result);
 } else if (ext === 'geojson' || ext === 'json') {
 features = parseGeoJSON(ev.target.result);
 } else if (ext === 'shp') {
 features = parseSHP(ev.target.result);
 } else {
 showToast('Unsupported format. Use .kml, .geojson, or .shp');
 return;
 }
 if (features.length === 0) { showToast('No features found in file'); return; }

 const exclusion = getExclusionZoneInput();
 const { name: customName, color: customColor } = _getObsNameAndColor(file.name.replace(/\.[^.]+$/, ''));
 const groupId = Date.now();
 features.forEach((feat, i) => {
 const id = groupId + i;
 const name = feat.name || `${customName}-${i + 1}`;
 if (feat.type === 'point') {
 state.obstructions.push({
 id, name, type: 'point',
 center: feat.center,
 polygon: [],
 exclusionZone: exclusion > 0 ? exclusion : 500,
 customColor, _sourceFile: customName, _groupId: groupId
 });
 } else {
 state.obstructions.push({
 id, name, type: 'polygon',
 polygon: feat.polygon,
 exclusionZone: exclusion,
 customColor, _sourceFile: customName, _groupId: groupId
 });
 }
 });
 renderObstructions();
 updateObstructionList();
 showToast(`Imported ${features.length} feature(s) from ${file.name} as "${customName}"`);
 promptReroute();
 } catch (err) {
 console.error('Import error:', err);
 showToast('Failed to parse file: ' + err.message);
 }
 };

 if (ext === 'shp') {
 reader.readAsArrayBuffer(file);
 } else {
 reader.readAsText(file);
 }
 event.target.value = '';
}

// KML parser - extracts Placemarks with Polygon or Point geometry
function parseKML(text) {
 const parser = new DOMParser();
 const doc = parser.parseFromString(text, 'text/xml');
 const features = [];

 const placemarks = doc.querySelectorAll('Placemark');
 placemarks.forEach(pm => {
 const nameEl = pm.querySelector('name');
 const name = nameEl ? nameEl.textContent.trim() : '';

 // Polygon
 const coords = pm.querySelector('Polygon coordinates');
 if (coords) {
 const poly = parseKMLCoords(coords.textContent);
 if (poly.length >= 3) features.push({ type: 'polygon', polygon: poly, name });
 return;
 }

 // LineString treated as polygon boundary if closed
 const lineCoords = pm.querySelector('LineString coordinates');
 if (lineCoords) {
 const pts = parseKMLCoords(lineCoords.textContent);
 if (pts.length >= 3) features.push({ type: 'polygon', polygon: pts, name });
 return;
 }

 // Point
 const pointCoords = pm.querySelector('Point coordinates');
 if (pointCoords) {
 const pts = parseKMLCoords(pointCoords.textContent);
 if (pts.length >= 1) features.push({ type: 'point', center: pts[0], name });
 }
 });
 return features;
}

function parseKMLCoords(text) {
 // KML coords: "lon,lat,alt lon,lat,alt ..." or newline-separated
 return text.trim().split(/\s+/).map(s => {
 const parts = s.split(',');
 if (parts.length >= 2) {
 const lon = parseFloat(parts[0]);
 const lat = parseFloat(parts[1]);
 if (isFinite(lat) && isFinite(lon)) return [lat, lon];
 }
 return null;
 }).filter(Boolean);
}

// GeoJSON parser
function parseGeoJSON(text) {
 const data = JSON.parse(text);
 const features = [];
 const geoFeatures = data.type === 'FeatureCollection' ? data.features :
 data.type === 'Feature' ? [data] : [];

 geoFeatures.forEach(f => {
 const name = (f.properties && f.properties.name) || '';
 const geom = f.geometry;
 if (!geom) return;

 if (geom.type === 'Polygon' && geom.coordinates && geom.coordinates[0]) {
 const poly = geom.coordinates[0].map(c => [c[1], c[0]]); // [lon,lat] ' [lat,lon]
 if (poly.length >= 3) features.push({ type: 'polygon', polygon: poly, name });
 } else if (geom.type === 'MultiPolygon' && geom.coordinates) {
 geom.coordinates.forEach(ring => {
 const poly = ring[0].map(c => [c[1], c[0]]);
 if (poly.length >= 3) features.push({ type: 'polygon', polygon: poly, name });
 });
 } else if (geom.type === 'Point' && geom.coordinates) {
 const center = [geom.coordinates[1], geom.coordinates[0]];
 features.push({ type: 'point', center, name });
 } else if (geom.type === 'LineString' && geom.coordinates) {
 const poly = geom.coordinates.map(c => [c[1], c[0]]);
 if (poly.length >= 3) features.push({ type: 'polygon', polygon: poly, name });
 }
 });
 return features;
}

// Basic SHP parser (handles polygon and point shape types)
function parseSHP(buffer) {
 const features = [];
 const view = new DataView(buffer);
 if (buffer.byteLength < 100) return features;

 // SHP header: shape type at byte 32 (LE)
 const shapeType = view.getInt32(32, true);
 // 1=Point, 3=PolyLine, 5=Polygon, 8=MultiPoint
 let offset = 100; // skip header

 while (offset < buffer.byteLength - 8) {
 // Record header: record number (BE) + content length in 16-bit words (BE)
 const contentLen = view.getInt32(offset + 4, false) * 2;
 offset += 8;
 if (offset + contentLen >buffer.byteLength) break;

 const recShapeType = view.getInt32(offset, true);
 if (recShapeType === 0) { offset += contentLen; continue; } // null shape

 if (recShapeType === 1) {
 // Point: x(double), y(double)
 const x = view.getFloat64(offset + 4, true);
 const y = view.getFloat64(offset + 12, true);
 features.push({ type: 'point', center: [y, x], name: '' });
 } else if (recShapeType === 5 || recShapeType === 3) {
 // Polygon or PolyLine
 // Bounding box: 4 doubles (32 bytes), numParts(int), numPoints(int)
 const numParts = view.getInt32(offset + 36, true);
 const numPoints = view.getInt32(offset + 40, true);
 const partsOffset = offset + 44;
 const pointsOffset = partsOffset + numParts * 4;

 for (let p = 0; p < numParts; p++) {
 const partStart = view.getInt32(partsOffset + p * 4, true);
 const partEnd = (p < numParts - 1) ? view.getInt32(partsOffset + (p + 1) * 4, true) : numPoints;
 const poly = [];
 for (let i = partStart; i < partEnd; i++) {
 const px = view.getFloat64(pointsOffset + i * 16, true);
 const py = view.getFloat64(pointsOffset + i * 16 + 8, true);
 poly.push([py, px]); // [lat, lon]
 }
 if (poly.length >= 3) features.push({ type: 'polygon', polygon: poly, name: '' });
 }
 }
 offset += contentLen;
 }
 return features;
}

// ===== HAZARD TYPE HELPERS =====
const HAZARD_STYLES = {
 platform: { color: '#e74c3c', icon: 'sTM', label: 'Platform / Rig' },
 shallow: { color: '#f39c12', icon: 's ', label: 'Shallow / Shoal' },
 wreck: { color: '#9b59b6', icon: 's"', label: 'Wreck' },
 island: { color: '#27ae60', icon: '', label: 'Island / Rock' },
 cable: { color: '#e67e22', icon: 's', label: 'Cable / Pipeline' },
 restricted: { color: '#c0392b', icon: '"', label: 'Restricted Area' },
 anchorage: { color: '#2980b9', icon: 's"', label: 'Anchorage' },
 fishfarm: { color: '#16a085', icon: 'Y', label: 'Fish Farm' },
 windfarm: { color: '#8e44ad', icon: 'WF', label: 'Wind Farm' },
 other: { color: '#e74c3c', icon: 'x', label: 'Obstruction' }
};

function getHazardStyle(hazardType) {
 return HAZARD_STYLES[hazardType] || HAZARD_STYLES.other;
}

function getHazardLabel(hazardType) {
 return (HAZARD_STYLES[hazardType] || HAZARD_STYLES.other).label;
}

// ===== RENDER & MANAGE OBSTRUCTIONS =====
function renderObstructions() {
 layerObstructions.clearLayers();
 state.obstructions.forEach(obs => {
 const style = getHazardStyle(obs.hazardType);
 const col = obs.customColor || style.color;
 const w = obs.strokeWeight != null ? obs.strokeWeight : 2;
 const tooltip = (style.icon ? style.icon + ' ' : '') + (obs.name || 'Obstruction') + ' - ' + (style.label || '');
 const openEdit = (e) => {
 if (typeof L !== 'undefined' && L.DomEvent) L.DomEvent.stop(e);
 editLayerFeature('obstruction', obs.id);
 };
 const tipOpts = obs.showLabel
  ? { permanent: true, direction: 'center', className: 'user-layer-label' }
  : { permanent: false };

 if (obs.type === 'point') {
 const radius = obs.exclusionZone || 500;
 // Draw exclusion circle
 L.circle(obs.center, {
 radius: radius,
 color: col, weight: w, fillColor: col, fillOpacity: 0.15, dashArray: '5,5'
 }).bindTooltip(`${tooltip} (${radius}m zone)`, tipOpts).on('dblclick', openEdit).addTo(layerObstructions);
 // Center marker with type icon
 const icon = L.divIcon({
 className: '',
 html: `<div style="width:18px;height:18px;display:flex;align-items:center;justify-content:center;background:${col};border-radius:50%;border:2px solid #fff;font-size:10px;">${style.icon || ''}</div>`,
 iconSize: [18, 18], iconAnchor: [9, 9]
 });
 L.marker(obs.center, { icon }).on('dblclick', openEdit).addTo(layerObstructions);
 } else {
 // Polygon obstruction - draw base polygon
 L.polygon(obs.polygon, {
 color: col, weight: w, fillColor: col, fillOpacity: 0.2
 }).bindTooltip(tooltip, tipOpts).on('dblclick', openEdit).addTo(layerObstructions);
 // If exclusion zone > 0, also draw the buffered polygon
 if (obs.exclusionZone > 0) {
 const buffered = bufferPolygon(obs.polygon, obs.exclusionZone);
 L.polygon(buffered, {
 color: col, weight: Math.max(1, w * 0.75), fillColor: col, fillOpacity: 0.08, dashArray: '5,5'
 }).on('dblclick', openEdit).addTo(layerObstructions);
 }
 }
 });
 // Re-draw user reference features on the same layer group
 renderUserFeatures();
}

function updateObstructionList() {
 const container = document.getElementById('obstruction-list');
 if (!container) return;
 container.innerHTML = '';

 // Group imported features, show ungrouped individually
 const groups = {};
 const ungrouped = [];
 state.obstructions.forEach((obs, idx) => {
 if (obs._groupId) {
 if (!groups[obs._groupId]) groups[obs._groupId] = { name: obs._sourceFile || 'Imported', color: obs.customColor || '#ff6b6b', items: [], firstIdx: idx };
 groups[obs._groupId].items.push(obs);
 } else {
 ungrouped.push({ obs, idx });
 }
 });

 // Render grouped imports
 Object.entries(groups).forEach(([gid, group]) => {
 const div = document.createElement('div');
 div.style.cssText = 'display:flex;align-items:center;justify-content:space-between;padding:5px 6px;font-size:11px;color:#e0e6f0;border-bottom:1px solid #334';
 const count = group.items.length;
 div.innerHTML = `<span style="display:flex;align-items:center;gap:4px;">
 <span style="display:inline-block;width:10px;height:10px;border-radius:2px;background:${group.color};"></span>
 <strong>${group.name}</strong> <span style="color:#7c8c9e;font-size:9px;">(${count} feature${count > 1 ? 's' : ''})</span>
 </span>
 <span style="display:flex;gap:4px;align-items:center;">
 <input type="color" value="${group.color}" onchange="_recolorGroup(${gid},this.value)" style="width:18px;height:18px;border:none;background:none;cursor:pointer;padding:0;"/>
 <button onclick="removeLayerGroup(${gid})" style="background:none;border:none;color:#e74c3c;cursor:pointer;font-size:13px">&#10005;</button>
 </span>`;
 container.appendChild(div);
 });

 // Render ungrouped items
 ungrouped.forEach(({ obs, idx }) => {
 const style = getHazardStyle(obs.hazardType);
 const col = obs.customColor || style.color;
 const div = document.createElement('div');
 div.style.cssText = 'display:flex;align-items:center;justify-content:space-between;padding:4px 6px;font-size:11px;color:#e0e6f0;border-bottom:1px solid #334';
 const typeLabel = obs.type === 'point' ? `pt | ${obs.exclusionZone || 500}m` : `${obs.polygon.length} pts` + (obs.exclusionZone > 0 ? ` +${obs.exclusionZone}m` : '');
 div.innerHTML = `<span style="display:inline-block;width:10px;height:10px;border-radius:2px;background:${col};margin-right:4px;"></span><span>${obs.name} | ${style.label} (${typeLabel})</span>
 <span style="display:flex;gap:4px;align-items:center;">
 <input type="color" value="${col}" onchange="state.obstructions[${idx}].customColor=this.value;renderObstructions()" style="width:18px;height:18px;border:none;background:none;cursor:pointer;padding:0;"/>
 <button onclick="removeObstruction(${idx})" style="background:none;border:none;color:#e74c3c;cursor:pointer;font-size:13px">&#10005;</button>
 </span>`;
 container.appendChild(div);
 });
}

function _recolorGroup(groupId, color) {
 state.obstructions.forEach(o => { if (o._groupId === groupId) o.customColor = color; });
 renderObstructions();
 updateObstructionList();
}

function removeObstruction(idx) {
 state.obstructions.splice(idx, 1);
 renderObstructions();
 updateObstructionList();
}

function clearAllObstructions() {
 state.obstructions = [];
 renderObstructions();
 updateObstructionList();
 showToast('All obstructions cleared');
}

function _getObsNameAndColor(defaultName) {
 const nameEl = document.getElementById('input-obs-name');
 const colorEl = document.getElementById('input-obs-color');
 const name = (nameEl && nameEl.value.trim()) || defaultName;
 const color = (colorEl && colorEl.value) || '#ff453a';
 if (nameEl) nameEl.value = '';
 return { name, color };
}

function pasteObstruction() {
 const textEl = document.getElementById('input-obs-paste');
 const fmtEl = document.getElementById('input-obs-paste-fmt');
 if (!textEl || !textEl.value.trim()) { showToast('Paste coordinates into the text area first.'); return; }

 const fmt = fmtEl ? fmtEl.value : 'latlon';
 const raw = textEl.value.trim();
 const lines = raw.split('\n').map(l =>l.trim()).filter(l =>l.length > 0);

 const points = [];
 for (const line of lines) {
 // Parse coordinate pair - support comma, space, or tab separated
 const parts = line.split(/[\s,\t]+/).map(s =>s.trim()).filter(s =>s.length > 0);
 if (parts.length < 2) continue;
 const a = parseFloat(parts[0]), b = parseFloat(parts[1]);
 if (!isFinite(a) || !isFinite(b)) continue;

 let lat, lon;
 if (fmt === 'latlon') { lat = a; lon = b; }
 else if (fmt === 'lonlat') { lat = b; lon = a; }
 else if (fmt === 'utm') {
 const zone = state.settings.utmZone || 31;
 const hemi = state.settings.utmHemi || 'N';
 const ll = utmToLatLon(a, b, zone, hemi);
 lat = ll.lat; lon = ll.lon;
 }
 if (isFinite(lat) && isFinite(lon)) points.push([lat, lon]);
 }

 if (points.length === 0) { showToast('No valid coordinates found. Check format.'); return; }

 const exclusion = parseFloat(document.getElementById('input-exclusion-zone')?.value) || 500;
 const id = Date.now();
 const hazardType = document.getElementById('layer-obstruction-type')?.value || 'other';

 if (points.length === 1) {
 // Single point obstruction
 const { name, color } = _getObsNameAndColor(`PT-${state.obstructions.length + 1}`);
 state.obstructions.push({
 id, name, type: 'point', hazardType, center: points[0],
 polygon: [], exclusionZone: exclusion, customColor: color
 });
 showToast(`Point obstruction "${name}" added (${exclusion}m zone)`);
 } else {
 // Polygon obstruction
 const { name, color } = _getObsNameAndColor(`OBS-${state.obstructions.length + 1}`);
 state.obstructions.push({
 id, name, type: 'polygon', hazardType, polygon: points,
 exclusionZone: exclusion, customColor: color
 });
 showToast(`Polygon obstruction "${name}" added (${points.length} vertices)`);
 }

 textEl.value = '';
 renderObstructions();
 updateObstructionList();
 promptReroute();
}

// Quick-add obstruction from right-click context menu
function quickAddObstruction(lat, lng, hazardType) {
 const exclusion = parseFloat(document.getElementById('layer-exclusion-zone')?.value) || 500;
 const id = Date.now();
 const name = `${getHazardLabel(hazardType).split('/')[0].trim()}-${state.obstructions.length + 1}`;
 state.obstructions.push({
 id, name, type: 'point',
 hazardType,
 center: [lat, lng],
 polygon: [],
 exclusionZone: exclusion
 });
 renderObstructions();
 updateObstructionList();
 refreshLayerFeaturesList();
 showToast(`${getHazardLabel(hazardType)} "${name}" placed (${exclusion}m zone)`);
 promptReroute();
}

// ===== PLAN ROUTE =====
// Nearest-neighbour TSP with direction optimisation.
// BUG FIX: The original site loop was caused by revisiting already-used lines
// because the visited set was never cleared between re-plans. Fixed here with
// a fresh Set on every call and a MAX_ITER guard.

var _startLineChooserShown = false;
var _pendingStartReversed = false;
var _pendingPlanRouteContinue = null;

/** Ask 2D / 3D / OBN before every route plan so the wrong acquisition mode is never silent. */
function confirmSurveyPlanTypeThen(continueFn) {
 const existing = document.getElementById('survey-plan-type-dialog');
 if (existing) existing.remove();

 const current = (state.settings.surveyType === '2d') ? '2d'
  : (state.settings.surveyType === 'obn') ? 'obn' : '3d';
 const overlay = document.createElement('div');
 overlay.id = 'survey-plan-type-dialog';
 overlay.style.cssText = 'position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(6,6,12,0.92);z-index:12000;display:flex;align-items:center;justify-content:center;';
 overlay.innerHTML = `
 <div style="background:#0e0e16;border:1px solid #2a2a3a;border-radius:10px;padding:24px 26px;width:100%;max-width:460px;box-shadow:0 20px 64px rgba(0,0,0,0.75);font-family:inherit;" onclick="event.stopPropagation()">
 <div style="font-size:11px;font-weight:700;color:#30d158;letter-spacing:0.6px;text-transform:uppercase;text-align:center;margin-bottom:6px;">Before route planning</div>
 <div style="font-size:15px;font-weight:700;color:#e0e8f0;margin-bottom:8px;text-align:center;">Choose 2D, 3D, or OBN</div>
 <div style="font-size:11px;color:#8a9bb0;margin-bottom:14px;text-align:center;line-height:1.45;">
 Pick the acquisition type for this plan. Current setting:
 <strong style="color:${current === '2d' ? '#67e8f9' : current === 'obn' ? '#fbbf24' : '#ffd60a'};">${current === '2d' ? '2D' : current === 'obn' ? 'OBN' : '3D'}</strong>.
 </div>
 <label style="display:flex;gap:10px;align-items:flex-start;padding:12px 14px;margin-bottom:8px;border-radius:8px;border:1px solid ${current === '2d' ? '#22d3ee' : '#1e293b'};background:${current === '2d' ? 'rgba(8,47,73,0.45)' : '#111'};cursor:pointer;">
 <input type="radio" name="survey-plan-type" value="2d"${current === '2d' ? ' checked' : ''} style="margin-top:3px;accent-color:#00d2ff;" />
 <span>
 <span style="display:block;color:#e2e8f0;font-size:13px;font-weight:700;">2D</span>
 <span style="display:block;color:#94a3b8;font-size:10px;line-height:1.35;margin-top:2px;">Streamer / towed lines - free optimizer or compass / line-number order. No swath interleave.</span>
 </span>
 </label>
 <label style="display:flex;gap:10px;align-items:flex-start;padding:12px 14px;margin-bottom:8px;border-radius:8px;border:1px solid ${current === '3d' ? '#fbbf24' : '#1e293b'};background:${current === '3d' ? 'rgba(66,32,6,0.35)' : '#111'};cursor:pointer;">
 <input type="radio" name="survey-plan-type" value="3d"${current === '3d' ? ' checked' : ''} style="margin-top:3px;accent-color:#fbbf24;" />
 <span>
 <span style="display:block;color:#e2e8f0;font-size:13px;font-weight:700;">3D</span>
 <span style="display:block;color:#94a3b8;font-size:10px;line-height:1.35;margin-top:2px;">Multi-streamer swath plan - progressive / interleaved coverage.</span>
 </span>
 </label>
 <label style="display:flex;gap:10px;align-items:flex-start;padding:12px 14px;margin-bottom:16px;border-radius:8px;border:1px solid ${current === 'obn' ? '#f59e0b' : '#1e293b'};background:${current === 'obn' ? 'rgba(66,32,6,0.4)' : '#111'};cursor:pointer;">
 <input type="radio" name="survey-plan-type" value="obn"${current === 'obn' ? ' checked' : ''} style="margin-top:3px;accent-color:#f59e0b;" />
 <span>
 <span style="display:block;color:#e2e8f0;font-size:13px;font-weight:700;">OBN - Ocean Bottom Nodes</span>
 <span style="display:block;color:#94a3b8;font-size:10px;line-height:1.35;margin-top:2px;">Source sail lines over a seabed node patch. No streamer swaths.</span>
 </span>
 </label>
 <div style="display:flex;gap:8px;">
 <button type="button" id="spt-cancel" style="flex:1;padding:11px;border-radius:6px;border:1px solid #333;background:#1a1a2e;color:#a0aebb;font-weight:700;cursor:pointer;font-size:12px;">Cancel</button>
 <button type="button" id="spt-continue" style="flex:1.5;padding:11px;border-radius:6px;border:none;background:#30d158;color:#000;font-weight:700;cursor:pointer;font-size:12px;">Continue to plan</button>
 </div>
 </div>`;
 document.body.appendChild(overlay);

 // Highlight selected card when radios change
 overlay.querySelectorAll('input[name="survey-plan-type"]').forEach(r => {
  r.addEventListener('change', () => {
   overlay.querySelectorAll('label').forEach(lab => {
    const inp = lab.querySelector('input[name="survey-plan-type"]');
    if (!inp) return;
    const on = inp.checked;
    const v = inp.value;
    lab.style.borderColor = on ? (v === '2d' ? '#22d3ee' : v === 'obn' ? '#f59e0b' : '#fbbf24') : '#1e293b';
    lab.style.background = on
     ? (v === '2d' ? 'rgba(8,47,73,0.45)' : 'rgba(66,32,6,0.35)')
     : '#111';
   });
  });
 });

 document.getElementById('spt-cancel').onclick = () => {
  overlay.remove();
  _pendingPlanRouteContinue = null;
 };
 overlay.onclick = (e) => { if (e.target === overlay) { overlay.remove(); _pendingPlanRouteContinue = null; } };
 document.getElementById('spt-continue').onclick = () => {
  const picked = (overlay.querySelector('input[name="survey-plan-type"]:checked') || {}).value;
  if (!picked) { showToast('Select 2D, 3D, or OBN before planning'); return; }
  applyConfirmedSurveyPlanType(picked);
  overlay.remove();
  const next = continueFn || _pendingPlanRouteContinue;
  _pendingPlanRouteContinue = null;
  if (typeof next === 'function') next();
 };
}

function applyConfirmedSurveyPlanType(type) {
 const is2d = type === '2d';
 const isObn = type === 'obn';
 state.settings.surveyType = isObn ? 'obn' : (is2d ? '2d' : '3d');
 let prog = state.settings.progression || ((is2d || isObn) ? 'auto' : 'interleaved');
 if (is2d || isObn) {
  // Swath-interleave strategies are 3D-only - force a 2D/OBN-safe progression.
  if (prog === 'interleaved' || prog === 'interleaved-reverse') {
   prog = 'auto';
   state.settings.optimizerMode = state.settings.optimizerMode || 'deep';
  }
 } else {
  if (prog === 'auto' || prog === 'auto-nn') {
  }
 }
 state.settings.progression = prog;
 if (typeof updateSurveyTypeIndicator === 'function') updateSurveyTypeIndicator(state.settings.surveyType);
 // Keep Survey Criteria select in sync if the panel DOM exists
 try {
  const el = document.getElementById('crit-survey-type');
  if (el) { el.value = state.settings.surveyType; if (typeof toggleSurveyTypeOptions === 'function') toggleSurveyTypeOptions(); }
 } catch (_) {}
 showToast(isObn
  ? 'Route plan locked to OBN - source sail lines (no streamer swaths)'
  : is2d
  ? 'Route plan locked to 2D - any direction (no swath interleave)'
  : 'Route plan locked to 3D - swath / progressive adjacency', 4000);
}

 /** Show/hide start-plan options that only apply to 3D swath surveys. */
function _syncStartPlanSelectForSurveyType() {
 const planSel = document.getElementById('start-plan-select');
 const banner = document.getElementById('start-plan-type-banner');
 const st = state.settings.surveyType || '3d';
 const is2d = st === '2d';
 const isObn = st === 'obn';
 const noSwath = is2d || isObn;
 if (banner) {
  banner.textContent = isObn
   ? 'Plan type: OBN - source sail lines'
   : is2d
   ? 'Plan type: 2D - any direction'
   : 'Plan type: 3D - swath plan';
  banner.style.borderColor = isObn ? '#92400e' : is2d ? '#155e75' : '#92400e';
  banner.style.color = isObn ? '#fbbf24' : is2d ? '#67e8f9' : '#fbbf24';
  banner.style.background = isObn ? 'rgba(66,32,6,0.4)' : is2d ? 'rgba(8,47,73,0.45)' : 'rgba(66,32,6,0.35)';
 }
 if (!planSel) return;
 const swathOnly = new Set(['interleaved', 'interleaved-reverse']);
 Array.from(planSel.options).forEach(opt => {
  if (swathOnly.has(opt.value)) {
   opt.disabled = noSwath;
   opt.hidden = noSwath;
  } else {
   opt.disabled = false;
   opt.hidden = false;
  }
 });
 // If current value is a hidden 3D swath option while in 2D, snap to auto
 if (is2d && swathOnly.has(planSel.value)) {
  planSel.value = 'auto';
 }
}

function showStartLineChooser() {
 const sel = document.getElementById('start-line-select');
 if (!sel || state.lines.length === 0) return;

 // Populate dropdown with line names
 sel.innerHTML = '';
 state.lines.forEach((line, idx) => {
 const opt = document.createElement('option');
 opt.value = idx;
 opt.textContent = line.name || ('Line ' + (idx + 1));
 if (state.settings.startLineIdx === idx) opt.selected = true;
 sel.appendChild(opt);
 });

 _pendingStartReversed = !!state.settings.startLineReversed;
 updateStartDirButtons();

 // Pre-fill plan strategy and deep-search iteration budget from settings
 _syncStartPlanSelectForSurveyType();
 const planSel = document.getElementById('start-plan-select');
 if (planSel) {
 const prog = state.settings.progression ||
 (state.settings.surveyType === '3d' ? 'interleaved' : 'auto');
 const desired = (prog === 'auto' && state.settings.optimizerMode === 'nn') ? 'auto-nn' : prog;
 if ([...planSel.options].some(o => o.value === desired && !o.disabled && !o.hidden)) {
  planSel.value = desired;
 } else {
  planSel.value = (state.settings.surveyType === '3d') ? 'interleaved' : 'auto';
 }
 }
 const itEl = document.getElementById('start-iterations');
 if (itEl) itEl.value = state.settings.optimizerIterations || 1500;

 document.getElementById('start-line-chooser').style.display = 'flex';
}

// Persist the chooser'plan strategy + iteration budget into settings.
function _applyChooserPlanSettings() {
 const planSel = document.getElementById('start-plan-select');
 if (planSel && planSel.value) {
  let val = planSel.value;
  // Guard: never apply 3D swath progression while survey is 2D
  if ((state.settings.surveyType || '3d') === '2d' &&
      (val === 'interleaved' || val === 'interleaved-reverse')) {
   val = 'auto';
   showToast('2D plan: swath interleave ignored - using Auto', 3500);
  }
  if (val === 'auto-nn') {
   state.settings.progression = 'auto';
   state.settings.optimizerMode = 'nn';
  } else {
   state.settings.progression = val;
   if (val === 'auto') state.settings.optimizerMode = 'deep';
   // Choosing interleaved implies 3D swath planning
   if (val === 'interleaved' || val === 'interleaved-reverse') {
    state.settings.surveyType = '3d';
    if (typeof updateSurveyTypeIndicator === 'function') updateSurveyTypeIndicator('3d');
   }
  }
 }
 const itEl = document.getElementById('start-iterations');
 const iters = parseInt(itEl && itEl.value, 10);
 if (isFinite(iters) && iters > 0) {
 state.settings.optimizerIterations = Math.min(iters, 20000);
 }
}

function setStartDirection(reversed) {
 _pendingStartReversed = reversed;
 updateStartDirButtons();
}

function updateStartDirButtons() {
 const fwd = document.getElementById('start-dir-fwd');
 const rev = document.getElementById('start-dir-rev');
 if (!fwd || !rev) return;
 if (_pendingStartReversed) {
 rev.style.borderColor = '#00d2ff'; rev.style.color = '#00d2ff';
 fwd.style.borderColor = '#333'; fwd.style.color = '#8a9bb0';
 } else {
 fwd.style.borderColor = '#00d2ff'; fwd.style.color = '#00d2ff';
 rev.style.borderColor = '#333'; rev.style.color = '#8a9bb0';
 }
}

function previewStartLine() {
 const sel = document.getElementById('start-line-select');
 if (!sel || !map) return;
 const idx = parseInt(sel.value);
 const line = state.lines[idx];
 if (line) {
 const pt = _pendingStartReversed ? line.end : line.start;
 map.panTo(pt);
 }
}

function confirmStartLine() {
 const sel = document.getElementById('start-line-select');
 const idx = parseInt(sel.value);
 state.settings.startLineIdx = idx;
 // Record the stable line id so the route solver can resolve the start line
 // regardless of any later line filtering (e.g. Line Manager subsets).
 state.settings.startLineId = (state.lines[idx] || {}).id ?? null;
 state.settings.startLineReversed = _pendingStartReversed;
 // An explicit start line overrides any custom start point.
 state.settings.startPoint = null;
 _applyChooserPlanSettings();
 document.getElementById('start-line-chooser').style.display = 'none';
 _startLineChooserShown = true;
 _syncStartPointPanel();
 executePlanRoute();
}

function skipStartLineChooser() {
 // "Auto": let the optimiser choose the start; clear any explicit start line.
 state.settings.startLineIdx = null;
 state.settings.startLineId = null;
 state.settings.startLineReversed = false;
 _applyChooserPlanSettings();
 document.getElementById('start-line-chooser').style.display = 'none';
 _startLineChooserShown = true;
 executePlanRoute();
}

// ===== LINE MANAGER =====
function closeLineManager() {
 const panel = document.getElementById('panel-line-manager');
 if (panel) {
 panel.style.display = 'none';
 // Undo minimize/maximize so the next open is a normal window
 if (panel._minimized || panel._maximized) {
 panel._minimized = false;
 panel._maximized = false;
 Array.from(panel.children).forEach(ch => { ch.style.display = ''; });
 if (panel._origStyle) {
 panel.style.top = panel._origStyle.top || '';
 panel.style.left = panel._origStyle.left || '';
 panel.style.width = panel._origStyle.width || '';
 panel.style.height = panel._origStyle.height || '';
 panel.style.maxWidth = panel._origStyle.maxWidth || '';
 panel.style.maxHeight = panel._origStyle.maxHeight || '';
 panel.style.minWidth = panel._origStyle.minWidth || '';
 panel.style.transform = panel._origStyle.transform || '';
 }
 }
 }
 if (typeof activePanels !== 'undefined' && activePanels) activePanels.delete('line-manager');
 const ctx = document.getElementById('lm-ctx-menu');
 if (ctx) ctx.remove();
}

function showLineManager() {
 if (!state.lines || state.lines.length === 0) {
 showToast('Load a preplot file first to manage lines');
 return;
 }
 if (!state.lineStatus) state.lineStatus = {};

 // A Line-Manager route plan temporarily replaces state.lines with the routed
 // subset (planned-only lines, partial '-seg' segments). Restore the FULL
 // preplot here so the manager always lists every line irrespective of status.
 if (state._allLines && state._allLines.length) {
 state.lines = state._allLines;
 state._allLines = null;
 renderSurveyLines();
 }

 // Restore saved line defaults if available BEFORE initializing
 _lmLoadDefaults();

 // Initialize any lines that don't have a status after loading defaults
 state.lines.forEach(l => {
 if (!state.lineStatus[l.id]) state.lineStatus[l.id] = { status: 'planned', partialPct: 0, priority: 0 };
 });

 hideAllPanels();
 const panel = document.getElementById('panel-line-manager');
 if (panel) {
 panel.style.display = 'block';
 activePanels.add('line-manager');
 makeDialogInteractive(panel);
 // Ensure Close stays clickable above any drag chrome
 const closeBtn = document.getElementById('lm-close-btn');
 if (closeBtn) {
 closeBtn.style.zIndex = '40';
 closeBtn.style.pointerEvents = 'auto';
 closeBtn.onclick = function(e) { e.stopPropagation(); closeLineManager(); };
 }
 }

 _renderLineManagerList();
 _updateLmInfillDropdowns();
 _updateLmSummary();
}

function _renderLineManagerList() {
 const container = document.getElementById('lm-line-list');
 if (!container) return;
 sanitizeAllLineNames(state.lines);

 container.innerHTML = state.lines.map((line, idx) => {
 const ls = state.lineStatus[line.id] || { status: 'planned', partialPct: 0 };
 const distM = haversine(line.start, line.end);
 const brg = gridBearing(line.start, line.end).toFixed(2);
 const spInt = state.settings.spInterval || 12.5;
 const firstSP = line.spStart || 1;
 const lastSP = line.spEnd || (firstSP + Math.round(distM / spInt));
 const numSP = (lastSP - firstSP) + 1;
 const lineLen = (numSP - 1) * spInt; // N SPs span N-1 intervals
 const dist = (lineLen / 1000).toFixed(2);
 const isPlanned = ls.status === 'planned';
 const isAcquired = ls.status === 'acquired';
 const isPartial = ls.status === 'partial';
 const isPartialInfill = ls.status === 'partial_infill';
 const isInfill = (ls.status === 'infill' || line._infill) && !isPartialInfill;
 // Intended acquisition direction: the user'hard-set lock is shown by the
 // dropdown itself; otherwise show the route planner'chosen direction for
 // this line from the last planned route (state._plannedDir).
 const _pd = (!line._forcedDirection && state._plannedDir) ? state._plannedDir[line.id] : undefined;
 const autoDirLabel = _pd === undefined ? 'Dir: Auto' : `Auto: ${_pd ? 'EOL->SOL' : 'SOL->EOL'}`;
 const rowBg = isAcquired ? '#0a1a0a' : isPartial ? '#1a1a0a' : isPartialInfill ? '#1a0a1a' : isInfill ? '#0a0a1a' : '#0e0e16';
 const borderColor = isAcquired ? '#30d158' : isPartial ? '#f5a623' : isPartialInfill ? '#ff44ff' : isInfill ? '#5ba3d9' : '#1a1a24';

 return `<div style="display:flex;align-items:center;gap:6px;padding:6px 8px;border-bottom:1px solid #1a1a24;background:${rowBg};border-left:3px solid ${borderColor};cursor:default;" data-line-idx="${idx}" oncontextmenu="lmContextMenu(event,${idx})">
 <input type="checkbox" class="lm-check" data-idx="${idx}" ${isPlanned || isInfill || isPartialInfill ? 'checked' : ''} onchange="lmToggleLine(${idx})" style="flex:none;width:16px;height:16px;accent-color:#30d158;cursor:pointer;" />
 <div style="flex:1;min-width:0;">
 <div style="font-size:11px;font-weight:600;color:${isAcquired ? '#30d158' : isPartial ? '#f5a623' : isPartialInfill ? '#ff44ff' : isInfill ? '#5ba3d9' : '#e2e8f0'};">${line.name}${_prioNorm(ls.priority) !== 50 ? ` <span style="color:${_prioNorm(ls.priority) < 50 ? '#ffd60a' : '#8a9bb0'};font-size:9px;">[P${_prioNorm(ls.priority)}]</span>` : ''}${isInfill ? ' <span style="color:#5ba3d9;font-size:9px;">[INFILL]</span>' : ''}${isPartialInfill ? ' <span style="color:#ff44ff;font-size:9px;">[PARTIAL INFILL]</span>' : ''}</div>
 <div style="font-size:9px;color:#666;">${dist} km | ${brg} deg | SP ${firstSP}-${lastSP}</div>
 </div>
 <select onchange="lmSetDirection(${idx}, this.value)" style="padding:3px 4px;background:#0a0a12;border:1px solid ${line._forcedDirection ? '#00d2ff' : '#222'};border-radius:3px;color:${line._forcedDirection ? '#00d2ff' : '#e2e8f0'};font-size:9px;outline:none;width:96px;" title="Acquisition direction: Auto lets the planner choose (intended direction shown once a route is planned); SOL->EOL / EOL->SOL hard-sets it">
 <option value="auto" ${!line._forcedDirection ? 'selected' : ''}>${autoDirLabel}</option>
 <option value="normal" ${line._forcedDirection === 'normal' ? 'selected' : ''}>SOL->EOL</option>
 <option value="reversed" ${line._forcedDirection === 'reversed' ? 'selected' : ''}>EOL->SOL</option>
 </select>
 <select onchange="lmSetStatus(${idx}, this.value)" style="padding:3px 4px;background:#0a0a12;border:1px solid #222;border-radius:3px;color:#e2e8f0;font-size:9px;outline:none;width:90px;">
 <option value="planned" ${isPlanned ? 'selected' : ''}>Planned</option>
 <option value="acquired" ${isAcquired ? 'selected' : ''}>Acquired</option>
 <option value="partial" ${isPartial ? 'selected' : ''}>Partial</option>
 <option value="infill" ${isInfill && !isPartialInfill ? 'selected' : ''}>Infill</option>
 <option value="partial_infill" ${isPartialInfill ? 'selected' : ''}>Partial Infill</option>
 <option value="delete" style="color:#ff453a;">Delete</option>
 </select>
 <input type="number" min="1" max="100" step="1" value="${_prioNorm(ls.priority)}" onchange="lmSetPriority(${idx}, this.value)" style="padding:3px 4px;background:#0a0a12;border:1px solid ${_prioNorm(ls.priority) !== 50 ? (_prioNorm(ls.priority) < 50 ? '#ffd60a' : '#8a9bb0') : '#222'};border-radius:3px;color:#e2e8f0;font-size:9px;outline:none;width:48px;" title="Acquisition priority 1-100: lower numbers acquired FIRST, higher numbers LAST. 50 = Neutral (default)." />
 ${isAcquired || isPartial || isPartialInfill ? `<input type="number" min="1" step="1" value="${ls.seq >= 1 ? ls.seq : ''}" placeholder="Seq" onchange="lmSetSeq(${idx}, this.value)" style="padding:3px 4px;background:#0a0a12;border:1px solid ${ls.seq >= 1 ? '#ffd60a' : '#222'};border-radius:3px;color:${ls.seq >= 1 ? '#ffd60a' : '#e2e8f0'};font-size:9px;outline:none;width:44px;" title="Acquisition sequence number: the order this line was shot in. Drives the Acquired Route display (Layers ' Acquired Route). Clear to remove from the route." />` : ''}
 ${isPartial || isPartialInfill ? `<button onclick="_lmShowSPRangeDialog(${idx})" style="padding:2px 6px;background:${isPartialInfill ? '#1a0a1a' : '#1a1a0a'};border:1px solid ${isPartialInfill ? '#ff44ff' : '#f5a623'};border-radius:3px;color:${isPartialInfill ? '#ff44ff' : '#f5a623'};font-size:9px;cursor:pointer;outline:none;white-space:nowrap;" title="Set SP ranges">${ls.acquiredRanges && ls.acquiredRanges.length > 0 ? ls.acquiredRanges.map(function(r){return r.from+'-'+r.to;}).join(', ') : 'Set SP'}</button>` : ''}
 </div>`;
 }).join('');
}

function _updateLmSummary() {
 const el = document.getElementById('lm-summary');
 if (!el) return;
 const spInt = state.settings.spInterval || 12.5;
 let primePlanned = 0, primeAcquired = 0, primePartial = 0, primeKm = 0;
 let infillCount = 0, infillKm = 0, partialInfillCount = 0;
 state.lines.forEach(l => {
 const s = (state.lineStatus[l.id] || {}).status || 'planned';
 const km = haversine(l.start, l.end) / 1000;
 if (l._infill || s === 'infill' || s === 'partial_infill') {
 infillCount++;
 infillKm += km;
 if (s === 'partial_infill') partialInfillCount++;
 } else {
 primeKm += km;
 if (s === 'planned') primePlanned++;
 else if (s === 'acquired') primeAcquired++;
 else if (s === 'partial') primePartial++;
 }
 });
 const primeTotal = primePlanned + primeAcquired + primePartial;
 let html = `<div style="margin-bottom:4px;"><strong>Prime:</strong> ${primeTotal} lines | ${primeKm.toFixed(1)} km | <span style="color:#30d158;">${primePlanned} planned</span> | <span style="color:#f5a623;">${primePartial} partial</span> | <span style="color:#666;">${primeAcquired} acquired</span></div>`;
 if (infillCount > 0) {
 const pct = primeKm > 0 ? ((infillKm / primeKm) * 100).toFixed(1) : '-';
 html += `<div><strong style="color:#ff44ff;">Infill:</strong> ${infillCount} lines | ${infillKm.toFixed(1)} km <span style="color:#888;">(${pct}% of prime)</span></div>`;
 }
 el.innerHTML = html;
}

function _updateLmInfillDropdowns() {
 const fromEl = document.getElementById('lm-infill-from');
 const toEl = document.getElementById('lm-infill-to');
 if (!fromEl || !toEl) return;
 const opts = state.lines.map((l, i) => `<option value="${i}">${l.name}</option>`).join('');
 fromEl.innerHTML = opts;
 toEl.innerHTML = opts;
 if (state.lines.length > 1) toEl.selectedIndex = 1;
}

function lmToggleLine(idx) {
 const line = state.lines[idx];
 if (!line) return;
 const ls = state.lineStatus[line.id] || { status: 'planned', partialPct: 0 };
 if (ls.status === 'planned') {
 ls.status = 'acquired';
 } else {
 ls.status = 'planned';
 ls.partialPct = 0;
 }
 state.lineStatus[line.id] = ls;
 _renderLineManagerList();
 _updateLmSummary();
 renderSurveyLines();
}

function lmToggleDirection(idx) {
 const line = state.lines[idx];
 if (!line) return;
 lmSetDirection(idx, line._forcedDirection === 'reversed' ? 'normal' : 'reversed');
}

// Hard-set a line'acquisition direction from the Line Manager.
// _forcedDirection tracks the geometry state relative to the preplot file:
// undefined ' Auto: planner/swath settings choose the direction
// 'normal' ' locked SOL->EOL (file direction, geometry unswapped)
// 'reversed' ' locked EOL->SOL (start/end swapped)
// Locked lines are always acquired start'end by the planner (_lineDirLocked).
function lmSetDirection(idx, val) {
 const line = state.lines[idx];
 if (!line) return;
 const geomReversed = line._forcedDirection === 'reversed';
 const wantReversed = val === 'reversed';
 if (geomReversed !== wantReversed) {
 const tmp = line.start;
 line.start = line.end;
 line.end = tmp;
 }
 if (val === 'auto') {
 delete line._forcedDirection;
 showToast(`"${line.name}" direction: Auto (planner / swath setting decides)`);
 } else {
 line._forcedDirection = wantReversed ? 'reversed' : 'normal';
 showToast(`"${line.name}" direction locked: ${wantReversed ? 'EOL->SOL' : 'SOL->EOL'}`);
 }
 renderSurveyLines();
 _renderLineManagerList();
}

// Parse the numeric line number from a line'name (falls back to a default).
// NOTE: matches the first UNSIGNED number - a hyphen in names like
// "INFILL-1234" is a separator, NOT a minus sign. Parsing it as -1234
// scrambled the line-number sort/swath banding whenever infill was present,
// which broke the user-defined swath progression and acquisition directions.
function _lineNumOf(line, fallback) {
 const m = String(line && line.name != null ? line.name : '').match(/\d+(\.\d+)?/);
 return m ? parseFloat(m[0]) : fallback;
}

// Returns the perpendicular bearing to offset an infill line so it sits on the
// side of its parent line that faces the progression'neighbouring line.
// - reverseProg=false (low'high): offset toward the next-higher line number.
// - reverseProg=true (high'low): offset toward the next-lower line number.
// Falls back to (bearing + 90) when no numbered neighbour can be found.
function _infillOffsetBearing(parentLine, brg, reverseProg) {
 const perpA = (brg + 90) % 360;
 const perpB = (brg + 270) % 360;
 const parentNum = _lineNumOf(parentLine, null);
 if (parentNum == null) return perpA;

 // Find the nearest neighbour line in the progression direction by number.
 let neighbour = null, bestDiff = Infinity;
 state.lines.forEach(l => {
 if (l === parentLine || l._infill) return;
 const num = _lineNumOf(l, null);
 if (num == null) return;
 const diff = reverseProg ? (parentNum - num) : (num - parentNum);
 if (diff > 0 && diff < bestDiff) { bestDiff = diff; neighbour = l; }
 });
 if (!neighbour) return perpA;

 const pMid = [(parentLine.start[0] + parentLine.end[0]) / 2, (parentLine.start[1] + parentLine.end[1]) / 2];
 const nMid = [(neighbour.start[0] + neighbour.end[0]) / 2, (neighbour.start[1] + neighbour.end[1]) / 2];
 const toward = bearing(pMid, nMid);
 const angDiff = (a, b) => { const d = Math.abs(a - b) % 360; return d > 180 ? 360 - d : d; };
 return angDiff(perpA, toward) <= angDiff(perpB, toward) ? perpA : perpB;
}

function lmSetStatus(idx, status) {
 const line = state.lines[idx];
 if (!line) return;
 const existing = state.lineStatus[line.id] || {};

 if (status === 'delete') {
 // Confirm before deleting
 if (confirm(`Are you sure you want to delete line "${line.name}"?`)) {
 state.lines.splice(idx, 1);
 delete state.lineStatus[line.id];
 if (line._infill) _lmPurgeInfillDefaults(new Set([line.id]));
 renderSurveyLines();
 _renderLineManagerList();
 _updateLmSummary();
 _updateLmInfillDropdowns();
 showToast(`Line "${line.name}" deleted`);
 } else {
 // User cancelled - revert dropdown
 _renderLineManagerList();
 }
 return;
 }

 if (status === 'infill' || status === 'partial_infill') {
 // Create a new infill line adjacent to the selected line
 _showInfillDirectionDialog(line, function(direction) {
 if (!direction) {
 // User cancelled - revert dropdown
 _renderLineManagerList();
 return;
 }
 
 // Swath progression: low'high lists/plots the infill AFTER (toward the
 // next line), high'low BEFORE (toward the previous line).
 const reverseProg = ['high-low', 'interleaved-reverse', 'east-west', 'north-south']
 .includes(state.settings.progression);

 // Calculate offset for infill line (default 50m perpendicular offset).
 // Choose the perpendicular side that points toward the progression's
 // neighbouring line so the map plot matches the list order.
 const offset = 50;
 const brg = bearing(line.start, line.end);
 let perpBrg = _infillOffsetBearing(line, brg, reverseProg);
 let start = destinationPoint(line.start, perpBrg, offset);
 let end = destinationPoint(line.end, perpBrg, offset);
 
 // Apply direction
 if (direction === 'opposite') {
 const tmp = start;
 start = end;
 end = tmp;
 }
 
 const infillName = sanitizeLineName(`INFILL-${line.name}`, 'INFILL');
 const infillLine = {
 id: `infill-${Date.now()}`,
 name: infillName,
 start,
 end,
 _infill: true,
 _infillDirection: direction,
 _parentLineId: line.id
 };
 
 // Insert the infill line adjacent to its parent line based on swath
 // progression: low'high lists it AFTER the parent, high'low BEFORE.
 // This keeps the Line Manager listing and the map plot order consistent.
 const srcIdx = state.lines.indexOf(line);
 const insertAt = srcIdx < 0 ? state.lines.length : (reverseProg ? srcIdx : srcIdx + 1);
 state.lines.splice(insertAt, 0, infillLine);
 state.lineStatus[infillLine.id] = { status: 'planned', partialPct: 0, priority: 0 };
 
 // If partial infill, show SP range dialog for the new line
 if (status === 'partial_infill') {
 state.lineStatus[infillLine.id] = { status: 'partial', partialPct: 0, acquiredRanges: [], priority: 0 };
 setTimeout(() => {
 const newIdx = state.lines.findIndex(l =>l.id === infillLine.id);
 if (newIdx >= 0) _lmShowSPRangeDialog(newIdx);
 }, 100);
 }
 
 renderSurveyLines();
 _renderLineManagerList();
 _updateLmSummary();
 _updateLmInfillDropdowns();
 showToast(`Infill line "${infillName}" added (${direction} direction)`);
 });
 return;
 }

 // Clear infill flag when changing back to non-infill status
 if (line._infill && status !== 'infill' && status !== 'partial_infill') {
 line._infill = false;
 delete line._infillDirection;
 }

 state.lineStatus[line.id] = { status, partialPct: existing.partialPct || 0, acquiredRanges: existing.acquiredRanges || [], priority: existing.priority || 0, seq: existing.seq };
 // Auto-assign the next acquisition sequence number so the acquired-route
 // display works out of the box; the user can edit it in the Seq column.
 if ((status === 'acquired' || status === 'partial' || status === 'partial_infill') && !(existing.seq >= 1)) {
 let maxSeq = 0;
 Object.values(state.lineStatus).forEach(s => { if (s && s.seq >maxSeq) maxSeq = s.seq; });
 state.lineStatus[line.id].seq = maxSeq + 1;
 }
 _renderLineManagerList();
 _updateLmSummary();
 renderSurveyLines();
 if (status === 'partial') _lmShowSPRangeDialog(idx);
}

// Set / clear the acquisition sequence number of a line (orders the line in
// the acquired-route display - Layers ' Acquired Route).
function lmSetSeq(idx, val) {
 const line = state.lines[idx];
 if (!line) return;
 const ls = state.lineStatus[line.id] || (state.lineStatus[line.id] = { status: 'planned', partialPct: 0 });
 const n = parseInt(val, 10);
 if (isFinite(n) && n >= 1) ls.seq = n; else delete ls.seq;
 _renderLineManagerList();
 renderAcquiredRoute();
}

function lmSetPriority(idx, priority) {
 const line = state.lines[idx];
 if (!line) return;
 const existing = state.lineStatus[line.id] || {};
 let priorityNum = parseInt(priority, 10);
 if (isNaN(priorityNum)) priorityNum = 50;
 priorityNum = Math.max(1, Math.min(100, priorityNum));
 state.lineStatus[line.id] = { status: existing.status || 'planned', partialPct: existing.partialPct || 0, acquiredRanges: existing.acquiredRanges || [], priority: priorityNum, seq: existing.seq };
 _renderLineManagerList();
 _updateLmSummary();
}

// Normalize a stored priority to the 1-100 scale. 50 = Neutral (default).
// Lower numbers are acquired FIRST, higher numbers LAST. Legacy values - // unset / 0 (old "Neutral") - map to 50; old 1-5 remain valid (high priority).
function _prioNorm(p) {
 return (p >= 1 && p <= 100) ? p : 50;
}

function _showInfillDirectionDialog(line, callback) {
 const existing = document.getElementById('infill-direction-dialog');
 if (existing) existing.remove();

 const overlay = document.createElement('div');
 overlay.id = 'infill-direction-dialog';
 overlay.style.cssText = 'position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,0.6);z-index:99999;display:flex;align-items:center;justify-content:center;';

 const dlg = document.createElement('div');
 dlg.style.cssText = 'background:#0e0e16;border:1px solid #5ba3d9;border-radius:8px;padding:24px 28px;min-width:320px;max-width:400px;color:#fff;font-family:inherit;box-shadow:0 8px 32px rgba(0,0,0,0.8);';
 dlg.innerHTML = `
 <div style="font-size:13px;font-weight:700;color:#5ba3d9;margin-bottom:6px;">Infill Direction</div>
 <div style="font-size:11px;color:#a0aebb;margin-bottom:16px;">Select the direction of acquisition for infill line <b style="color:#fff;">"${line.name}"</b>:</div>
 <div style="display:flex;flex-direction:column;gap:8px;margin-bottom:16px;">
 <button class="infill-dir-btn" data-dir="same" style="padding:10px 14px;border-radius:4px;border:1px solid #333;background:#1a1a2e;color:#e2e8f0;font-size:12px;cursor:pointer;text-align:left;outline:none;transition:background 0.15s;">>Same as swath direction</button>
 <button class="infill-dir-btn" data-dir="auto" style="padding:10px 14px;border-radius:4px;border:1px solid #333;background:#1a1a2e;color:#e2e8f0;font-size:12px;cursor:pointer;text-align:left;outline:none;transition:background 0.15s;">Y3 Auto</button>
 <button class="infill-dir-btn" data-dir="opposite" style="padding:10px 14px;border-radius:4px;border:1px solid #333;background:#1a1a2e;color:#e2e8f0;font-size:12px;cursor:pointer;text-align:left;outline:none;transition:background 0.15s;">< Opposite to swath direction</button>
 </div>
 <div style="text-align:right;">
 <button class="infill-dir-cancel" style="padding:6px 18px;border-radius:4px;border:1px solid #333;background:transparent;color:#888;font-size:11px;cursor:pointer;outline:none;">Cancel</button>
 </div>`;

 overlay.appendChild(dlg);
 document.body.appendChild(overlay);

 dlg.querySelectorAll('.infill-dir-btn').forEach(function(btn) {
 btn.onmouseover = function() { btn.style.background = '#2a2a3e'; btn.style.borderColor = '#5ba3d9'; };
 btn.onmouseout = function() { btn.style.background = '#1a1a2e'; btn.style.borderColor = '#333'; };
 btn.onclick = function() {
 overlay.remove();
 callback(btn.getAttribute('data-dir'));
 };
 });

 dlg.querySelector('.infill-dir-cancel').onclick = function() {
 overlay.remove();
 callback(null);
 };

 overlay.onclick = function(e) {
 if (e.target === overlay) {
 overlay.remove();
 callback(null);
 }
 };
}

function lmSetPartial(idx, pct) {
 const line = state.lines[idx];
 if (!line) return;
 // Legacy - open SP range dialog instead
 _lmShowSPRangeDialog(idx);
}

function lmSelectAll() {
 state.lines.forEach(l => { state.lineStatus[l.id] = { status: 'planned', partialPct: 0, priority: 0 }; });
 _renderLineManagerList();
 _updateLmSummary();
 renderSurveyLines();
}

function lmDeselectAll() {
 state.lines.forEach(l => { state.lineStatus[l.id] = { status: 'acquired', partialPct: 0, priority: 0 }; });
 _renderLineManagerList();
 _updateLmSummary();
 renderSurveyLines();
}

function lmMarkSelectedAcquired() {
 document.querySelectorAll('.lm-check:checked').forEach(cb => {
 const idx = parseInt(cb.dataset.idx);
 const line = state.lines[idx];
 if (line) state.lineStatus[line.id] = { status: 'acquired', partialPct: 0, priority: 0 };
 });
 _renderLineManagerList();
 _updateLmSummary();
 renderSurveyLines();
}

function lmResetAllPriorities() {
 let changed = 0;
 const pool = (state._allLines && state._allLines.length) ? state._allLines : state.lines;
 pool.forEach(l => {
 const ls = state.lineStatus[l.id];
 if (ls && _prioNorm(ls.priority) !== 50) { ls.priority = 50; changed++; }
 });
 _renderLineManagerList();
 _updateLmSummary();
 showToast(changed > 0 ? `${changed} line prioritie(s) reset to Neutral` : 'All lines already at Neutral priority');
}

function lmResetAll() {
 if (!confirm('Reset all prime lines to "Planned" status? This cannot be undone.')) return;
 state.lines.forEach(l => {
 if (!l._infill) {
 state.lineStatus[l.id] = { status: 'planned', partialPct: 0, priority: 0 };
 }
 });
 _renderLineManagerList();
 _updateLmSummary();
 renderSurveyLines();
 showToast('All prime lines reset to Planned');
}

function lmRemoveAllInfill() {
 const infill = state.lines.filter(l =>l._infill);
 if (infill.length === 0) {
 showToast('No infill lines to remove');
 return;
 }
 if (!confirm(`Remove ${infill.length} infill line(s) from the list and plan? This cannot be undone.`)) return;
 const removedIds = new Set(infill.map(l =>l.id));
 state.lines = state.lines.filter(l => !l._infill);
 removedIds.forEach(id =>delete state.lineStatus[id]);
 // Also purge them from the saved Line-Manager defaults, otherwise
 // _lmLoadDefaults() silently reintroduces them next time the panel opens.
 _lmPurgeInfillDefaults(removedIds);
 _renderLineManagerList();
 _updateLmSummary();
 _updateLmInfillDropdowns();
 renderSurveyLines();
 showToast(`${infill.length} infill line(s) removed`);
}

// Remove the given infill line ids (or ALL infill when ids is null) from the
// saved Line-Manager defaults in localStorage. Without this, removed infill
// lines are reintroduced by _lmLoadDefaults() every time the panel opens.
function _lmPurgeInfillDefaults(removedIds) {
 try {
 const raw = localStorage.getItem('candooka_line_manager_defaults');
 if (!raw) return;
 const data = JSON.parse(raw);
 if (!data) return;
 if (Array.isArray(data.infillLines)) {
 data.infillLines = removedIds
 ? data.infillLines.filter(l =>l && !removedIds.has(l.id))
 : [];
 }
 if (data.lineStatus && removedIds) {
 removedIds.forEach(id =>delete data.lineStatus[id]);
 }
 localStorage.setItem('candooka_line_manager_defaults', JSON.stringify(data));
 } catch (e) {}
}

function lmMarkAllAcquired() {
 if (!confirm('Mark all lines as "Acquired"? This cannot be undone.')) return;
 state.lines.forEach(l => {
 state.lineStatus[l.id] = { status: 'acquired', partialPct: 0, priority: 0 };
 });
 _renderLineManagerList();
 _updateLmSummary();
 renderSurveyLines();
 showToast('All lines marked as Acquired');
}

function lmSaveAsDefault() {
 const data = {
 lineStatus: { ...state.lineStatus },
 infillLines: state.lines.filter(l =>l._infill).map(l => ({
 id: l.id, name: l.name, start: l.start, end: l.end, _infill: true
 })),
 savedAt: new Date().toISOString()
 };
 localStorage.setItem('candooka_line_manager_defaults', JSON.stringify(data));
 showToast('Line statuses and infill lines saved as defaults.');
}

function _lmLoadDefaults() {
 try {
 const data = JSON.parse(localStorage.getItem('candooka_line_manager_defaults') || 'null');
 if (!data) return;
 // Restore line statuses for matching line IDs
 if (data.lineStatus) {
 Object.keys(data.lineStatus).forEach(id => {
 if (state.lineStatus[id] !== undefined || state.lines.some(l =>l.id == id)) {
 state.lineStatus[id] = data.lineStatus[id];
 }
 });
 }
 // Restore infill lines if not already present
 if (data.infillLines && data.infillLines.length > 0) {
 data.infillLines.forEach(inf => {
 if (!state.lines.some(l =>l.id === inf.id)) {
 state.lines.push(inf);
 if (!state.lineStatus[inf.id]) state.lineStatus[inf.id] = { status: 'planned', partialPct: 0, priority: 0 };
 }
 });
 }
 } catch(e) {}
}

// ===== INFILL PANEL (Tier 2) =====
function openInfillPanel() {
 if (!state.lines || state.lines.length < 2) { showToast('Load at least 2 survey lines first'); return; }
 let dlg = document.getElementById('infill-panel-dialog');
 if (dlg) { dlg.style.display = dlg.style.display === 'none' ? 'block' : 'none'; if (dlg.style.display === 'block') _refreshInfillPanel(dlg); return; }
 dlg = document.createElement('div');
 dlg.id = 'infill-panel-dialog';
 dlg.style.cssText = 'position:fixed;top:50%;left:50%;transform:translate(-50%,-50%);background:#0e0e16;border:1px solid #ff44ff;border-radius:8px;padding:24px 28px;z-index:9999;min-width:440px;max-width:540px;max-height:85vh;overflow-y:auto;box-shadow:0 8px 32px rgba(0,0,0,0.8);color:#fff;font-family:inherit;';
 document.body.appendChild(dlg);
 _refreshInfillPanel(dlg);
 makeDialogInteractive(dlg);
}

function _refreshInfillPanel(dlg) {
 const lines = state.lines;
 const infillLines = lines.filter(l =>l._infill);
 const nonInfill = lines.filter(l => !l._infill);
 const opts = nonInfill.map((l, i) => {
 const origIdx = lines.indexOf(l);
 return `<option value="${origIdx}">${l.name}</option>`;
 }).join('');

 dlg.innerHTML = `
 <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:14px;">
 <div style="font-size:13px;font-weight:700;color:#ff44ff;letter-spacing:0.5px;">INFILL LINES</div>
 <button onclick="document.getElementById('infill-panel-dialog').style.display='none'" style="background:none;border:none;color:#666;font-size:16px;cursor:pointer;">x</button>
 </div>
 <div style="font-size:10px;color:#a0aebb;margin-bottom:12px;">Add infill lines between existing survey lines. Infill lines appear in <span style="color:#ff44ff;font-weight:700;">magenta</span>.</div>
 <div style="font-size:9px;color:#5a6a7a;font-weight:600;letter-spacing:0.4px;margin-bottom:6px;text-transform:uppercase;">Add Infill Between Lines</div>
 <div class="panel-row" style="margin-bottom:8px;">
 <label style="width:80px;color:#fff;">From</label>
 <select id="infill-p-from" style="flex:1;padding:5px 8px;border-radius:4px;border:1px solid #222;background:#111;color:#fff;font-size:11px;outline:none;">${opts}</select>
 </div>
 <div class="panel-row" style="margin-bottom:8px;">
 <label style="width:80px;color:#fff;">To</label>
 <select id="infill-p-to" style="flex:1;padding:5px 8px;border-radius:4px;border:1px solid #222;background:#111;color:#fff;font-size:11px;outline:none;">${opts}</select>
 </div>
 <div class="panel-row" style="margin-bottom:10px;">
 <label style="width:80px;color:#fff;">Offset (m)</label>
 <input id="infill-p-offset" type="number" value="0" step="10" style="flex:1;padding:5px 8px;border-radius:4px;border:1px solid #222;background:#111;color:#fff;font-size:12px;outline:none;" placeholder="0 = midpoint"/>
 </div>
 <button onclick="_infillPanelAdd()" style="width:100%;padding:8px;border-radius:4px;border:none;background:#ff44ff;color:#000;font-weight:700;cursor:pointer;font-size:12px;margin-bottom:14px;">Add Infill Line</button>
 ${infillLines.length > 0 ? `
 <div style="font-size:9px;color:#5a6a7a;font-weight:600;letter-spacing:0.4px;margin:8px 0 6px 0;text-transform:uppercase;">Current Infill Lines (${infillLines.length})</div>
 <div style="max-height:180px;overflow-y:auto;border:1px solid #222;border-radius:4px;background:#0a0a12;">
 ${infillLines.map(l => `<div style="display:flex;justify-content:space-between;align-items:center;padding:6px 10px;border-bottom:1px solid #1a1a24;">
 <span style="color:#ff44ff;font-size:11px;font-weight:600;">${l.name}</span>
 <button onclick="_infillPanelRemove('${l.id}')" style="background:none;border:1px solid #ff453a;color:#ff453a;font-size:9px;padding:2px 8px;border-radius:3px;cursor:pointer;">Remove</button>
 </div>`).join('')}
 </div>
 <button onclick="_infillPanelClearAll()" style="width:100%;padding:6px;border-radius:4px;border:1px solid #ff453a;background:transparent;color:#ff453a;font-weight:600;cursor:pointer;font-size:11px;margin-top:8px;">Remove All Infill Lines</button>
 ` : '<div style="font-size:10px;color:#5a6a7a;margin-top:6px;text-align:center;">No infill lines added yet.</div>'}
 <div style="margin-top:12px;text-align:center;"><button onclick="document.getElementById('infill-panel-dialog').style.display='none'" style="padding:6px 20px;border-radius:4px;border:1px solid #333;background:#1a1a2e;color:#e0e8f0;cursor:pointer;font-size:11px;">Close</button></div>`;

 // Default the "To" dropdown to second line if available
 const toEl = document.getElementById('infill-p-to');
 if (toEl && toEl.options.length > 1) toEl.selectedIndex = 1;
}

function _infillPanelAdd() {
 const fromIdx = parseInt(document.getElementById('infill-p-from').value);
 const toIdx = parseInt(document.getElementById('infill-p-to').value);
 const offset = parseFloat(document.getElementById('infill-p-offset').value) || 0;
 // Reuse existing lmAddInfillLine logic
 const origFrom = document.getElementById('lm-infill-from');
 const origTo = document.getElementById('lm-infill-to');
 const origOff = document.getElementById('lm-infill-offset');
 // Directly call the core logic
 const lineA = state.lines[fromIdx];
 const lineB = state.lines[toIdx];
 if (!lineA || !lineB) { showToast('Select two valid lines'); return; }
 if (fromIdx === toIdx) { showToast('Select two different lines'); return; }

 const midStart = [(lineA.start[0] + lineB.start[0]) / 2, (lineA.start[1] + lineB.start[1]) / 2];
 const midEnd = [(lineA.end[0] + lineB.end[0]) / 2, (lineA.end[1] + lineB.end[1]) / 2];
 let start = midStart, end = midEnd;
 if (offset !== 0) {
 const brg = bearing(midStart, midEnd);
 const perpBrg = (brg + 90) % 360;
 start = destinationPoint(midStart, perpBrg, offset);
 end = destinationPoint(midEnd, perpBrg, offset);
 }
 const infillName = sanitizeLineName(`INFILL-${lineA.name}/${lineB.name}`, 'INFILL');
 const infillLine = { id: `infill-${Date.now()}`, name: infillName, start, end, _infill: true };
 // Place the infill line between its two parent lines in the listing/map order.
 state.lines.splice(Math.min(fromIdx, toIdx) + 1, 0, infillLine);
 state.lineStatus[infillLine.id] = { status: 'planned', partialPct: 0, priority: 0 };
 renderSurveyLines();
 if (typeof _renderLineManagerList === 'function') { _renderLineManagerList(); _updateLmSummary(); _updateLmInfillDropdowns(); }
 _refreshInfillPanel(document.getElementById('infill-panel-dialog'));
 showToast(`Infill "${infillName}" added`);
}

function _infillPanelRemove(id) {
 const idx = state.lines.findIndex(l =>l.id === id);
 if (idx >= 0) {
 const name = state.lines[idx].name;
 state.lines.splice(idx, 1);
 delete state.lineStatus[id];
 _lmPurgeInfillDefaults(new Set([id]));
 renderSurveyLines();
 if (typeof _renderLineManagerList === 'function') { _renderLineManagerList(); _updateLmSummary(); _updateLmInfillDropdowns(); }
 _refreshInfillPanel(document.getElementById('infill-panel-dialog'));
 showToast(`Removed "${name}"`);
 }
}

function _infillPanelClearAll() {
 if (!confirm('Remove all infill lines?')) return;
 const removedIds = new Set(state.lines.filter(l =>l._infill).map(l =>l.id));
 state.lines = state.lines.filter(l => !l._infill);
 removedIds.forEach(id =>delete state.lineStatus[id]);
 _lmPurgeInfillDefaults(removedIds);
 renderSurveyLines();
 if (typeof _renderLineManagerList === 'function') { _renderLineManagerList(); _updateLmSummary(); _updateLmInfillDropdowns(); }
 _refreshInfillPanel(document.getElementById('infill-panel-dialog'));
 showToast('All infill lines removed');
}

function lmAddInfillLine() {
 const fromIdx = parseInt(document.getElementById('lm-infill-from').value);
 const toIdx = parseInt(document.getElementById('lm-infill-to').value);
 const offset = parseFloat(document.getElementById('lm-infill-offset').value) || 0;
 const lineA = state.lines[fromIdx];
 const lineB = state.lines[toIdx];
 if (!lineA || !lineB) { showToast('Select two valid lines'); return; }

 // Infill line is midpoint between the two lines, optionally offset
 const midStart = [(lineA.start[0] + lineB.start[0]) / 2, (lineA.start[1] + lineB.start[1]) / 2];
 const midEnd = [(lineA.end[0] + lineB.end[0]) / 2, (lineA.end[1] + lineB.end[1]) / 2];

 // Apply perpendicular offset if specified
 let start = midStart, end = midEnd;
 if (offset !== 0) {
 const brg = bearing(midStart, midEnd);
 const perpBrg = (brg + 90) % 360;
 start = destinationPoint(midStart, perpBrg, offset);
 end = destinationPoint(midEnd, perpBrg, offset);
 }

 const infillName = sanitizeLineName(`INFILL-${lineA.name}/${lineB.name}`, 'INFILL');
 const infillLine = {
 id: `infill-${Date.now()}`,
 name: infillName,
 start, end,
 _infill: true
 };
 // Place the infill line between its two parent lines in the listing/map order.
 state.lines.splice(Math.min(fromIdx, toIdx) + 1, 0, infillLine);
 state.lineStatus[infillLine.id] = { status: 'planned', partialPct: 0, priority: 0 };

 renderSurveyLines();
 _renderLineManagerList();
 _updateLmSummary();
 _updateLmInfillDropdowns();
 showToast(`Infill line "${infillName}" added`);
}

function lmContextMenu(event, idx) {
 event.preventDefault();
 event.stopPropagation();
 // Remove any existing context menu
 const existing = document.getElementById('lm-ctx-menu');
 if (existing) existing.remove();

 const line = state.lines[idx];
 if (!line) return;
 const ls = state.lineStatus[line.id] || { status: 'planned', partialPct: 0 };

 const menu = document.createElement('div');
 menu.id = 'lm-ctx-menu';
 menu.style.cssText = `position:fixed;z-index:99999;
 background:#0e0e16;border:1px solid #333;border-radius:6px;padding:4px 0;min-width:180px;
 box-shadow:0 8px 32px rgba(0,0,0,0.8);font-size:11px;color:#e2e8f0;`;

 const distM = haversine(line.start, line.end);
 const spInt = state.settings.spInterval || 12.5;
 const firstSP = line.spStart || 1;
 const lastSP = line.spEnd || (firstSP + Math.round(distM / spInt));
 const totalLineSP = (lastSP - firstSP) + 1;
 const dist = ((totalLineSP - 1) * spInt / 1000).toFixed(2); // N SPs span N-1 intervals
 const acquiredRanges = ls.acquiredRanges || [];
 const acquiredSPCount = acquiredRanges.reduce((sum, r) =>sum + (r.to - r.from + 1), 0);
 const remainingSP = totalLineSP - acquiredSPCount;

 const items = [
 { label: 'Zoom to Line', action: () => { if (map) map.fitBounds([line.start, line.end], { padding: [60, 60] }); } },
 { label: 'Copy Coordinates', action: () => { navigator.clipboard.writeText(`${line.start[0].toFixed(6)}, ${line.start[1].toFixed(6)} - ${line.end[0].toFixed(6)}, ${line.end[1].toFixed(6)}`); showToast('Coordinates copied'); } },
 { header: true, label: `${sanitizeLineName(line.name, 'Line')} | SP ${firstSP}-${lastSP} (${totalLineSP}) | ${dist} km` },
 { label: 'Planned (full line needed)', action: () => { lmSetStatus(idx, 'planned'); }, disabled: ls.status === 'planned' },
 { label: 'Acquired (all SP - exclude from route)', action: () => { lmSetStatus(idx, 'acquired'); }, disabled: ls.status === 'acquired' },
 { header: true, label: `Acquired SP Ranges (${acquiredSPCount}/${totalLineSP} SP)` },
 { label: 'Set acquired SP range...', action: () => { _lmShowSPRangeDialog(idx); } },
 ];

 if (acquiredRanges.length > 0) {
 acquiredRanges.forEach((r, ri) => {
 items.push({ label: `SP ${r.from}-${r.to} (${r.to - r.from + 1} SP) - remove`, action: () => { _lmRemoveAcquiredRange(idx, ri); } });
 });
 items.push({ label: `${remainingSP} SP remaining to acquire`, disabled: true });
 }

 items.push({ header: true, label: 'Edit Line' });
 items.push({ label: 'Reverse Direction', action: () => { lmToggleDirection(idx); } });
 items.push({ label: 'Split at SP...', action: () => { _lmPromptSplitSP(idx, totalLineSP); } });
 items.push({ label: 'Trim from start (SOL)...', action: () => { _lmPromptTrimSP(idx, 'start', totalLineSP); } });
 items.push({ label: 'Trim from end (EOL)...', action: () => { _lmPromptTrimSP(idx, 'end', totalLineSP); } });

 if (line._infill) {
 items.push({ header: true, label: 'Infill' });
 items.push({ label: 'Remove Infill Line', action: () => { state.lines.splice(idx, 1); delete state.lineStatus[line.id]; renderSurveyLines(); _renderLineManagerList(); _updateLmSummary(); _updateLmInfillDropdowns(); showToast('Infill line removed'); } });
 }

 items.forEach(item => {
 if (item.divider) {
 const hr = document.createElement('div');
 hr.style.cssText = 'height:1px;background:#222;margin:4px 0;';
 menu.appendChild(hr);
 return;
 }
 if (item.header) {
 const hdr = document.createElement('div');
 hdr.textContent = item.label;
 hdr.style.cssText = 'padding:4px 14px;font-size:9px;color:#5a6a7a;font-weight:700;letter-spacing:0.3px;pointer-events:none;';
 menu.appendChild(hdr);
 return;
 }
 const btn = document.createElement('div');
 btn.textContent = item.label;
 btn.style.cssText = `padding:6px 14px;cursor:pointer;white-space:nowrap;transition:background 0.1s;font-size:11px;${item.disabled ? 'opacity:0.3;pointer-events:none;' : ''}`;
 btn.onmouseover = () => { if (!item.disabled) btn.style.background = '#1a1a2e'; };
 btn.onmouseout = () => { btn.style.background = 'transparent'; };
 btn.onclick = () => { menu.remove(); item.action(); };
 menu.appendChild(btn);
 });

 // Temporarily show menu to measure dimensions after items are added
 menu.style.visibility = 'hidden';
 menu.style.display = 'block';
 document.body.appendChild(menu);
 const menuWidth = menu.offsetWidth;
 const menuHeight = menu.offsetHeight;
 menu.style.visibility = '';
 menu.style.display = '';

 // Calculate position to keep menu within window bounds
 const windowWidth = window.innerWidth;
 const windowHeight = window.innerHeight;
 let top = event.clientY;
 let left = event.clientX;

 // Check right edge
 if (left + menuWidth >windowWidth) {
 left = windowWidth - menuWidth - 10;
 }

 // Check bottom edge
 if (top + menuHeight >windowHeight) {
 top = windowHeight - menuHeight - 10;
 }

 // Ensure menu doesn't go off top or left
 if (top < 10) top = 10;
 if (left < 10) left = 10;

 menu.style.top = top + 'px';
 menu.style.left = left + 'px';

 // Close on click outside
 const closeHandler = (e) => {
 if (!menu.contains(e.target)) { menu.remove(); document.removeEventListener('click', closeHandler); }
 };
 setTimeout(() =>document.addEventListener('click', closeHandler), 10);
}

function _lmSplitLine(idx, pct) {
 const line = state.lines[idx];
 if (!line) return;
 const frac = pct / 100;
 const midPt = [
 line.start[0] + (line.end[0] - line.start[0]) * frac,
 line.start[1] + (line.end[1] - line.start[1]) * frac
 ];
 // Create two lines from the split
 const line1 = { id: line.id + '-A', name: sanitizeLineName(line.name + '-A', 'Line-A'), start: line.start, end: midPt, _infill: line._infill };
 const line2 = { id: line.id + '-B', name: sanitizeLineName(line.name + '-B', 'Line-B'), start: midPt, end: line.end, _infill: line._infill };
 state.lines.splice(idx, 1, line1, line2);
 state.lineStatus[line1.id] = { status: 'planned', partialPct: 0, priority: 0 };
 state.lineStatus[line2.id] = { status: 'planned', partialPct: 0, priority: 0 };
 delete state.lineStatus[line.id];
 renderSurveyLines();
 _renderLineManagerList();
 _updateLmSummary();
 _updateLmInfillDropdowns();
 showToast(`"${line.name}" split into two lines`);
}

function _lmAddInfillAdjacent(idx) {
 const line = state.lines[idx];
 if (!line) return;
 // Find next line for infill reference
 const nextIdx = idx + 1 < state.lines.length ? idx + 1 : idx - 1;
 if (nextIdx < 0) { showToast('Need at least 2 lines for infill'); return; }
 const nextLine = state.lines[nextIdx];
 const midStart = [(line.start[0] + nextLine.start[0]) / 2, (line.start[1] + nextLine.start[1]) / 2];
 const midEnd = [(line.end[0] + nextLine.end[0]) / 2, (line.end[1] + nextLine.end[1]) / 2];
 const infillName = sanitizeLineName(`INFILL-${line.name}/${nextLine.name}`, 'INFILL');
 const infillLine = { id: `infill-${Date.now()}`, name: infillName, start: midStart, end: midEnd, _infill: true };
 state.lines.splice(idx + 1, 0, infillLine);
 state.lineStatus[infillLine.id] = { status: 'planned', partialPct: 0, priority: 0 };
 renderSurveyLines();
 _renderLineManagerList();
 _updateLmSummary();
 _updateLmInfillDropdowns();
 showToast(`Infill "${infillName}" added`);
}

function _lmShowSPRangeDialog(idx) {
 const line = state.lines[idx];
 if (!line) return;
 const ls = state.lineStatus[line.id] || { status: 'planned', partialPct: 0 };
 const spInt = state.settings.spInterval || 12.5;
 const firstSP = line.spStart || 1;
 const lastSP = line.spEnd || (firstSP + Math.round(haversine(line.start, line.end) / spInt));
 const totalSP = (lastSP - firstSP) + 1;
 const existing = ls.acquiredRanges || [];

 const input = prompt(
 `"${line.name}" - ${totalSP} total SP (SP ${firstSP} to ${lastSP})\n\n` +
 `Enter acquired SP ranges (comma-separated):\n` +
 `e.g. ${firstSP}-${firstSP + Math.round(totalSP/2)}, ${lastSP - 200}-${lastSP}\n\n` +
 (existing.length > 0 ? `Current: ${existing.map(r =>r.from + '-' + r.to).join(', ')}\n` : '') +
 `This ADDS to existing ranges. Enter ranges to add:`,
 ''
 );
 if (!input || !input.trim()) return;

 const newRanges = _parseSPRanges(input, lastSP);
 if (newRanges.length === 0) { showToast('Invalid SP range format. Use e.g. 1-500, 800-1200'); return; }

 if (!state.lineStatus[line.id]) state.lineStatus[line.id] = { status: 'planned', partialPct: 0 };
 const merged = _mergeSPRanges([...existing, ...newRanges]);
 state.lineStatus[line.id].acquiredRanges = merged;
 state.lineStatus[line.id].status = 'partial';
 // Update partialPct for backward compat with rendering
 const acquiredCount = merged.reduce((s, r) =>s + (r.to - r.from + 1), 0);
 state.lineStatus[line.id].partialPct = Math.round((acquiredCount / totalSP) * 100);

 renderSurveyLines();
 _renderLineManagerList();
 _updateLmSummary();
 showToast(`"${line.name}": ${merged.length} acquired range(s), ${totalSP - acquiredCount} SP remaining`);
}

function _lmRemoveAcquiredRange(idx, rangeIdx) {
 const line = state.lines[idx];
 if (!line) return;
 const ls = state.lineStatus[line.id];
 if (!ls || !ls.acquiredRanges) return;
 ls.acquiredRanges.splice(rangeIdx, 1);
 if (ls.acquiredRanges.length === 0) {
 ls.status = 'planned';
 ls.partialPct = 0;
 } else {
 const spInt = state.settings.spInterval || 12.5;
 const firstSP = line.spStart || 1;
 const lastSP = line.spEnd || (firstSP + Math.round(haversine(line.start, line.end) / spInt));
 const totalSP = (lastSP - firstSP) + 1;
 const acquiredCount = ls.acquiredRanges.reduce((s, r) =>s + (r.to - r.from + 1), 0);
 ls.partialPct = Math.round((acquiredCount / totalSP) * 100);
 }
 renderSurveyLines();
 _renderLineManagerList();
 _updateLmSummary();
 showToast('SP range removed');
}

function _parseSPRanges(text, maxSP) {
 const ranges = [];
 const parts = text.split(',').map(s =>s.trim()).filter(Boolean);
 for (const part of parts) {
 const m = part.match(/^(\d+)\s*[--]\s*(\d+)$/);
 if (!m) continue;
 let from = parseInt(m[1]), to = parseInt(m[2]);
 if (from >to) { const tmp = from; from = to; to = tmp; }
 if (from < 1) from = 1;
 if (to >maxSP) to = maxSP;
 if (from <= to) ranges.push({ from, to });
 }
 return ranges;
}

function _mergeSPRanges(ranges) {
 if (ranges.length === 0) return [];
 const sorted = [...ranges].sort((a, b) =>a.from - b.from);
 const merged = [sorted[0]];
 for (let i = 1; i < sorted.length; i++) {
 const last = merged[merged.length - 1];
 if (sorted[i].from <= last.to + 1) {
 last.to = Math.max(last.to, sorted[i].to);
 } else {
 merged.push(sorted[i]);
 }
 }
 return merged;
}

function _getGapsFromRanges(acquiredRanges, totalSP) {
 // Returns array of {from, to} SP ranges that are NOT acquired
 const gaps = [];
 let cursor = 1;
 const sorted = [...acquiredRanges].sort((a, b) =>a.from - b.from);
 for (const r of sorted) {
 if (r.from >cursor) {
 gaps.push({ from: cursor, to: r.from - 1 });
 }
 cursor = Math.max(cursor, r.to + 1);
 }
 if (cursor <= totalSP) {
 gaps.push({ from: cursor, to: totalSP });
 }
 return gaps;
}

function _lmPromptSplitSP(idx, totalSP) {
 const line = state.lines[idx];
 if (!line) return;
 const sp = prompt(`Split "${line.name}" at which SP? (1 to ${totalSP})`, Math.round(totalSP / 2));
 if (sp === null) return;
 const val = parseInt(sp);
 if (isNaN(val) || val < 1 || val >= totalSP) { showToast(`Enter SP between 1 and ${totalSP - 1}`); return; }
 _lmSplitLine(idx, (val / totalSP) * 100);
}

function _lmPromptTrimSP(idx, end, totalSP) {
 const line = state.lines[idx];
 if (!line) return;
 const label = end === 'start' ? 'start (SOL)' : 'end (EOL)';
 const sp = prompt(`Trim "${line.name}" from ${label}.\n\nRemove how many SP from ${label}? (1 to ${totalSP - 1})`, '100');
 if (sp === null) return;
 const val = parseInt(sp);
 if (isNaN(val) || val < 1 || val >= totalSP) { showToast(`Enter SP between 1 and ${totalSP - 1}`); return; }
 const frac = val / totalSP;
 if (end === 'start') {
 line.start = [
 line.start[0] + (line.end[0] - line.start[0]) * frac,
 line.start[1] + (line.end[1] - line.start[1]) * frac
 ];
 } else {
 line.end = [
 line.start[0] + (line.end[0] - line.start[0]) * (1 - frac),
 line.start[1] + (line.end[1] - line.start[1]) * (1 - frac)
 ];
 }
 renderSurveyLines();
 _renderLineManagerList();
 _updateLmSummary();
 showToast(`"${line.name}" trimmed ${val} SP from ${label}`);
}

function _lmAddPartialInfill(idx, totalSP) {
 const line = state.lines[idx];
 if (!line) return;
 const input = prompt(
 `Add partial infill for "${line.name}" (${totalSP} SP total).\n\n` +
 `Enter SP range(s) that need infill:\n` +
 `e.g. 200-600, 900-1100\n\n` +
 `An infill line will be created for each range.`,
 ''
 );
 if (!input || !input.trim()) return;

 const ranges = _parseSPRanges(input, totalSP);
 if (ranges.length === 0) { showToast('Invalid SP range format'); return; }

 const nextIdx = idx + 1 < state.lines.length ? idx + 1 : idx - 1;
 if (nextIdx < 0) { showToast('Need at least 2 lines for infill offset'); return; }
 const nextLine = state.lines[nextIdx];

 ranges.forEach((r, i) => {
 const fracFrom = (r.from - 1) / totalSP;
 const fracTo = r.to / totalSP;
 const startPt = [
 line.start[0] + (line.end[0] - line.start[0]) * fracFrom,
 line.start[1] + (line.end[1] - line.start[1]) * fracFrom
 ];
 const endPt = [
 line.start[0] + (line.end[0] - line.start[0]) * fracTo,
 line.start[1] + (line.end[1] - line.start[1]) * fracTo
 ];
 // Offset towards adjacent line
 const offsetFrac = 0.5;
 const infillStart = [
 startPt[0] + (nextLine.start[0] - line.start[0]) * offsetFrac,
 startPt[1] + (nextLine.start[1] - line.start[1]) * offsetFrac
 ];
 const infillEnd = [
 endPt[0] + (nextLine.end[0] - line.end[0]) * offsetFrac,
 endPt[1] + (nextLine.end[1] - line.end[1]) * offsetFrac
 ];
 const infillName = sanitizeLineName(`INFILL-${line.name}/SP${r.from}-${r.to}`, `INFILL-SP${r.from}-${r.to}`);
 const infillLine = { id: `infill-${Date.now()}-${i}`, name: infillName, start: infillStart, end: infillEnd, _infill: true };
 state.lines.splice(idx + 1 + i, 0, infillLine);
 state.lineStatus[infillLine.id] = { status: 'planned', partialPct: 0, priority: 0 };
 });

 renderSurveyLines();
 _renderLineManagerList();
 _updateLmSummary();
 _updateLmInfillDropdowns();
 showToast(`${ranges.length} infill segment(s) added for "${line.name}"`);
}

function lmSolveRoute() {
 // Filter lines: only 'planned' and 'partial' (with remaining portion) go to route solver
 const linesToRoute = [];
 const spInt = state.settings.spInterval || 12.5;

 state.lines.forEach(l => {
 const ls = state.lineStatus[l.id] || { status: 'planned', partialPct: 0 };
 if (ls.status === 'acquired') return; // skip fully acquired

 if ((ls.status === 'partial' || ls.status === 'partial_infill') && ls.acquiredRanges && ls.acquiredRanges.length > 0) {
 // Build remaining segments from gaps between acquired SP ranges
 const firstSP = l.spStart || 1;
 const lastSP = l.spEnd || (firstSP + Math.round(haversine(l.start, l.end) / spInt));
 const totalSP = (lastSP - firstSP) + 1;
 const gaps = _getGapsFromRanges(ls.acquiredRanges, lastSP);
 gaps.forEach((gap, gi) => {
 const fracFrom = (gap.from - firstSP) / totalSP;
 const fracTo = (gap.to - firstSP + 1) / totalSP;
 const segStart = [
 l.start[0] + (l.end[0] - l.start[0]) * fracFrom,
 l.start[1] + (l.end[1] - l.start[1]) * fracFrom
 ];
 const segEnd = [
 l.start[0] + (l.end[0] - l.start[0]) * fracTo,
 l.start[1] + (l.end[1] - l.start[1]) * fracTo
 ];
 linesToRoute.push({
 ...l,
 id: l.id + '-seg' + gi,
 name: sanitizeLineName(l.name + (gaps.length > 1 ? `/SP${gap.from}-${gap.to}` : ''), l.name || 'Line'),
 start: segStart,
 end: segEnd,
 _originalStart: l.start,
 _partial: true
 });
 });
 } else if ((ls.status === 'partial' || ls.status === 'partial_infill') && ls.partialPct > 0) {
 // Legacy fallback: single percentage
 const pct = ls.partialPct / 100;
 const remainStart = [
 l.start[0] + (l.end[0] - l.start[0]) * pct,
 l.start[1] + (l.end[1] - l.start[1]) * pct
 ];
 linesToRoute.push({ ...l, start: remainStart, _originalStart: l.start, _partial: true });
 } else {
 linesToRoute.push(l);
 }
 });

 if (linesToRoute.length === 0) {
 showToast('No lines selected for routing. Mark at least one line as Planned.', 4000);
 return;
 }

 // Replace state.lines temporarily for route solver, but keep original list
 // (never overwrite a cached full list with an earlier routed subset)
 if (!state._allLines || !state._allLines.length) state._allLines = state.lines;
 state.lines = linesToRoute;
 hidePanel('line-manager');
 planRoute();
}

function planRoute() {
 if (state.lines.length === 0) return;

 confirmSurveyPlanTypeThen(() => {
  // Show start line chooser on first plan after loading lines - but only if the
  // start wasn't already specified in the Survey Criteria dialog (Start Point /
  // Start Time), in which case that selection is used directly.
  if (!_startLineChooserShown && !state.settings.startConfigured) {
   showStartLineChooser();
   return;
  }
  executePlanRoute();
 });
}

function executePlanRoute() {
 if (state.lines.length === 0) return;

 const run = () => {
 // Pull min turn radius from the open UI so Apply is not required for detours
 syncTurnRadiusUi();
 syncOfflineNoSpUi();
 state._detourFailCount = 0;

 // Ensure replan does not blend with a previous solution.
 state.route = null;
 state.skippedRanges = [];
 state._optimizerStats = null;
 if (layerRoute) layerRoute.clearLayers();
 if (layerArrows) layerArrows.clearLayers();

 showPlanningOverlay(true);

 // Defer to next tick so the overlay renders before heavy work starts
 setTimeout(() => {
 try {
 state._optimizerStats = null;
 const route = computeRoute();
 state.route = route;
 renderRoute(route);
 renderSurveyLines(); // refresh preplot gaps through exclusions
 showRouteStats(route);
 const nDetours = (route || []).filter(w => w.type === 'obsAvoidStart' || w.type === 'transit-detour').length;
 if ((state.obstructions || []).length && nDetours > 0) {
  const th = getOfflineNoSpThresholdM();
  showToast(
   `Route rebuilt with ${nDetours} obstruction detour(s)` +
   (th ? ` (no SP when offline > ${th} m)` : '') +
   ` at ${(getEffectiveTurnRadius() / 1000).toFixed(1)} km min turn radius`,
   5000
  );
 }
 if (state._detourFailCount > 0) {
  showToast(
   `Could not fully clear ${state._detourFailCount} obstruction detour(s) at ${(getEffectiveTurnRadius() / 1000).toFixed(1)} km min turn radius - check exclusion size vs turn radius`,
   8000
  );
 }
 // Report deep-optimizer performance (auto/2D optimizer only)
 const os = state._optimizerStats;
 if (os && os.mode === 'nn') {
 showToast(`Simple nearest-neighbour plan - transit time ${(os.finalSec / 3600).toFixed(1)} h (no deep optimization, as selected)`, 6000);
 } else if (os && os.iterations > 0) {
 const secs = (os.elapsedMs / 1000).toFixed(1);
 let msg = `Route optimized: ${os.iterations} iterations, ${os.starts} multi-starts in ${secs}s`;
 if (os.greedySec != null && os.finalSec != null && os.greedySec > 0) {
 const savedPct = ((os.greedySec - os.finalSec) / os.greedySec * 100);
 if (savedPct > 0.05) {
 msg += ` - transit time ${(os.finalSec / 3600).toFixed(1)} h (${savedPct.toFixed(1)}% faster than greedy nearest-line)`;
 } else {
 // Honest reporting: on regular parallel grids the greedy plan is
 // often already optimal - say so instead of implying magic gains.
 msg += ` - transit time ${(os.finalSec / 3600).toFixed(1)} h (deep search found no better order: greedy plan is already locally optimal for this geometry)`;
 }
 }
 if (os.altChecked > 0 && os.altBestSec != null && os.finalSec != null &&
 os.finalSec <= os.altBestSec + 0.5) {
 const marginH = (os.altBestSec - os.finalSec) / 3600;
 msg += ` - verified fastest vs ${os.altChecked} directional plans`;
 if (marginH > 0.05) msg += ` (best alternative ${os.altBestName} +${marginH.toFixed(1)} h)`;
 }
 // Proven optimality: LKH-3'Held-Karp bound is a hard lower limit on
 // the transit of ANY possible line order, so the gap is a proof, not
 // an estimate. A zero gap means this plan IS the optimum.
 if (os.gapPct != null) {
 const g = Math.max(0, os.gapPct);
 const ref = os.gapConstrained ? 'unconstrained optimum' : 'mathematical optimum';
 msg += g < 0.005
 ? ` - PROVEN OPTIMAL (matches the ${ref})`
 : ` - proven within ${g.toFixed(2)}% of the ${ref}`;
 }
 showToast(msg, 9000);
 }
 } catch (err) {
 console.error('Planning error:', err);
 showToast('Planning failed: ' + err.message);
 } finally {
 showPlanningOverlay(false);
 }
 }, 50);
 };

 // When exclusions exist, require the offline no-SP threshold before planning
 if ((state.obstructions || []).length > 0 && getOfflineNoSpThresholdM() == null) {
  ensureOfflineNoSpThreshold().then((thresh) => {
   if (thresh == null) {
    showToast('Plan cancelled - set offline no-SP threshold (Obstructions panel).', 6000);
    return;
   }
   run();
  });
 } else {
  run();
 }
}

// Returns true when the user has explicitly fixed a line'acquisition direction
// via the Line Manager, so the route planner must acquire it start'end
// (reversed:false) rather than choosing a direction for turn efficiency.
// lmToggleDirection() swaps start/end and sets _forcedDirection.
//
// NOTE: Infill lines are intentionally NOT locked here. Their 'same'/'opposite'
// choice is relative to the swath progression direction, so their acquisition
// direction is resolved from the parent line'actual route flip after the
// order is built (see the infill direction pass below). This lets infill follow
// the swath progression instead of being pinned to a fixed orientation.
function _lineDirLocked(line) {
 if (!line) return false;
 if (line._forcedDirection) return true;
 return false;
}

// ===== TIME-BASED TRANSIT COST MODEL (Dubins-aware) =====
// Length (metres) of the shortest Dubins path between two configurations in a
// local XY metre frame. Mirrors dubinsShortestPath() but returns length only.
function dubinsPathLengthM(x1, y1, th1, x2, y2, th2, R) {
 const dx = x2 - x1, dy = y2 - y1;
 const d = Math.sqrt(dx * dx + dy * dy);
 const phi = Math.atan2(dy, dx);
 const alpha = th1 - phi;
 const beta = th2 - phi;
 const dNorm = d / R;
 const paths = [
 dubinsLSL(alpha, beta, dNorm),
 dubinsRSR(alpha, beta, dNorm),
 dubinsLSR(alpha, beta, dNorm),
 dubinsRSL(alpha, beta, dNorm),
 dubinsRLR(alpha, beta, dNorm),
 dubinsLRL(alpha, beta, dNorm)
 ].filter(p =>p !== null);
 if (paths.length === 0) return d;
 let best = Infinity;
 for (const p of paths) if (p.length < best) best = p.length;
 return best * R;
}

// Build a transit-TIME cost model for line changes. The cost between two lines
// is the sailing time (seconds) of the true Dubins turn path from the end of
// the current line'run-out to the start of the next line'run-in, at turn
// speed. This replaces straight-line distance so the planner minimises actual
// TIME: a geometrically "close" adjacent line that needs a loop turn is
// correctly costed as expensive.
function buildTransitTimeModel(lines) {
 const R = getEffectiveTurnRadius();
 const turnKn = state.settings.turnSpeed || state.settings.speed || 4.5;
 const turnSpeedMs = turnKn * 0.514444; // knots ' m/s
 const runIn = state.settings.runIn || 0;
 const runOut = state.settings.runOut || 0;

 // Local metric frame centred on the survey
 let cLat = 0, cLon = 0;
 lines.forEach(l => { cLat += (l.start[0] + l.end[0]) / 2; cLon += (l.start[1] + l.end[1]) / 2; });
 cLat /= lines.length; cLon /= lines.length;
 const mLat = 111320;
 const mLon = 111320 * Math.cos(cLat * Math.PI / 180);
 const toXY = pt => [(pt[1] - cLon) * mLon, (pt[0] - cLat) * mLat];

 // Per line & direction: entry config (before run-in) and exit config (after run-out)
 const cfg = lines.map(l => {
 const mk = (s, e) => {
 const hdg = bearing(s, e);
 const th = (90 - hdg) * Math.PI / 180; // math angle, CCW from +X
 const entryPt = runIn > 0 ? destinationPoint(s, (hdg + 180) % 360, runIn) : s;
 const exitPt = runOut > 0 ? destinationPoint(e, hdg, runOut) : e;
 return { entry: toXY(entryPt), exit: toXY(exitPt), th };
 };
 return { fwd: mk(l.start, l.end), rev: mk(l.end, l.start) };
 });

 function transitTimeSec(aIdx, aRev, bIdx, bRev) {
 const A = aRev ? cfg[aIdx].rev : cfg[aIdx].fwd;
 const B = bRev ? cfg[bIdx].rev : cfg[bIdx].fwd;
 const distM = dubinsPathLengthM(A.exit[0], A.exit[1], A.th, B.entry[0], B.entry[1], B.th, R);
 return distM / turnSpeedMs;
 }

 return { transitTimeSec, turnSpeedMs };
}

// ===== 3D PROGRESSIVE-SWATH INTERLEAVE OPTIMIZER =====
// On 3D swath shooting each new line MUST be acquired adjacent to the last
// line acquired on that swath (progressive infill requirement). Each swath is
// therefore shot strictly in adjacent order and the planner'only freedom is
// WHICH swath to shoot from next. This solves that sequencing for minimum
// transit time - exact DP when the state space is small, beam search otherwise.
// swaths: arrays of line indices in per-swath acquisition order.
// revOf: acquisition direction (reversed flag) per line index.
// Returns { seq: [lineIdx...], costSec } or null.
function optimizeSwathInterleave(swaths, revOf, transitTimeSec, forceStartSwath) {
 const numSw = swaths.length;
 const lens = swaths.map(s =>s.length);
 const total = lens.reduce((a, b) =>a + b, 0);
 if (total === 0) return null;

 // Mixed-radix state key: pointers per swath + last swath shot
 const radix = lens.map(L =>L + 1);
 let stateCount = numSw;
 let overflow = false;
 for (const r of radix) {
 stateCount *= r;
 if (stateCount >Number.MAX_SAFE_INTEGER) { overflow = true; break; }
 }
 const beamCap = (overflow || stateCount > 2e6) ? 400 : Infinity; // exact DP when feasible
 const keyOf = (ptrs, last) => {
 if (overflow) return ptrs.join(',') + '|' + last;
 let k = last;
 for (let g = numSw - 1; g >= 0; g--) k = k * radix[g] + ptrs[g];
 return k;
 };

 const memo = new Map(); // pairwise transit-time cache
 const T = (a, b) => {
 const mk = a * 65536 + b;
 let v = memo.get(mk);
 if (v === undefined) { v = transitTimeSec(a, revOf[a], b, revOf[b]); memo.set(mk, v); }
 return v;
 };

 // Level-by-level forward DP: level t = number of lines acquired
 let level = new Map(); // key ' { cost, ptrs, last, prev, line }
 const startSwaths = forceStartSwath >= 0
 ? [forceStartSwath]
 : swaths.map((_, g) =>g).filter(g =>lens[g] > 0);
 for (const g of startSwaths) {
 if (lens[g] === 0) continue;
 const ptrs = new Array(numSw).fill(0);
 ptrs[g] = 1;
 level.set(keyOf(ptrs, g), { cost: 0, ptrs, last: g, prev: null, line: swaths[g][0] });
 }

 for (let t = 1; t < total; t++) {
 const next = new Map();
 for (const st of level.values()) {
 const curLine = swaths[st.last][st.ptrs[st.last] - 1];
 for (let h = 0; h < numSw; h++) {
 if (st.ptrs[h] >= lens[h]) continue;
 const nextLine = swaths[h][st.ptrs[h]];
 const cost = st.cost + T(curLine, nextLine);
 const ptrs = st.ptrs.slice();
 ptrs[h]++;
 const k = keyOf(ptrs, h);
 const ex = next.get(k);
 if (!ex || cost < ex.cost) next.set(k, { cost, ptrs, last: h, prev: st, line: nextLine });
 }
 }
 if (next.size === 0) return null;
 if (next.size >beamCap) {
 const kept = Array.from(next.entries()).sort((a, b) =>a[1].cost - b[1].cost).slice(0, beamCap);
 level = new Map(kept);
 } else {
 level = next;
 }
 }

 let best = null;
 for (const st of level.values()) if (!best || st.cost < best.cost) best = st;
 if (!best) return null;
 const seq = [];
 for (let st = best; st; st = st.prev) seq.push(st.line);
 seq.reverse();
 return { seq, costSec: best.cost };
}

function computeRoute() {
 syncTurnRadiusUi();
 // Filter out acquired lines from route planning
 const originalCount = state.lines.length;
 const lines = state.lines.filter(l => {
 const status = state.lineStatus[l.id];
 return !status || status.status !== 'acquired';
 });
 const acquiredCount = originalCount - lines.length;
 if (acquiredCount > 0) {
 showToast(`Excluding ${acquiredCount} acquired line(s) from route planning`);
 }
 const n = lines.length;
 if (n === 0) return [];

 // --- VISITED SET: fresh every call (key fix for the live-site loop bug) ---
 const visited = new Set();

 // Each line can be traversed in forward or reverse direction.
 // State: { lineIdx, reversed }
 // Cost between two states = transit distance (current endpoint ' next line start/end)
 // + turn penalty if turn < minTurnRadius

 // Resolve the user-chosen start line by its stable id. The start line index
 // is ambiguous because it may have been recorded against the full line list
 // (survey-criteria dialog) or a filtered subset (Line Manager) and those
 // arrays diverge. Resolving by id works regardless of which array was used.
 const _startPool = state._allLines || state.lines;
 const _resolveStartLine = () => {
 if (state.settings.startLineId != null) {
 const o = _startPool.find(l =>l && l.id === state.settings.startLineId);
 if (o) return o;
 }
 if (state.settings.startLineIdx !== undefined && state.settings.startLineIdx !== null &&
 state.settings.startLineIdx >= 0) {
 return _startPool[state.settings.startLineIdx] || null;
 }
 return null;
 };
 const startLineObj = _resolveStartLine();

 // Locate the start line in the FILTERED routing list. Partial lines are
 // routed as '-segN' segments whose ids differ from the parent line id, so
 // match on the id with any '-segN' suffix stripped as well - otherwise a
 // start line that is partially acquired is silently ignored.
 const _startIdxIn = (arr) => {
 if (!startLineObj) return -1;
 const sid = String(startLineObj.id);
 let i = arr.findIndex(l =>l && l.id === startLineObj.id);
 if (i < 0) i = arr.findIndex(l =>l && String(l.id).replace(/-seg\d+$/, '') === sid);
 return i;
 };

 // Determine starting line and direction: support specific selected start line and direction
 let startIdx = 0;
 let startReversed = false;
 if (startLineObj) {
 const filteredIdx = _startIdxIn(lines);
 if (filteredIdx >= 0) {
 startIdx = filteredIdx;
 startReversed = !!state.settings.startLineReversed;
 } else {
 showToast(`Start line "${startLineObj.name || startLineObj.id}" is fully acquired/excluded - starting from the nearest remaining line`, 6000);
 }
 } else if (state.settings.startPoint) {
 let best = Infinity;
 for (let i = 0; i < n; i++) {
 const ds = haversine(state.settings.startPoint, lines[i].start);
 const de = haversine(state.settings.startPoint, lines[i].end);
 if (ds < best) { best = ds; startIdx = i; startReversed = false; }
 if (de < best) { best = de; startIdx = i; startReversed = true; }
 }
 }

 // Pre-compute line midpoints
 const midpoints = lines.map(l => [
 (l.start[0] + l.end[0]) / 2,
 (l.start[1] + l.end[1]) / 2
 ]);

 // 3D surveys must maintain progressive adjacent-line acquisition (swath
 // interleaving) due to geophysical coverage constraints - the free 'auto'
 // optimizer is only permitted for 2D surveys.
 let progression = state.settings.progression || (state.settings.surveyType === '3d' ? 'interleaved' : 'auto');
 if (state.settings.surveyType === '3d' && progression === 'auto') {
 progression = 'interleaved';
 showToast('3D survey: progressive swath adjacency enforced - optimizing swath interleave for transit time');
 }
 const order = []; // [{ lineIdx, reversed }]

 // Get priority for each line from lineStatus, on the 1-100 scale where 1 is
 // acquired FIRST, 100 LAST and 50 = Neutral (default / legacy unset).
 // Partial '-segN' ids resolve to their parent line'status.
 const priorities = lines.map((l, i) => {
 const ls = state.lineStatus[l.id] ||
 state.lineStatus[String(l.id).replace(/-seg\d+$/, '')] || {};
 return _prioNorm(ls.priority);
 });

 if (progression !== 'auto') {
 // --- Directional or line-number progression ---
 // Build sorted index list
 const indices = lines.map((_, i) =>i);
 let interleaveOptimized = false; // set when the 3D interleave optimizer placed the start itself

 // Acquisition direction (SP direction) for each line, derived from its
 // swath'Low'High / High'Low setting. 'low-high' = acquire low SP -> high SP
 // (SOL ' EOL, reversed:false); 'high-low' = high SP -> low SP (reversed:true).
 const swathDirOf = new Array(lines.length).fill('low-high');

 // Derive a numeric "line number" key for each line so that low'high /
 // high'low and interleaved progressions follow the true line numbering
 // rather than the (arbitrary) order lines appear in the preplot file.
 // Falls back to the file index when a line name has no number.
 const lineNumKey = lines.map((l, i) => {
 // Infill lines sort/band next to their PARENT line - never by the number
 // parsed from their own "INFILL-" name, which would scramble the
 // progression order and per-swath direction banding.
 if (l._infill && l._parentLineId != null) {
 const p = lines.find(x =>x && x.id === l._parentLineId);
 if (p) {
 const pn = _lineNumOf(p, null);
 if (pn != null) return pn + 0.5;
 }
 }
 const num = _lineNumOf(l, null);
 return num != null ? num : i;
 });

 if (progression === 'west-east') {
 indices.sort((a, b) => {
 const prioA = priorities[a], prioB = priorities[b];
 if (prioA !== prioB) return prioA - prioB; // priority first
 return midpoints[a][1] - midpoints[b][1]; // then longitude ascending
 });
 } else if (progression === 'east-west') {
 indices.sort((a, b) => {
 const prioA = priorities[a], prioB = priorities[b];
 if (prioA !== prioB) return prioA - prioB; // priority first
 return midpoints[b][1] - midpoints[a][1]; // then longitude descending
 });
 } else if (progression === 'south-north') {
 indices.sort((a, b) => {
 const prioA = priorities[a], prioB = priorities[b];
 if (prioA !== prioB) return prioA - prioB; // priority first
 return midpoints[a][0] - midpoints[b][0]; // then latitude ascending
 });
 } else if (progression === 'north-south') {
 indices.sort((a, b) => {
 const prioA = priorities[a], prioB = priorities[b];
 if (prioA !== prioB) return prioA - prioB; // priority first
 return midpoints[b][0] - midpoints[a][0]; // then latitude descending
 });
 } else if (progression === 'low-high') {
 indices.sort((a, b) => {
 const prioA = priorities[a], prioB = priorities[b];
 if (prioA !== prioB) return prioA - prioB; // priority first
 return lineNumKey[a] - lineNumKey[b]; // then ascending line number
 });
 } else if (progression === 'high-low') {
 indices.sort((a, b) => {
 const prioA = priorities[a], prioB = priorities[b];
 if (prioA !== prioB) return prioA - prioB; // priority first
 return lineNumKey[b] - lineNumKey[a]; // then descending line number
 });
 } else if (progression === 'interleaved' || progression === 'interleaved-reverse') {
 // Band lines into N swaths by ASCENDING line number (Swath 1 = lowest
 // lines), then round-robin across the bands so consecutive acquired lines
 // are spaced apart (wider transits for the turn radius).
 indices.sort((a, b) => {
 const prioA = priorities[a], prioB = priorities[b];
 if (prioA !== prioB) return prioA - prioB; // priority first
 return lineNumKey[a] - lineNumKey[b]; // then line number
 });
 const numSw = state.settings.numSwaths || 2;
 const groupSize = Math.ceil(indices.length / numSw);
 const swaths = [];
 for (let g = 0; g < numSw; g++) {
 swaths.push(indices.slice(g * groupSize, (g + 1) * groupSize));
 }

 // 3D PROGRESSIVE ADJACENCY: within a swath every new line must be
 // acquired adjacent to the LAST line acquired on that swath, so each
 // swath is shot strictly in adjacent order. 'interleaved-reverse'
 // progresses each swath High'Low instead of Low'High.
 if (progression === 'interleaved-reverse') swaths.forEach(s =>s.reverse());

 // Per-line acquisition direction (mirrors the swathDirOf banding below)
 const revOfLocal = new Array(lines.length).fill(false);
 {
 const swDirs = state.settings.swathDirections || [];
 for (let g = 0; g < numSw; g++) {
 const dir = swDirs[g] || defaultSwathDirection(g);
 for (const idx of swaths[g]) {
 revOfLocal[idx] = _lineDirLocked(lines[idx]) ? false : (dir === 'high-low');
 }
 }
 }

 // Honour a user-chosen start line: adjacency requires it to be the FIRST
 // line of its swath (starting mid-swath would force a non-adjacent jump).
 let forceStartSwath = -1;
 if (startLineObj) {
 const startFilteredIdx = _startIdxIn(lines);
 if (startFilteredIdx >= 0) {
 for (let g = 0; g < numSw; g++) {
 const pos = swaths[g].indexOf(startFilteredIdx);
 if (pos < 0) continue;
 if (pos === 0) forceStartSwath = g;
 else if (pos === swaths[g].length - 1) { swaths[g].reverse(); forceStartSwath = g; }
 else showToast('Start line is mid-swath - progressive adjacency takes precedence over start-line lock');
 break;
 }
 }
 } else if (state.settings.startPoint) {
 // Custom start point: adjacency only allows starting at a swath'FIRST
 // or LAST line, so force the start onto the swath end whose entry point
 // is nearest the user'point - the start point is ALWAYS honoured
 // (previously the globally nearest line was used, which is usually
 // mid-swath, so the user'start point was silently ignored).
 let bestD = Infinity, bestG = -1, bestRevSwath = false;
 const entryOf = li => (revOfLocal[li] ? lines[li].end : lines[li].start);
 for (let g = 0; g < numSw; g++) {
 if (!swaths[g].length) continue;
 const dh = haversine(state.settings.startPoint, entryOf(swaths[g][0]));
 const dt = haversine(state.settings.startPoint, entryOf(swaths[g][swaths[g].length - 1]));
 if (dh < bestD) { bestD = dh; bestG = g; bestRevSwath = false; }
 if (dt < bestD) { bestD = dt; bestG = g; bestRevSwath = true; }
 }
 if (bestG >= 0) {
 if (bestRevSwath && swaths[bestG].length > 1) swaths[bestG].reverse();
 forceStartSwath = bestG;
 }
 }

 // Time-based interleave: choose WHICH swath to shoot from next so total
 // Dubins transit TIME is minimised, while preserving per-swath adjacency.
 const model3d = buildTransitTimeModel(lines);
 const opt = optimizeSwathInterleave(swaths, revOfLocal, model3d.transitTimeSec, forceStartSwath);

 // Rigid round-robin sequence (fallback + reporting baseline)
 const interleaved = [];
 const maxLen = Math.max(...swaths.map(s =>s.length));
 for (let k = 0; k < maxLen; k++) {
 for (let g = 0; g < numSw; g++) {
 if (k < swaths[g].length) interleaved.push(swaths[g][k]);
 }
 }

 indices.length = 0;
 if (opt && opt.seq.length === interleaved.length) {
 indices.push(...opt.seq);
 interleaveOptimized = true;
 // Report time saved vs the rigid round-robin baseline
 let baseCost = 0;
 for (let k = 0; k < interleaved.length - 1; k++) {
 baseCost += model3d.transitTimeSec(
 interleaved[k], revOfLocal[interleaved[k]],
 interleaved[k + 1], revOfLocal[interleaved[k + 1]]);
 }
 if (baseCost >opt.costSec + 1) {
 const savedH = (baseCost - opt.costSec) / 3600;
 showToast(`Swath interleave optimized: transit ${(opt.costSec / 3600).toFixed(1)} h (saves ${savedH.toFixed(1)} h vs round-robin)`, 6000);
 }
 } else {
 indices.push(...interleaved);
 }
 }

 // Assign each line'per-swath acquisition direction. Lines are banded into
 // swaths so that Swath 1 ALWAYS covers the lowest line numbers (matching the
 // on-map swath labels), regardless of the progression direction. Compass
 // progressions band along their (spatial) sort order instead.
 {
 const nSw = state.settings.numSwaths || 1;
 const swDirs = state.settings.swathDirections || [];
 const isCompass = (progression === 'west-east' || progression === 'east-west' ||
 progression === 'south-north' || progression === 'north-south');
 const bandOrder = isCompass
 ? indices.slice()
 : lines.map((_, i) =>i).sort((a, b) =>lineNumKey[a] - lineNumKey[b]);
 const gSize = Math.ceil(bandOrder.length / nSw);
 for (let g = 0; g < nSw; g++) {
 const dir = swDirs[g] || defaultSwathDirection(g);
 for (let k = g * gSize; k < Math.min((g + 1) * gSize, bandOrder.length); k++) {
 swathDirOf[bandOrder[k]] = dir;
 }
 }
 }

 // If the user selected a specific start line, or set a custom start
 // point, rotate the progression order so it begins there. `indices` is
 // already sorted in the chosen progression direction, so we ALWAYS walk
 // forward from the start position and wrap around - walking backward
 // would invert the user'chosen progression.
 let progStartFilteredIdx = -1;
 let progStartReversed = false;
 if (startLineObj) {
 progStartFilteredIdx = _startIdxIn(lines);
 progStartReversed = !!state.settings.startLineReversed;
 } else if (state.settings.startPoint) {
 // Custom start point: begin the progression at the nearest line,
 // in the direction whose entry point is closest (computed above).
 progStartFilteredIdx = startIdx;
 progStartReversed = startReversed;
 }
 if (progStartFilteredIdx >= 0 && !interleaveOptimized) {
 const sIdx = indices.indexOf(progStartFilteredIdx);
 if (sIdx > 0) {
 const rotated = indices.slice(sIdx).concat(indices.slice(0, sIdx));
 indices.length = 0;
 indices.push(...rotated);
 }
 }

 // The first line may have a user-forced direction: an explicit start-line
 // direction, or a line reversed in the Line Manager. Otherwise every line's
 // direction comes from its swath'Low'High / High'Low setting.
 let firstRev = false;
 let firstDirLocked = false;
 if (progStartFilteredIdx >= 0 && indices[0] === progStartFilteredIdx) {
 firstRev = progStartReversed;
 firstDirLocked = true; // user explicitly chose the start direction
 }
 if (indices.length >= 1 && _lineDirLocked(lines[indices[0]])) {
 firstRev = false; // geometry already arranged so forward = chosen direction
 firstDirLocked = true;
 }

 // Build the order. Acquisition direction follows each line'swath
 // progression direction: 'low-high' acquires low SP -> high SP (SOL ' EOL,
 // reversed:false); 'high-low' acquires high SP -> low SP (reversed:true).
 // A user-forced line direction and an explicit start-line direction override.
 for (let k = 0; k < indices.length; k++) {
 const idx = indices[k];
 let rev;
 if (_lineDirLocked(lines[idx])) {
 rev = false;
 } else if (k === 0 && firstDirLocked) {
 rev = firstRev;
 } else {
 rev = (swathDirOf[idx] === 'high-low');
 }
 visited.add(idx);
 order.push({ lineIdx: idx, reversed: rev });
 }
 } else {
 // --- Auto: nearest-neighbour + 2-opt improvement for optimal transit ---

 // === ADVANCED ROUTE OPTIMIZER ===
 // When the user has explicitly chosen a start line or a custom start
 // point, the route MUST begin there - the optimiser may not relocate or
 // flip the first line.
 // A custom start POINT no longer pins the nearest line. The vessel's
 // departure leg is costed as a depot edge inside the objective instead, so
 // the optimizer chooses the first line that minimises TOTAL time - the
 // nearest line is frequently a slow start (long sail back across the
 // survey afterwards). An explicit start LINE is still a hard lock.
 let userStartLocked = !!startLineObj;
 const depotPtInit = (!startLineObj && state.settings.startPoint) ? state.settings.startPoint : null;
 let depotPt = depotPtInit;

 // === USER DEFINITIONS TAKE PRECEDENCE (hard search constraints) ===
 // User-defined line directions are FIXED inside the deep search itself,
 // not patched afterwards (which would make the search optimize a
 // different route than the one delivered): Line-Manager direction locks,
 // the Survey Criteria 2D "Line Direction" setting (low-high / high-low),
 // and an explicit start-line direction. 'alternate' is position-dependent
 // and stays a post-pass; 'auto' leaves directions free for the optimizer.
 // fixedRev[i] = null (free) or the mandatory reversed flag for line i.
 const fixedRev = new Array(n).fill(null);
 {
 // Default is 'auto' (directions free). A one-direction setting pins
 // EVERY line, forcing a long sail back after each line - routes get
 // dramatically slower, so warn the user that this constraint is active.
 const dirMode2d = state.settings.lineDirection2d || 'auto';
 for (let i = 0; i < n; i++) {
 if (_lineDirLocked(lines[i])) fixedRev[i] = false;
 else if (dirMode2d === 'low-high') fixedRev[i] = false;
 else if (dirMode2d === 'high-low') fixedRev[i] = true;
 }
 if (dirMode2d === 'low-high' || dirMode2d === 'high-low') {
 showToast('All line directions fixed ' + (dirMode2d === 'low-high' ? 'Low->High' : 'High->Low') +
 ' by Survey Criteria - set Line Direction to Auto for the fastest route', 8000);
 }
 if (userStartLocked && !_lineDirLocked(lines[startIdx])) {
 fixedRev[startIdx] = startReversed;
 }
 }
 // Constrained flip: a direction-fixed line always keeps its direction.
 const flipEntry = (o) =>fixedRev[o.lineIdx] != null
 ? { lineIdx: o.lineIdx, reversed: fixedRev[o.lineIdx] }
 : { lineIdx: o.lineIdx, reversed: !o.reversed };

 // === TIME-BASED COST MODEL ===
 // Transit cost between two lines is the sailing TIME (seconds) of the true
 // Dubins turn path (run-out ' turn ' run-in) at turn speed - NOT the
 // straight-line distance. A nearby line that needs a loop turn is
 // correctly costed as expensive, so the planner minimises actual time.
 const timeModel = buildTransitTimeModel(lines);

 // Precompute NxN transit-time matrix for all 4 direction combinations
 // ff = i fwd ' j fwd, fr = i fwd ' j rev, rf = i rev ' j fwd, rr = i rev ' j rev
 const D = new Array(n);
 for (let i = 0; i < n; i++) {
 D[i] = new Array(n);
 for (let j = 0; j < n; j++) {
 if (i === j) { D[i][j] = { ff: 0, fr: 0, rf: 0, rr: 0 }; continue; }
 D[i][j] = {
 ff: timeModel.transitTimeSec(i, false, j, false),
 fr: timeModel.transitTimeSec(i, false, j, true),
 rf: timeModel.transitTimeSec(i, true, j, false),
 rr: timeModel.transitTimeSec(i, true, j, true)
 };
 }
 }

 // O(1) edge cost lookup using precomputed matrix
 function edgeCost(a, b) {
 const d = D[a.lineIdx][b.lineIdx];
 if (!a.reversed && !b.reversed) return d.ff;
 if (!a.reversed && b.reversed) return d.fr;
 if (a.reversed && !b.reversed) return d.rf;
 return d.rr;
 }

 // Departure leg from the vessel'start point to a line'entry point.
 // No heading is known at the depot, so this is a straight run at transit
 // speed rather than a Dubins path.
 function depotSec(e) {
 if (!depotPt) return 0;
 const l = lines[e.lineIdx];
 const entry = e.reversed ? l.end : l.start;
 return haversine(depotPt, entry) / timeModel.turnSpeedMs;
 }

 // Cost of the link into `b`. A null predecessor means the depot.
 const linkCost = (a, b) => (a ? edgeCost(a, b) : depotSec(b));

 // Total transit cost for an ordering, including the departure leg
 function transitCost(ord) {
 let cost = ord.length ? depotSec(ord[0]) : 0;
 for (let k = 0; k < ord.length - 1; k++) {
 cost += edgeCost(ord[k], ord[k + 1]);
 }
 return cost;
 }

 // Build nearest-neighbour solution from a given start (uses matrix).
 // Direction-fixed lines are only considered in their user-defined direction.
 function buildNNSolution(sIdx, sRev) {
 const sol = [{ lineIdx: sIdx, reversed: fixedRev[sIdx] != null ? fixedRev[sIdx] : sRev }];
 const vis = new Set([sIdx]);
 while (vis.size < n) {
 const cur = sol[sol.length - 1];
 let bestD = Infinity, bestI = -1, bestR = false;
 for (let i = 0; i < n; i++) {
 if (vis.has(i)) continue;
 const fr = fixedRev[i];
 if (fr !== true) {
 const dF = edgeCost(cur, { lineIdx: i, reversed: false });
 if (dF < bestD) { bestD = dF; bestI = i; bestR = false; }
 }
 if (fr !== false) {
 const dR = edgeCost(cur, { lineIdx: i, reversed: true });
 if (dR < bestD) { bestD = dR; bestI = i; bestR = true; }
 }
 }
 if (bestI === -1) break;
 vis.add(bestI);
 sol.push({ lineIdx: bestI, reversed: bestR });
 }
 return sol;
 }

 // User-selected optimizer mode: 'nn' = simple nearest-neighbour plan only
 // (quick, no improvement passes); 'deep' (default) = full deep search.
 const nnOnly = state.settings.optimizerMode === 'nn';

 // Deep-search budget: iteration-driven (like SurvOpt's 1500 iterations),
 // with only a generous wall-clock safety cap to avoid hanging the browser.
 const optimizerStart = Date.now();
 const targetIterations = Math.max(1, state.settings.optimizerIterations || 1500);
 const safetyCapMs = 120000; // 2 min hard safety cap
 function timeUp() { return (Date.now() - optimizerStart) >safetyCapMs; }

 // 2-opt to LOCAL OPTIMALITY (first-improvement). The previous version
 // broke out of BOTH loops after each applied move with the pass count
 // capped at 4-8, so at most ~8 moves were ever applied - leaving routes
 // barely better than nearest-neighbour. Now moves keep being applied
 // until a full scan finds none (wall-clock guarded by timeUp).
 // The transit-time matrix is ASYMMETRIC (a Dubins turn from A to B is not
 // the turn from B to A), so reversing a segment also changes every edge
 // INSIDE it. Evaluating only the two boundary edges - as the previous
 // version did - made a quarter of all applied moves lengthen the route
 // (measured: 818k of 3.27M moves on a 30-line survey, worst move +6 h),
 // and the resulting churn burnt the whole time budget without converging.
 // Both internal sums are maintained incrementally, so the scan stays O(n2).
 function twoOptImprove(ord) {
 let improved = true;
 while (improved && !timeUp()) {
 improved = false;
 // i = -1 is the depot: prefix reversals (which change the first line
 // acquired) are only reachable through it, and they matter most when
 // the vessel starts away from the survey.
 for (let i = depotPt ? -1 : 0; i < ord.length - 1; i++) {
 if (timeUp()) break;
 let fwdInternal = 0, revInternal = 0;
 for (let j = i + 2; j < ord.length; j++) {
 // Extend the segment [i+1..j] by ord[j]
 fwdInternal += edgeCost(ord[j - 1], ord[j]);
 revInternal += edgeCost(flipEntry(ord[j]), flipEntry(ord[j - 1]));
 const A = i < 0 ? null : ord[i], B = ord[i + 1], C = ord[j];
 const Dn = j + 1 < ord.length ? ord[j + 1] : null;
 const oldCost = linkCost(A, B) + fwdInternal + (Dn ? edgeCost(C, Dn) : 0);
 const revC = flipEntry(C);
 const revB = flipEntry(B);
 const newCost = linkCost(A, revC) + revInternal + (Dn ? edgeCost(revB, Dn) : 0);
 if (newCost < oldCost - 1) {
 // Reverse the segment [i+1..j] in place (direction-fixed lines
 // keep their user-defined direction via flipEntry)
 let lo = i + 1, hi = j;
 while (lo < hi) {
 const tmp = ord[lo];
 ord[lo] = flipEntry(ord[hi]);
 ord[hi] = flipEntry(tmp);
 lo++; hi--;
 }
 if (lo === hi) ord[lo] = flipEntry(ord[lo]);
 improved = true;
 break; // edge (i, i+1) changed - rescan from next i
 }
 }
 }
 }
 return ord;
 }

 // Or-opt with delta evaluation: relocate segments of size 1, 2, 3.
 // Runs until no relocation improves (previously capped at 5 moves total).
 function orOptImprove(ord) {
 const segSizes = [1, 2, 3];
 let improved = true;
 let passes = 0;
 const maxPasses = 10000; // effectively unbounded - timeUp() is the guard
 while (improved && passes++ < maxPasses && !timeUp()) {
 improved = false;
 for (const sz of segSizes) {
 if (timeUp()) break;
 for (let i = 0; i < ord.length - sz + 1 && !timeUp(); i++) {
 if (i === 0 && userStartLocked) continue;
 // Cost of removing segment [i..i+sz-1]: boundary edges plus the
 // TRUE sum of the segment'internal edges (the old first'last
 // shortcut was wrong for 3-line segments, so "improvements" could
 // actually lengthen the route and cycle until the time cap).
 let origInternal = 0;
 for (let si = 0; si < sz - 1; si++) origInternal += edgeCost(ord[i + si], ord[i + si + 1]);
 const prevOut = i > 0 ? ord[i - 1] : null;
 const nextOut = i + sz < ord.length ? ord[i + sz] : null;
 const removeCost =
 linkCost(prevOut, ord[i]) +
 (nextOut ? edgeCost(ord[i + sz - 1], nextOut) : 0) +
 origInternal;
 // Cost of stitching gap
 const stitchCost = nextOut ? linkCost(prevOut, nextOut) : 0;
 const removalSaving = removeCost - stitchCost;

 const seg = ord.slice(i, i + sz);
 const flipped = seg.map(o =>flipEntry(o)).reverse();

 let bestPos = -1, bestSaving = 0, bestFlip = false;
 // Try inserting at every position in the rest
 for (let j = 0; j < ord.length - sz + 1; j++) {
 if (j === 0 && userStartLocked) continue; // keep user start first
 if (j >= i && j <= i + sz) continue;
 const actualJ = j >i ? j + sz : j; // adjust for removal
 // We check insertion between ord[actualJ-1] and ord[actualJ]
 // but simpler: just compute insertion cost for both variants
 const posInRest = j >i ? j - 1 : j; // position in the "rest" array
 // Use full delta: saving from removal - cost of insertion
 for (const tryFlip of [false, true]) {
 const useSeg = tryFlip ? flipped : seg;
 const insertBefore = j >i ? j + sz : j;
 const prevNode = insertBefore > 0 ? ord[insertBefore - 1] : null;
 const nextNode = insertBefore < ord.length ? ord[insertBefore] : null;
 // Skip if prevNode/nextNode is in the segment being moved
 if (prevNode && insertBefore - 1 >= i && insertBefore - 1 < i + sz) continue;
 if (nextNode && insertBefore >= i && insertBefore < i + sz) continue;

 let insertCost = linkCost(prevNode, useSeg[0]);
 if (nextNode) insertCost += edgeCost(useSeg[useSeg.length - 1], nextNode);
 // Subtract the edge that was there before
 let removedEdge = 0;
 if (nextNode) removedEdge = linkCost(prevNode, nextNode);
 // Internal segment cost
 let segInternal = 0;
 for (let si = 0; si < useSeg.length - 1; si++) segInternal += edgeCost(useSeg[si], useSeg[si + 1]);

 const netCost = insertCost - removedEdge + segInternal;
 const saving = removalSaving - netCost;
 if (saving >bestSaving + 0.5) {
 bestSaving = saving;
 bestPos = j;
 bestFlip = tryFlip;
 }
 }
 }
 if (bestPos >= 0) {
 const useSeg = bestFlip ? flipped : seg;
 // Remove then insert. The evaluated gap was between original
 // indices (insertBefore-1, insertBefore) with insertBefore =
 // bestPos+sz when bestPos >i (or bestPos when below i); after
 // removing sz entries at i both cases land at index bestPos.
 ord.splice(i, sz);
 ord.splice(Math.max(0, Math.min(bestPos, ord.length)), 0, ...useSeg);
 improved = true;
 break;
 }
 }
 if (improved) break;
 }
 }
 return ord;
 }

 // Direction optimization: flip individual lines to reduce transit
 function directionOptimize(ord) {
 let improved = true;
 while (improved && !timeUp()) {
 improved = false;
 for (let i = 0; i < ord.length; i++) {
 if (i === 0 && userStartLocked) continue;
 if (fixedRev[ord[i].lineIdx] != null) continue; // user-defined direction wins
 const prevN = i > 0 ? ord[i - 1] : null;
 const before = linkCost(prevN, ord[i]) +
 (i + 1 < ord.length ? edgeCost(ord[i], ord[i + 1]) : 0);
 const flipped = { lineIdx: ord[i].lineIdx, reversed: !ord[i].reversed };
 const after = linkCost(prevN, flipped) +
 (i + 1 < ord.length ? edgeCost(flipped, ord[i + 1]) : 0);
 if (after < before - 0.5) {
 ord[i] = flipped;
 improved = true;
 }
 }
 }
 return ord;
 }

 // Perturbation: double-bridge move to escape local optima
 function doubleBridge(ord) {
 if (ord.length < 8) return ord;
 const len = ord.length;
 const cuts = [0];
 while (cuts.length < 4) {
 const c = 1 + Math.floor(Math.random() * (len - 2));
 if (!cuts.includes(c)) cuts.push(c);
 }
 cuts.sort((a, b) =>a - b);
 cuts.push(len);
 const a = ord.slice(cuts[0], cuts[1]);
 const b = ord.slice(cuts[1], cuts[2]);
 const c = ord.slice(cuts[2], cuts[3]);
 const d = ord.slice(cuts[3], cuts[4]);
 return [...a, ...c, ...b, ...d]; // reconnect in different order
 }

 // Local-search pipeline: run each operator to (near) local optimality.
 function fullImprove(ord) {
 ord = twoOptImprove(ord);
 if (timeUp()) return ord;
 ord = directionOptimize(ord);
 if (timeUp()) return ord;
 ord = orOptImprove(ord);
 if (timeUp()) return ord;
 ord = directionOptimize(ord);
 return ord;
 }

 // Random segment-reversal perturbation (alternative kick to double-bridge)
 function segmentReversalKick(ord) {
 if (ord.length < 4) return ord;
 const lo = 1 + Math.floor(Math.random() * (ord.length - 3));
 const hi = lo + 1 + Math.floor(Math.random() * (ord.length - lo - 1));
 const out = ord.slice(0, lo);
 for (let k = hi; k >= lo; k--) {
 out.push(flipEntry(ord[k]));
 }
 return out.concat(ord.slice(hi + 1));
 }

 // --- PHASE 1: Multi-start construction ---
 // Seed from many different start lines/directions to diversify the search.
 const maxStarts = (userStartLocked || nnOnly) ? 1 : Math.min(2 * n, 24);
 let bestSolution = null;
 let bestTotalCost = Infinity;

 const startCandidates = [];
 if (userStartLocked) {
 // Only the user-specified start (line + direction, or the entry point
 // nearest a custom start point) may begin the route.
 startCandidates.push({ idx: startIdx, rev: startReversed });
 } else {
 startCandidates.push({ idx: startIdx, rev: startReversed });
 startCandidates.push({ idx: startIdx, rev: !startReversed });
 // Try all lines as starts (both forward and reverse)
 for (let i = 0; i < n; i++) {
 if (i === startIdx) continue;
 startCandidates.push({ idx: i, rev: false });
 startCandidates.push({ idx: i, rev: true });
 }
 }

 let initialCost = Infinity;
 for (const cand of startCandidates.slice(0, maxStarts)) {
 if (timeUp()) break;
 let sol = buildNNSolution(cand.idx, cand.rev);
 const nnCost = transitCost(sol);
 if (nnCost < initialCost) initialCost = nnCost; // best greedy baseline
 if (!nnOnly) sol = fullImprove(sol);
 const cost = transitCost(sol);
 if (cost < bestTotalCost) {
 bestTotalCost = cost;
 bestSolution = sol;
 }
 }

 // --- PHASE 1.5: LKH-3 server solver (near-optimal tour) ---
 // The Dubins transit-time matrix is encoded as an ATSP (two nodes per
 // line + fixed edges; direction locks and a locked start are hard
 // constraints) and solved by LKH-3 on the VPS - typically within ~1% of
 // the proven optimum. Synchronous call (the whole planner is synchronous);
 // falls back silently to the local search when offline or on any error.
 function callLkhSolver() {
 if (nnOnly || n < 4 || n > 500) return null;
 if (typeof XMLHttpRequest === 'undefined') return null;
 try {
 const m = new Array(n * n * 4);
 for (let i = 0; i < n; i++) {
 for (let j = 0; j < n; j++) {
 const d = D[i][j], base = (i * n + j) * 4;
 m[base] = Math.round(d.ff); m[base + 1] = Math.round(d.fr);
 m[base + 2] = Math.round(d.rf); m[base + 3] = Math.round(d.rr);
 }
 }
 const payload = JSON.stringify({
 n, m, fixed: fixedRev,
 start: userStartLocked ? { idx: startIdx, rev: startReversed } : null
 });
 const xhr = new XMLHttpRequest();
 xhr.open('POST', '/api/solve-route.php', false);
 xhr.setRequestHeader('Content-Type', 'application/json');
 xhr.send(payload);
 if (xhr.status !== 200) return null;
 const res = JSON.parse(xhr.responseText);
 if (!res.ok || !Array.isArray(res.order) || res.order.length !== n) return null;
 // Validate: permutation of all lines, constraints respected
 const seenL = new Set();
 for (const o of res.order) {
 if (o.lineIdx < 0 || o.lineIdx >= n || seenL.has(o.lineIdx)) return null;
 seenL.add(o.lineIdx);
 if (fixedRev[o.lineIdx] != null && !!o.reversed !== fixedRev[o.lineIdx]) return null;
 }
 if (userStartLocked && res.order[0].lineIdx !== startIdx) return null;
 // Held-Karp lower bound on the line-to-line transit of ANY valid tour.
 // This is what lets the plan claim a proven optimality gap rather than
 // just "deeply searched".
 if (typeof res.lowerBoundSec === 'number' && res.lowerBoundSec > 0) {
 lkhLowerBoundSec = res.lowerBoundSec;
 }
 return res.order.map(o => ({ lineIdx: o.lineIdx, reversed: !!o.reversed }));
 } catch (e) {
 return null;
 }
 }
 let lkhUsed = false;
 let lkhLowerBoundSec = null;
 if (!nnOnly) {
 const lkhOrd = callLkhSolver();
 if (lkhOrd) {
 const sol = fullImprove(lkhOrd.map(o => ({ ...o })));
 const cost = transitCost(sol);
 if (cost < bestTotalCost) {
 bestTotalCost = cost;
 bestSolution = sol;
 }
 lkhUsed = true;
 }
 }

 // --- PHASE 2: Iterated Local Search (deep exhaustive-style search) ---
 // Repeatedly kick the best-known solution out of its local optimum and
 // re-optimize, for the full configured iteration count (default 1500).
 // Unlike the previous version there is NO short time budget - only a
 // generous safety cap guards against browser hangs.
 // When LKH-3 provided the seed the tour is already near-optimal - a short
 // polish suffices instead of the full iteration budget.
 const effIterations = lkhUsed ? Math.min(200, targetIterations) : targetIterations;
 let iterationsRun = 0;
 if (!nnOnly && bestSolution && n >= 4) {
 let current = bestSolution.map(o => ({ ...o }));
 let currentCost = bestTotalCost;
 let stagnation = 0;
 for (let iter = 0; iter < effIterations; iter++) {
 if (timeUp()) break;
 iterationsRun = iter + 1;

 // Kick: mostly double-bridge (classic ILS for TSP-like problems);
 // occasionally a segment reversal, and after long stagnation restart
 // from a fresh random NN seed for extra diversification.
 let cand;
 if (stagnation >= 100 && !userStartLocked) {
 const rIdx = Math.floor(Math.random() * n);
 cand = buildNNSolution(rIdx, Math.random() < 0.5);
 stagnation = 0;
 } else if (Math.random() < 0.75) {
 cand = doubleBridge(current.map(o => ({ ...o })));
 } else {
 cand = segmentReversalKick(current.map(o => ({ ...o })));
 }

 cand = fullImprove(cand);
 const cost = transitCost(cand);

 // Acceptance: better-or-equal accepts (allows lateral moves along
 // plateaus); best-so-far is always recorded separately.
 if (cost <= currentCost) {
 current = cand;
 currentCost = cost;
 } else {
 stagnation++;
 }
 if (cost < bestTotalCost - 0.5) {
 bestTotalCost = cost;
 bestSolution = cand.map(o => ({ ...o }));
 stagnation = 0;
 }
 }
 }

 // --- PHASE 3: STRATEGY CROSS-CHECK (proof the plan is the quickest) ---
 // Evaluate every directional progression as a candidate plan under the
 // SAME Dubins transit-time model. If any beats the deep search it is
 // adopted; otherwise the margin over the best alternative is reported so
 // the chosen plan is verifiably the fastest of all candidate strategies.
 let altBestSec = Infinity, altBestName = null, altChecked = 0;
 if (!nnOnly && bestSolution && !timeUp()) {
 const numKey = lines.map((l, i) => {
 const v = _lineNumOf(l, null);
 return v != null ? v : i;
 });
 const idxAll = lines.map((_, i) =>i);
 const strategies = {
 'Low\u2192High': idxAll.slice().sort((a, b) =>numKey[a] - numKey[b]),
 'High\u2192Low': idxAll.slice().sort((a, b) =>numKey[b] - numKey[a]),
 'West\u2192East': idxAll.slice().sort((a, b) =>midpoints[a][1] - midpoints[b][1]),
 'East\u2192West': idxAll.slice().sort((a, b) =>midpoints[b][1] - midpoints[a][1]),
 'South\u2192North': idxAll.slice().sort((a, b) =>midpoints[a][0] - midpoints[b][0]),
 'North\u2192South': idxAll.slice().sort((a, b) =>midpoints[b][0] - midpoints[a][0])
 };
 for (const [name, idxOrder] of Object.entries(strategies)) {
 if (timeUp()) break;
 // A user-locked start line/point must stay first - skip plans that move it.
 if (userStartLocked && idxOrder[0] !== startIdx) continue;
 let ord = idxOrder.map(i => ({ lineIdx: i, reversed: fixedRev[i] != null ? fixedRev[i] : false }));
 ord = directionOptimize(ord);
 const cost = transitCost(ord);
 altChecked++;
 if (cost < altBestSec) { altBestSec = cost; altBestName = name; }
 if (cost < bestTotalCost - 0.5) {
 bestTotalCost = cost;
 bestSolution = ord.map(o => ({ ...o }));
 }
 }
 }

 // Record optimizer stats for reporting
 state._optimizerStats = {
 mode: nnOnly ? 'nn' : 'deep',
 solver: lkhUsed ? 'lkh3' : 'local',
 iterations: iterationsRun,
 starts: Math.min(startCandidates.length, maxStarts),
 greedySec: isFinite(initialCost) ? initialCost : null,
 finalSec: isFinite(bestTotalCost) ? bestTotalCost : null,
 altChecked,
 altBestSec: isFinite(altBestSec) ? altBestSec : null,
 altBestName,
 elapsedMs: Date.now() - optimizerStart,
 capped: timeUp(),
 lowerBoundSec: lkhLowerBoundSec,
 // Gap against the proven bound, measured on the line-to-line transit only
 // (the bound does not model the depot leg). Priority groups and direction
 // locks constrain the route further, so the gap is then measured against
 // the UNCONSTRAINED optimum and is reported as such.
 gapPct: null,
 gapConstrained: priorities.some(p =>p !== 50) ||
 fixedRev.some(f =>f != null) || !!depotPt
 };
 if (lkhLowerBoundSec && bestSolution) {
 const lineOnly = transitCost(bestSolution) - depotSec(bestSolution[0]);
 state._optimizerStats.gapPct = ((lineOnly - lkhLowerBoundSec) / lkhLowerBoundSec) * 100;
 }

 // Hitting the safety cap means the search stopped early and the plan is
 // NOT the deep-search result - say so instead of silently degrading.
 if (state._optimizerStats.capped) {
 showToast(`s Optimizer hit the ${Math.round(safetyCapMs / 1000)} s safety cap after ` +
 `${iterationsRun} of ${effIterations} iterations - the route may not be the fastest ` +
 `possible. Reduce the line count or lower the iteration setting.`, 9000);
 }

 // Use the best solution found
 if (bestSolution) {
 // Post-process: reorder by priority while preserving optimized order within each priority group
 const groups = new Map(); // priority ->array of route entries
 for (const o of bestSolution) {
 const prio = priorities[o.lineIdx];
 if (!groups.has(prio)) groups.set(prio, []);
 groups.get(prio).push(o);
 }
 // Concatenate groups in ascending priority order (1 first ... 100 last).
 // Regrouping a globally optimized tour into priority buckets shreds its
 // transit ordering, so each bucket is RE-OPTIMIZED as its own sub-tour,
 // chained to the previous bucket: the previous bucket'last line is
 // prepended as a locked anchor so the hand-off transit is costed too.
 const sortedPriorities = Array.from(groups.keys()).sort((a, b) =>a - b);
 const savedLock = userStartLocked, savedDepot = depotPt;
 let anchor = null;
 for (const prio of sortedPriorities) {
 let blk = groups.get(prio).map(o => ({ ...o }));
 if (blk.length > 1 && !nnOnly && !timeUp()) {
 if (anchor) {
 userStartLocked = true;
 depotPt = null;
 blk = fullImprove([anchor, ...blk]).slice(1);
 } else {
 userStartLocked = savedLock;
 depotPt = savedDepot;
 blk = fullImprove(blk);
 }
 }
 anchor = blk[blk.length - 1];
 for (const o of blk) {
 visited.add(o.lineIdx);
 order.push(o);
 }
 }
 userStartLocked = savedLock;
 depotPt = savedDepot;
 // A user-locked start (start line or custom start point) must stay FIRST
 // even after priority regrouping - the explicit start wins.
 if (userStartLocked && order.length && bestSolution.length &&
 order[0].lineIdx !== bestSolution[0].lineIdx) {
 const sPos = order.findIndex(o =>o.lineIdx === bestSolution[0].lineIdx);
 if (sPos > 0) order.unshift(order.splice(sPos, 1)[0]);
 }
 } else {
 // Fallback: basic NN from user start
 visited.add(startIdx);
 order.push({ lineIdx: startIdx, reversed: startReversed });
 while (visited.size < n) {
 const cur = order[order.length - 1];
 const curLine = lines[cur.lineIdx];
 const curEnd = cur.reversed ? curLine.start : curLine.end;
 let bestCost = Infinity, bestI = -1, bestR = false;
 for (let i = 0; i < n; i++) {
 if (visited.has(i)) continue;
 const dF = haversine(curEnd, lines[i].start);
 const dR = haversine(curEnd, lines[i].end);
 if (dF < bestCost) { bestCost = dF; bestI = i; bestR = false; }
 if (dR < bestCost) { bestCost = dR; bestI = i; bestR = true; }
 }
 if (bestI === -1) break;
 visited.add(bestI);
 order.push({ lineIdx: bestI, reversed: bestR });
 }
 }
 }

 // GLOBAL PRIORITY PASS: acquisition priority (1 first ... 100 last, 50 =
 // Neutral) must be honoured in EVERY progression mode. The directional
 // progressions sort priority-first and the auto optimizer regroups, but the
 // 3D interleave optimizer and its round-robin fallback ordered purely by
 // transit time - silently ignoring priorities. Stable regroup here:
 // preserves the planner'order within each priority group, and a
 // user-locked start line / start point stays first.
 if (order.length > 1 && priorities.some(p =>p !== 50)) {
 const before = order.map(o =>o.lineIdx).join(',');
 const firstEntry = order[0];
 const regrouped = order.slice().sort((a, b) =>priorities[a.lineIdx] - priorities[b.lineIdx]);
 if ((startLineObj || state.settings.startPoint) && regrouped[0] !== firstEntry) {
 const sPos = regrouped.indexOf(firstEntry);
 if (sPos > 0) regrouped.unshift(regrouped.splice(sPos, 1)[0]);
 }
 order.length = 0;
 order.push(...regrouped);
 if ((progression === 'interleaved' || progression === 'interleaved-reverse') &&
 order.map(o =>o.lineIdx).join(',') !== before) {
 showToast('Line priorities override swath interleave order for prioritized lines', 5000);
 }
 }

 // Initial acquisition directions are USER-DEFINED via the Survey Criteria
 // menu. The directional/interleaved progressions already apply the per-swath
 // Low'High / High'Low settings (swathDirOf); the free 'auto' optimizer
 // honours the 2D "Line Direction" criteria setting here - the optimizer then
 // only chooses the line ORDER. 'auto' keeps the planner'turn-efficient
 // directions. Per-line Line-Manager direction locks (enforced below), an
 // explicit start-line direction and infill same/opposite (below) still win.
 if (progression === 'auto') {
 const mode = state.settings.lineDirection2d || 'auto';
 if (mode !== 'auto') {
 let firstRev = (mode === 'high-low');
 if (startLineObj && order.length &&
 order[0].lineIdx === _startIdxIn(lines)) {
 firstRev = !!state.settings.startLineReversed;
 }
 order.forEach((o, pos) => {
 if (mode === 'alternate') o.reversed = ((pos % 2 === 1) !== firstRev);
 else if (pos === 0) o.reversed = firstRev;
 else o.reversed = (mode === 'high-low');
 });
 }
 }

 // Enforce user-defined (locked) line acquisition directions. This runs after
 // both the directional-progression and auto-optimiser branches so that a
 // line the user explicitly reversed in the Line Manager is always acquired
 // start'end, regardless of any turn-efficiency choices the planner made.
 order.forEach(o => {
 if (_lineDirLocked(lines[o.lineIdx])) o.reversed = false;
 });

 // Infill direction pass: an infill line's 'same'/'opposite' choice is relative
 // to the swath progression, which is embodied by its parent line'actual
 // acquisition direction in the route. The same/opposite offset is already
 // baked into the infill geometry, so acquiring the infill with the SAME route
 // flip as its parent makes it follow the swath progression direction. 'auto'
 // infill keeps the planner'turn-efficient choice, and a user-forced infill
 // direction (handled above) still wins.
 const _posByLineIdx = new Map();
 order.forEach((o, pos) => _posByLineIdx.set(o.lineIdx, pos));
 order.forEach(o => {
 const ln = lines[o.lineIdx];
 if (!ln || !ln._infill) return;
 if (ln._forcedDirection) return; // explicit per-line override wins
 if (ln._infillDirection !== 'same' && ln._infillDirection !== 'opposite') return; // 'auto' ' planner decides
 if (ln._parentLineId == null) return;
 const pIdx = lines.findIndex(l =>l.id === ln._parentLineId);
 if (pIdx >= 0 && _posByLineIdx.has(pIdx)) {
 o.reversed = order[_posByLineIdx.get(pIdx)].reversed;
 }
 });

 // Record the planner'intended acquisition direction per line so the Line
 // Manager can display it. Keyed by line id; partial '-segN' segment ids also
 // map back to their parent line id.
 {
 const pd = {};
 order.forEach(o => {
 const ln = lines[o.lineIdx];
 if (!ln) return;
 pd[ln.id] = !!o.reversed;
 if (ln._partial) pd[String(ln.id).replace(/-seg\d+$/, '')] = !!o.reversed;
 });
 state._plannedDir = pd;
 }

 // Build waypoints from order, with obstruction avoidance
 const waypoints = [];
 const { runIn, runOut } = state.settings;
 state.skippedRanges = [];

 order.forEach(({ lineIdx, reversed }) => {
 const line = lines[lineIdx];
 let s = reversed ? line.end : line.start;
 let e = reversed ? line.start : line.end;

 // Check for obstruction intersections on this line segment
 const intersections = findLineObstructionIntersections(s, e);

 if (intersections.length === 0) {
 // Include run-in/out as part of the route path
 const brng = bearing(s, e);
 if (runIn > 0) {
 const riPt = destinationPoint(s, (brng + 180) % 360, runIn);
 waypoints.push({ type: 'runInStart', pt: riPt, lineName: line.name });
 }
 waypoints.push({ type: 'lineStart', pt: s, lineName: line.name });
 waypoints.push({ type: 'lineEnd', pt: e, lineName: line.name });
 if (runOut > 0) {
 const roPt = destinationPoint(e, brng, runOut);
 waypoints.push({ type: 'runOutEnd', pt: roPt, lineName: line.name });
 }
 } else {
 // Obstructions found - split line into clear segments and route around obstructed portions
 // intersections: [{ enterFrac, exitFrac, obstructionIdx }] sorted by enterFrac
 intersections.sort((a, b) =>a.enterFrac - b.enterFrac);

 const lineDistM = haversine(s, e);
 const lineDistKm = lineDistM / 1000;
 const R = getEffectiveTurnRadius(); // min turn radius in metres
 // User-specified cross-track offline (m) beyond which SP are not acquired
 const offlineThresh = getOfflineNoSpThresholdM() || suggestOfflineNoSpM();
 // True preplot line separation (not swath width stored in settings.lineSpacing)
 const lineSep = getPreplotLineSeparationM();

 // Break off ~1R before the exclusion boundary so the vessel can turn
 // offline without cutting through the zone. Rejoin ~1R after.
 const turnBufferFrac = lineDistM > 0 ? R / lineDistM : 0;

 // Expand enter/exit fractions by turn buffer
 const buffered = intersections.map(rng => ({
 enterFrac: Math.max(0, rng.enterFrac - turnBufferFrac),
 exitFrac: Math.min(1, rng.exitFrac + turnBufferFrac),
 obstructionIdx: rng.obstructionIdx,
 obsEnterFrac: rng.enterFrac,
 obsExitFrac: rng.exitFrac
 }));

 // Merge overlapping buffered ranges
 const merged = [{ ...buffered[0] }];
 for (let k = 1; k < buffered.length; k++) {
 const prev = merged[merged.length - 1];
 if (buffered[k].enterFrac <= prev.exitFrac) {
 prev.exitFrac = Math.max(prev.exitFrac, buffered[k].exitFrac);
 prev.obsExitFrac = Math.max(prev.obsExitFrac, buffered[k].obsExitFrac);
 } else {
 merged.push({ ...buffered[k] });
 }
 }

 // Build segmented waypoints: clear portions as survey, obstructed portions as obsAvoidance
 let lastFrac = 0;
 merged.forEach((rng, idx) => {
 // Clear segment before this obstruction (accounting for turn buffer)
 if (rng.enterFrac > lastFrac) {
 const segStart = interpolatePoint(s, e, lastFrac);
 const segEnd = interpolatePoint(s, e, rng.enterFrac);
 if (lastFrac === 0 && runIn > 0) {
 const brng = bearing(segStart, segEnd);
 const riPt = destinationPoint(segStart, (brng + 180) % 360, runIn);
 waypoints.push({ type: 'runInStart', pt: riPt, lineName: line.name });
 }
 waypoints.push({ type: 'lineStart', pt: segStart, lineName: line.name, frac: lastFrac });
 waypoints.push({ type: 'lineEnd', pt: segEnd, lineName: line.name, frac: rng.enterFrac });
 }

 // Obstruction avoidance detour (Dubins-smoothed, clearance >= R)
 const detourStart = interpolatePoint(s, e, rng.enterFrac);
 const detourEnd = interpolatePoint(s, e, rng.exitFrac);
 const detourPath = computeDetourPath(detourStart, detourEnd, rng.obstructionIdx);
 waypoints.push({ type: 'obsAvoidStart', pt: detourStart, lineName: line.name, obstructionIdx: rng.obstructionIdx, frac: rng.enterFrac });
 detourPath.forEach((pt, pi) => {
 if (pi === 0 || pi === detourPath.length - 1) return; // skip start/end dupes
 waypoints.push({ type: 'obsAvoidance', pt, lineName: line.name });
 });
 waypoints.push({ type: 'obsAvoidEnd', pt: detourEnd, lineName: line.name, obstructionIdx: rng.obstructionIdx, frac: rng.exitFrac });

 // Sacrifice coverage where vessel is more than the user offline threshold
 // from the planned survey line (no SP acquired on that along-line span).
 const sacrificed = sacrificedRangeFromDetour(s, e, detourPath, offlineThresh);
 if (sacrificed) {
 // Prefer SP count from the line's SP records when available
 let spLost = sacrificed.spLost;
 const spInt = state.settings.spInterval || 12.5;
 const lineSp = lineSpCount(line, spInt);
 if (lineSp > 2) {
  spLost = Math.max(0, Math.round((sacrificed.toFrac - sacrificed.fromFrac) * lineSp));
 }
 state.skippedRanges.push({
 lineName: line.name,
 lineId: line.id,
 fromFrac: sacrificed.fromFrac,
 toFrac: sacrificed.toFrac,
 distKm: sacrificed.distKm,
 spLost,
 maxOfflineM: sacrificed.maxOfflineM,
 offlineThresholdM: sacrificed.offlineThresholdM || offlineThresh,
 lineSepM: lineSep,
 obsEnterFrac: rng.obsEnterFrac,
 obsExitFrac: rng.obsExitFrac,
 turnBufferFrac: turnBufferFrac
 });
 }

 lastFrac = rng.exitFrac;
 });

 // Clear segment after last obstruction
 if (lastFrac < 1) {
 const segStart = interpolatePoint(s, e, lastFrac);
 waypoints.push({ type: 'lineStart', pt: segStart, lineName: line.name, frac: lastFrac });
 waypoints.push({ type: 'lineEnd', pt: e, lineName: line.name, frac: 1.0 });
 if (runOut > 0) {
 const brng = bearing(segStart, e);
 const roPt = destinationPoint(e, brng, runOut);
 waypoints.push({ type: 'runOutEnd', pt: roPt, lineName: line.name });
 }
 }
 }
 });

 // Post-process: route transit segments around obstructions too.
 // Transit must avoid exclusion zones on BOTH the straight chord AND the
 // Dubins turn that renderRoute draws (large R loops often clip a hazard
 // the straight line misses).
 if (state.obstructions.length > 0) {
 const finalWaypoints = [];
 for (let i = 0; i < waypoints.length; i++) {
 finalWaypoints.push(waypoints[i]);

 if (i < waypoints.length - 1) {
 const cur = waypoints[i];
 const nxt = waypoints[i + 1];
 // Skip survey line segments (already handled)
 if (cur.type === 'lineStart' && nxt.type === 'lineEnd' && cur.lineName === nxt.lineName) continue;
 // Skip run-in/out segments
 if (cur.type === 'runInStart' && nxt.type === 'lineStart' && cur.lineName === nxt.lineName) continue;
 if (cur.type === 'lineEnd' && nxt.type === 'runOutEnd' && cur.lineName === nxt.lineName) continue;
 // Skip obstruction avoidance segments (already routed around obstructions)
 if (cur.type === 'obsAvoidStart' || cur.type === 'obsAvoidance' || cur.type === 'obsAvoidEnd') continue;
 if (nxt.type === 'obsAvoidStart' || nxt.type === 'obsAvoidance' || nxt.type === 'obsAvoidEnd') continue;
 if (cur.type === 'detour' || nxt.type === 'detour') continue;
 if (cur.type === 'transit-detour' || nxt.type === 'transit-detour') continue;

 // Chord + the rendered Dubins turn (same geometry renderRoute will use)
 const chordHits = findLineObstructionIntersections(cur.pt, nxt.pt);
 let arcPts = null;
 try { arcPts = computeArcTurn(waypoints, i); } catch (_) { arcPts = [cur.pt, nxt.pt]; }
 const arcHits = polylineHitsObstruction(arcPts);

 if (chordHits.length > 0 || arcHits) {
 transitHitsToDetour: {
  // Prefer primary obstruction from chord; fall back to arc sample
  let primaryIdx = chordHits.length ? chordHits[0].obstructionIdx : firstObstructionHitByPolyline(arcPts);
  // Whole-leg detour: safer than partial chord enter/exit when the Dubins
  // loop is what actually hits (enter/exit of chord may be null).
  const detourPath = computeDetourPath(cur.pt, nxt.pt, primaryIdx);
  if (!detourPath || detourPath.length < 2) break transitHitsToDetour;
  // Skip first point (current waypoint already pushed)
  detourPath.forEach((pt, idx) => {
   if (idx === 0) return;
   // Avoid duplicating the exact next waypoint as a detour penultimate
   if (idx === detourPath.length - 1) {
    const dLat = Math.abs(pt[0] - nxt.pt[0]);
    const dLon = Math.abs(pt[1] - nxt.pt[1]);
    if (dLat < 1e-9 && dLon < 1e-9) return;
   }
   finalWaypoints.push({ type: 'transit-detour', pt, lineName: '', obstructionIdx: primaryIdx });
  });
 }
 }
 }
 }
 return finalWaypoints;
 }

 return waypoints;
}

// ===== DUBINS PATH SOLVER =====
// Proper geometric Dubins path: shortest path between two oriented points
// subject to a minimum turn radius R. Path consists of arcs and straights.
// No Bezier approximation - actual circular arcs computed geometrically.

function computeArcTurn(waypoints, i) {
 const a = waypoints[i], b = waypoints[i + 1];
 const dist = haversine(a.pt, b.pt);
 if (dist < 10) return [a.pt, b.pt];

 // Use configured turn radius - vessel cannot turn tighter than this
 const R = getEffectiveTurnRadius(); // metres

 // Determine headings (in degrees, clockwise from north)
 let hdg1 = bearing(a.pt, b.pt); // fallback
 if (i > 0) hdg1 = bearing(waypoints[i - 1].pt, a.pt);
 let hdg2 = bearing(a.pt, b.pt); // fallback
 if (i + 2 < waypoints.length) hdg2 = bearing(b.pt, waypoints[i + 2].pt);

 // Convert to local XY (metres) centered on midpoint
 const midLat = (a.pt[0] + b.pt[0]) / 2;
 const midLon = (a.pt[1] + b.pt[1]) / 2;
 const mPerDegLat = 111320;
 const mPerDegLon = 111320 * Math.cos(midLat * Math.PI / 180);

 const x1 = (a.pt[1] - midLon) * mPerDegLon;
 const y1 = (a.pt[0] - midLat) * mPerDegLat;
 const x2 = (b.pt[1] - midLon) * mPerDegLon;
 const y2 = (b.pt[0] - midLat) * mPerDegLat;

 // Convert headings to math angle (radians, CCW from +X axis)
 const th1 = (90 - hdg1) * Math.PI / 180;
 const th2 = (90 - hdg2) * Math.PI / 180;

 // Compute Dubins path in local XY
 const path = dubinsShortestPath(x1, y1, th1, x2, y2, th2, R);

 // Convert path points back to lat/lon
 return path.map(p => [
 midLat + p[1] / mPerDegLat,
 midLon + p[0] / mPerDegLon
 ]);
}

// Compute the shortest Dubins path between two configurations.
// Returns array of [x,y] points along the path.
function dubinsShortestPath(x1, y1, th1, x2, y2, th2, R) {
 const dx = x2 - x1, dy = y2 - y1;
 const d = Math.sqrt(dx * dx + dy * dy);

 // Normalize: translate to origin, rotate so start heading is along +X
 const phi = Math.atan2(dy, dx);
 const alpha = th1 - phi; // start heading relative to line connecting points
 const beta = th2 - phi; // end heading relative to line connecting points
 const dNorm = d / R; // normalized distance

 // Try all 6 Dubins path types, pick shortest
 const paths = [
 dubinsLSL(alpha, beta, dNorm),
 dubinsRSR(alpha, beta, dNorm),
 dubinsLSR(alpha, beta, dNorm),
 dubinsRSL(alpha, beta, dNorm),
 dubinsRLR(alpha, beta, dNorm),
 dubinsLRL(alpha, beta, dNorm)
 ].filter(p =>p !== null);

 if (paths.length === 0) {
 // Fallback: straight line
 return [[x1, y1], [x2, y2]];
 }

 // Shortest first, but only accept a candidate whose generated geometry actually
 // arrives at the target configuration - a malformed segment sequence would draw
 // a plausible-looking loop that never joins the next line.
 paths.sort((a, b) =>a.length - b.length);
 const tol = Math.max(50, R * 0.01);
 for (const cand of paths) {
 const pts = dubinsGeneratePoints(x1, y1, th1, cand.segments, R, phi);
 const end = pts[pts.length - 1];
 if (Math.hypot(end[0] - x2, end[1] - y2) <= tol) return pts;
 }
 return dubinsGeneratePoints(x1, y1, th1, paths[0].segments, R, phi);
}

function mod2pi(angle) {
 let a = angle % (2 * Math.PI);
 if (a < 0) a += 2 * Math.PI;
 return a;
}

// CSC paths
function dubinsLSL(alpha, beta, d) {
 const ca = Math.cos(alpha), sa = Math.sin(alpha);
 const cb = Math.cos(beta), sb = Math.sin(beta);
 const tmp = 2 + d * d - 2 * (ca * cb + sa * sb - d * (sa - sb));
 if (tmp < 0) return null;
 const p = Math.sqrt(tmp);
 const theta = Math.atan2(cb - ca, d + sa - sb);
 const t = mod2pi(-alpha + theta);
 const q = mod2pi(beta - theta);
 return { length: t + p + q, segments: [{ type: 'L', len: t }, { type: 'S', len: p }, { type: 'L', len: q }] };
}

function dubinsRSR(alpha, beta, d) {
 const ca = Math.cos(alpha), sa = Math.sin(alpha);
 const cb = Math.cos(beta), sb = Math.sin(beta);
 const tmp = 2 + d * d - 2 * (ca * cb + sa * sb - d * (sb - sa));
 if (tmp < 0) return null;
 const p = Math.sqrt(tmp);
 const theta = Math.atan2(ca - cb, d - sa + sb);
 const t = mod2pi(alpha - theta);
 const q = mod2pi(-beta + theta);
 return { length: t + p + q, segments: [{ type: 'R', len: t }, { type: 'S', len: p }, { type: 'R', len: q }] };
}

function dubinsLSR(alpha, beta, d) {
 const ca = Math.cos(alpha), sa = Math.sin(alpha);
 const cb = Math.cos(beta), sb = Math.sin(beta);
 const tmp = -2 + d * d + 2 * (ca * cb + sa * sb + d * (sa + sb));
 if (tmp < 0) return null;
 const p = Math.sqrt(tmp);
 const theta = Math.atan2(-ca - cb, d + sa + sb) - Math.atan2(-2, p);
 const t = mod2pi(-alpha + theta);
 const q = mod2pi(-beta + theta);
 return { length: t + p + q, segments: [{ type: 'L', len: t }, { type: 'S', len: p }, { type: 'R', len: q }] };
}

function dubinsRSL(alpha, beta, d) {
 const ca = Math.cos(alpha), sa = Math.sin(alpha);
 const cb = Math.cos(beta), sb = Math.sin(beta);
 const tmp = -2 + d * d + 2 * (ca * cb + sa * sb - d * (sa + sb));
 if (tmp < 0) return null;
 const p = Math.sqrt(tmp);
 const theta = Math.atan2(ca + cb, d - sa - sb) - Math.atan2(2, p);
 const t = mod2pi(alpha - theta);
 const q = mod2pi(beta - theta);
 return { length: t + p + q, segments: [{ type: 'R', len: t }, { type: 'S', len: p }, { type: 'L', len: q }] };
}

// CCC paths
function dubinsRLR(alpha, beta, d) {
 const ca = Math.cos(alpha), sa = Math.sin(alpha);
 const cb = Math.cos(beta), sb = Math.sin(beta);
 const tmp = (6 - d * d + 2 * (ca * cb + sa * sb) + 2 * d * (sa - sb)) / 8;
 if (Math.abs(tmp) > 1) return null;
 const p = mod2pi(2 * Math.PI - Math.acos(tmp));
 const theta = Math.atan2(ca - cb, d - sa + sb);
 const t = mod2pi(alpha - theta + p / 2);
 const q = mod2pi(alpha - beta - t + p);
 return { length: t + p + q, segments: [{ type: 'R', len: t }, { type: 'L', len: p }, { type: 'R', len: q }] };
}

function dubinsLRL(alpha, beta, d) {
 const ca = Math.cos(alpha), sa = Math.sin(alpha);
 const cb = Math.cos(beta), sb = Math.sin(beta);
 const tmp = (6 - d * d + 2 * (ca * cb + sa * sb) + 2 * d * (sb - sa)) / 8;
 if (Math.abs(tmp) > 1) return null;
 const p = mod2pi(2 * Math.PI - Math.acos(tmp));
 const theta = Math.atan2(-ca + cb, d + sa - sb);
 const t = mod2pi(-alpha + theta + p / 2);
 const q = mod2pi(beta - alpha - t + p);
 return { length: t + p + q, segments: [{ type: 'L', len: t }, { type: 'R', len: p }, { type: 'L', len: q }] };
}

// Generate XY points along a Dubins path
function dubinsGeneratePoints(x1, y1, th1, segments, R, phi) {
 const points = [];
 let cx = x1, cy = y1, cth = th1;
 const stepsPerSeg = 12;

 for (const seg of segments) {
 if (seg.type === 'S') {
 // Straight segment
 const len = seg.len * R;
 for (let s = 1; s <= stepsPerSeg; s++) {
 const frac = s / stepsPerSeg;
 points.push([
 cx + Math.cos(cth) * len * frac,
 cy + Math.sin(cth) * len * frac
 ]);
 }
 cx += Math.cos(cth) * len;
 cy += Math.sin(cth) * len;
 } else {
 // Arc segment (L = left/CCW, R = right/CW)
 const arcLen = seg.len; // in radians
 const dir = (seg.type === 'L') ? 1 : -1;
 // Center of turning circle
 const ccx = cx - dir * R * Math.sin(cth);
 const ccy = cy + dir * R * Math.cos(cth);
 // Starting angle on the circle
 const startAngle = Math.atan2(cy - ccy, cx - ccx);

 for (let s = 1; s <= stepsPerSeg; s++) {
 const frac = s / stepsPerSeg;
 const angle = startAngle + dir * arcLen * frac;
 points.push([
 ccx + R * Math.cos(angle),
 ccy + R * Math.sin(angle)
 ]);
 }
 // Update position and heading
 const endAngle = startAngle + dir * arcLen;
 cx = ccx + R * Math.cos(endAngle);
 cy = ccy + R * Math.sin(endAngle);
 cth = cth + dir * arcLen;
 }
 }

 // Prepend start point
 points.unshift([x1, y1]);
 return points;
}

// Compute actual Dubins path distance (in metres) for a transit between two route segments
function computeDubinsTransitDist(waypoints, startIdx, endIdx) {
 if (endIdx <= startIdx) return 0;
 const R = getEffectiveTurnRadius();
 let totalDist = 0;
 for (let i = startIdx; i < endIdx; i++) {
 const a = waypoints[i], b = waypoints[i + 1];
 const sameLine = a.lineName && b.lineName && a.lineName === b.lineName;
 if (sameLine) {
 totalDist += haversine(a.pt, b.pt);
 } else {
 // Use Dubins arc for this transit segment
 const arcPts = computeArcTurn(waypoints, i);
 let arcDist = 0;
 for (let k = 1; k < arcPts.length; k++) arcDist += haversine(arcPts[k - 1], arcPts[k]);
 totalDist += arcDist;
 }
 }
 return totalDist;
}

// ===== RENDER ROUTE =====
// Time-gradient color interpolation: green ' cyan ' yellow ' orange ' red
function timeGradientColor(fraction) {
 // 5-stop gradient: 0=green, 0.25=cyan, 0.5=yellow, 0.75=orange, 1.0=red
 const stops = [
 { t: 0.0, r: 48, g: 209, b: 88 }, // #30d158 green
 { t: 0.25, r: 0, g: 210, b: 255 }, // #00d2ff cyan
 { t: 0.5, r: 255, g: 214, b: 10 }, // #ffd60a yellow
 { t: 0.75, r: 255, g: 149, b: 0 }, // #ff9500 orange
 { t: 1.0, r: 255, g: 69, b: 58 } // #ff453a red
 ];
 const f = Math.max(0, Math.min(1, fraction));
 let lo = stops[0], hi = stops[stops.length - 1];
 for (let s = 0; s < stops.length - 1; s++) {
 if (f >= stops[s].t && f <= stops[s + 1].t) { lo = stops[s]; hi = stops[s + 1]; break; }
 }
 const range = hi.t - lo.t || 1;
 const t = (f - lo.t) / range;
 const r = Math.round(lo.r + (hi.r - lo.r) * t);
 const g = Math.round(lo.g + (hi.g - lo.g) * t);
 const b = Math.round(lo.b + (hi.b - lo.b) * t);
 return `rgb(${r},${g},${b})`;
}

function _addRouteArrow(from, to, color, layer, opacity) {
 // Place an arrow at the midpoint of the segment pointing in direction of travel.
 // Use a filled triangle (same glyph as vessel heading markers), rotated by bearing.
 const midLat = (from[0] + to[0]) / 2;
 const midLon = (from[1] + to[1]) / 2;
 const angle = bearing(from, to); // degrees clockwise from north
 const op = opacity != null ? opacity : 1;
 const icon = L.divIcon({
 className: '',
 html: `<div style="width:18px;height:18px;display:flex;align-items:center;justify-content:center;` +
  `transform:rotate(${angle}deg);transform-origin:center center;` +
  `color:${color};font-size:15px;line-height:1;font-weight:700;opacity:${op};` +
  `text-shadow:0 0 3px rgba(0,0,0,0.85);pointer-events:none;">&#9650;</div>`,
 iconAnchor: [9, 9],
 iconSize: [18, 18]
 });
 L.marker([midLat, midLon], { icon, interactive: false }).addTo(layer);
}

function _bezierSpline(points, segmentsPerCurve) {
 // Generate a smooth cubic Bezier spline through an array of [lat,lng] points
 // Uses Catmull-Rom ' Bezier conversion for smooth interpolation
 if (!points || points.length < 2) return points || [];
 if (points.length === 2) {
 // Simple linear interpolation for 2 points
 const result = [];
 const n = segmentsPerCurve || 8;
 for (let t = 0; t <= n; t++) {
 const f = t / n;
 result.push([
 points[0][0] + (points[1][0] - points[0][0]) * f,
 points[0][1] + (points[1][1] - points[0][1]) * f
 ]);
 }
 return result;
 }
 const n = segmentsPerCurve || 8;
 const result = [];
 // Extend points with virtual start/end for Catmull-Rom
 const ext = [points[0], ...points, points[points.length - 1]];
 for (let i = 1; i < ext.length - 2; i++) {
 const p0 = ext[i - 1], p1 = ext[i], p2 = ext[i + 1], p3 = ext[i + 2];
 // Catmull-Rom to cubic Bezier control points
 const cp1 = [
 p1[0] + (p2[0] - p0[0]) / 6,
 p1[1] + (p2[1] - p0[1]) / 6
 ];
 const cp2 = [
 p2[0] - (p3[0] - p1[0]) / 6,
 p2[1] - (p3[1] - p1[1]) / 6
 ];
 for (let t = 0; t <= n; t++) {
 if (t === 0 && i > 1) continue; // avoid duplicating junction points
 const f = t / n;
 const u = 1 - f;
 const lat = u*u*u*p1[0] + 3*u*u*f*cp1[0] + 3*u*f*f*cp2[0] + f*f*f*p2[0];
 const lng = u*u*u*p1[1] + 3*u*u*f*cp1[1] + 3*u*f*f*cp2[1] + f*f*f*p2[1];
 result.push([lat, lng]);
 }
 }
 return result;
}

function renderRoute(waypoints) {
 layerRoute.clearLayers();
 layerAnnotations.clearLayers();
 if (layerArrows) layerArrows.clearLayers();
 if (!waypoints || waypoints.length === 0) return;
 state._staleRouteObsHits = 0;

 const pts = waypoints.map(w =>w.pt);

 // Compute cumulative distance for time gradient
 const cumDist = [0];
 for (let i = 1; i < waypoints.length; i++) {
 cumDist.push(cumDist[i - 1] + haversine(waypoints[i - 1].pt, waypoints[i].pt));
 }
 const totalDist = cumDist[cumDist.length - 1] || 1;

 // Draw each segment with differentiated styles
 // Survey lines: bold coloured | Run-in/out: dotted white | Turns: thin dashed grey
 for (let i = 0; i < waypoints.length - 1; i++) {
 const a = waypoints[i], b = waypoints[i + 1];
 const frac = cumDist[i] / totalDist;
 const col = timeGradientColor(frac);

 if (a.type === 'lineStart' && b.type === 'lineEnd' && a.lineName === b.lineName) {
 // Survey line segment - bold solid colour. Never paint acquisition through
 // an exclusion (stale route before re-plan, or a missed intersection).
 if ((state.obstructions || []).length && findLineObstructionIntersections(a.pt, b.pt).length) {
  state._staleRouteObsHits = (state._staleRouteObsHits || 0) + 1;
  L.polyline([a.pt, b.pt], {
   color: '#e74c3c', weight: 2, opacity: 0.45, dashArray: '4,6'
  }).addTo(layerRoute);
 } else {
  L.polyline([a.pt, b.pt], { color: col, weight: 3.5, opacity: 1.0 }).addTo(layerRoute);
  _addRouteArrow(a.pt, b.pt, col, layerArrows);
 }
 } else if (a.type === 'lineEnd' && b.type === 'runOutEnd' && a.lineName === b.lineName) {
 // Run-out - same colour as the survey line (part of acquisition)
 L.polyline([a.pt, b.pt], { color: col, weight: 3, opacity: 0.9, dashArray: '8,4' }).addTo(layerRoute);
 _addRouteArrow(a.pt, b.pt, col, layerArrows, 0.9);
 } else if (a.type === 'runInStart' && b.type === 'lineStart' && a.lineName === b.lineName) {
 // Run-in - white dashed (part of line turn)
 L.polyline([a.pt, b.pt], { color: '#ffffff', weight: 2, opacity: 0.7, dashArray: '6,4' }).addTo(layerRoute);
 _addRouteArrow(a.pt, b.pt, '#ffffff', layerArrows, 0.7);
 } else if ((a.type === 'obsAvoidStart' || a.type === 'obsAvoidance' || a.type === 'obsAvoidEnd') &&
 (b.type === 'obsAvoidStart' || b.type === 'obsAvoidance' || b.type === 'obsAvoidEnd' ||
 b.type === 'lineStart') && a.lineName === b.lineName) {
 // Obstruction avoidance - path is already densified with Dubins arcs of radius R
 if (a.type === 'obsAvoidStart') {
 const obsAvoidPts = [a.pt];
 let k = i + 1;
 while (k < waypoints.length) {
 obsAvoidPts.push(waypoints[k].pt);
 if (waypoints[k].type === 'obsAvoidEnd') break;
 k++;
 }
 L.polyline(obsAvoidPts, { color: '#ffd60a', weight: 2.5, opacity: 0.9, dashArray: '6,4' }).addTo(layerRoute);
 if (obsAvoidPts.length >= 2) {
 const midIdx = Math.floor(obsAvoidPts.length / 2);
 const endIdx = Math.min(midIdx + 1, obsAvoidPts.length - 1);
 _addRouteArrow(obsAvoidPts[midIdx], obsAvoidPts[endIdx], '#ffd60a', layerArrows, 0.9);
 }
 }
 // Skip individual segment rendering (handled by block above)
 } else if ((a.type === 'lineEnd' && b.type === 'obsAvoidStart' && a.lineName === b.lineName) ||
 (a.type === 'obsAvoidEnd' && b.type === 'lineStart' && a.lineName === b.lineName)) {
 // Same-line transition into/out of obstruction avoidance - zero-length, skip
 } else if (a.type === 'detour' || b.type === 'detour' ||
 a.type === 'transit-detour' || b.type === 'transit-detour') {
 // Legacy detour / transit detour - dashed yellow
 L.polyline([a.pt, b.pt], { color: '#ffd60a', weight: 2.5, opacity: 0.9, dashArray: '6,4' }).addTo(layerRoute);
 } else {
 // Transit / line turn - Dubins arc respecting min turn radius
 const arcPts = computeArcTurn(waypoints, i);
 L.polyline(arcPts, { color: '#ff9500', weight: 2.5, opacity: 0.85 }).addTo(layerRoute);
 if (arcPts.length >= 2) {
 const midIdx = Math.floor(arcPts.length / 2);
 const endIdx = Math.min(midIdx + 1, arcPts.length - 1);
 _addRouteArrow(arcPts[midIdx], arcPts[endIdx], '#ff9500', layerArrows, 0.85);
 }
 }
 }

 // Start marker
 L.circleMarker(pts[0], {
 radius: 7, color: '#fff', fillColor: '#1abc9c', fillOpacity: 1, weight: 2
 }).bindTooltip('Start', { permanent: false }).addTo(layerAnnotations);

 // End marker
 L.circleMarker(pts[pts.length - 1], {
 radius: 7, color: '#fff', fillColor: '#e74c3c', fillOpacity: 1, weight: 2
 }).bindTooltip('End', { permanent: false }).addTo(layerAnnotations);

 // Line number labels (every lineStart)
 if (state.showAnnotations) {
 let lineNum = 1;
 waypoints.forEach((w, i) => {
 if (w.type === 'lineStart') {
 const frac = cumDist[i] / totalDist;
 const col = timeGradientColor(frac);
 const label = w.lineName || lineNum;
 const icon = L.divIcon({
 className: '',
 html: `<div style="color:#fff;font-size:12px;font-weight:700;background:${col};
 padding:3px 7px;border-radius:4px;border:2px solid #fff;
 box-shadow:0 2px 6px rgba(0,0,0,0.7);white-space:nowrap;
 pointer-events:none;line-height:1.2;">${label}</div>`,
 iconAnchor: [12, 12]
 });
 L.marker(w.pt, { icon }).addTo(layerAnnotations);
 lineNum++;
 }
 });
 }

 if (state._staleRouteObsHits > 0) {
  showToast(
   `Route still crosses ${state._staleRouteObsHits} exclusion segment(s) - click Plan Route to rebuild detours`,
   7000
  );
 }
}

// ===== ROUTE STATS =====
function showRouteStats(waypoints) {
 if (!waypoints || waypoints.length < 2) return;

 // Total route distance split by segment type (online vs line change vs obstruction avoidance)
 // Online = preplot line (lineStart'lineEnd) + run-out (lineEnd'runOutEnd)
 // Line change = turns, transits, run-ins
 // Obstruction avoidance = obsAvoidStart/obsAvoidance/obsAvoidEnd segments
 let onlineDist = 0; // metres on survey lines + run-outs
 let transitDist = 0; // metres on line changes (turns, transits, run-ins)
 let obsAvoidDist = 0; // metres on obstruction avoidance detours
 for (let i = 0; i < waypoints.length - 1; i++) {
 const a = waypoints[i], b = waypoints[i + 1];
 const sameLine = a.lineName && b.lineName && a.lineName === b.lineName;
 const isRunIn = sameLine && a.type === 'runInStart';
 const isObsAvoid = a.type === 'obsAvoidStart' || a.type === 'obsAvoidance' || a.type === 'obsAvoidEnd' ||
 b.type === 'obsAvoidStart' || b.type === 'obsAvoidance' || b.type === 'obsAvoidEnd';
 if (isObsAvoid) {
 // Obstruction avoidance - separate category
 obsAvoidDist += haversine(a.pt, b.pt);
 } else if (sameLine && !isRunIn) {
 // Online: preplot, run-out
 onlineDist += haversine(a.pt, b.pt);
 } else if (isRunIn) {
 // Run-in (runInStart'lineStart) - part of line change
 transitDist += haversine(a.pt, b.pt);
 } else {
 // Compute Dubins arc distance for this transit segment
 const arcPts = computeArcTurn(waypoints, i);
 let arcDist = 0;
 for (let k = 1; k < arcPts.length; k++) arcDist += haversine(arcPts[k - 1], arcPts[k]);
 transitDist += arcDist;
 }
 }
 const totalDist = onlineDist + transitDist + obsAvoidDist;
 const nm = totalDist / 1852;
 const onlineSpeed = state.settings.speed ?? 4;
 const turnSpeed = state.settings.turnSpeed ?? 6;
 const onlineHours = (onlineDist / 1852) / onlineSpeed;
 const transitHours = (transitDist / 1852) / turnSpeed;
 const obsAvoidHours = (obsAvoidDist / 1852) / turnSpeed; // obs avoidance at turn speed
 const hours = onlineHours + transitHours + obsAvoidHours;
 const hh = Math.floor(hours);
 const mm = Math.round((hours - hh) * 60);

 // Apply user-defined start time if available
 let startTimeStr = '';
 let endTimeStr = '';
 if (state.settings.startTime) {
 const startDate = new Date(state.settings.startTime);
 const endDate = new Date(startDate.getTime() + hours * 60 * 60 * 1000);
 startTimeStr = fmtDMT24(startDate);
 endTimeStr = fmtDMT24(endDate);
 }

 // Total survey line km: per-line numSP x spInterval (use full original line set)
 const allLines = state._allLines || state.lines;
 const nStr = state.settings.numStreamers || 6;
 const strSep = state.settings.streamerSeparation || 100;
 const spInt = state.settings.spInterval || 12.5;
 const crossLineM = (nStr * strSep) / 2;

 // Separate prime from infill and track acquired vs remaining
 let primeM = 0, infillM = 0;
 let primeAcquiredM = 0, primeRemainingM = 0;
 let infillAcquiredM = 0, infillRemainingM = 0;
 allLines.forEach(line => {
 const lineM = lineFullFoldM(line, spInt);
 const ls = (state.lineStatus && state.lineStatus[line.id]) || { status: 'planned', partialPct: 0 };
 if (line._infill) {
 infillM += lineM;
 if (ls.status === 'acquired') infillAcquiredM += lineM;
 else if ((ls.status === 'partial' || ls.status === 'partial_infill') && ls.partialPct > 0) {
 infillAcquiredM += lineM * (ls.partialPct / 100);
 infillRemainingM += lineM * (1 - ls.partialPct / 100);
 } else infillRemainingM += lineM;
 } else {
 primeM += lineM;
 if (ls.status === 'acquired') primeAcquiredM += lineM;
 else if ((ls.status === 'partial' || ls.status === 'partial_infill') && ls.partialPct > 0) {
 primeAcquiredM += lineM * (ls.partialPct / 100);
 primeRemainingM += lineM * (1 - ls.partialPct / 100);
 } else primeRemainingM += lineM;
 }
 });
 let primeKm = primeM / 1000;
 let infillKm = infillM / 1000;
 let primeAcquiredKm = primeAcquiredM / 1000;
 let primeRemainingKm = primeRemainingM / 1000;

 // Skipped km / SP (from obstruction detours where vessel is > offline threshold)
 let skippedKm = 0;
 let skippedSP = 0;
 let offlineThreshUsed = null;
 state.skippedRanges.forEach(r => {
  skippedKm += r.distKm || 0;
  skippedSP += r.spLost || 0;
  if (r.offlineThresholdM != null) offlineThreshUsed = r.offlineThresholdM;
 });
 if (offlineThreshUsed == null) offlineThreshUsed = getOfflineNoSpThresholdM();

 // Net full fold km / area / SP: subtract sacrificed coverage
 const netFullFoldKm = Math.max(0, primeKm - skippedKm);
 const sqKm = (netFullFoldKm * 1000) * crossLineM / 1000000;

 // Infill area
 const infillSqKm = (infillKm * 1000) * crossLineM / 1000000;

 // Acquired/remaining areas
 const primeAcquiredSqKm = (primeAcquiredM) * crossLineM / 1000000;
 const primeRemainingSqKm = (primeRemainingM) * crossLineM / 1000000;

 const is2D = (state.settings.surveyType || '3d') === '2d';
 document.getElementById('stat-distance').textContent = `${nm.toFixed(1)} nm total`;
 document.getElementById('stat-line-km').textContent = is2D
  ? `${netFullFoldKm.toFixed(3)} km prime`
  : `${netFullFoldKm.toFixed(3)} km prime full fold`;
 const sqEl = document.getElementById('stat-sq-km');
 if (sqEl) {
  sqEl.textContent = is2D ? '' : `${sqKm.toFixed(4)} km2 prime full fold`;
  sqEl.style.display = is2D ? 'none' : '';
 }
 setAreaStatsVisible(!is2D);
 
 // Show start/end times if available
 if (startTimeStr && endTimeStr) {
 document.getElementById('stat-time').textContent = `${startTimeStr} - ${endTimeStr} (${hh}h ${mm}m)`;
 } else {
 document.getElementById('stat-time').textContent = `${hh}h ${mm}m @ ${onlineSpeed}/${turnSpeed}kn`;
 }

 // Proven optimality readout: LKH-3'Held-Karp bound is a hard lower limit
 // on the transit of any possible line order, so this is a proof rather than
 // a claim. Created on demand so index.html needs no markup change.
 {
 const os = state._optimizerStats;
 const timeEl = document.getElementById('stat-time');
 let optEl = document.getElementById('stat-optimality');
 if (!optEl && timeEl && timeEl.parentNode) {
 optEl = document.createElement('div');
 optEl.id = 'stat-optimality';
 optEl.style.cssText = 'font-size:11px; margin-top:2px;';
 timeEl.parentNode.insertBefore(optEl, timeEl.nextSibling);
 }
 if (optEl) {
 if (os && os.gapPct != null) {
 const g = Math.max(0, os.gapPct);
 const ref = os.gapConstrained ? 'unconstrained optimum' : 'optimum';
 optEl.style.color = g < 0.005 ? '#34c759' : '#8e8e93';
 optEl.textContent = g < 0.005
 ? `Proven optimal transit (LKH-3 lower bound)`
 : `Proven within ${g.toFixed(2)}% of the ${ref} (LKH-3 lower bound)`;
 } else {
 optEl.textContent = '';
 }
 }
 }

 if (skippedKm > 0 || skippedSP > 0) {
 const thLabel = offlineThreshUsed != null ? `offline > ${offlineThreshUsed} m` : 'offline threshold';
 document.getElementById('stat-skipped').textContent =
 `${skippedKm.toFixed(2)} km sacrificed (${thLabel}, ${state.skippedRanges.length} zone${state.skippedRanges.length > 1 ? 's' : ''})`;
 const spEl = document.getElementById('stat-skipped-sp');
 if (spEl) spEl.textContent = skippedSP > 0 ? `${skippedSP.toLocaleString()} SP not acquired` : '';
 } else {
 document.getElementById('stat-skipped').textContent = '';
 const spEl = document.getElementById('stat-skipped-sp');
 if (spEl) spEl.textContent = '';
 }

 // Obstruction avoidance stats
 const obsAvoidEl = document.getElementById('stat-obs-avoid');
 if (obsAvoidEl) {
 if (obsAvoidDist > 0) {
 const oaHH = Math.floor(obsAvoidHours);
 const oaMM = Math.round((obsAvoidHours - oaHH) * 60);
 const oaTime = oaHH > 0 ? `${oaHH}h ${oaMM}m` : `${oaMM}m`;
 obsAvoidEl.textContent = `Obs. avoidance: ${(obsAvoidDist/1000).toFixed(2)} km / ${oaTime}`;
 } else {
 obsAvoidEl.textContent = '';
 }
 }

 // Infill stats (separate from prime)
 const infillEl = document.getElementById('stat-infill');
 if (infillEl) {
 if (infillKm > 0) {
 const infillPctKm = primeKm > 0 ? ((infillKm / primeKm) * 100).toFixed(1) : '-';
 infillEl.textContent = is2D
 ? `+${infillKm.toFixed(3)} km infill (${infillPctKm}% of prime)`
 : `+${infillKm.toFixed(3)} km / ${infillSqKm.toFixed(4)} km2 infill (${infillPctKm}% of prime)`;
 } else {
 infillEl.textContent = '';
 }
 }

 // Acquired vs Remaining stats
 const acqEl = document.getElementById('stat-acquired');
 if (acqEl) {
 if (primeAcquiredM > 0 || infillAcquiredM > 0) {
 const parts = [];
 parts.push(is2D ? `Acq: ${primeAcquiredKm.toFixed(1)}km` : `Acq: ${primeAcquiredKm.toFixed(1)}km / ${primeAcquiredSqKm.toFixed(3)}km2`);
 parts.push(is2D ? `Rem: ${primeRemainingKm.toFixed(1)}km` : `Rem: ${primeRemainingKm.toFixed(1)}km / ${primeRemainingSqKm.toFixed(3)}km2`);
 if (infillAcquiredM > 0) {
 const iAcqKm = (infillAcquiredM / 1000).toFixed(1);
 const iRemKm = (infillRemainingM / 1000).toFixed(1);
 parts.push(`Infill Acq: ${iAcqKm}km Rem: ${iRemKm}km`);
 }
 acqEl.textContent = parts.join(' | ');
 } else {
 acqEl.textContent = '';
 }
 }

 document.getElementById('route-stats').style.display = 'flex';

 // Helper function to format hours as days/hours/minutes
 function formatDaysHoursMinutes(totalHours) {
 const days = Math.floor(totalHours / 24);
 const hours = Math.floor(totalHours % 24);
 const minutes = Math.round((totalHours - Math.floor(totalHours)) * 60);
 const parts = [];
 if (days > 0) parts.push(days + 'd');
 if (hours > 0 || days > 0) parts.push(hours + 'h');
 parts.push(minutes + 'm');
 return parts.join(' ');
 }

 // Format survey and transit times
 const survHh = Math.floor(onlineHours);
 const survMm = Math.round((onlineHours - survHh) * 60);
 const tranHh = Math.floor(transitHours);
 const tranMm = Math.round((transitHours - tranHh) * 60);

 // Weather-adjusted time
 const weatherPct = state.settings.weatherDowntime || 0;
 const weatherFactor = 1 / (1 - weatherPct / 100);
 const adjHours = hours * weatherFactor;
 const adjHh = Math.floor(adjHours);
 const adjMm = Math.round((adjHours - adjHh) * 60);
 const adjDays = (adjHours / 24).toFixed(1);

 // Vessel utilization
 const utilOnline = ((onlineHours / hours) * 100).toFixed(0);
 const utilTransit = ((transitHours / hours) * 100).toFixed(0);

 // Cost estimation
 const dayRate = state.settings.vesselDayRate || 0;
 const mobDemob = state.settings.mobDemob || 0;
 const vesselCost = dayRate > 0 ? (adjHours / 24) * dayRate : 0;
 const totalCost = vesselCost + mobDemob;

 // Update floating survey summary with route stats
 updateSurveySummary({
 transitNm: (transitDist / 1852).toFixed(1),
 totalNm: nm.toFixed(1),
 surveyTime: survHh + 'h ' + survMm + 'm @ ' + onlineSpeed + 'kn (' + formatDaysHoursMinutes(onlineHours) + ')',
 transitTime: tranHh + 'h ' + tranMm + 'm @ ' + turnSpeed + 'kn (' + formatDaysHoursMinutes(transitHours) + ')',
 time: hh + 'h ' + mm + 'm (' + formatDaysHoursMinutes(hours) + ')',
 weatherPct: weatherPct,
 adjTime: weatherPct > 0 ? adjHh + 'h ' + adjMm + 'm (' + adjDays + ' days)' : null,
 utilOnline: utilOnline,
 utilTransit: utilTransit,
 totalCost: dayRate > 0 ? totalCost : null,
 vesselCost: dayRate > 0 ? vesselCost : null,
 mobDemob: mobDemob > 0 ? mobDemob : null,
 dayRate: dayRate,
 skipped: (skippedKm > 0 || skippedSP > 0)
  ? `${skippedKm.toFixed(1)} km / ${skippedSP.toLocaleString()} SP sacrificed` +
    (offlineThreshUsed != null ? ` (offline > ${offlineThreshUsed} m)` : '')
  : null
 });

 // Show route step-through controls
 showRouteStepper();

 // Show line schedule panel
 showLineSchedulePanel(waypoints);

 // Show timeline bar at bottom of map
 showRouteTimeline(waypoints);

}

// ===== LINE SCHEDULE PANEL =====
function showLineSchedulePanel(route) {
 if (!route || route.length < 2) return;
 const s = state.settings;
 const speed = s.speed ?? 4.5;
 const turnSpeed = s.turnSpeed ?? speed;
 const startTime = s.startTime ? new Date(s.startTime) : new Date();
 let currentTime = new Date(startTime);

 const fmtDT = d =>fmtDMT24(d);
 const fmtDur = h =>Math.floor(h) > 0 ? `${Math.floor(h)}h ${Math.round((h - Math.floor(h)) * 60)}m` : `${Math.round(h * 60)}m`;

 let rows = '';
 let seqNum = 0;
 let i = 0;
 while (i < route.length) {
 const wp = route[i];
 // Survey line acquisition: lineStart ' lineEnd ' runOutEnd (full fold + run-out)
 // Run-in is NOT part of the line - it belongs to the line turn
 if (wp.type === 'lineStart') {
 const lineName = wp.lineName || '?';
 let lineDistM = 0;
 let endIdx = i;
 let j = i;
 while (j < route.length - 1) {
 const cur = route[j], nxt = route[j + 1];
 lineDistM += haversine(cur.pt, nxt.pt);
 if (nxt.type === 'runOutEnd') { endIdx = j + 1; j++; break; }
 if (nxt.type === 'lineEnd') {
 // Check if run-out follows - if so, continue to include it
 if (j + 2 < route.length && route[j + 2].type === 'runOutEnd' && route[j + 2].lineName === nxt.lineName) {
 j++;
 continue;
 }
 endIdx = j + 1; j++; break;
 }
 j++;
 }
 const lineHrs = (lineDistM / 1852) / speed;
 const sol = new Date(currentTime);
 currentTime = new Date(currentTime.getTime() + lineHrs * 3600000);
 seqNum++;
 rows += `<tr>
 <td>${seqNum}</td>
 <td style="font-weight:600;color:#30d158;">* ${lineName}</td>
 <td>${(lineDistM/1000).toFixed(2)} km</td>
 <td>${fmtDT(sol)}</td>
 <td>${fmtDT(currentTime)}</td>
 <td>${fmtDur(lineHrs)}</td>
 </tr>`;
 i = endIdx;
 continue;
 }
 // Line change / turn: runOutEnd ' transit ' runInStart ' lineStart
 // Includes run-in distance; Dubins distance from end of run-out to next lineStart
 if (wp.type === 'lineEnd' || wp.type === 'runOutEnd') {
 // Find next lineStart (not runInStart - we include run-in in the turn)
 let j = i + 1;
 let nextLineStartIdx = -1;
 while (j < route.length) {
 if (route[j].type === 'lineStart') { nextLineStartIdx = j; break; }
 j++;
 }
 if (nextLineStartIdx >i) {
 // Compute Dubins transit distance from end of run-out to next lineStart (includes run-in)
 const transitDistM = computeDubinsTransitDist(route, i, nextLineStartIdx);
 const lcHrs = (transitDistM / 1852) / turnSpeed;
 const lcStart = new Date(currentTime);
 currentTime = new Date(currentTime.getTime() + lcHrs * 3600000);
 seqNum++;
 rows += `<tr style="color:#8a9bb0;">
 <td>${seqNum}</td>
 <td>Line Change</td>
 <td>${(transitDistM/1000).toFixed(2)} km</td>
 <td>${fmtDT(lcStart)}</td>
 <td>${fmtDT(currentTime)}</td>
 <td>${fmtDur(lcHrs)}</td>
 </tr>`;
 i = nextLineStartIdx;
 } else {
 i++;
 }
 continue;
 }
 // Skip run-in waypoints (handled as part of line change above)
 if (wp.type === 'runInStart') {
 // Find the lineStart that follows
 let j = i + 1;
 while (j < route.length && route[j].type !== 'lineStart') j++;
 i = (j < route.length) ? j : i + 1;
 continue;
 }
 i++;
 }

 // Create or update panel
 let panel = document.getElementById('line-schedule-panel');
 if (!panel) {
 panel = document.createElement('div');
 panel.id = 'line-schedule-panel';
 panel.style.cssText = 'position:fixed;bottom:52px;right:12px;width:340px;max-height:50vh;overflow-y:auto;' +
 'background:rgba(14,14,22,0.96);border:1px solid #1a1a2e;border-radius:8px;z-index:1200;' +
 'box-shadow:0 8px 32px rgba(0,0,0,0.7);color:#e0e8f0;font-family:inherit;font-size:10px;resize:both;';
 document.body.appendChild(panel);
 }
 panel.innerHTML = `
 <div id="line-schedule-drag-handle" style="display:flex;justify-content:space-between;align-items:center;padding:8px 12px 6px;border-bottom:1px solid #1a1a2e;position:sticky;top:0;background:rgba(14,14,22,0.98);z-index:1;cursor:move;user-select:none;">
 <span style="font-size:10px;font-weight:700;color:#00d2ff;letter-spacing:0.5px;">LINE SCHEDULE</span>
 <button onclick="document.getElementById('line-schedule-panel').style.display='none'" style="background:none;border:none;color:#666;font-size:14px;cursor:pointer;">x</button>
 </div>
 <div style="padding:8px 10px;">
 <table style="width:100%;border-collapse:collapse;">
 <tr style="color:#5a6a7a;font-weight:600;font-size:9px;text-transform:uppercase;letter-spacing:0.3px;">
 <th style="padding:4px 3px;text-align:left;">#</th>
 <th style="padding:4px 3px;text-align:left;">Name</th>
 <th style="padding:4px 3px;text-align:right;">Dist</th>
 <th style="padding:4px 3px;text-align:right;">Start</th>
 <th style="padding:4px 3px;text-align:right;">End</th>
 <th style="padding:4px 3px;text-align:right;">Dur</th>
 </tr>
 ${rows}
 </table>
 </div>`;
 panel.style.display = 'block';

 // Make panel draggable via header (vertical only - locked to right side)
 const dragHandle = document.getElementById('line-schedule-drag-handle');
 if (dragHandle && !dragHandle._dragInit) {
 dragHandle._dragInit = true;
 let dragging = false, dy = 0;
 dragHandle.addEventListener('mousedown', e => {
 if (e.target.tagName === 'BUTTON') return;
 dragging = true;
 const rect = panel.getBoundingClientRect();
 dy = e.clientY - rect.top;
 e.preventDefault();
 });
 document.addEventListener('mousemove', e => {
 if (!dragging) return;
 panel.style.top = (e.clientY - dy) + 'px';
 panel.style.bottom = 'auto';
 // Keep locked to right side
 panel.style.left = 'auto';
 panel.style.right = '12px';
 });
 document.addEventListener('mouseup', () => { dragging = false; });
 }
}

// ===== ROUTE TIMELINE BAR =====
function showRouteTimeline(route) {
 if (!route || route.length < 2) return;
 const s = state.settings;
 const speed = s.speed ?? 4.5;
 const turnSpeed = s.turnSpeed ?? speed;
 const startTime = s.startTime ? new Date(s.startTime) : new Date();
 let currentTime = new Date(startTime);

 // Build segments array: { type, name, hours, startTime, endTime }
 const segments = [];
 let i = 0;
 while (i < route.length) {
 const wp = route[i];
 if (wp.type === 'lineStart' || wp.type === 'runInStart') {
 const lineName = wp.lineName || '?';
 let distM = 0;
 let j = i;
 while (j < route.length - 1) {
 distM += haversine(route[j].pt, route[j + 1].pt);
 if (route[j + 1].type === 'lineEnd' || route[j + 1].type === 'runOutEnd') { j++; break; }
 j++;
 }
 const hrs = (distM / 1852) / speed;
 const segStart = new Date(currentTime);
 currentTime = new Date(currentTime.getTime() + hrs * 3600000);
 segments.push({ type: 'line', name: lineName, hours: hrs, startTime: segStart, endTime: new Date(currentTime) });
 i = j + 1;
 continue;
 }
 if (wp.type === 'lineEnd' || wp.type === 'runOutEnd') {
 let distM = 0;
 let j = i;
 while (j < route.length - 1) {
 distM += haversine(route[j].pt, route[j + 1].pt);
 j++;
 if (route[j].type === 'lineStart' || route[j].type === 'runInStart') break;
 }
 if (distM > 0) {
 const hrs = (distM / 1852) / turnSpeed;
 const segStart = new Date(currentTime);
 currentTime = new Date(currentTime.getTime() + hrs * 3600000);
 segments.push({ type: 'transit', name: 'LC', hours: hrs, startTime: segStart, endTime: new Date(currentTime) });
 }
 i = Math.max(j, i + 1);
 continue;
 }
 i++;
 }

 if (segments.length === 0) return;
 const totalHrs = segments.reduce((sum, seg) =>sum + seg.hours, 0);

 // Apply the same adjustments as the time panel (weather downtime, standby, time adjustments, infill, mob/demob, additional days)
 // so the timeline'total days and end date match the line schedule and time panel.
 const weatherPct = s.weatherDowntime || 0;
 const standbyPct = s.standbyPct || 0;
 const timeAdjPct = s.timeAdjustmentsPct || 0;
 const infillPct = s.infillPct || 0;
 const techFactor = weatherPct > 0 ? 1 / (1 - weatherPct / 100) : 1;
 const standbyFactor = standbyPct > 0 ? 1 / (1 - standbyPct / 100) : 1;
 const timeAdjFactor = timeAdjPct > 0 ? 1 / (1 - timeAdjPct / 100) : 1;
 const infillFactor = infillPct > 0 ? 1 + infillPct / 100 : 1;
 const adjHrs = totalHrs * techFactor * standbyFactor * timeAdjFactor * infillFactor;
 const mobDays = s.mobDemobDays || 0;
 const plannedDays = s.additionalPlanned || 0;
 const unplannedDays = s.additionalUnplanned || 0;
 const totalAdjHrs = adjHrs + (mobDays + plannedDays + unplannedDays) * 24;
 const endTime = new Date(startTime.getTime() + totalAdjHrs * 3600000);

 // Build day markers based on the adjusted total duration
 const dayMarkers = [];
 const firstDay = new Date(startTime);
 firstDay.setHours(0, 0, 0, 0);
 let d = new Date(firstDay.getTime() + 86400000); // start of next day
 while (d < endTime) {
 const elapsed = (d - startTime) / 3600000;
 const pct = (elapsed / totalAdjHrs) * 100;
 dayMarkers.push({ pct, label: fmtDM24(d) });
 d = new Date(d.getTime() + 86400000);
 }

 // Create or update timeline element
 let bar = document.getElementById('route-timeline-bar');
 if (!bar) {
 bar = document.createElement('div');
 bar.id = 'route-timeline-bar';
 bar.style.cssText = 'position:absolute;bottom:0;left:0;right:0;z-index:900;background:#0e0e16;border-top:1px solid #1a1a2e;padding:0;';
 document.getElementById('main').appendChild(bar);
 }

 // Build smooth gradient CSS matching the route line colors (green'cyan'yellow'orange'red)
 const gradientStops = '#30d158 0%, #00d2ff 25%, #ffd60a 50%, #ff9500 75%, #ff453a 100%';

 let markersHtml = '';
 dayMarkers.forEach(m => {
 markersHtml += `<div style="position:absolute;left:${m.pct}%;top:0;bottom:0;border-left:1px solid rgba(255,255,255,0.4);pointer-events:none;">
 <span style="position:absolute;top:-12px;left:2px;font-size:8px;color:#a0aebb;white-space:nowrap;">${m.label}</span>
 </div>`;
 });

 const totalDays = (totalAdjHrs / 24).toFixed(1);
 const fmtStart = fmtDM24(startTime);
 const fmtEnd = fmtDM24(endTime);

 bar.innerHTML = `
 <div style="display:flex;justify-content:space-between;align-items:center;padding:2px 8px;font-size:9px;color:#5a6a7a;">
 <span>${fmtStart} start</span>
 <span style="color:#00d2ff;font-weight:600;">${totalDays} days total</span>
 <span>${fmtEnd} end</span>
 </div>
 <div style="position:relative;margin:0 8px 6px;">
 <div style="min-height:18px;height:18px;border-radius:3px;overflow:hidden;opacity:0.9;"
 title="Route timeline: ${totalDays} days"></div>
 ${markersHtml}
 </div>`;
 // Apply gradient via JS property to avoid template literal escaping issues
 const gradBar = bar.querySelector('div[title]');
 if (gradBar) gradBar.style.background = 'linear-gradient(to right, ' + gradientStops + ')';
 bar.style.display = 'block';

 // Push bottom-bar and Leaflet scale control above the timeline bar
 const barHeight = bar.offsetHeight || 44;
 const bottomBar = document.getElementById('bottom-bar');
 if (bottomBar) bottomBar.style.bottom = (barHeight + 8) + 'px';
 const scaleCtrl = document.querySelector('.leaflet-control-scale');
 if (scaleCtrl) scaleCtrl.style.marginBottom = (barHeight + 4) + 'px';
}

