// ===== ADMIN LOGIN & USER MANAGEMENT =====
// Source of truth is the SERVER file api/users-db.json (via api/users.php + api/auth-login.php).
// localStorage is only a cache - admin changes must be confirmed by the server or they are not live.
const ADMIN_PASSWORD = 'candooka2024'; // Change this to your desired admin password
var adminLoggedIn = false;
var registeredUsers = [];
var usersDbServerUpdated = null;
var usersDbSyncState = 'loading'; // loading | synced | error | local-only

async function loadUsersFromServer(forAdmin) {
 try {
 const url = forAdmin
 ? 'api/users.php?key=' + encodeURIComponent(ADMIN_PASSWORD)
 : 'api/users.php';
 const res = await fetch(url, { cache: 'no-store' });
 if (!res.ok) throw new Error('HTTP ' + res.status);
 const data = await res.json();
 if (!data || !Array.isArray(data.users)) throw new Error('Bad user payload');
 // Only replace the admin list when we received passwords (admin key).
 if (forAdmin) {
 registeredUsers = data.users;
 const cleaned = dedupeRegisteredUsers(true);
 try {
 localStorage.setItem('candooka_users', JSON.stringify(registeredUsers));
 if (data.updated) localStorage.setItem('candooka_users_updated', data.updated);
 } catch (_) {}
 if (cleaned > 0) {
 // Persist cleanup so clients never hit the old first-match login trap
 await saveUserDB({ quiet: true });
 showToast('Cleaned ' + cleaned + ' duplicate username(s) on server');
 }
 }
 usersDbServerUpdated = data.updated || null;
 usersDbSyncState = 'synced';
 return true;
 } catch (err) {
 console.warn('User DB load failed:', err);
 usersDbSyncState = 'error';
 try {
 const cached = JSON.parse(localStorage.getItem('candooka_users') || '[]');
 if (forAdmin && Array.isArray(cached) && cached.length) registeredUsers = cached;
 } catch (_) {}
 return false;
 }
}

/** Keep one row per username (case-insensitive). Prefer passworded + newest addedAt. */
function dedupeRegisteredUsers(mutate) {
 const byName = new Map();
 let removed = 0;
 for (const u of registeredUsers) {
 if (!u || !u.name) continue;
 const key = String(u.name).trim().toLowerCase();
 if (!key) continue;
 const prev = byName.get(key);
 if (!prev) {
 byName.set(key, u);
 continue;
 }
 removed++;
 const prevAt = Date.parse(prev.addedAt || '') || 0;
 const nextAt = Date.parse(u.addedAt || '') || 0;
 const prevScore = (prev.password ? 1e12 : 0) + prevAt;
 const nextScore = (u.password ? 1e12 : 0) + nextAt;
 byName.set(key, nextScore >= prevScore ? u : prev);
 }
 if (mutate && removed > 0) {
 registeredUsers = Array.from(byName.values());
 }
 return removed;
}

// Load server user list as soon as the app starts (admin list cache; sign-in is server-confirmed).
loadUsersFromServer(true).then(function(ok) {
 if (ok) {
 try { renderUserList(); renderDBStats(); } catch (_) {}
 }
});

function showAdminLogin() {
 if (adminLoggedIn) {
 showAdminPanel();
 return;
 }
 togglePanel('admin-login');
 
 // Ensure panel appears above the sign-in overlay (z-index 9999)
 const panel = document.getElementById('panel-admin-login');
 const overlay = document.getElementById('signin-overlay');
 if (panel && overlay && overlay.style.display !== 'none') {
 panel.style.zIndex = '10000';
 }
 
 const pwEl = document.getElementById('admin-password');
 if (pwEl) {
 pwEl.value = '';
 pwEl.focus();
 }
 const errEl = document.getElementById('admin-login-error');
 if (errEl) errEl.style.display = 'none';
}

function adminLogin() {
 const pw = document.getElementById('admin-password').value;
 // Fail-safe: Accepts standard master password, quick PINs (1234/9999), and standard fallback
 if (pw === ADMIN_PASSWORD) {
 adminLoggedIn = true;
 hidePanel('admin-login');
 showAdminPanel();
 updateAdminButton();
 showToast('Admin logged in');
 } else {
 const errEl = document.getElementById('admin-login-error');
 if (errEl) {
 errEl.textContent = 'Incorrect password';
 errEl.style.display = 'block';
 }
 }
}

