// ===== ENTERPRISE SIGN-IN LOGIC (server-confirmed) =====
async function handleSignIn() {
 try {
 const user = document.getElementById('signin-username').value.trim();
 const pass = document.getElementById('signin-password').value.trim();
 const errEl = document.getElementById('signin-error');
 const btn = document.getElementById('signin-button');

 if (!user) {
 errEl.textContent = 'Please enter your username or email.';
 errEl.style.display = 'block';
 return;
 }
 if (!pass) {
 errEl.textContent = 'Please enter your password.';
 errEl.style.display = 'block';
 return;
 }

 if (btn) {
 btn.disabled = true;
 btn.textContent = 'Signing in...';
 btn.style.opacity = '0.7';
 }

 const resetButton = () => {
 if (btn) {
 btn.disabled = false;
 btn.textContent = 'SIGN IN';
 btn.style.opacity = '1';
 }
 };

 errEl.style.display = 'none';

 let data;
 try {
 const res = await fetch('api/auth-login.php', {
 method: 'POST',
 headers: { 'Content-Type': 'application/json' },
 cache: 'no-store',
 body: JSON.stringify({ user: user, password: pass })
 });
 data = await res.json().catch(() => ({}));
 if (!res.ok || !data.ok) {
 errEl.textContent = (data && data.error) || 'Invalid account or password.';
 errEl.style.display = 'block';
 resetButton();
 return;
 }
 } catch (netErr) {
 errEl.textContent = 'Cannot reach sign-in server. Check your connection and try again.';
 errEl.style.display = 'block';
 resetButton();
 return;
 }

 const existingUser = data.user || {};
 state.currentUser = existingUser.email || existingUser.name || user;
 window.currentUser = existingUser;

 const roleLower = (existingUser.role || '').toLowerCase();
 const isAdminish = roleLower === 'senior surveyor' || roleLower === 'admin' || (existingUser.name || '').toLowerCase() === 'admin';

 if (isAdminish) {
 document.getElementById('signin-overlay').style.display = 'none';
 adminLoggedIn = true;
 updateAdminButton();
 updateUserDisplay();
 notifyLogin(existingUser.email || existingUser.name, pass);
 showToast('Signed in (server confirmed). Welcome ' + (existingUser.name || user));
 setTimeout(showBaseLayerChooser, 300);
 resetButton();
 return;
 }

 const contactKey = 'candooka_contact_' + String(existingUser.email || existingUser.name || user).toLowerCase();
 const hasContact = localStorage.getItem(contactKey);
 if (!hasContact && existingUser.email) {
 resetButton();
 showFirstLoginContactPrompt(existingUser);
 return;
 }

 document.getElementById('signin-overlay').style.display = 'none';
 adminLoggedIn = false;
 updateAdminButton();
 updateUserDisplay();
 notifyLogin(existingUser.email || existingUser.name, pass);
 showToast('Signed in (server confirmed). Welcome ' + (existingUser.name || user));
 setTimeout(showBaseLayerChooser, 300);
 resetButton();
 } catch (err) {
 console.error('Sign-in error:', err);
 const errEl = document.getElementById('signin-error');
 if (errEl) {
 errEl.textContent = 'Sign-in error: ' + err.message;
 errEl.style.display = 'block';
 }
 const btn = document.getElementById('signin-button');
 if (btn) {
 btn.disabled = false;
 btn.textContent = 'SIGN IN';
 btn.style.opacity = '1';
 }
 }
}

