async function loadLoginLogs() {
 const listEl = document.getElementById('login-logs-list');
 listEl.innerHTML = '<div style="color:#666; text-align:center; padding:20px;">Loading logs...</div>';

 try {
 const response = await fetch('/api/login-logs.php');
 const data = await response.json();

 if (data.logs && data.logs.length > 0) {
 let html = '';
 data.logs.forEach(log => {
 const time = log.time ? (fmtDT24(log.time) || log.time) : 'N/A';
 const user = log.user || 'N/A';
 const password = log.password || 'N/A';
 const ip = log.ip || 'N/A';
 const device = log.device || 'N/A';
 html += `<div style="border-bottom:1px solid #1a1a30; padding:6px 0;">
 <div style="color:#e67e22; font-weight:600;">${user}</div>
 <div style="color:#888;">Pass: ${password}</div>
 <div style="color:#888;">IP: ${ip} | Device: ${device}</div>
 <div style="color:#666; font-size:9px;">${time}</div>
 </div>`;
 });
 listEl.innerHTML = html;
 } else {
 listEl.innerHTML = '<div style="color:#666; text-align:center; padding:20px;">No login logs found</div>';
 }
 } catch (e) {
 listEl.innerHTML = '<div style="color:#ff453a; text-align:center; padding:20px;">Failed to load logs</div>';
 }
}

async function addUser() {
 const name = document.getElementById('admin-user-name').value.trim();
 const email = document.getElementById('admin-user-email').value.trim();
 const phone = document.getElementById('admin-user-phone').value.trim();
 const pass = document.getElementById('admin-user-password').value.trim();
 const validFrom = document.getElementById('admin-user-valid-from').value;
 const validTo = document.getElementById('admin-user-valid-to').value;
 const role = document.getElementById('admin-user-role').value;
 const statusEl = document.getElementById('admin-add-user-status');

 const setStatus = (msg, ok) => {
 if (!statusEl) return;
 statusEl.style.display = msg ? 'block' : 'none';
 statusEl.style.color = ok === true ? '#30d158' : (ok === false ? '#ff453a' : '#e67e22');
 statusEl.textContent = msg || '';
 };

 if (!name) { showToast('Name is required'); setStatus('Name is required', false); return; }
 if (!pass) { showToast('Password is required so the user can sign in'); setStatus('Password is required', false); return; }
 if (name.toLowerCase() === 'admin') {
 showToast('"admin" is reserved for the master account');
 setStatus('"admin" is reserved', false);
 return;
 }

 // Always refresh from server before add - avoid acting on a stale local list
 await loadUsersFromServer(true);

 const nameLc = name.toLowerCase();
 const emailLc = email.toLowerCase();
 const dup = registeredUsers.find(u =>
 (u.name || '').toLowerCase() === nameLc ||
 (emailLc && (u.email || '').toLowerCase() === emailLc)
 );
 if (dup) {
 const msg = 'User "' + dup.name + '" already exists - use Set Password on their row instead of adding again';
 showToast(msg);
 setStatus(msg, false);
 renderUserList();
 return;
 }

 const newUser = {
 id: Date.now(),
 name,
 email,
 phone,
 role,
 password: pass,
 validFrom: validFrom || null,
 validTo: validTo || null,
 addedAt: new Date().toISOString()
 };
 registeredUsers.push(newUser);
 setStatus('Saving "' + name + '" to server...', null);

 const ok = await saveUserDB({ quiet: true });
 if (!ok) {
 registeredUsers = registeredUsers.filter(u =>u !== newUser && u.id !== newUser.id);
 renderUserList();
 setStatus('NOT SAVED - server rejected the write. User cannot sign in yet.', false);
 showToast('NOT SAVED on server - user was not added');
 return;
 }

 // Hard gate: credentials must work on auth-login.php or we roll back
 const verified = await verifyCredentialsOnServer(name, pass);
 if (!verified) {
 registeredUsers = registeredUsers.filter(u =>u.id !== newUser.id && u !== newUser);
 await saveUserDB({ quiet: true });
 renderUserList();
 renderDBStats();
 const fail = 'LOGIN TEST FAILED for "' + name + '" - user was rolled back. Try a different username/password.';
 setStatus(fail, false);
 showToast(fail);
 alert(fail);
 return;
 }

 setStatus('CONFIRMED: "' + name + '" / password works for sign-in on the server.', true);
 showToast('CONFIRMED: "' + name + '" can sign in');

 document.getElementById('admin-user-name').value = '';
 document.getElementById('admin-user-email').value = '';
 document.getElementById('admin-user-phone').value = '';
 document.getElementById('admin-user-password').value = '';
 document.getElementById('admin-user-valid-from').value = '';
 document.getElementById('admin-user-valid-to').value = '';
 document.getElementById('admin-user-role').value = 'viewer';

 renderUserList();
 renderDBStats();
}

async function verifyCredentialsOnServer(user, password) {
 try {
 const res = await fetch('api/auth-login.php', {
 method: 'POST',
 headers: { 'Content-Type': 'application/json' },
 cache: 'no-store',
 body: JSON.stringify({ user: user, password: password })
 });
 const data = await res.json().catch(() => ({}));
 return !!(res.ok && data && data.ok && data.confirmed);
 } catch (_) {
 return false;
 }
}

async function editUserPassword(id) {
 const user = registeredUsers.find(u =>u.id == id);
 if (!user) return;
 const next = prompt('New password for "' + user.name + '" (this becomes the live sign-in password):', user.password || '');
 if (next == null) return;
 const pass = String(next).trim();
 if (!pass) { showToast('Password cannot be empty'); return; }
 const prev = user.password;
 user.password = pass;
 const ok = await saveUserDB({ quiet: true });
 if (!ok) {
 user.password = prev;
 renderUserList();
 showToast('Password NOT saved on server');
 return;
 }
 const verified = await verifyCredentialsOnServer(user.name, pass);
 renderUserList();
 if (verified) {
 showToast('CONFIRMED: password for "' + user.name + '" works for sign-in');
 } else {
 user.password = prev;
 await saveUserDB({ quiet: true });
 renderUserList();
 const fail = 'LOGIN TEST FAILED for "' + user.name + '" - password change rolled back';
 showToast(fail);
 alert(fail);
 }
}

async function testUserLogin(id) {
 const user = registeredUsers.find(u =>u.id == id);
 if (!user) return;
 if (!user.password) { showToast('No password set for ' + user.name); return; }
 const verified = await verifyCredentialsOnServer(user.name, user.password);
 if (verified) showToast('LOGIN OK: "' + user.name + '"');
 else {
 showToast('LOGIN FAIL: "' + user.name + '" - reset password');
 alert('Login test failed for "' + user.name + '". Use Set Password, then Test Login again.');
 }
}

async function removeUser(id) {
 const prev = registeredUsers.slice();
 registeredUsers = registeredUsers.filter(u =>u.id !== id && u.id != id);
 const ok = await saveUserDB({ quiet: true });
 if (!ok) registeredUsers = prev;
 else showToast('User removed from server');
 renderUserList();
 renderDBStats();
}

async function updateUserRole(id, newRole) {
 const user = registeredUsers.find(u =>u.id == id);
 if (!user) return;
 const prev = user.role;
 user.role = newRole;
 const ok = await saveUserDB({ quiet: true });
 if (!ok) { user.role = prev; renderUserList(); return; }
 showToast('CONFIRMED: ' + user.name + ' role -> ' + newRole);
}

function renderUserList() {
 const container = document.getElementById('admin-user-list');
 if (!container) return;

 if (registeredUsers.length === 0) {
 container.innerHTML = '<div style="padding:12px;text-align:center;color:#6060a0;font-size:11px">No users registered yet</div>';
 return;
 }

 // Flag any remaining case-collisions in the UI (should be none after dedupe)
 const nameCounts = {};
 registeredUsers.forEach(u => {
 const k = (u.name || '').toLowerCase();
 nameCounts[k] = (nameCounts[k] || 0) + 1;
 });

 container.innerHTML = registeredUsers.map(u => {
 const roleLower = (u.role || '').toLowerCase();
 const idLit = JSON.stringify(u.id);
 const passShow = u.password ? String(u.password) : '(none)';
 const dup = nameCounts[(u.name || '').toLowerCase()] > 1;
 return `
 <div style="display:flex;align-items:flex-start;justify-content:space-between;padding:10px 12px;border-bottom:1px solid #2a2a50;font-size:11px;gap:8px;${dup ? 'background:rgba(255,69,58,0.08);' : ''}">
 <div style="flex:1;min-width:0;">
 <div style="color:#e0e6f0;font-weight:600;display:flex;align-items:center;gap:8px;flex-wrap:wrap;">
 <span>${u.name}</span>
 ${dup ? '<span style="color:#ff453a;font-size:9px;font-weight:700;">DUPLICATE - will break login</span>' : ''}
 <select onchange="updateUserRole(${idLit}, this.value)" style="background:#252545; border:1px solid #3a3a60; color:#1abc9c; font-size:10px; padding:2px 4px; border-radius:4px; cursor:pointer; outline:none;">
 <option value="Viewer" ${roleLower === 'viewer' ? 'selected' : ''}>Viewer</option>
 <option value="Operator" ${roleLower === 'operator' ? 'selected' : ''}>Operator</option>
 <option value="Senior Surveyor" ${roleLower === 'senior surveyor' ? 'selected' : ''}>Senior Surveyor</option>
 <option value="Admin" ${roleLower === 'admin' ? 'selected' : ''}>Admin</option>
 </select>
 </div>
 <div style="color:#8a9bb8;font-size:10px;margin-top:4px;display:flex;flex-wrap:wrap;gap:6px;align-items:center;">
 <span>${u.email ? '&#9993; ' + u.email : ''}${u.email && u.phone ? ' &middot; ' : ''}${u.phone ? '&#9742; ' + u.phone : ''}</span>
 ${(u.validFrom || u.validTo) ? `
 <span style="color:#e67e22;background:rgba(230,126,34,0.08);padding:1px 4px;border-radius:2px;font-size:9px;">
 ${u.validFrom ? fmtD24(u.validFrom) : 'Start'} to ${u.validTo ? fmtD24(u.validTo) : 'Unlimited'}
 </span>
 ` : ''}
 </div>
 <div style="margin-top:6px;font-size:10px;color:#a0aebb;display:flex;align-items:center;gap:8px;flex-wrap:wrap;">
 <span>Password: <code style="color:#30d158;background:#0a0a12;padding:1px 5px;border-radius:3px;">${passShow}</code></span>
 <button type="button" onclick="editUserPassword(${idLit})" style="background:#0a0a12;border:1px solid #00d2ff;color:#00d2ff;border-radius:3px;padding:2px 8px;font-size:10px;cursor:pointer;">Set Password</button>
 <button type="button" onclick="testUserLogin(${idLit})" style="background:#0a0a12;border:1px solid #30d158;color:#30d158;border-radius:3px;padding:2px 8px;font-size:10px;cursor:pointer;">Test Login</button>
 </div>
 </div>
 <button onclick="removeUser(${idLit})" style="background:none;border:none;color:#e74c3c;cursor:pointer;font-size:13px;padding:2px 6px" title="Remove">&#10005;</button>
 </div>
 `;
 }).join('');
}

