 const waUrl = `https://api.whatsapp.com/send?text=${encodeURIComponent(msg)}`;
 const mailUrl = `mailto:aledmorgan@hotmail.com?subject=New%20Candooka%20Premium%20Subscription&body=${encodeURIComponent(msg)}`;

 window.open(waUrl, '_blank');
 window.location.href = mailUrl;
 
 // Clear inputs
