// ===== TIER 2 BUTTON ACTION HANDLERS =====

// Open/close the "Copy Map" options menu (mirrors the Export dropdown: measures
// itself, flips to stay on-screen, and closes on an outside click).
function toggleCopyMapMenu(e) {
 if (e) e.stopPropagation();
 const dd = document.getElementById('copymap-dropdown');
 const btn = document.getElementById('btn-copy-map');
 if (!dd) return;
 const isHidden = dd.style.display === 'none' || dd.style.display === '';
 if (isHidden && btn) {
 const rect = btn.getBoundingClientRect();
 dd.style.display = 'block';
 dd.style.visibility = 'hidden';
 const ddWidth = dd.offsetWidth, ddHeight = dd.offsetHeight;
 dd.style.visibility = '';
 dd.style.display = 'none';
 dd.style.left = (rect.left + ddWidth >window.innerWidth)
 ? (rect.right - ddWidth) + 'px' : rect.left + 'px';
 dd.style.top = (rect.bottom + ddHeight >window.innerHeight)
 ? (rect.top - ddHeight - 4) + 'px' : (rect.bottom + 4) + 'px';
 }
 dd.style.display = isHidden ? 'block' : 'none';
 if (isHidden) {
 setTimeout(() => {
 const handler = function(ev) {
 if (!dd.contains(ev.target) && ev.target.id !== 'btn-copy-map') {
 dd.style.display = 'none';
 document.removeEventListener('click', handler);
 }
 };
 document.addEventListener('click', handler);
 }, 10);
 }
}

// Copy the active 2D map to the clipboard as a PNG image - WITHOUT any of the
// floating panels/dialogs (those live outside the #map element, so capturing
// #map alone excludes them). Leaflet zoom/attribution chrome is skipped; the
// scale bar is kept. Falls back to a file download if clipboard image writes
// are unsupported. The `mode` selects which map layers to include:
// 'full' - basemap + preplot + route + swaths + user layers (default)
// 'nobasemap' - all overlays on a transparent background (no basemap tiles)
// 'preplot' - basemap + preplot lines/labels only (route + arrows hidden)
// 'route' - basemap + planned route only (preplot lines + swaths hidden)
async function copyMapToClipboard(mode = 'full') {
 const ddEl = document.getElementById('copymap-dropdown');
 if (ddEl) ddEl.style.display = 'none';

 const mapEl = document.getElementById('map');
 if (!map || !mapEl || mapEl.style.display === 'none') {
 showToast('Switch to the Map view first');
 return;
 }
 if (typeof html2canvas === 'undefined') {
 showToast('Map capture library not loaded - check your connection');
 return;
 }

 // Temporarily remove the layers that this mode should exclude, remembering
 // them so they can be restored after the capture completes.
 const hidden = [];
 const hide = (layer) => {
 if (layer && map.hasLayer(layer)) { map.removeLayer(layer); hidden.push(layer); }
 };
 let transparent = false;
 if (mode === 'nobasemap') {
 transparent = true;
 hide(currentBaseLayer);
 if (typeof mapLayers === 'object' && mapLayers) {
 hide(mapLayers.bathy); hide(mapLayers.gebco); hide(mapLayers.nav);
 }
 } else if (mode === 'preplot') {
 hide(layerRoute); hide(layerArrows);
 } else if (mode === 'route') {
 hide(layerSurveyLines); hide(layerSwaths);
 }

 const restore = () => {
 hidden.forEach(l => { if (l && !map.hasLayer(l)) map.addLayer(l); });
 // Keep the basemap beneath the vector overlays after re-adding it.
 if (hidden.includes(currentBaseLayer) && currentBaseLayer && currentBaseLayer.bringToBack) {
 currentBaseLayer.bringToBack();
 }
 };

 const btn = document.getElementById('btn-copy-map');
 const prevLabel = btn ? btn.innerHTML : '';
 if (btn) { btn.innerHTML = '3 CAPTURING...'; btn.disabled = true; }
 showToast('Capturing map...');

 // html2canvas misplaces the overlay SVGs because Leaflet positions the SVG
 // pane with translate3d. In html2canvas' cloned DOM the transform origin is
 // not resolved the same way the live browser does, so the preplot lines / user
 // layers shift while labels (which live in a different pane) stay correct.
 // Fix: in the cloned document, strip the SVG transform and replace it with
 // plain left/top positioning, then capture everything in one pass.
 const normaliseLeafletSvgTransforms = (doc) => {
 const svgs = doc.querySelectorAll('.leaflet-overlay-pane svg');
 svgs.forEach((svg) => {
 const txStr = svg.style.transform || svg.style.webkitTransform ||
 svg.style.mozTransform || svg.style.msTransform || '';
 const m = txStr.match(/translate(?:3d)?\(([^,]+)[, ]+([^,)\s]+)/i) ||
 txStr.match(/matrix\([^,]+,[^,]+,[^,]+,[^,]+,([^,]+),([^)]+)\)/i);
 let x = 0, y = 0;
 if (m) { x = parseFloat(m[1]) || 0; y = parseFloat(m[2]) || 0; }
 svg.style.transform = 'none';
 svg.style.webkitTransform = 'none';
 svg.style.mozTransform = 'none';
 svg.style.msTransform = 'none';
 svg.style.position = 'absolute';
 svg.style.left = x + 'px';
 svg.style.top = y + 'px';
 });
 };

 try {
 // Ensure all tiles for the current view are requested, then let them settle.
 map.invalidateSize();
 await new Promise(r =>setTimeout(r, 400));

 const canvas = await html2canvas(mapEl, {
 useCORS: true,
 allowTaint: false,
 backgroundColor: transparent ? null : '#000',
 logging: false,
 width: mapEl.clientWidth,
 height: mapEl.clientHeight,
 onclone: (doc) => { normaliseLeafletSvgTransforms(doc); },
 // Drop the interactive Leaflet chrome, keep the scale bar for context.
 ignoreElements: (el) => !!(el.classList && (
 el.classList.contains('leaflet-control-zoom') ||
 el.classList.contains('leaflet-control-attribution')
 ))
 });

 const blob = await new Promise(res =>canvas.toBlob(res, 'image/png'));
 if (!blob) throw new Error('image render failed');

 if (navigator.clipboard && window.ClipboardItem) {
 await navigator.clipboard.write([new ClipboardItem({ 'image/png': blob })]);
 showToast('Map copied to clipboard "');
 } else {
 downloadBlob(blob, 'candooka-map.png');
 showToast('Clipboard images unsupported - map downloaded instead');
 }
 } catch (err) {
 console.error('copyMapToClipboard failed:', err);
 showToast('Could not copy map: ' + ((err && err.message) || 'capture failed'));
 } finally {
 restore();
 if (btn) { btn.innerHTML = prevLabel; btn.disabled = false; }
 }
}

// Human-readable description of the current start-point selection.
function _startPointLabel() {
 const s = state.settings;
 if (s.startPoint && Array.isArray(s.startPoint)) {
 return `Custom: ${s.startPoint[0].toFixed(4)}, ${s.startPoint[1].toFixed(4)}`;
 }
 if (s.startLineId != null || s.startLineIdx != null) {
 const line = (state.lines || []).find(l =>l.id === s.startLineId) || (state.lines || [])[s.startLineIdx];
 const nm = line ? (line.name || ('Line ' + ((s.startLineIdx || 0) + 1))) : 'Selected line';
 return `${nm} (${s.startLineReversed ? 'EOL->SOL' : 'SOL->EOL'})`;
 }
 return 'First line start (Auto)';
}

// Reflect the current start-point selection in the stand-alone Start Point panel.
function _syncStartPointPanel() {
 const el = document.getElementById('start-point-status');
 if (el) el.textContent = 'Current: ' + _startPointLabel();
 _populateStartPointLineSelect();
 _renderStartPointMarker();
}

// Layers panel "Annotations & Arrows" also gates the user-defined start
// point/line marker (same yellow annotation style).
function _annotationsLayerWanted() {
 const el = document.getElementById('layer-toggle-annotations');
 return el ? !!el.checked : true;
}

function _syncStartPointLayerVisibility() {
 if (!map || !layerStartPoint) return;
 const want = _annotationsLayerWanted();
 if (want) {
  if (!map.hasLayer(layerStartPoint)) layerStartPoint.addTo(map);
 } else if (map.hasLayer(layerStartPoint)) {
  map.removeLayer(layerStartPoint);
 }
}

// Draw/refresh the user-defined start point marker + label on the map.
function _renderStartPointMarker() {
 if (!map || typeof L === 'undefined') return;
 if (!layerStartPoint) layerStartPoint = L.layerGroup();
 layerStartPoint.clearLayers();

 // User-defined start POINT (map-picked coordinates)
 const sp = state.settings.startPoint;
 if (sp && Array.isArray(sp)) {
 L.circleMarker(sp, { radius: 9, color: '#ffd60a', weight: 2, fillColor: '#ffd60a', fillOpacity: 0.25 }).addTo(layerStartPoint);
 L.circleMarker(sp, { radius: 2.5, color: '#ffd60a', weight: 2, fillColor: '#ffd60a', fillOpacity: 1 }).addTo(layerStartPoint);
 L.marker(sp, {
 interactive: false,
 icon: L.divIcon({
 className: '', iconSize: [0, 0], iconAnchor: [0, 0],
 html: '<div style="transform:translate(13px,-26px);color:#ffd60a;font-size:10px;font-weight:700;white-space:nowrap;text-shadow:1px 1px 3px #000;pointer-events:none;">START POINT (user-defined)' +
 '<br><span style="font-weight:400;font-size:9px;">' + sp[0].toFixed(5) + ', ' + sp[1].toFixed(5) + '</span></div>'
 })
 }).addTo(layerStartPoint);
 _syncStartPointLayerVisibility();
 return;
 }

 // User-defined start LINE: flag its entry end (SOL or EOL per the chosen
 // direction) on the preplot - shown before AND after route planning.
 if (state.settings.startLineId == null && (state.settings.startLineIdx === undefined || state.settings.startLineIdx === null)) {
  _syncStartPointLayerVisibility();
  return;
 }
 const pool = (state._allLines && state._allLines.length) ? state._allLines : (state.lines || []);
 let line = null;
 if (state.settings.startLineId != null) line = pool.find(l =>l && l.id === state.settings.startLineId);
 if (!line && state.settings.startLineIdx != null) line = pool[state.settings.startLineIdx];
 if (!line || !line.start || !line.end) {
  _syncStartPointLayerVisibility();
  return;
 }
 const rev = !!state.settings.startLineReversed;
 const entry = rev ? line.end : line.start;
 L.circleMarker(entry, { radius: 9, color: '#ffd60a', weight: 2, fillColor: '#ffd60a', fillOpacity: 0.25 }).addTo(layerStartPoint);
 L.circleMarker(entry, { radius: 2.5, color: '#ffd60a', weight: 2, fillColor: '#ffd60a', fillOpacity: 1 }).addTo(layerStartPoint);
 L.polyline([line.start, line.end], { color: '#ffd60a', weight: 2, opacity: 0.9, dashArray: '6,4', interactive: false }).addTo(layerStartPoint);
 L.marker(entry, {
 interactive: false,
 icon: L.divIcon({
 className: '', iconSize: [0, 0], iconAnchor: [0, 0],
 html: '<div style="transform:translate(13px,-26px);color:#ffd60a;font-size:10px;font-weight:700;white-space:nowrap;text-shadow:1px 1px 3px #000;pointer-events:none;">START LINE (user-defined)' +
 '<br><span style="font-weight:400;font-size:9px;">' + (line.name || 'Line') + ' | ' + (rev ? 'EOL -> SOL' : 'SOL -> EOL') + '</span></div>'
 })
 }).addTo(layerStartPoint);
 _syncStartPointLayerVisibility();
}

// Apply the Start Point + Start Time chosen in the Survey Criteria dialog to
// state.settings and the stand-alone toolbar inputs, and mark the start as
// configured so the route planner does not prompt again with the start-line
// chooser. Requires state.lines to be populated for 'line-N' selections.
function _applyCriteriaStartSettings() {
 const sp = document.getElementById('crit-startpoint');
 if (sp) {
 const spVal = sp.value;
 state.settings.startLineIdx = null;
 state.settings.startLineId = null;
 state.settings.startLineReversed = false;
 if (spVal === 'first') {
 state.settings.startPoint = null;
 } else if (spVal.startsWith('line-')) {
 const parts = spVal.split('-');
 const lineIdx = parseInt(parts[1]);
 const dir = parts[2];
 const targetLine = state.lines[lineIdx];
 if (targetLine) {
 state.settings.startLineIdx = lineIdx;
 state.settings.startLineId = targetLine.id;
 state.settings.startLineReversed = (dir === 'rev');
 state.settings.startPoint = null;
 } else {
 state.settings.startPoint = null;
 }
 } else {
 const flat = parseFloat(document.getElementById('crit-start-lat').value);
 const flon = parseFloat(document.getElementById('crit-start-lon').value);
 if (!isNaN(flat) && !isNaN(flon)) state.settings.startPoint = [flat, flon];
 }
 }
 const stEl = document.getElementById('crit-starttime');
 if (stEl) {
 state.settings.startTime = stEl.value || null;
 const tEl = document.getElementById('input-start-time');
 if (tEl && stEl.value) tEl.value = stEl.value;
 }
 // Start is now explicitly configured in the criteria dialog - don't re-prompt.
 state.settings.startConfigured = true;
 _startLineChooserShown = true;
 _syncStartPointPanel();
}

// Apply the survey-type / progression / swath-count / per-swath acquisition
// direction chosen in the Survey Criteria dialog to state.settings. Used by
// BOTH the "Line Manager" submit and the "View Preplot" exit so the swath
// labels and the planned route always reflect the dialog selections.
function _applyCriteriaSwathSettings() {
 const surveyType = document.getElementById('crit-survey-type')?.value;
 if (surveyType) state.settings.surveyType = surveyType;
 const progEl = (surveyType === '2d')
 ? document.getElementById('crit-progression-2d')
 : document.getElementById('crit-progression');
 if (progEl && progEl.value) state.settings.progression = progEl.value;
 const lineDir2d = document.getElementById('crit-line-direction-2d');
 if (lineDir2d && lineDir2d.value) state.settings.lineDirection2d = lineDir2d.value;
 const numSwaths = parseInt(document.getElementById('crit-num-swaths')?.value);
 if (!isNaN(numSwaths)) state.settings.numSwaths = numSwaths;
 const swathDirections = [];
 document.querySelectorAll('.swath-dir-select').forEach(select => {
 const i = parseInt(select.dataset.swath);
 if (!isNaN(i)) swathDirections[i] = select.value;
 });
 if (swathDirections.length) {
 state.settings.swathDirections = swathDirections;
 // Remember these directions as this user'default for the next round.
 _persistSwathDefaults(swathDirections);
 }
}

// Carry any user-added infill lines (from the current line list) over to a
// freshly parsed line list, so re-parsing the preplot after a criteria edit
// does not silently discard planned infill lines.
function _mergeExistingInfill(newLines) {
 const infill = (state.lines || []).filter(l =>l && l._infill);
 if (infill.length === 0) return newLines;
 const ids = new Set(newLines.map(l =>l && l.id));
 return newLines.concat(infill.filter(l => !ids.has(l.id)));
}

function triggerStartPointSelection() {
 settingStartPoint = true;
 if (map) {
 map.getContainer().style.cursor = 'crosshair';
 }
 hidePanel('start-point');
 showToast('Click on the map to set the Start Point.');
}

// --- Start line & direction selection from the Start Pt panel ---
var _spPendingReversed = false;

function _populateStartPointLineSelect() {
 const sel = document.getElementById('sp-start-line');
 if (!sel) return;
 const lines = (state._allLines && state._allLines.length) ? state._allLines : (state.lines || []);
 sel.innerHTML = '';
 const none = document.createElement('option');
 none.value = '';
 none.textContent = lines.length ? '- choose a line -' : 'No preplot loaded';
 sel.appendChild(none);
 lines.forEach((line, idx) => {
 const opt = document.createElement('option');
 opt.value = idx;
 opt.textContent = line.name || ('Line ' + (idx + 1));
 if (state.settings.startLineId != null ? line.id === state.settings.startLineId : state.settings.startLineIdx === idx) opt.selected = true;
 sel.appendChild(opt);
 });
 _spPendingReversed = !!state.settings.startLineReversed;
 _updateSpDirButtons();
}

function _updateSpDirButtons() {
 const fwd = document.getElementById('sp-dir-fwd');
 const rev = document.getElementById('sp-dir-rev');
 if (!fwd || !rev) return;
 if (_spPendingReversed) {
 rev.style.borderColor = '#00d2ff'; rev.style.color = '#00d2ff';
 fwd.style.borderColor = '#333'; fwd.style.color = '#8a9bb0';
 } else {
 fwd.style.borderColor = '#00d2ff'; fwd.style.color = '#00d2ff';
 rev.style.borderColor = '#333'; rev.style.color = '#8a9bb0';
 }
}

function spSetDirection(reversed) {
 _spPendingReversed = reversed;
 _updateSpDirButtons();
}

function spPreviewStartLine() {
 const sel = document.getElementById('sp-start-line');
 if (!sel || !map || sel.value === '') return;
 const lines = (state._allLines && state._allLines.length) ? state._allLines : (state.lines || []);
 const line = lines[parseInt(sel.value, 10)];
 if (line) map.panTo(_spPendingReversed ? line.end : line.start);
}

function spApplyStartLine() {
 const sel = document.getElementById('sp-start-line');
 if (!sel || sel.value === '') { showToast('Choose a start line first'); return; }
 const lines = (state._allLines && state._allLines.length) ? state._allLines : (state.lines || []);
 const idx = parseInt(sel.value, 10);
 const line = lines[idx];
 if (!line) { showToast('Invalid line selection'); return; }
 state.settings.startLineIdx = idx;
 state.settings.startLineId = line.id ?? null;
 state.settings.startLineReversed = _spPendingReversed;
 // An explicit start line overrides any custom start point.
 state.settings.startPoint = null;
 state.settings.startConfigured = true;
 _startLineChooserShown = true;
 _syncStartPointPanel();
 hidePanel('start-point');
 showToast(`Start: ${line.name || 'Line ' + (idx + 1)} (${_spPendingReversed ? 'EOL->SOL' : 'SOL->EOL'})`);
 planRoute();
}

function useDefaultStartPoint() {
 state.settings.startPoint = null;
 state.settings.startLineIdx = null;
 state.settings.startLineId = null;
 state.settings.startLineReversed = false;
 state.settings.startConfigured = true;
 _syncStartPointPanel();
 showToast('Start point set to: First Survey Line Start (Default).');
 hidePanel('start-point');
 planRoute();
}

function toggleSurveyLayer(layerName) {
 if (!map) return;
 
 const el = document.getElementById(`layer-toggle-${layerName}`);
 const show = el ? el.checked : true;
 
 if (layerName === 'lines') {
 if (show) map.addLayer(layerSurveyLines); else map.removeLayer(layerSurveyLines);
 } else if (layerName === 'labels') {
 // Line number & SP annotations. Re-render to (re)build the label markers,
 // then add/remove the label layer group from the map.
 state.showLabels = show;
 renderSurveyLines();
 if (show) map.addLayer(layerLabels); else map.removeLayer(layerLabels);
 } else if (layerName === 'route') {
 if (show) map.addLayer(layerRoute); else map.removeLayer(layerRoute);
 } else if (layerName === 'annotations') {
 // Note: line number & SP labels have their own dedicated toggle ('labels').
 // User-defined start point/line marker is part of annotations.
 if (show) {
 map.addLayer(layerAnnotations);
 if (layerArrows) map.addLayer(layerArrows);
 if (layerSwaths) map.addLayer(layerSwaths);
 if (layerStartPoint) map.addLayer(layerStartPoint);
 } else {
 map.removeLayer(layerAnnotations);
 if (layerArrows) map.removeLayer(layerArrows);
 if (layerSwaths) map.removeLayer(layerSwaths);
 if (layerStartPoint) map.removeLayer(layerStartPoint);
 }
 } else if (layerName === 'obstructions') {
 if (show) map.addLayer(layerObstructions); else map.removeLayer(layerObstructions);
 }
 
 showToast(`${layerName.charAt(0).toUpperCase() + layerName.slice(1)} layer toggled.`);
}

function changeOptimizationStrategy(strategy) {
 state.settings.priority = strategy;
 showToast(`Pathfinding priority optimized: ${strategy === 'shortest' ? 'Shortest Distance' : strategy === 'turns' ? 'Minimum Turn Complexity' : 'Sequential West-to-East'}`);
 planRoute();
}

// ===== REPORTS PANEL POPULATION =====

function openReportsPanel() {
 togglePanel('reports');

 const s = state.settings;
 // Use the full original line set: the route solver replaces state.lines with only
 // the lines it routes (acquired lines removed), which would otherwise blank out the
 // acquired-vs-planned split. state._allLines holds the complete set.
 const lines = state._allLines || state.lines || [];
 const route = state.route || [];
 const fmt = (id, val) => { const el = document.getElementById(id); if (el) el.textContent = val; };
 const fmtDeg = (deg) => {
 const d = Math.abs(deg);
 const dd = Math.floor(d);
 const mm = ((d - dd) * 60).toFixed(4);
 return `${dd} deg ${mm}'`;
 };

 // Report metadata
 fmt('rep-generated', `Generated: ${fmtDT24(new Date())}`);
 fmt('rep-user', state.currentUser || '');

 // --- Survey Configuration ---
 fmt('rep-survey-type', (s.surveyType || '2D').toUpperCase());
 fmt('rep-speed', `${s.speed ?? 0} knots`);
 fmt('rep-radius', `${((s.turnRadius || 0) / 1000).toFixed(2)} km (${s.turnRadius || 0} m)`);
 fmt('rep-runinout', `${s.runIn || 0} m / ${s.runOut || 0} m`);

 // Line spacing = preplot line separation: the average distance between
 // adjacent PRIME line midpoints. This matches the Preplot Summary. Do NOT use
 // s.lineSpacing here - that stores the swath width, not the preplot spacing.
 const repPrimeLinesForSpacing = lines.filter(l => !l._infill);
 let lineSpacing = 0;
 if (repPrimeLinesForSpacing.length >= 2) {
 const mids = repPrimeLinesForSpacing.map(l => [(l.start[0]+l.end[0])/2, (l.start[1]+l.end[1])/2]);
 let sepSum = 0, sepCnt = 0;
 for (let i = 1; i < mids.length; i++) { sepSum += haversine(mids[i-1], mids[i]); sepCnt++; }
 lineSpacing = sepCnt > 0 ? Math.round(sepSum / sepCnt) : 0;
 }
 fmt('rep-line-spacing', lineSpacing > 0 ? `${lineSpacing} m` : '-');
 const swathW = lines.length > 0 && lineSpacing > 0 ? (lines.length * lineSpacing / 2) : 0;
 fmt('rep-swath-width', swathW > 0 ? `${(swathW / 1000).toFixed(2)} km` : '-');
 fmt('rep-progression', s.progression || 'sequential');
 fmt('rep-fold', `${calculateFoldOfCoverage().toFixed(1)}x`);
 fmt('rep-datum', (document.getElementById('geo-ellipsoid')?.value) || 'WGS 84');
 const repProj = (document.getElementById('geo-projection')?.value) || 'UTM';
 const repZone = s.utmZone || (lines.length > 0 ? Math.floor((lines[0].start[1] + 180) / 6) + 1 : null);
 const repHemi = s.utmHemi || (lines.length > 0 && lines[0].start[0] < 0 ? 'S' : 'N');
 fmt('rep-projection', repZone ? `${repProj} Zone ${repZone}${repHemi}` : repProj);

 // --- Survey Area Extents ---
 if (lines.length > 0) {
 let minLat = Infinity, maxLat = -Infinity, minLon = Infinity, maxLon = -Infinity;
 lines.forEach(l => {
 [l.start, l.end].forEach(p => {
 if (p[0] < minLat) minLat = p[0];
 if (p[0] >maxLat) maxLat = p[0];
 if (p[1] < minLon) minLon = p[1];
 if (p[1] >maxLon) maxLon = p[1];
 });
 });
 const cLat = (minLat + maxLat) / 2;
 const cLon = (minLon + maxLon) / 2;
 fmt('rep-bound-n', `${fmtDeg(maxLat)} ${maxLat >= 0 ? 'N' : 'S'}`);
 fmt('rep-bound-s', `${fmtDeg(minLat)} ${minLat >= 0 ? 'N' : 'S'}`);
 fmt('rep-bound-e', `${fmtDeg(maxLon)} ${maxLon >= 0 ? 'E' : 'W'}`);
 fmt('rep-bound-w', `${fmtDeg(minLon)} ${minLon >= 0 ? 'E' : 'W'}`);
 fmt('rep-centroid', `${cLat.toFixed(5)}, ${cLon.toFixed(5)}`);
 // Bounding box area (approximate)
 const nsKm = haversine([minLat, minLon], [maxLat, minLon]) / 1000;
 const ewKm = haversine([cLat, minLon], [cLat, maxLon]) / 1000;
 fmt('rep-bbox-area', isSurvey2D() ? '' : `${(nsKm * ewKm).toFixed(1)} km2`);
 }

 // --- Line Metrics ---
 const primeLines = lines.filter(l => !l._infill);
 const infillLines = lines.filter(l =>l._infill);
 fmt('rep-lines-count', `${primeLines.length}${infillLines.length > 0 ? ' + ' + infillLines.length + ' infill' : ''}`);
 if (lines.length > 0) {
 const nStr = s.numStreamers || 6;
 const strSep = s.streamerSeparation || 100;
 const spInt = s.spInterval || 12.5;
 const crossLineM = (nStr * strSep) / 2;

 // Per-line: SP count from the preplot'SP range (fallback: dist / spInt),
 // coverage = spCount x spInt (CMP bins). Separate prime/infill,
 // acquired vs remaining
 // tracked per line status.
 let primeTotalSP = 0, primeFullFoldM = 0;
 let infillTotalSP = 0, infillFullFoldM = 0;
 let primeAcquiredM = 0, primeAcquiredCount = 0, primeRemainingM = 0, primeRemainingCount = 0;
 let infillAcquiredM = 0, infillAcquiredCount = 0, infillRemainingM = 0, infillRemainingCount = 0;
 const primeLineLenMs = [];
 primeLines.forEach(l => {
 const spCount = lineSpCount(l, spInt);
 const lenM = lineFullFoldM(l, spInt);
 const ls = (state.lineStatus && state.lineStatus[l.id]) || { status: 'planned', partialPct: 0 };
 primeTotalSP += spCount;
 primeFullFoldM += lenM;
 primeLineLenMs.push(lenM);
 if (ls.status === 'acquired') {
 primeAcquiredM += lenM;
 primeAcquiredCount++;
 } else if ((ls.status === 'partial' || ls.status === 'partial_infill') && ls.partialPct > 0) {
 primeAcquiredM += lenM * (ls.partialPct / 100);
 primeRemainingM += lenM * (1 - ls.partialPct / 100);
 primeRemainingCount++;
 } else {
 primeRemainingM += lenM;
 primeRemainingCount++;
 }
 });
 infillLines.forEach(l => {
 const spCount = lineSpCount(l, spInt);
 const lenM = lineFullFoldM(l, spInt);
 const ls = (state.lineStatus && state.lineStatus[l.id]) || { status: 'planned', partialPct: 0 };
 infillTotalSP += spCount;
 infillFullFoldM += lenM;
 if (ls.status === 'acquired') {
 infillAcquiredM += lenM;
 infillAcquiredCount++;
 } else if ((ls.status === 'partial' || ls.status === 'partial_infill') && ls.partialPct > 0) {
 infillAcquiredM += lenM * (ls.partialPct / 100);
 infillRemainingM += lenM * (1 - ls.partialPct / 100);
 infillRemainingCount++;
 } else {
 infillRemainingM += lenM;
 infillRemainingCount++;
 }
 });
 const totalSP = primeTotalSP + infillTotalSP;
 const minLine = primeLineLenMs.length > 0 ? Math.min(...primeLineLenMs) : 0;
 const maxLine = primeLineLenMs.length > 0 ? Math.max(...primeLineLenMs) : 0;
 const primeLineKmGross = primeFullFoldM / 1000;
 const infillLineKm = infillFullFoldM / 1000;
 let skippedKmRep = 0;
 let skippedSPRep = 0;
 let offlineThreshRep = getOfflineNoSpThresholdM();
 (state.skippedRanges || []).forEach(r => {
  skippedKmRep += r.distKm || 0;
  skippedSPRep += r.spLost || 0;
  if (r.offlineThresholdM != null) offlineThreshRep = r.offlineThresholdM;
 });
 const primeLineKm = Math.max(0, primeLineKmGross - skippedKmRep);
 const lineKm = (primeFullFoldM + infillFullFoldM) / 1000 - skippedKmRep;
 const netPrimeSP = Math.max(0, primeTotalSP - skippedSPRep);
 const avgLineKm = primeLines.length > 0 ? primeLineKm / primeLines.length : 0;

 // Line bearing from first prime line (geographical + grid)
 const firstLine = primeLines.length > 0 ? primeLines[0] : lines[0];
 const brg = bearing(firstLine.start, firstLine.end);
 const reciprocal = (brg + 180) % 360;
 const gridBrg = gridBearing(firstLine.start, firstLine.end);
 const gridRecip = (gridBrg + 180) % 360;
 fmt('rep-line-bearing', `${gridBrg.toFixed(2)} deg / ${gridRecip.toFixed(2)} deg (Grid) | ${brg.toFixed(2)} deg / ${reciprocal.toFixed(2)} deg (Geo)`);
 fmt('rep-shortest-line', `${(minLine / 1000).toFixed(3)} km (${(minLine / 1852).toFixed(3)} nm)`);
 fmt('rep-longest-line', `${(maxLine / 1000).toFixed(3)} km (${(maxLine / 1852).toFixed(3)} nm)`);
 fmt('rep-avg-line', `${avgLineKm.toFixed(3)} km (${(avgLineKm / 1.852).toFixed(3)} nm)`);
 fmt('rep-line-km', skippedKmRep > 0
 ? `${primeLineKm.toFixed(3)} km (${(primeLineKm / 1.852).toFixed(3)} nm) prime (after ${skippedKmRep.toFixed(2)} km / ${skippedSPRep.toLocaleString()} SP sacrificed)`
 : `${primeLineKm.toFixed(3)} km (${(primeLineKm / 1.852).toFixed(3)} nm) prime`);

 // Full fold area = net fullFoldLength x crossLineWidth / 1,000,000
 const sqKm = Math.max(0, primeFullFoldM - skippedKmRep * 1000) * crossLineM / 1000000;
 const infillSqKm = infillFullFoldM * crossLineM / 1000000;
 const infillPctKm = primeLineKm > 0 ? ((infillLineKm / primeLineKm) * 100).toFixed(1) : '-';
 const infillPctArea = sqKm > 0 ? ((infillSqKm / sqKm) * 100).toFixed(1) : '-';
 const repIs2D = (s.surveyType || '3d') === '2d';
 fmt('rep-sq-km', repIs2D ? '' : (sqKm > 0 ? `${sqKm.toFixed(4)} km2 prime` : '-'));

 // Infill stats
 if (infillLineKm > 0) {
 fmt('rep-infill-km', `${infillLineKm.toFixed(3)} km (${infillPctKm}% of prime)`);
 fmt('rep-infill-area', repIs2D ? '' : `${infillSqKm.toFixed(4)} km2 (${infillPctArea}% of prime)`);
 setAreaStatsVisible(!repIs2D);
 }

 // Run-outs only (run-ins are part of line turn, never included)
 const repRunOutM = s.runOut || 0;
 const repRunOutKm = (repRunOutM / 1000) * primeLines.length;
 const repTotalProdKm = primeLineKm + repRunOutKm;
 fmt('rep-run-inout', `${repRunOutKm.toFixed(3)} km (${(repRunOutM).toFixed(0)}m x ${primeLines.length} prime lines, run-out only)`);
 fmt('rep-total-line-km', `${repTotalProdKm.toFixed(3)} km (${(repTotalProdKm / 1.852).toFixed(3)} nm) prime`);

 // Acquired lines: full fold + runouts
 const primeAcquiredKm = primeAcquiredM / 1000;
 const infillAcquiredKm = infillAcquiredM / 1000;
 const primeAcquiredRunOutKm = (repRunOutM / 1000) * primeAcquiredCount;
 const infillAcquiredRunOutKm = (repRunOutM / 1000) * infillAcquiredCount;
 const primeAcquiredFullFoldRunOutKm = primeAcquiredKm + primeAcquiredRunOutKm;
 const infillAcquiredFullFoldRunOutKm = infillAcquiredKm + infillAcquiredRunOutKm;
 const primeAcquiredFullFoldRunOutSqKm = (primeAcquiredM + primeAcquiredRunOutKm * 1000) * crossLineM / 1000000;
 const infillAcquiredFullFoldRunOutSqKm = (infillAcquiredM + infillAcquiredRunOutKm * 1000) * crossLineM / 1000000;

 // Planned (remaining) lines: full fold + runouts
 const primeRemainingKm = primeRemainingM / 1000;
 const infillRemainingKm = infillRemainingM / 1000;
 const primeRemainingRunOutKm = (repRunOutM / 1000) * primeRemainingCount;
 const infillRemainingRunOutKm = (repRunOutM / 1000) * infillRemainingCount;
 const primeRemainingFullFoldRunOutKm = primeRemainingKm + primeRemainingRunOutKm;
 const infillRemainingFullFoldRunOutKm = infillRemainingKm + infillRemainingRunOutKm;
 const primeRemainingFullFoldRunOutSqKm = (primeRemainingM + primeRemainingRunOutKm * 1000) * crossLineM / 1000000;
 const infillRemainingFullFoldRunOutSqKm = (infillRemainingM + infillRemainingRunOutKm * 1000) * crossLineM / 1000000;

 // km | km2 formatter (returns 'None' when nothing to show, so acquired/planned
 // rows are never left visually blank)
 const fmtKmArea = (km, m) =>km > 0 ? `${km.toFixed(3)} km` + (repIs2D ? '' : ` | ${(m * crossLineM / 1000000).toFixed(4)} km2`) : 'None';
 const fmtKmAreaDirect = (km, sqKm) =>km > 0 ? `${km.toFixed(3)} km` + (repIs2D ? '' : ` | ${sqKm.toFixed(4)} km2`) : 'None';

 // Acquired vs planned line counts
 fmt('rep-lines-count', `${primeLines.length}${infillLines.length > 0 ? ' + ' + infillLines.length + ' infill' : ''} (${primeAcquiredCount + infillAcquiredCount} acquired | ${primeRemainingCount + infillRemainingCount} planned)`);

 // Populate acquired line statistics
 fmt('rep-prime-acquired-ff', fmtKmArea(primeAcquiredKm, primeAcquiredM));
 fmt('rep-prime-acquired-ro', fmtKmAreaDirect(primeAcquiredFullFoldRunOutKm, primeAcquiredFullFoldRunOutSqKm));
 fmt('rep-infill-acquired-ff', fmtKmArea(infillAcquiredKm, infillAcquiredM));
 fmt('rep-infill-acquired-ro', fmtKmAreaDirect(infillAcquiredFullFoldRunOutKm, infillAcquiredFullFoldRunOutSqKm));

 // Populate planned (remaining) line statistics
 fmt('rep-prime-remaining-ff', fmtKmArea(primeRemainingKm, primeRemainingM));
 fmt('rep-prime-remaining-ro', fmtKmAreaDirect(primeRemainingFullFoldRunOutKm, primeRemainingFullFoldRunOutSqKm));
 fmt('rep-infill-remaining-ff', fmtKmArea(infillRemainingKm, infillRemainingM));
 fmt('rep-infill-remaining-ro', fmtKmAreaDirect(infillRemainingFullFoldRunOutKm, infillRemainingFullFoldRunOutSqKm));

 // --- Route & Transit ---
 if (route.length > 1) {
 let totalRouteM = 0, onlineM = 0, transitM = 0, numTurns = 0;
 for (let i = 0; i < route.length - 1; i++) {
 const prev = route[i], cur = route[i + 1];
 const sameLine = prev.lineName && cur.lineName && prev.lineName === cur.lineName;
 const isRunIn = sameLine && prev.type === 'runInStart';
 const isObsAvoid = prev.type === 'obsAvoidStart' || prev.type === 'obsAvoidance' || prev.type === 'obsAvoidEnd' ||
 cur.type === 'obsAvoidStart' || cur.type === 'obsAvoidance' || cur.type === 'obsAvoidEnd';
 if (isObsAvoid) {
 // Obstruction avoidance - count as transit (line change)
 const segDist = haversine(prev.pt, cur.pt);
 totalRouteM += segDist;
 transitM += segDist;
 } else if (sameLine && !isRunIn) {
 // Online: preplot, run-out
 const segDist = haversine(prev.pt, cur.pt);
 totalRouteM += segDist;
 onlineM += segDist;
 } else if (isRunIn) {
 // Run-in (runInStart'lineStart) - part of line change
 const segDist = haversine(prev.pt, cur.pt);
 totalRouteM += segDist;
 transitM += segDist;
 } else {
 // Transit segment: compute Dubins arc distance to match the line schedule
 const arcPts = computeArcTurn(route, i);
 let arcDist = 0;
 for (let k = 1; k < arcPts.length; k++) arcDist += haversine(arcPts[k - 1], arcPts[k]);
 totalRouteM += arcDist;
 transitM += arcDist;
 }
 }
 // Count line changes
 for (let i = 0; i < route.length; i++) {
 const wt = route[i].type;
 if (wt === 'runOutEnd' && i < route.length - 1) {
 numTurns++;
 } else if (wt === 'lineEnd' && i < route.length - 1) {
 const nxt = route[i + 1];
 if (!(nxt.type === 'runOutEnd' && nxt.lineName === route[i].lineName)) numTurns++;
 }
 }
 const totalNm = totalRouteM / 1852;
 const onlineNm = onlineM / 1852;
 const transitNm = transitM / 1852;

 fmt('rep-total-km', `${(totalRouteM / 1000).toFixed(2)} km (${totalNm.toFixed(2)} nm)`);
 fmt('rep-online-km', `${(onlineM / 1000).toFixed(2)} km (${onlineNm.toFixed(2)} nm)`);
 fmt('rep-transit-km', `${(transitM / 1000).toFixed(2)} km (${transitNm.toFixed(2)} nm)`);
 fmt('rep-num-turns', `${numTurns}`);
 fmt('rep-avg-transit', numTurns > 0 ? `${((transitM / numTurns) / 1000).toFixed(2)} km` : '-');

 // --- Duration ---
 const speed = s.speed ?? 5;
 const turnSpeed = s.turnSpeed ?? speed;
 const onlineHrs = onlineNm / speed;
 const transitHrs = transitNm / turnSpeed;
 const bareHrs = onlineHrs + transitHrs; // Bare bones: online + line change only
 const fmtTime = (hrs) => {
 const h = Math.floor(hrs);
 const m = Math.round((hrs - h) * 60);
 return `${h}h ${m}m`;
 };
 fmt('rep-online-time', fmtTime(onlineHrs));
 fmt('rep-transit-time', fmtTime(transitHrs));
 fmt('rep-bare-duration', fmtTime(bareHrs));

 // Bare bones completion = survey start time + bare-bones duration.
 // Uses the same start-time base as the Line Schedule so the two agree.
 const repStartBase = s.startTime ? new Date(s.startTime) : new Date();
 const bareCompletionDate = new Date(repStartBase.getTime() + bareHrs * 3600000);
 fmt('rep-bare-completion', fmtDT24(bareCompletionDate));

 // --- Adjustments ---
 const techPct = s.weatherDowntime || 0;
 const standbyPct = s.standbyPct || 0;
 const timeAdjPct = s.timeAdjustmentsPct || 0;
 const infillPct = s.infillPct || 0;
 const techFactor = techPct > 0 ? 1 / (1 - techPct / 100) : 1;
 const standbyFactor = standbyPct > 0 ? 1 / (1 - standbyPct / 100) : 1;
 const timeAdjFactor = timeAdjPct > 0 ? 1 / (1 - timeAdjPct / 100) : 1;
 const infillFactor = infillPct > 0 ? 1 + infillPct / 100 : 1;
 const adjSurveyHrs = bareHrs * techFactor * standbyFactor * timeAdjFactor * infillFactor;
 const techHrs = bareHrs * techFactor - bareHrs;
 const standbyHrs = bareHrs * standbyFactor - bareHrs;
 const timeAdjHrs = bareHrs * timeAdjFactor - bareHrs;
 const infillHrs = bareHrs * infillFactor - bareHrs;
 const mobDays = s.mobDemobDays || 0;
 const plannedDays = s.additionalPlanned || 0;
 const unplannedDays = s.additionalUnplanned || 0;
 const mobHrs = mobDays * 24;
 const plannedHrs = plannedDays * 24;
 const unplannedHrs = unplannedDays * 24;
 const totalHrs = adjSurveyHrs + mobHrs + plannedHrs + unplannedHrs;

 fmt('rep-tech-downtime', techPct > 0 ? fmtTime(techHrs) + ` (${techPct}%)` : '0%');
 fmt('rep-standby-time', standbyPct > 0 ? fmtTime(standbyHrs) + ` (${standbyPct}%)` : '0%');
 fmt('rep-time-adjustments', timeAdjPct > 0 ? fmtTime(timeAdjHrs) + ` (${timeAdjPct}%)` : '0%');
 fmt('rep-infill-pct', infillPct > 0 ? fmtTime(infillHrs) + ` (${infillPct}%)` : '0%');
 fmt('rep-mob-demob-days', mobDays > 0 ? `${mobDays} days` : '0 days');
 fmt('rep-additional-planned', plannedDays > 0 ? `${plannedDays} days` : '0 days');
 fmt('rep-additional-unplanned', unplannedDays > 0 ? `${unplannedDays} days` : '0 days');

 // Full duration
 fmt('rep-duration', fmtTime(totalHrs));

 // Full completion = survey start time + full projected duration.
 const completionDate = new Date(repStartBase.getTime() + totalHrs * 3600000);
 fmt('rep-completion', fmtDT24(completionDate));

 // --- Weather & Adjusted Duration ---
 const weatherPct = state.settings.weatherDowntime || 0;
 const weatherFactor = weatherPct > 0 ? 1 / (1 - weatherPct / 100) : 1;
 const adjHrs = totalHrs * weatherFactor;
 const adjDays = (adjHrs / 24).toFixed(1);
 fmt('rep-weather-pct', weatherPct > 0 ? `${weatherPct}%` : 'None');
 fmt('rep-adj-duration', weatherPct > 0 ? fmtTime(adjHrs) : fmtTime(totalHrs));
 fmt('rep-adj-days', `${adjDays} days`);

 // --- Cost Estimation ---
 // Calculate prime and infill costs based on their respective cost basis
 const totalDays = totalHrs / 24;
 const surveyDays = totalDays - (s.mobDemobDays || 0); // exclude mob/demob from production days
 const cFmt = v => '$' + Math.round(v).toLocaleString();

 // Prime cost calculation
 let primeCost = 0;
 let primeCostDesc = '';
 const primeMode = s.primeCostMode || 'dayrate';
 if (primeMode === 'dayrate') {
 primeCost = (s.vesselDayRate || 0) * surveyDays;
 primeCostDesc = `${cFmt(s.vesselDayRate || 0)}/day x ${surveyDays.toFixed(1)}d (survey)`;
 } else if (primeMode === 'linekm') {
 const primeFullFoldKm = primeLineKm; // full fold line km (excludes run-outs)
 primeCost = (s.costPerLineKm || 0) * primeFullFoldKm;
 primeCostDesc = `${cFmt(s.costPerLineKm || 0)}/km x ${primeFullFoldKm.toFixed(3)} km (full fold)`;
 } else if (primeMode === 'sqkm') {
 const primeFullFoldSqKm = sqKm; // full fold sq km
 primeCost = (s.costPerSqKm || 0) * primeFullFoldSqKm;
 primeCostDesc = `${cFmt(s.costPerSqKm || 0)}/sq km x ${primeFullFoldSqKm.toFixed(4)} sq km (full fold)`;
 }

 // Infill cost calculation
 let infillCost = 0;
 let infillCostDesc = '';
 const infillMode = s.infillCostMode || 'dayrate';
 if (infillLineKm > 0) {
 if (infillMode === 'dayrate') {
 infillCost = (s.vesselDayRate || 0) * surveyDays * (infillLineKm / (primeLineKm + infillLineKm));
 infillCostDesc = `${cFmt(s.vesselDayRate || 0)}/day x ${surveyDays.toFixed(1)}d x ${((infillLineKm / (primeLineKm + infillLineKm)) * 100).toFixed(1)}% (infill share)`;
 } else if (infillMode === 'linekm') {
 const infillFullFoldKm = infillLineKm;
 infillCost = (s.costPerLineKm || 0) * infillFullFoldKm;
 infillCostDesc = `${cFmt(s.costPerLineKm || 0)}/km x ${infillFullFoldKm.toFixed(3)} km (infill)`;
 } else if (infillMode === 'sqkm') {
 const infillFullFoldSqKm = infillSqKm;
 infillCost = (s.costPerSqKm || 0) * infillFullFoldSqKm;
 infillCostDesc = `${cFmt(s.costPerSqKm || 0)}/sq km x ${infillFullFoldSqKm.toFixed(4)} sq km (infill)`;
 }
 }

 // Mob/demob cost (always on day rate)
 const mobDemobDays = s.mobDemobDays || 0;
 const mobCost = (s.vesselDayRate || 0) * mobDemobDays;
 const mobCostDesc = mobDemobDays > 0 ? `${cFmt(s.vesselDayRate || 0)}/day x ${mobDemobDays}d (mob/demob)` : '';

 // Total vessel cost
 const vesselCost = primeCost + infillCost + mobCost;
 fmt('rep-day-rate', primeCostDesc + (infillCostDesc ? ' + ' + infillCostDesc : '') + (mobCostDesc ? ' + ' + mobCostDesc : ''));
 const weatherStandbyDays = Math.max(0, (adjHrs - totalHrs) / 24);
 const standbyCost = (s.chargeableStandby || 0) * weatherStandbyDays;
 const ancilVessel = (s.ancilVesselRate || 0) * (s.ancilVesselCount || 0) * totalDays;
 const pmCost = (s.pmRate || 0) * (s.pmMultiplier || 1) * (s.pmCount || 0) * totalDays;
 const repCost = (s.clientRepRate || 0) * (s.clientRepCount || 0) * totalDays;
 const mfoCost = (s.mfoRate || 0) * (s.mfoCount || 0) * totalDays;
 const svcCost = (s.svcRate || 0) * (s.svcCount || 0) * totalDays;
 const equipCost = ((s.ancilEquipRate || 0) * totalDays) + (s.ancilEquipFixed || 0);
 const mobDemobCost = s.mobDemob || 0;
 const fixedCosts = (s.permitting || 0) + (s.environmental || 0) + (s.fisheriesComp || 0) + (s.preSurveyScout || 0) + (s.bathySurvey || 0);
 const ud1Cost = ((s.ud1Rate || 0) * totalDays) + (s.ud1Fixed || 0);
 const ud2Cost = ((s.ud2Rate || 0) * totalDays) + (s.ud2Fixed || 0);
 const ud3Cost = ((s.ud3Rate || 0) * totalDays) + (s.ud3Fixed || 0);
 const grandTotal = vesselCost + standbyCost + ancilVessel + pmCost + repCost + mfoCost +
 svcCost + equipCost + mobDemobCost + fixedCosts + ud1Cost + ud2Cost + ud3Cost;

 const bd = document.getElementById('rep-cost-breakdown');
 if (bd) {
 const rows = [];
 const addRow = (label, val) =>rows.push(`<div style="display:flex;justify-content:space-between;"><span style="color:#a0aebb;">${label}</span><strong>${cFmt(val)}</strong></div>`);
 if (dayRate > 0) addRow(`Vessel (${totalDays.toFixed(1)}d)`, vesselCost);
 if (standbyCost > 0) addRow('Chargeable Standby', standbyCost);
 if (ancilVessel > 0) addRow(`Ancillary Vessels (\u00d7${s.ancilVesselCount || 0})`, ancilVessel);
 if (pmCost > 0) addRow(`Project Management (\u00d7${s.pmCount || 0})`, pmCost);
 if (repCost > 0) addRow(`Client Reps / QCs (\u00d7${s.clientRepCount || 0})`, repCost);
 if (mfoCost > 0) addRow(`MFOs (\u00d7${s.mfoCount || 0})`, mfoCost);
 if (svcCost > 0) addRow(`SV Coordinators (\u00d7${s.svcCount || 0})`, svcCost);
 if (equipCost > 0) addRow('Ancillary Equipment', equipCost);
 if (mobDemobCost > 0) addRow('Mob / Demob', mobDemobCost);
 if ((s.permitting || 0) > 0) addRow('Permitting', s.permitting);
 if ((s.environmental || 0) > 0) addRow('Environmental', s.environmental);
 if ((s.fisheriesComp || 0) > 0) addRow('Fisheries Compensation', s.fisheriesComp);
 if ((s.preSurveyScout || 0) > 0) addRow('Pre-survey Scouting', s.preSurveyScout);
 if ((s.bathySurvey || 0) > 0) addRow('Bathymetry Surveys', s.bathySurvey);
 if (ud1Cost > 0) addRow(s.ud1Name || 'User Defined 1', ud1Cost);
 if (ud2Cost > 0) addRow(s.ud2Name || 'User Defined 2', ud2Cost);
 if (ud3Cost > 0) addRow(s.ud3Name || 'User Defined 3', ud3Cost);
 bd.innerHTML = rows.length ? rows.join('') : '<div style="color:#666;">No costings specified in Survey Criteria</div>';
 }
 fmt('rep-total-cost', grandTotal > 0 ? cFmt(grandTotal) : '-');

 // --- Efficiency ---
 const prodRatio = totalRouteM > 0 ? (onlineM / totalRouteM * 100) : 0;
 const transitOverhead = totalRouteM > 0 ? (transitM / totalRouteM * 100) : 0;
 fmt('rep-productive-ratio', `${prodRatio.toFixed(1)}% on-line`);
 fmt('rep-transit-overhead', `${transitOverhead.toFixed(1)}% line changes`);
 const sourceDensity = sqKm > 0 ? ((Math.max(0, totalSP - skippedSPRep)) / sqKm) : 0;
 fmt('rep-density', pdfIs2D ? '' : (sourceDensity > 0 ? `${sourceDensity.toFixed(1)} SP/km2` : '-'));
 } else {
 ['rep-total-km','rep-online-km','rep-transit-km','rep-num-turns','rep-avg-transit',
 'rep-online-time','rep-transit-time','rep-bare-duration','rep-bare-completion',
 'rep-tech-downtime','rep-standby-time','rep-time-adjustments','rep-infill-pct','rep-mob-demob-days','rep-additional-planned','rep-additional-unplanned',
 'rep-duration','rep-completion',
 'rep-weather-pct','rep-adj-duration','rep-adj-days',
 'rep-day-rate','rep-vessel-cost','rep-mob-demob','rep-total-cost',
 'rep-productive-ratio','rep-transit-overhead','rep-density'].forEach(id =>fmt(id, 'No route'));
 }
 }

 // --- Hazards ---
 const obs = state.obstructions || [];
 const skipped = state.skippedRanges || [];
 fmt('rep-hazards', `${obs.length} zone${obs.length !== 1 ? 's' : ''}`);
 let skippedKm = 0;
 let skippedSP = 0;
 let offlineTh = getOfflineNoSpThresholdM();
 skipped.forEach(r => {
  skippedKm += r.distKm || 0;
  skippedSP += r.spLost || 0;
  if (r.offlineThresholdM != null) offlineTh = r.offlineThresholdM;
 });
 fmt('rep-skipped', skippedKm > 0
  ? `${skippedKm.toFixed(2)} km` + (offlineTh != null ? ` (offline > ${offlineTh} m)` : '')
  : 'None');
 fmt('rep-skipped-sp', skippedSP > 0 ? `${skippedSP.toLocaleString()} SP` : 'None');
 fmt('rep-offline-threshold', offlineTh != null ? `${offlineTh} m` : 'Not set');
 const affectedLines = new Set(skipped.map(r =>r.lineName)).size;
 fmt('rep-lines-affected', affectedLines > 0 ? `${affectedLines} line${affectedLines !== 1 ? 's' : ''}` : 'None');

 // --- Line Schedule (follows actual optimized route order) ---
 const scheduleEl = document.getElementById('rep-line-schedule');
 if (scheduleEl && lines.length > 0 && route.length > 1) {
 const speed = s.speed ?? 5;
 const turnSpeed = s.turnSpeed ?? speed;
 const startTime = s.startTime ? new Date(s.startTime) : new Date();
 let currentTime = new Date(startTime);

 const fmtDateTime = (d) => {
 return fmtDT24(d);
 };
 const fmtDur = (hrs) => {
 const h = Math.floor(hrs);
 const m = Math.round((hrs - h) * 60);
 return h > 0 ? `${h}h ${m}m` : `${m}m`;
 };

 // Extract line segments from route waypoints in actual acquisition order
 // Online = lineStart through runOutEnd (or lineEnd if no run-out)
 const lineSegs = [];
 for (let i = 0; i < route.length; i++) {
 if (route[i].type === 'lineStart') {
 const seg = { name: route[i].lineName, startIdx: i, endIdx: i, start: route[i].pt, end: route[i].pt };
 // Walk forward to find end of online segment (runOutEnd or lineEnd if no runout)
 for (let j = i + 1; j < route.length; j++) {
 if (route[j].type === 'runOutEnd' && route[j].lineName === route[i].lineName) { seg.endIdx = j; seg.end = route[j].pt; break; }
 if (route[j].type === 'lineEnd' && route[j].lineName === route[i].lineName) {
 seg.endIdx = j; seg.end = route[j].pt;
 // Check if runOutEnd follows
 if (j + 1 < route.length && route[j + 1].type === 'runOutEnd' && route[j + 1].lineName === route[i].lineName) {
 seg.endIdx = j + 1; seg.end = route[j + 1].pt;
 }
 break;
 }
 }
 lineSegs.push(seg);
 }
 }

 // Helper: compute SP numbers for a segment based on line fracs
 const spInt = s.spInterval || 25;
 const defaultFirstSP = s.firstSP || 1001;
 function getSegSP(lineName, fracStart, fracEnd) {
 const lineObj = lines.find(l =>l.name === lineName);
 const baseFirstSP = lineObj && lineObj.spStart != null ? lineObj.spStart : defaultFirstSP;
 const lineLen = lineObj ? haversine(lineObj.start, lineObj.end) : 0;
 const totalSPs = lineLen > 0 ? Math.round(lineLen / spInt) : 0;
 const spFrom = baseFirstSP + Math.round((fracStart || 0) * totalSPs);
 const spTo = baseFirstSP + Math.round((fracEnd || 1) * totalSPs);
 return { spFrom, spTo };
 }

 let html = '<table style="width:100%; border-collapse:collapse; font-size:10px;">';
 html += '<tr style="border-bottom:1px solid #444; color:#e0e8f0; font-weight:700;">';
 html += '<td style="padding:3px 4px;">#</td>';
 html += '<td style="padding:3px 4px;">Line</td>';
 html += '<td style="padding:3px 4px;">SP Range</td>';
 html += '<td style="padding:3px 4px;">SOL</td>';
 html += '<td style="padding:3px 4px;">EOL</td>';
 html += '<td style="padding:3px 4px;">Acq</td>';
 html += '<td style="padding:3px 4px;">Trn/Obs</td>';
 html += '<td style="padding:3px 4px;">Cum.</td>';
 html += '</tr>';

 let cumHrs = 0;
 let obsAvoidTotalHrs = 0;
 let lineNum = 0;
 lineSegs.forEach((seg, idx) => {
 // Transit / Obs avoidance from end of previous segment to this segment'start
 let transitHrs = 0;
 let isObsAvoid = false;
 if (idx > 0) {
 isObsAvoid = lineSegs[idx - 1].name === seg.name;
 let transitDist = 0;
 for (let w = lineSegs[idx - 1].endIdx + 1; w <= seg.startIdx; w++) {
 transitDist += haversine(route[w - 1].pt, route[w].pt);
 }
 if (transitDist < 0) transitDist = 0;
 transitHrs = (transitDist / 1852) / turnSpeed;

 // Show transit/obs avoidance row
 const trStartTime = new Date(currentTime);
 currentTime = new Date(currentTime.getTime() + transitHrs * 3600000);
 cumHrs += transitHrs;
 if (isObsAvoid) {
 obsAvoidTotalHrs += transitHrs;
 html += `<tr style="border-bottom:1px solid #222; background:rgba(255,214,10,0.06);">`;
 html += `<td style="padding:3px 4px; color:#ffd60a;">s </td>`;
 html += `<td style="padding:3px 4px; color:#ffd60a; font-weight:600;">Obs. Avoidance</td>`;
 html += `<td style="padding:3px 4px; color:#ffd60a; font-size:9px;">offline</td>`;
 html += `<td style="padding:3px 4px; color:#888;">${fmtDateTime(trStartTime)}</td>`;
 html += `<td style="padding:3px 4px; color:#888;">${fmtDateTime(currentTime)}</td>`;
 html += `<td style="padding:3px 4px;"></td>`;
 html += `<td style="padding:3px 4px; color:#ffd60a; font-weight:600;">${fmtDur(transitHrs)}</td>`;
 html += `<td style="padding:3px 4px; color:#8a9bb0; font-size:9px;">${fmtDur(cumHrs)}</td>`;
 html += `</tr>`;
 } else {
 html += `<tr style="border-bottom:1px solid #1a1a24; background:rgba(96,165,250,0.04);">`;
 html += `<td style="padding:2px 4px;"></td>`;
 html += `<td style="padding:2px 4px; color:#60a5fa; font-size:9px;">Line Change</td>`;
 html += `<td style="padding:2px 4px;"></td>`;
 html += `<td style="padding:2px 4px; color:#666; font-size:9px;">${fmtDateTime(trStartTime)}</td>`;
 html += `<td style="padding:2px 4px; color:#666; font-size:9px;">${fmtDateTime(currentTime)}</td>`;
 html += `<td style="padding:2px 4px;"></td>`;
 html += `<td style="padding:2px 4px; color:#60a5fa; font-size:9px;">${fmtDur(transitHrs)}</td>`;
 html += `<td style="padding:2px 4px; color:#8a9bb0; font-size:9px;">${fmtDur(cumHrs)}</td>`;
 html += `</tr>`;
 }
 }

 // Compute SP range for this segment
 const startWp = route[seg.startIdx];
 const endWp = route[seg.endIdx];
 const fracStart = startWp && startWp.frac != null ? startWp.frac : 0;
 const fracEnd = endWp && endWp.frac != null ? endWp.frac : 1;
 const { spFrom, spTo } = getSegSP(seg.name, fracStart, fracEnd);

 // Online distance: sum all segments from startIdx to endIdx
 let totalLineM = 0;
 for (let w = seg.startIdx; w < seg.endIdx; w++) {
 totalLineM += haversine(route[w].pt, route[w + 1].pt);
 }
 const lineTimeHrs = (totalLineM / 1852) / speed;

 const solTime = new Date(currentTime);
 currentTime = new Date(currentTime.getTime() + lineTimeHrs * 3600000);
 cumHrs += lineTimeHrs;
 const eolTime = new Date(currentTime);

 // Increment line number only for new line (not continuation after obs avoid)
 if (!isObsAvoid) lineNum++;
 const segLabel = isObsAvoid ? `${seg.name} (cont.)` : seg.name;

 const rowBg = isObsAvoid ? 'background:rgba(90,250,130,0.04);' : (lineNum % 2 === 0 ? 'background:rgba(255,255,255,0.03);' : '');
 html += `<tr style="border-bottom:1px solid #222;${rowBg}">`;
 html += `<td style="padding:3px 4px; color:#8a9bb0;">${lineNum}</td>`;
 html += `<td style="padding:3px 4px; color:#ffffff; font-weight:700;">${segLabel}</td>`;
 html += `<td style="padding:3px 4px; color:#a0aebb; font-size:9px;">SP ${spFrom} - ${spTo}</td>`;
 html += `<td style="padding:3px 4px; color:#e8ecf2;">${fmtDateTime(solTime)}</td>`;
 html += `<td style="padding:3px 4px; color:#e8ecf2;">${fmtDateTime(eolTime)}</td>`;
 html += `<td style="padding:3px 4px; color:#5afa82; font-weight:600;">${fmtDur(lineTimeHrs)}</td>`;
 html += `<td style="padding:3px 4px;"></td>`;
 html += `<td style="padding:3px 4px; color:#8a9bb0; font-size:9px;">${fmtDur(cumHrs)}</td>`;
 html += `</tr>`;
 });

 // Summary row
 html += `<tr style="border-top:2px solid #444;">`;
 html += `<td colspan="5" style="padding:4px; color:#00d2ff; font-weight:700;">Total: ${lineNum} lines (${lineSegs.length} segments)</td>`;
 html += `<td colspan="3" style="padding:4px; color:#30d158; font-weight:700; text-align:right;">${fmtDur(cumHrs)}</td>`;
 html += `</tr>`;
 if (obsAvoidTotalHrs > 0) {
 html += `<tr><td colspan="5" style="padding:3px 4px; color:#ffd60a; font-size:9px;">s Obstruction avoidance: ${fmtDur(obsAvoidTotalHrs)}</td><td colspan="3"></td></tr>`;
 }
 html += '</table>';
 scheduleEl.innerHTML = html;
 } else if (scheduleEl) {
 scheduleEl.innerHTML = '<div style="color:#7c8c9e; text-align:center;">No route planned</div>';
 }
}

// ===== VESSEL SIMULATION =====
var simState = { running: false, paused: false, progress: 0, animId: null, marker: null, trail: null };

function startVesselSimulation() {
 if (!state.route || state.route.length < 2) {
 showToast('Plan a route first');
 return;
 }
 if (simState.running) { stopVesselSimulation(); return; }

 // Build path segments with cumulative distance
 const wp = state.route;
 const pts = wp.map(w =>w.pt);
 const dists = [0];
 for (let i = 1; i < pts.length; i++) {
 dists.push(dists[i - 1] + haversine(pts[i - 1], pts[i]));
 }
 const totalDist = dists[dists.length - 1];
 if (totalDist === 0) return;

 // Create vessel icon
 const vesselIcon = L.divIcon({
 className: '',
 html: '<div style="width:18px;height:18px;background:#00d2ff;border:3px solid #fff;border-radius:50%;box-shadow:0 0 12px #00d2ff,0 0 24px rgba(0,210,255,0.4);"></div>',
 iconAnchor: [12, 12]
 });
 simState.marker = L.marker(pts[0], { icon: vesselIcon, zIndexOffset: 2000 }).addTo(map);
 simState.trail = L.polyline([], { color: '#00d2ff', weight: 2, opacity: 0.6, dashArray: '4 4' }).addTo(map);

 // Simulation control panel
 let panel = document.getElementById('sim-panel');
 if (!panel) {
 panel = document.createElement('div');
 panel.id = 'sim-panel';
 panel.style.cssText = 'position:absolute;bottom:60px;right:12px;z-index:900;' +
 'background:rgba(8,8,16,0.92);border:1px solid #1a1a2e;border-radius:8px;padding:12px 16px;' +
 'color:#e0e8f0;font-size:11px;min-width:220px;box-shadow:0 8px 32px rgba(0,0,0,0.6);backdrop-filter:blur(8px);';
 document.getElementById('main').appendChild(panel);
 }

 const speedS = state.settings.speed ?? 4.5;
 const startTime = state.settings.startTime ? new Date(state.settings.startTime) : new Date();

 simState.running = true;
 simState.paused = false;
 simState.progress = 0;
 let simSpeed = 50; // simulation speed multiplier (x real-time)
 let lastFrame = performance.now();

 function updateSimPanel() {
 const pct = (simState.progress * 100).toFixed(1);
 const elapsedDist = totalDist * simState.progress;
 const elapsedNm = (elapsedDist / 1852).toFixed(1);
 // Estimate elapsed hours based on segment speeds
 let elapsedHrs = 0;
 let accDist = 0;
 const onlineSpeed = state.settings.speed ?? 4.5;
 const turnSpd = state.settings.turnSpeed ?? 6;
 for (let i = 1; i < pts.length; i++) {
 const segDist = haversine(pts[i - 1], pts[i]);
 if (accDist + segDist >elapsedDist) {
 const remain = elapsedDist - accDist;
 const isOnline = (wp[i - 1].type === 'lineStart' && wp[i].type === 'lineEnd') ||
 (wp[i - 1].type === 'runInStart' && wp[i].type === 'lineStart') ||
 (wp[i - 1].type === 'lineEnd' && wp[i].type === 'runOutEnd');
 elapsedHrs += (remain / 1852) / (isOnline ? onlineSpeed : turnSpd);
 break;
 }
 const isOnline = (wp[i - 1].type === 'lineStart' && wp[i].type === 'lineEnd') ||
 (wp[i - 1].type === 'runInStart' && wp[i].type === 'lineStart') ||
 (wp[i - 1].type === 'lineEnd' && wp[i].type === 'runOutEnd');
 elapsedHrs += (segDist / 1852) / (isOnline ? onlineSpeed : turnSpd);
 accDist += segDist;
 }
 const simTime = new Date(startTime.getTime() + elapsedHrs * 3600000);

 // Find current line
 let currentLine = '';
 let segIdx = 0;
 accDist = 0;
 for (let i = 1; i < pts.length; i++) {
 accDist += haversine(pts[i - 1], pts[i]);
 if (accDist >= elapsedDist) { segIdx = i - 1; break; }
 }
 const curWp = wp[segIdx];
 if (curWp) {
 if (curWp.type === 'lineStart' || curWp.type === 'lineEnd') currentLine = curWp.lineName || '';
 else if (curWp.type === 'runInStart' || curWp.type === 'runOutEnd') currentLine = curWp.lineName || '';
 else currentLine = 'Line Change';
 }

 panel.innerHTML =
 '<div style="font-size:10px;color:#00d2ff;font-weight:700;letter-spacing:0.5px;margin-bottom:6px;">VESSEL SIMULATION</div>' +
 '<div><span style="color:#8a9bb0;">Time:</span> <strong>' + fmtDMT24(simTime) + '</strong></div>' +
 '<div><span style="color:#8a9bb0;">Distance:</span> <strong>' + elapsedNm + ' nm</strong></div>' +
 '<div><span style="color:#8a9bb0;">Activity:</span> <strong style="color:' + (currentLine === 'Line Change' || currentLine === 'Transit' ? '#ff9500' : '#30d158') + ';">' + currentLine + '</strong></div>' +
 '<div style="margin:8px 0;"><div style="background:#222;height:6px;border-radius:3px;overflow:hidden;">' +
 '<div style="width:' + pct + '%;height:100%;background:linear-gradient(90deg,#00d2ff,#30d158);border-radius:3px;transition:width 0.3s;"></div></div>' +
 '<div style="display:flex;justify-content:space-between;font-size:9px;color:#666;margin-top:2px;"><span>0%</span><span>' + pct + '%</span><span>100%</span></div></div>' +
 '<div style="display:flex;gap:6px;margin-bottom:6px;">' +
 '<button onclick="simPauseResume()" style="flex:1;padding:7px;border-radius:4px;border:1px solid #333;background:' + (simState.paused ? '#1a3a1a' : '#1a1a2e') + ';color:#fff;cursor:pointer;font-size:11px;font-weight:700;">' + (simState.paused ? '>Resume' : ' Pause') + '</button>' +
 '<button onclick="stopVesselSimulation()" style="flex:1;padding:7px;border-radius:4px;border:1px solid #ff453a;background:#2a0a0a;color:#ff453a;cursor:pointer;font-size:11px;font-weight:700;">- Stop</button>' +
 '</div>' +
 '<div style="display:flex;gap:4px;align-items:center;">' +
 '<span style="font-size:9px;color:#8a9bb0;width:40px;">Speed:</span>' +
 '<button onclick="simSpeedSet(1)" style="flex:1;padding:4px;border-radius:3px;border:1px solid ' + (simSpeed===1?'#00d2ff':'#333') + ';background:' + (simSpeed===1?'#0a2a3a':'#111') + ';color:' + (simSpeed===1?'#00d2ff':'#888') + ';cursor:pointer;font-size:9px;font-weight:700;">x1</button>' +
 '<button onclick="simSpeedSet(5)" style="flex:1;padding:4px;border-radius:3px;border:1px solid ' + (simSpeed===5?'#00d2ff':'#333') + ';background:' + (simSpeed===5?'#0a2a3a':'#111') + ';color:' + (simSpeed===5?'#00d2ff':'#888') + ';cursor:pointer;font-size:9px;font-weight:700;">x5</button>' +
 '<button onclick="simSpeedSet(10)" style="flex:1;padding:4px;border-radius:3px;border:1px solid ' + (simSpeed===10?'#00d2ff':'#333') + ';background:' + (simSpeed===10?'#0a2a3a':'#111') + ';color:' + (simSpeed===10?'#00d2ff':'#888') + ';cursor:pointer;font-size:9px;font-weight:700;">x10</button>' +
 '<button onclick="simSpeedSet(50)" style="flex:1;padding:4px;border-radius:3px;border:1px solid ' + (simSpeed===50?'#00d2ff':'#333') + ';background:' + (simSpeed===50?'#0a2a3a':'#111') + ';color:' + (simSpeed===50?'#00d2ff':'#888') + ';cursor:pointer;font-size:9px;font-weight:700;">x50</button>' +
 '<button onclick="simSpeedSet(200)" style="flex:1;padding:4px;border-radius:3px;border:1px solid ' + (simSpeed===200?'#00d2ff':'#333') + ';background:' + (simSpeed===200?'#0a2a3a':'#111') + ';color:' + (simSpeed===200?'#00d2ff':'#888') + ';cursor:pointer;font-size:9px;font-weight:700;">x200</button>' +
 '<button onclick="simSpeedSet(1000)" style="flex:1;padding:4px;border-radius:3px;border:1px solid ' + (simSpeed===1000?'#00d2ff':'#333') + ';background:' + (simSpeed===1000?'#0a2a3a':'#111') + ';color:' + (simSpeed===1000?'#00d2ff':'#888') + ';cursor:pointer;font-size:9px;font-weight:700;">x1k</button>' +
 '</div>' +
 '<div style="font-size:8px;color:#555;margin-top:6px;text-align:center;">Press <strong>Esc</strong>to stop | <strong>Space</strong>to pause</div>';
 }

 function interpolatePosition(frac) {
 const targetDist = frac * totalDist;
 for (let i = 1; i < pts.length; i++) {
 if (dists[i] >= targetDist) {
 const segLen = dists[i] - dists[i - 1];
 const t = segLen > 0 ? (targetDist - dists[i - 1]) / segLen : 0;
 return [
 pts[i - 1][0] + (pts[i][0] - pts[i - 1][0]) * t,
 pts[i - 1][1] + (pts[i][1] - pts[i - 1][1]) * t
 ];
 }
 }
 return pts[pts.length - 1];
 }

 function animate(now) {
 if (!simState.running) return;
 if (!simState.paused) {
 const dt = (now - lastFrame) / 1000; // seconds
 // Advance: simSpeed knots equivalent in fraction of total route
 const advanceM = (speedS * 1852 / 3600) * dt * simSpeed;
 simState.progress += advanceM / totalDist;
 if (simState.progress >= 1) {
 simState.progress = 1;
 const pos = interpolatePosition(1);
 simState.marker.setLatLng(pos);
 updateSimPanel();
 showToast('Simulation complete');
 return;
 }
 const pos = interpolatePosition(simState.progress);
 simState.marker.setLatLng(pos);
 simState.trail.addLatLng(pos);
 }
 lastFrame = now;
 updateSimPanel();
 simState.animId = requestAnimationFrame(animate);
 }

 // Store simSpeed in closure for speed changes
 window._simSpeedRef = { get: () =>simSpeed, set: (v) => { simSpeed = v; } };

 // Keyboard controls
 function simKeyHandler(e) {
 if (!simState.running) { document.removeEventListener('keydown', simKeyHandler); return; }
 if (e.key === 'Escape') { e.preventDefault(); stopVesselSimulation(); }
 else if (e.key === ' ' || e.code === 'Space') { e.preventDefault(); simPauseResume(); }
 }
 document.addEventListener('keydown', simKeyHandler);
 simState._keyHandler = simKeyHandler;

 updateSimPanel();
 simState.animId = requestAnimationFrame(animate);
 showToast('Simulation started - Esc to stop, Space to pause', 3000);
}

function simPauseResume() {
 simState.paused = !simState.paused;
 if (simState.paused) showToast('Simulation paused');
 else showToast('Simulation resumed');
}

function simSpeedSet(speed) {
 if (!window._simSpeedRef) return;
 window._simSpeedRef.set(speed);
}

function simSpeedChange() {
 if (!window._simSpeedRef) return;
 const speeds = [1, 5, 10, 50, 200, 1000];
 const cur = window._simSpeedRef.get();
 const idx = speeds.indexOf(cur);
 const next = speeds[(idx + 1) % speeds.length];
 window._simSpeedRef.set(next);
}

function stopVesselSimulation() {
 simState.running = false;
 simState.paused = false;
 if (simState.animId) cancelAnimationFrame(simState.animId);
 if (simState.marker) { map.removeLayer(simState.marker); simState.marker = null; }
 if (simState.trail) { map.removeLayer(simState.trail); simState.trail = null; }
 if (simState._keyHandler) { document.removeEventListener('keydown', simState._keyHandler); simState._keyHandler = null; }
 const panel = document.getElementById('sim-panel');
 if (panel) panel.remove();
 showToast('Simulation stopped');
}

// ===== GEOJSON / KML IMPORT FOR OBSTRUCTIONS =====
function importGeoObstructions() {
 const input = document.createElement('input');
 input.type = 'file';
 input.accept = '.geojson,.json,.kml';
 input.onchange = (e) => {
 const file = e.target.files[0];
 if (!file) return;
 const reader = new FileReader();
 reader.onload = (ev) => {
 try {
 let features = [];
 const text = ev.target.result;
 if (file.name.endsWith('.kml')) {
 features = parseKMLToFeatures(text);
 } else {
 const gj = JSON.parse(text);
 if (gj.type === 'FeatureCollection') features = gj.features;
 else if (gj.type === 'Feature') features = [gj];
 else if (gj.type === 'Polygon' || gj.type === 'MultiPolygon') features = [{ type: 'Feature', geometry: gj, properties: {} }];
 }
 let count = 0;
 features.forEach(f => {
 if (!f.geometry) return;
 const geom = f.geometry;
 const name = f.properties?.name || f.properties?.Name || 'Imported ' + (count + 1);
 if (geom.type === 'Polygon') {
 const coords = geom.coordinates[0].map(c => [c[1], c[0]]); // [lon,lat] ' [lat,lon]
 addGeoObstruction(coords, name);
 count++;
 } else if (geom.type === 'MultiPolygon') {
 geom.coordinates.forEach((poly, pi) => {
 const coords = poly[0].map(c => [c[1], c[0]]);
 addGeoObstruction(coords, name + (pi > 0 ? ' (' + (pi + 1) + ')' : ''));
 count++;
 });
 } else if (geom.type === 'Point') {
 const lat = geom.coordinates[1], lon = geom.coordinates[0];
 const radius = f.properties?.radius || f.properties?.exclusion || 500;
 addPointObstruction([lat, lon], name, radius);
 count++;
 }
 });
 showToast(count + ' obstruction' + (count !== 1 ? 's' : '') + ' imported');
 if (count > 0) promptReroute();
 } catch (err) {
 console.error('GeoJSON import error:', err);
 showToast('Import failed: ' + err.message);
 }
 };
 reader.readAsText(file);
 };
 input.click();
}

function parseKMLToFeatures(kmlText) {
 const parser = new DOMParser();
 const doc = parser.parseFromString(kmlText, 'text/xml');
 const features = [];
 // Parse Placemarks with Polygon geometry
 doc.querySelectorAll('Placemark').forEach(pm => {
 const nameEl = pm.querySelector('name');
 const name = nameEl ? nameEl.textContent : 'KML Import';
 const polygon = pm.querySelector('Polygon');
 const point = pm.querySelector('Point');
 if (polygon) {
 const coordsText = polygon.querySelector('coordinates')?.textContent?.trim();
 if (coordsText) {
 const coords = coordsText.split(/\s+/).map(c => {
 const parts = c.split(',');
 return [parseFloat(parts[0]), parseFloat(parts[1])]; // lon, lat
 }).filter(c => !isNaN(c[0]) && !isNaN(c[1]));
 if (coords.length > 2) {
 features.push({
 type: 'Feature',
 geometry: { type: 'Polygon', coordinates: [coords] },
 properties: { name }
 });
 }
 }
 } else if (point) {
 const coordsText = point.querySelector('coordinates')?.textContent?.trim();
 if (coordsText) {
 const parts = coordsText.split(',');
 features.push({
 type: 'Feature',
 geometry: { type: 'Point', coordinates: [parseFloat(parts[0]), parseFloat(parts[1])] },
 properties: { name, radius: 500 }
 });
 }
 }
 });
 return features;
}

function addGeoObstruction(coords, name) {
 const centroid = [
 coords.reduce((s, c) =>s + c[0], 0) / coords.length,
 coords.reduce((s, c) =>s + c[1], 0) / coords.length
 ];
 // Compute max radius from centroid
 let maxR = 0;
 coords.forEach(c => { const d = haversine(centroid, c); if (d >maxR) maxR = d; });

 const obs = {
 id: 'geo-' + Date.now() + '-' + Math.random().toString(36).substr(2, 4),
 type: 'polygon',
 name: name,
 center: centroid,
 radius: maxR,
 polygon: coords,
 hazardType: 'obstruction'
 };
 state.obstructions.push(obs);

 // Render on map
 L.polygon(coords, {
 color: '#ff453a', fillColor: '#ff453a', fillOpacity: 0.15, weight: 2, dashArray: '6 3'
 }).bindTooltip(name, { permanent: false }).addTo(layerAnnotations);
}

function addPointObstruction(latLng, name, radius) {
 const obs = {
 id: 'geo-pt-' + Date.now() + '-' + Math.random().toString(36).substr(2, 4),
 type: 'circle',
 name: name,
 center: latLng,
 radius: radius,
 hazardType: 'obstruction'
 };
 state.obstructions.push(obs);

 L.circle(latLng, { radius: radius, color: '#ff453a', fillColor: '#ff453a', fillOpacity: 0.15, weight: 2, dashArray: '6 3' })
 .bindTooltip(name + ' (' + radius + 'm)', { permanent: false }).addTo(layerAnnotations);
}

// ===== SCENARIO SAVE / COMPARE =====
function saveScenario() {
 const name = prompt('Scenario name:', 'Scenario ' + ((getSavedScenarios().length) + 1));
 if (!name) return;
 const scenario = {
 name: name,
 savedAt: new Date().toISOString(),
 settings: JSON.parse(JSON.stringify(state.settings)),
 lineCount: state.lines.length,
 stats: extractCurrentStats()
 };
 const scenarios = getSavedScenarios();
 scenarios.push(scenario);
 localStorage.setItem('candooka_scenarios', JSON.stringify(scenarios));
 showToast('Scenario "' + name + '" saved');
}

function getSavedScenarios() {
 try {
 return JSON.parse(localStorage.getItem('candooka_scenarios') || '[]');
 } catch (e) { return []; }
}

function extractCurrentStats() {
 const stats = {};
 ['stat-distance', 'stat-line-km', 'stat-sq-km', 'stat-time'].forEach(id => {
 const el = document.getElementById(id);
 if (el) stats[id] = el.textContent;
 });
 // Extract from summary overlay
 const box = document.getElementById('survey-summary-overlay');
 if (box) stats.summaryHTML = box.innerHTML;
 return stats;
}

function showScenarioCompare() {
 const scenarios = getSavedScenarios();
 if (scenarios.length === 0) {
 showToast('No saved scenarios. Save the current plan first.');
 return;
 }

 let panel = document.getElementById('scenario-compare-panel');
 if (!panel) {
 panel = document.createElement('div');
 panel.id = 'scenario-compare-panel';
 panel.style.cssText = 'position:fixed;top:50%;left:50%;transform:translate(-50%,-50%);z-index:9500;' +
 'background:#0e0e16;border:1px solid #1a1a24;border-radius:8px;padding:20px 24px;' +
 'min-width:500px;max-width:700px;max-height:80vh;overflow-y:auto;box-shadow:0 16px 64px rgba(0,0,0,0.8);';
 document.body.appendChild(panel);
 }

 let html = '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:14px;">' +
 '<div style="font-size:14px;font-weight:700;color:#e0e8f0;">Scenario Comparison</div>' +
 '<button onclick="document.getElementById(\'scenario-compare-panel\').remove()" style="background:none;border:none;color:#ff453a;font-size:18px;cursor:pointer;">&times;</button></div>';

 html += '<table style="width:100%;border-collapse:collapse;font-size:11px;">';
 html += '<tr style="border-bottom:1px solid #333;color:#00d2ff;font-weight:700;">' +
 '<td style="padding:6px;">Scenario</td>' +
 '<td style="padding:6px;">Speed</td>' +
 '<td style="padding:6px;">Radius</td>' +
 '<td style="padding:6px;">Weather</td>' +
 '<td style="padding:6px;">Stats</td>' +
 '<td style="padding:6px;">Saved</td>' +
 '<td style="padding:6px;"></td></tr>';

 scenarios.forEach((sc, idx) => {
 const s = sc.settings || {};
 const bg = idx % 2 === 0 ? '' : 'background:rgba(255,255,255,0.03);';
 html += '<tr style="border-bottom:1px solid #222;' + bg + '">' +
 '<td style="padding:6px;color:#fff;font-weight:700;">' + sc.name + '</td>' +
 '<td style="padding:6px;color:#e8ecf2;">' + (s.speed || '-') + '/' + (s.turnSpeed || '-') + ' kn</td>' +
 '<td style="padding:6px;color:#e8ecf2;">' + ((s.turnRadius || 0) / 1000).toFixed(1) + ' km</td>' +
 '<td style="padding:6px;color:#e8ecf2;">' + (s.weatherDowntime || 0) + '%</td>' +
 '<td style="padding:6px;color:#30d158;">' + (sc.stats?.['stat-time'] || '-') + '</td>' +
 '<td style="padding:6px;color:#8a9bb0;font-size:9px;">' + fmtD24(sc.savedAt) + '</td>' +
 '<td style="padding:6px;"><button onclick="deleteScenario(' + idx + ')" style="background:none;border:none;color:#ff453a;cursor:pointer;font-size:10px;">x</button></td>' +
 '</tr>';
 });
 html += '</table>';

 html += '<div style="display:flex;gap:8px;margin-top:14px;">' +
 '<button onclick="saveScenario();showScenarioCompare();" style="flex:1;padding:8px;border-radius:5px;border:none;background:#00d2ff;color:#0e0e16;font-weight:700;cursor:pointer;font-size:11px;">+ Save Current</button>' +
 '<button onclick="clearAllScenarios()" style="flex:1;padding:8px;border-radius:5px;border:1px solid #333;background:transparent;color:#ff453a;font-weight:600;cursor:pointer;font-size:11px;">Clear All</button></div>';

 panel.innerHTML = html;
}

function deleteScenario(idx) {
 const scenarios = getSavedScenarios();
 scenarios.splice(idx, 1);
 localStorage.setItem('candooka_scenarios', JSON.stringify(scenarios));
 showScenarioCompare();
}

function clearAllScenarios() {
 if (!confirm('Delete all saved scenarios?')) return;
 localStorage.removeItem('candooka_scenarios');
 document.getElementById('scenario-compare-panel')?.remove();
 showToast('All scenarios cleared');
}

function exportReportCSV() {
 const rows = [];
 const body = document.getElementById('report-body');
 if (!body) return;
 body.querySelectorAll('div').forEach(div => {
 const spans = div.querySelectorAll('span');
 const strongs = div.querySelectorAll('strong');
 if (spans.length && strongs.length) {
 rows.push(`"${spans[0].textContent.trim()}","${strongs[0].textContent.trim()}"`);
 } else if (div.style.borderBottom && div.textContent.trim()) {
 rows.push(`\n"${div.textContent.trim()}",""`);
 }
 });
 const csv = `Candooka Survey Planning Report\nGenerated,${new Date().toISOString()}\n\n` + rows.join('\n');
 const blob = new Blob([csv], { type: 'text/csv' });
 downloadBlob(blob, `candooka_survey_report_${new Date().toISOString().slice(0,10)}.csv`);
 showToast('Report exported as CSV');
}

